	 */
	public void changeContractBaseParamCheck(ContractReqDTO contractReq) {
		if (org.apache.commons.lang3.StringUtils.isBlank(contractReq.getContractBaseInfo().getProjectOrderId())
			|| contractReq.getContractBaseInfo().getContractType() == null) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "项目订单号、合同类型不能为空");
		}
		if (ContractTypeEnum.NEED_CHANGE_ID_CONTRACT_LIST.contains(contractReq.getContractBaseInfo().getContractType()) && org.apache.commons.lang3.StringUtils.isBlank(contractReq.getContractBaseInfo().getChangeOrderId())) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "变更单号不能为空");
		}
	}

	/**
	 * 后续中控报价输出统一接口，本次先用这个方法转换
	 */
	public PlanAllDTO atomChangeQuotationConvertToPlanAllDTO(QuoteChangePreviewDTO quoteChangePreviewDTO, @Nullable PlanAttachmentDTO baseChangePdf) {
		PlanAllDTO planAllDTO = new PlanAllDTO();
		//房产类型
		HouseLayoutInfoDTO houseLayoutInfoDTO = HouseLayoutInfoDTO.builder()
			.houseType(quoteChangePreviewDTO.getHouseType())
			.houseLayoutDesc(quoteChangePreviewDTO.getReconstructionHouseLayoutDesc())
			.build();
		planAllDTO.setReconstructionHouseLayout(houseLayoutInfoDTO);
		//套餐名称
		PlanInfoDTO planInfoDTO = new PlanInfoDTO();
		planInfoDTO.setComboName(CollUtil.isNotEmpty(quoteChangePreviewDTO.getComboNameList()) ? String.join(",", quoteChangePreviewDTO.getComboNameList()) : null);
		//计价面积(所有套餐累加)
		planInfoDTO.setPricingArea(CollectionUtils.isNotEmpty(quoteChangePreviewDTO.getPricingAreaList()) ? quoteChangePreviewDTO.getPricingAreaList().stream().reduce(BigDecimal.ZERO, BigDecimal::add) : null);
		//备注
		planInfoDTO.setRemark(quoteChangePreviewDTO.getRemark());
		//报价单总价
		planInfoDTO.setQuotePrice(quoteChangePreviewDTO.getHardTotalPriceAfterCoupon());
		planInfoDTO.setContractPrice(quoteChangePreviewDTO.getHardTotalPriceAfterCoupon());
		planInfoDTO.setContractPriceTotal(quoteChangePreviewDTO.getHardTotalPriceAfterCoupon());
		planInfoDTO.setPersonalTotalPrice(quoteChangePreviewDTO.getPersonalTotalPriceAfterCoupon());


		planAllDTO.setPlanInfo(planInfoDTO);
		//变更报价单PDF
		PlanAttachmentDTO planAttachmentDTO = new PlanAttachmentDTO();
		planAttachmentDTO.setFileType(PlanAttachment.报价单);
		planAttachmentDTO.setFileUrl(baseChangePdf != null ? baseChangePdf.getFileUrl() : null);
		planAttachmentDTO.setPrevUrl(baseChangePdf != null ? baseChangePdf.getPrevUrl() : null);
		planAllDTO.setPlanAttachmentList(Collections.singletonList(planAttachmentDTO));

		if (planAttachmentDTO.getFileUrl() != null && planAttachmentDTO.getPrevUrl() != null) {
			planAllDTO.setPlanAttachmentList(Collections.singletonList(planAttachmentDTO));
		} else {
			planAllDTO.setPlanAttachmentList(new ArrayList<>());
		}

		return planAllDTO;
	}

	/**
	 * 变更合同提交，相当于保存草稿，并没有最终生成合同，变更合同需要最终确认才是合同发起完成
	 * 1、保存合同信息，相当于只保存草稿
	 * 2、计算diff，组装给前端
	 *
	 * @param contractReq
	 * @return
	 */
	@ContractDataPrepare
	@Transactional
	public ChangeContractSubmitRes changeContractSubmit(ContractReqDTO contractReq) {
		LOGGER.info("变更合同提交开始，请求参数：{}", JSON.toJSONString(contractReq));
		//校验合同字段一致性
		contractUnifyService.checkContractFieldConsistency(contractReq);
		contractUnifyService.checkIdCardInfo(contractReq);
		//校验参数合法性
		contractUnifyService.checkParamLegitimacy(contractReq);
		//构建合同数据,没有DB更新
		Contract currentContract = contractUnifyService.buildDraftContract(contractReq);
		//DB-合同数据入库
		contractUnifyService.saveCoreContractDb(currentContract, contractReq);
		//合同节点信息处理
		contractUnifyService.updateOrSaveContractNode(currentContract, contractReq);
		//计算合同diff
		return buildChangeContractDiff(currentContract, contractReq);
	}

	public boolean isChangeContractPdf(ChangeContractFreeformDTO freeformDTO) {
		if (freeformDTO != null && !org.apache.commons.lang3.StringUtils.isBlank(freeformDTO.getDynamicChangeContent())) {
			ChangeContractFreeformDTO.DynamicChangeContent dynamicChangeContentDTO = JSON.parseObject(freeformDTO.getDynamicChangeContent(), ChangeContractFreeformDTO.DynamicChangeContent.class);
//			if (Boolean.FALSE.equals(dynamicChangeContentDTO.getIsChangeDiscount()) &&
//				org.springframework.util.CollectionUtils.isEmpty(dynamicChangeContentDTO.getChangeData()) &&
//				org.springframework.util.CollectionUtils.isEmpty(dynamicChangeContentDTO.getBudgetUrl()) &&
//				org.springframework.util.CollectionUtils.isEmpty(dynamicChangeContentDTO.getDecorateRuleUrl()) &&
//				org.springframework.util.CollectionUtils.isEmpty(dynamicChangeContentDTO.getInternalConfigurationsUrl()) &&
//				org.springframework.util.CollectionUtils.isEmpty(dynamicChangeContentDTO.getExtraConfigurationsUrl()) &&
//				org.springframework.util.CollectionUtils.isEmpty(dynamicChangeContentDTO.getPersonalQuotionUrl()) &&
//				org.springframework.util.CollectionUtils.isEmpty(dynamicChangeContentDTO.getBaseConstructionDrawUrl()) &&
//				org.springframework.util.CollectionUtils.isEmpty(dynamicChangeContentDTO.getMaterialList())) {
//				return false;
//			}
			//是否有基础施工图,2.5施工图纸直接返回的图片，2.0是pdf
			boolean isHaveBaseConstructionDraw = CollectionUtils.isNotEmpty(dynamicChangeContentDTO.getBaseConstructionDrawUrl()) || StringUtils.isNotBlank(dynamicChangeContentDTO.getBaseConstructionDrawPdfUrl());
			return !Boolean.FALSE.equals(dynamicChangeContentDTO.getIsChangeDiscount()) ||
				!CollectionUtils.isEmpty(dynamicChangeContentDTO.getChangeData()) ||
				!StringUtils.isBlank(dynamicChangeContentDTO.getBudgetPdfUrl()) ||
				!CollectionUtils.isEmpty(dynamicChangeContentDTO.getDecorateRuleUrl()) ||
				!StringUtils.isBlank(dynamicChangeContentDTO.getInternalConfigurationsPdfUrl()) ||
				!StringUtils.isBlank(dynamicChangeContentDTO.getExtraConfigurationsPdfUrl()) ||
				!StringUtils.isBlank(dynamicChangeContentDTO.getPersonalQuotionPdfUrl()) ||
				isHaveBaseConstructionDraw ||
				!CollectionUtils.isEmpty(dynamicChangeContentDTO.getMaterialList());
		}

		return true;
	}

	public ChangeContractSubmitRes buildChangeContractDiff(Contract currentContract, ContractReqDTO contractReq) {
		List<ContractFieldChangeRecord> list = changeContractService.calculateDiff(currentContract.getContractCode());
		boolean isChangePrice = changeContractService.changePriceScope(contractReq.getContractBaseInfo().getChangeOrderId());
		ChangeContractSubmitRes changeContractSubmitRes = new ChangeContractSubmitRes();
		changeContractSubmitRes.setContractCode(currentContract.getContractCode());
		ContractDiffDTO contractDiffDTO = changeContractService.getAllContractDiffWithSection(contractReq.getContractBaseInfo().getProjectOrderId(),
			contractReq.getContractBaseInfo().getChangeOrderId(), list);
		String filePrevUrl = "";
		if (isChangePrice) {
			PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(contractReq.getContractBaseInfo().getProjectOrderId(),
				contractReq.getContractBaseInfo().getChangeOrderId());
			if (CollectionUtils.isNotEmpty(planAllDTO.getPlanAttachmentList())) {
				Optional<PlanAttachmentDTO> optionalPlanAttachmentDTO = planAllDTO.getPlanAttachmentList().stream()
					.filter(planAttachmentDTO -> planAttachmentDTO.getFileType() == 50).findFirst();
				if (optionalPlanAttachmentDTO.isPresent()) {
					filePrevUrl = optionalPlanAttachmentDTO.get().getMultimediaPreviewUrl();
				}
			}
		}
		changeContractSubmitRes.setSignObjectDiff(contractDiffDTO.getSignObjectDiff());
		changeContractSubmitRes.setContentDiff(contractDiffDTO.getContentDiff());
		changeContractSubmitRes.setDiscountDiff(contractDiffDTO.getDiscountDiff());
		changeContractSubmitRes.setQuotePdfUrl(filePrevUrl);
		return changeContractSubmitRes;
	}


