	public ChangeContractSubmitResV2 buildChangeContractDiffV2(Contract currentContract, String projectOrderId, String changeOrderId) {
		List<ModelDiffDTO> changeData = getChangeData(currentContract, projectOrderId, changeOrderId);
		ChangeContractFreeformDTO changeContractFreeformDTO = buildChangeContractFreeformDTO(currentContract.getContractCode(), currentContract.getProjectOrderId(), currentContract.getChangeOrderId(), false);
		return ChangeContractSubmitResV2.builder()
			.projectOrderId(currentContract.getProjectOrderId())
