	/**
	 * 合同变更确认
	 *
	 * @param contract
	 * @return
	 */
	public ContractSubmitResDTO changeContractConfirm(Contract contract) {
		//如果状态不是草稿中，提示合同已提交
		if (!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			LOGGER.warn("该合同已提交，请勿重复操作,projectOrderId:{},contractCode:{}", contract.getProjectOrderId(), contract.getContractCode());
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "该合同已提交，请勿重复操作", Level.WARN);
		}
		contractUnifyService.checkContractLaunching(contract.getProjectOrderId(), contract.getType());
		String contractPollKey = contractUnifyService.getContractPollKey(contract.getProjectOrderId(), contract.getType());
		List<FileInfo> contractUrl = new ArrayList<>();
		HeaderParam headerContext = HeaderContext.getContext();
		CompletableFuture<Void> launchFuture = CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				LOGGER.info("异步合同变更确认开始，contractCode:{}，threadId:{}", contract.getContractCode(), Thread.currentThread().getId());
				launchChangeContractBefore(contract, headerContext);
				//生成pdf,pdfUrl设置到contract对象中
				if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
					ChangeContractFreeformDTO freeformDTO = changeContractUnifyService.buildChangeContractFreeformDTO(contract.getContractCode(), contract.getProjectOrderId(), contract.getChangeOrderId(), true);
					boolean changeContractPdf = isChangeContractPdf(freeformDTO);
					if (changeContractPdf) {
						ObjectMapper objectMapper = new ObjectMapper();
						Map<String, Object> map = objectMapper.convertValue(freeformDTO, Map.class);
						String pdfUrl = contractBusinessService.generatePdf(contract, map);
						contractUrl.add(FileInfo.builder()
							.type(FileTypeEnum.PDF.getKey())
							.contractType(contract.getType())
							.url(pdfUrl).build());
					}
					// 校验合同pdf是否需要更新
					boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
					if (!changeContractPdf && !processV25) {
						throw new NrsBusinessException(ResponseCodeEnum.CONTRACT_NO_CHANGE.getCode(), ResponseCodeEnum.CONTRACT_NO_CHANGE.getMsg(), Level.WARN);
					}
				} else {
					//线下签约
					List<ContractAttach> offlineAttachList = contractAttachService.getListByContractCode(contract.getContractCode(), AttachTypeEnum.OFFLINE_CONTRACT.getCode());
					for (ContractAttach attach : offlineAttachList) {
						contractUrl.add(FileInfo.builder()
							.type(contractBusinessService.getAttachFileKey(Collections.singletonList(attach.getUrl())))
							.contractType(contract.getType())
							.url(attach.getUrl()).build());
					}
				}
				//更新contract状态，记录日志
				String operatorName = homeAndPcCommonService.getOperatorName(HeaderContext.getUserId());
				changeContractUnifyService.updateChangeContract(contract, operatorName);
				launchChangeContractAfter(contractPollKey, contract, contractUrl);
				LOGGER.info("异步合同变更确认结束，contractCode:{}，threadId:{}", contract.getContractCode(), Thread.currentThread().getId());
			} catch (Exception e) {
				LOGGER.info("异步合同变更确认异常，contractCode:{}，threadId:{}", contract.getContractCode(), Thread.currentThread().getId());
				launchChangeContractException(contract, e, contractPollKey);
			}
		}), contractSubmitExternalExecutor);
		if (contractUnifyService.contractSubmitSync(contract.getType())) {
			try {
				launchFuture.get();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			} catch (Exception e) {
				Throwable cause = e.getCause();
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), cause == null ? e.getMessage() : cause.getMessage());
			}
		}
		return ContractSubmitResDTO.builder()
			.contractCode(contract.getContractCode())
			.contractUrl(contractUrl)
			.contractResultPollingKey(contractPollKey)
			.estimatedLaunchTime(ContractTypeEnum.getEnumByCode(contract.getType()).getEstimatedLaunchTime())
			.build();
	}

	/**
	 * 发起变更合同前处理
	 */
	public void launchChangeContractBefore(Contract contract, HeaderParam headerContext) {
		//加锁
		lockService.lockElseThrow(LockConstant.getContractLaunchingKey(contract.getProjectOrderId(), contract.getType()));
		try {
			HeaderContext.setContext(headerContext);
		} catch (Exception e) {
			throw new RuntimeException(e);
		}
	}

	/**
	 * 发起变更合同后处理
	 */
	public void launchChangeContractAfter(String contractPollKey, Contract contract, List<FileInfo> contractUrl) {
		try {
			ContractSubmitResDTO contractSubmitResDTO = ContractSubmitResDTO.builder().contractUrl(contractUrl).contractCode(contract.getContractCode()).build();
			contractUnifyService.saveContractSubmitToRedis(contractSubmitResDTO, ContractSubmitStatusEnum.SUCCESS, contractPollKey, null, false);
			//回写客源
			Map<String, String> fieldKeyValueMap = pcContractService.getContractFieldKeyValueMap(contract.getContractCode());
			changeContractService.rewriteCustomer(contract.getProjectOrderId(), contract.getContractCode(), fieldKeyValueMap);
		} finally {
			HeaderContext.clearContext();
			//解锁
			lockService.unLock(LockConstant.getContractLaunchingKey(contract.getProjectOrderId(), contract.getType()));
		}

	}

	/**
	 * 发起变更合同异常处理
	 */
	public void launchChangeContractException(Contract contract, Throwable e, String contractPollKey) {
		try {
			Throwable cause = e.getCause();
			String errorMessage = contractUnifyService.getContractSubmitErrorMessage(e);
			//pdf生成失败,允许重试
			boolean retrySubmit = cause instanceof NrsBusinessException && ((NrsBusinessException) cause).getCode() == ResponseCodeEnum.PDF_CREATE_ERROR.getCode();
			//保存发起结果到redis
			contractUnifyService.saveContractSubmitToRedis(Lists.emptyList(), ContractSubmitStatusEnum.FAIL, contractPollKey, errorMessage, retrySubmit);
			//记录变更合同发起失败信息
			contractService.updateContractErrorMessage(contract.getContractCode(), errorMessage);
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), errorMessage);
		} finally {
			HeaderContext.clearContext();
			//解锁
			lockService.unLock(LockConstant.getContractLaunchingKey(contract.getProjectOrderId(), contract.getType()));
		}
	}


	/**
	 * 撤销合同审核
	 *
	 * @param contract
	 */
	public Boolean undoAudit(Contract contract) {
		if (!BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType())) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "非团装合同不允许撤销审核", Level.WARN);
		}
		if (!ContractStatusEnum.AUDITING.getCode().equals(contract.getStatus())) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "合同不处于审核中，不允许撤销审核", Level.WARN);

		}
		String operatorName = homeAndPcCommonService.getOperatorName(HeaderContext.getUserId());
		((ChangeContractUnifyService) AopContext.currentProxy()).undoAuditChangeContract(contract, operatorName);
		return true;
	}

	@Transactional
	public void undoAuditChangeContract(Contract contract, String userName) {
		//更新contract状态
		contract.setUserQueryStatus(UserQueryStatusEnum.INVALID.getCode());
		contract.setStatus(ContractStatusEnum.DRAFT.getCode());
		contract.setUserQueryStatus(CommonEnum.NO.getCode());
		contract.setUserSignStatus(CommonEnum.NO.getCode());
		contract.setUserSignedKey("");
		contract.setBothSignedKey("");
		contract.setPreviewKey("");
		contract.setModifyUserName(userName);
		contract.setModifyUserId(HeaderContext.getUserId().toString());
		contractService.updateUnchecked(contract);
		//日志&消息
		contractUnifyService.doAfterUndoAudit(contract);
	}

	/**
	 * 更新contract状态，记录日志
	 *
	 * @param contract
	 * @param userName
	 */
	@Transactional
	public void updateChangeContract(Contract contract, String userName) {
		//更新contract状态
		boolean userCanSee = SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType()) || !AuditTypeEnum.BEFORE_SIGN.getCode().equals(contract.getAuditType());
		contract.setUserQueryStatus(userCanSee ? UserQueryStatusEnum.VALID.getCode() : UserQueryStatusEnum.INVALID.getCode());
		contract.setStatus(homeAndPcCommonService.getContractSubmitStatus(contract));
		contract.setModifyUserName(userName);
		contractService.update(contract);
		contractService.updateContractErrorMessage(contract.getContractCode(), "");
		//日志&消息
		contractUnifyService.doAfterSubmit(contract);
		//同步中控变更
		notifyAtomChange(contract);

	}

	private void notifyAtomChange(Contract contract) {
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
		if (processV25 && !ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contract.getType())) {
			CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(contract.getProjectOrderId());
			atomChangeRpc.submitSubProcessToChange(coordinationProjectOrder.getProjectOrderId(), contract.getChangeOrderId(), contract.getContractCode(), HeaderContext.getContext());
			atomChangeRpc.submitChangeToRiskAudit(coordinationProjectOrder.getProjectOrderId(), contract.getChangeOrderId(), HeaderContext.getContext());
			contractLogService.createLog(contract.getContractCode(), LogTypeEnum.SUBMIT_AUDIT.getCode(), LogTypeEnum.SUBMIT_AUDIT.getName(), "",
				HeaderContext.getContext().getOperatorUcId(), HeaderContext.getContext().getOperatorName());
		}
	}

	public NotifyPersonalContractDTO generatePersonalContract(String projectOrderId, String changeOrderId, Long operatorUcid) {
		//查询变更范围，不包含报价不处理
		ChangeApplyInfoDTO changeApplyInfoDTO = atomChangeRpc.getChangeApplyInfo(changeOrderId);
		List<Integer> changeScopeList = changeApplyInfoDTO.getChangeScopeList();
		if (!changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode())) {
			return null;
		}
		//如果变更单不包含个性化报价,则不处理
		if (!atomBudgetRpc.containPersonQuotation(changeOrderId)) {
			return null;
		}
		//包含个性化报价
		List<Contract> contractList = contractService.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode());
		//C合同已存在
		if (CollectionUtils.isNotEmpty(contractList)) {
			Contract personContract = contractList.get(0);
			List<ContractNode> contractConfirmNodeList = contractNodeService.getByContractCodeAndType(personContract.getContractCode(), NodeTypeEnum.USER_CONFIRM.getCode());
			if (CollectionUtils.isNotEmpty(contractConfirmNodeList) || ContractStatusEnum.FINISH.getCode().equals(personContract.getStatus()) || ContractStatusEnum.USER_CONFIRMED.getCode().equals(personContract.getStatus())) {
				//合同签署完成，不用生成新的合同，直接返回已生成的合同
				return NotifyPersonalContractDTO.builder()
					.alreadyGenerated(Boolean.TRUE)
					.baseContract(NotifyPersonalContractDTO.BaseContract.builder()
						.contractCode(personContract.getContractCode())
						.businessType(personContract.getBusinessType())
						.projectOrderId(personContract.getProjectOrderId())
						.status(personContract.getStatus())
						.type(personContract.getType())
						.build())
					.build();
			} else {
				//合同未签署，作废合同
				commonContractService.cancelCurrentContract(personContract, operatorUcid, true);
			}
		}
		//C合同没有生成，直接生成新的C合同
		return NotifyPersonalContractDTO.builder()
			.alreadyGenerated(Boolean.FALSE)
			.baseContract(buildPersonContract(projectOrderId, changeOrderId, operatorUcid, changeScopeList, null, null))
			.build();
	}

	public NotifyPersonalContractDTO generatePersonalContractV2(NotifyPersonalContractReqDTO req) {
		//获取可创建的C合同
		ContractCreateBaseInfo canCreateContract = commonBusinessService.getCanCreateContract(req.getProjectOrderId(), ContractTypeEnum.PERSONAL.getCode(), req.getBillCodeList());
		//如果不存在报价单列表和分公司，则不处理C合同
		if (CollectionUtils.isEmpty(req.getBillCodeList()) || StringUtils.isBlank(req.getCompanyCode())) {
			//合同签署完成，不用生成新的合同，直接返回已生成的合同
			return NotifyPersonalContractDTO.builder()
				.alreadyGenerated(Boolean.TRUE)
				.baseContract(NotifyPersonalContractDTO.BaseContract.builder().build())
				.build();
		}
		//查询变更范围，不包含报价不处理
		ChangeApplyInfoDTO changeApplyInfoDTO = atomChangeRpc.getChangeApplyInfo(req.getChangeOrderId());
		List<Integer> changeScopeList = changeApplyInfoDTO.getChangeScopeList();
		if (!changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode())) {
			return null;
		}
		//如果变更单不包含个性化报价,则不处理
		if (!atomBudgetRpc.containPersonQuotation(req.getChangeOrderId())) {
			return null;
		}
		//查询变更报价单的原始报价单
		HashMap<String, ChangeDTO.ChangeBillDTO> changeBillDTOHashMap = atomBudgetRpc.queryChangeByQuotationBillCode(req.getBillCodeList());
		if (changeBillDTOHashMap == null || changeBillDTOHashMap.isEmpty()) {
			throw new NrsBusinessException("查询变更报价单的原始报价单失败, billCodeList: " + req.getBillCodeList());
		}
		//获取原始报价单列表
		List<String> originalBillCodeList = changeBillDTOHashMap.values().stream().map(ChangeDTO.ChangeBillDTO::getRelationBillCode).collect(Collectors.toList());
		List<ContractQuotationRelation> contractQuotationRelationList = contractQuotationRelationService.getByBillCodesAndStatus(originalBillCodeList, RelationStatusEnum.RELATED.getCode());
		boolean isSubsidyGoods = subsidyOrderService.isSubsidyGoods(originalBillCodeList.get(0));
		//是否包含补贴商品&&原始报价单没有对应的合同code
		if (isSubsidyGoods && CollectionUtil.isEmpty(contractQuotationRelationList)) {
			NotifyPersonalContractDTO.BaseContract baseContract = buildPersonContract(canCreateContract.getProjectOrderId(), req.getChangeOrderId(), req.getOperatorUcid(), changeScopeList, req.getBillCodeList(), originalBillCodeList);
			if (!UserSignTypeEnum.SIGN.getCode().equals(baseContract.getUserSignType())) {
				LOGGER.info("国补单签署方式非正式签署情况下，撤回合同,contractCode:{}", baseContract.getContractCode());
				homeAndPcCommonService.undoContract(baseContract.getContractCode(), req.getOperatorUcid());
			}
			//如果是国补订单，直接返回已生成的合同
			return NotifyPersonalContractDTO.builder()
				.alreadyGenerated(Boolean.FALSE)
				.baseContract(baseContract)
				.build();
		}
		//获取协同项目单号下的C合同列表(兼容历史C合同项目单号为整装项目单号场景)
		List<Contract> contractList = contractService.getContractList(canCreateContract.getProjectOrderId(), ContractTypeEnum.PERSONAL.getCode());
		Contract personalContract = contractList.stream()
			.filter(contract -> ContractStatusEnum.USER_CONFIRMED.getCode().equals(contract.getStatus()) || ContractStatusEnum.FINISH.getCode().equals(contract.getStatus()) ||
				(ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus()) && CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus())))
			.filter(m -> m.getCompanyCode().equals(req.getCompanyCode()))
			.findFirst().orElse(null);
		//C合同已存在
		if (CollectionUtils.isNotEmpty(contractList) && ObjectUtil.isNotEmpty(personalContract)) {
			return NotifyPersonalContractDTO.builder()
				.alreadyGenerated(Boolean.TRUE)
				.baseContract(NotifyPersonalContractDTO.BaseContract.builder()
					.contractCode(personalContract.getContractCode())
					.businessType(personalContract.getBusinessType())
					.projectOrderId(req.getProjectOrderId())
					.status(personalContract.getStatus())
					.type(personalContract.getType())
					.build())
				.build();
		} else {
			//查询和变更报价单关联的C合同
			List<Contract> contractListByBillCodeList = quotationRelationCommonService.getContractListByBillCodeList(originalBillCodeList);
			if (CollectionUtils.isNotEmpty(contractListByBillCodeList)) {
				for (Contract contract : contractListByBillCodeList) {
					//合同未签署，作废合同
					commonContractService.cancelCurrentContract(contract, req.getOperatorUcid(), true);
				}
			}
		}
		//C合同没有生成，直接生成新的C合同
		return NotifyPersonalContractDTO.builder()
			.alreadyGenerated(Boolean.FALSE)
			.baseContract(buildPersonContract(canCreateContract.getProjectOrderId(), req.getChangeOrderId(), req.getOperatorUcid(), changeScopeList, req.getBillCodeList(), originalBillCodeList))
			.build();
	}

	public NotifyPersonalContractDTO.BaseContract buildPersonContract(String projectOrderId, String changeOrderId, Long operatorUcid, List<Integer> changeScopeList, List<String> billCodeList, List<String> originalBillCodeList) {
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(projectOrderId);
		//并行获取构建个性化合同信息
		PersonContractBuildRpcInfo personContractBuildRpcInfo = getPersonContractBuildRpcInfo(projectOrderId, changeOrderId, operatorUcid, billCodeList);
		//个性化金额
		BigDecimal personalTotalPrice = personContractBuildRpcInfo.getChangeBaseAndPriceInfo().getChangePriceInfo().getPersonalChangeTotalPrice();
		//个性化报价单主体
		String companyCode = personContractBuildRpcInfo.getChangeBaseAndPriceInfo().getBillDTO().getOrganizationCode();
		//获取合同配置
		List<ContractCityCompanyInfo> configList = contractCityCompanyConfigService.getConfig(
			projectOrderId,
			projectInfoDTO.getCustomerHouse().getGbCode(),
			companyCode,
			commonContractService.getBusinessType(projectInfoDTO),
			ContractTypeEnum.PERSONAL.getCode(),
			SignChannelTypeEnum.ONLINE.getCode()
		);
		if (CollectionUtil.isEmpty(configList)) {
			throw new NrsBusinessException(String.format("合同配置不存在,projectOrderId:%s,gbcode:%s,companyCode:%s,联系运营配置", projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), companyCode));
		}
		//默认生成线上合同-电子手签的合同，没有审核流程，直接到待签署，签署完成后自动完成
		Contract personalContract = Contract.builder()
			.contractCode(RandomCodeUtils.generateContractCode())
			.contractNo(RandomCodeUtils.generateContractNo())
			.userSignType(UserSignTypeEnum.SIGN.getCode())
			.type(ContractTypeEnum.PERSONAL.getCode())
			.gbCode(projectInfoDTO.getCustomerHouse().getGbCode())
			.signChannelType(SignChannelTypeEnum.ONLINE.getCode())
			.projectOrderId(projectOrderId)
			.changeOrderId(changeOrderId)
			.businessType(commonContractService.getBusinessType(projectInfoDTO))
			.auditType(configList.get(0).getAuditType().byteValue())
			.companyCode(companyCode)
			.userSignStatus(CommonEnum.NO.getCode())
			.userQueryStatus(UserQueryStatusEnum.VALID.getCode())
			.createUserId(operatorUcid.toString())
			.createUserName(personContractBuildRpcInfo.getUserName())
			.modifyUserId(operatorUcid.toString())
			.modifyUserName(personContractBuildRpcInfo.getUserName())
			.status(ContractStatusEnum.PENDING_COMPANY_SIGN.getCode())
			.amount(personalTotalPrice)
			.build();

		Contract latestContract = getChangePrevEffectContractByPid(personalContract.getProjectOrderId());
		if (UserSignTypeEnum.CONFIRM.getCode().equals(latestContract.getUserSignType()) || SignChannelTypeEnum.OFFLINE.getCode().equals(latestContract.getSignChannelType())) {
			personalContract.setStatus(ContractStatusEnum.PENDING_USER_CONFIRM.getCode());
			personalContract.setUserSignType(UserSignTypeEnum.CONFIRM.getCode());
		}

		// 获取协同项目类型
		CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectOrderId);
		boolean hasDecorateProjectOrder = coordinationProjectOrder.hasDecorateProjectOrder();
		Map<String, Object> formData;
		//生成合同pdf
		formData = buildFreeFormData(personalContract, personContractBuildRpcInfo, latestContract);
		contractBusinessService.generatePdf(personalContract, formData);
		//保存合同DB
		((ChangeContractUnifyService) AopContext.currentProxy()).savePersonalContract(personalContract, billCodeList, latestContract, originalBillCodeList);
		contractUnifyService.doAfterSubmit(personalContract);

		return NotifyPersonalContractDTO.BaseContract.builder()
			.contractCode(personalContract.getContractCode())
			.businessType(personalContract.getBusinessType())
			.projectOrderId(personalContract.getProjectOrderId())
			.status(personalContract.getStatus())
			.type(personalContract.getType())
			.userSignType(personalContract.getUserSignType())
			.build();
	}

	/**
	 * 个性化合同构建并发请求获取信息
	 */
	private PersonContractBuildRpcInfo getPersonContractBuildRpcInfo(String projectOrderId, String changeOrderId, Long operatorUcid, List<String> billCodeList) {
		LOGGER.info("个性化合同构建并发请求开始，{}", changeOrderId);

		ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();
		PersonContractBuildRpcInfo personContractBuildRpcInfo = new PersonContractBuildRpcInfo();
		parallelTaskService.addNewTask(parallelTasksContext, () -> {
			//最新报价信息
