		//合同金额
		if (changeKeyList.contains(ChangeKeyEnum.CONTRACT_AMOUNT.getKey()) && changeMap.containsKey("contractAmount")) {
			ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.CONTRACT_AMOUNT.getKey());
			String contractAmount = changeMap.getOrDefault("contractAmount", "");
			String oldContractAmount = oldValueMap.getOrDefault("contractAmount", "");
			BigDecimal contractAmountBigDecimal = StrUtil.isBlankIfStr(contractAmount) ? BigDecimal.ZERO : new BigDecimal(contractAmount).setScale(2, RoundingMode.HALF_UP);
			BigDecimal oldContractAmountBigDecimal = StrUtil.isBlankIfStr(oldContractAmount) ? BigDecimal.ZERO : new BigDecimal(oldContractAmount).setScale(2, RoundingMode.HALF_UP);
			//获取新旧合同金额差值的绝对值,保留两位小数点
			BigDecimal contractAmountDiff = contractAmountBigDecimal.subtract(oldContractAmountBigDecimal).abs().setScale(2, RoundingMode.HALF_UP);
			ChangeContractFreeformDTO.ChangeDataItem item = new ChangeContractFreeformDTO.ChangeDataItem();
			item.setArticle(changeKeyConfig.getArticle());
			item.setParagraph(changeKeyConfig.getParagraph());
