	/**
	 * 构建备件模块diff
	 */
	public List<FieldDiffDTOV2> buildAttachModelDiff(String projectOrderId, String contractCode, Byte businessType) {
		List<FieldDiffDTOV2> fieldDiffDTOV2List = new ArrayList<>();
		// 当前合同备件
		List<ContractAttach> contractAttachList = contractAttachService.getListCompatibleByContractCode(contractCode);
		Contract currentContract = contractService.getByContractCode(contractCode);
		// 上一份合同备件
		Contract preContract = contractService.getChangePrevEffectContract(currentContract.getId(), projectOrderId);
		List<ContractAttach> preContractAttachList = contractAttachService.getListCompatibleByContractCode(preContract.getContractCode());

		//根据备件id获取对应备件url(取值备件返回fileKey，fileKey为上传时原始url信息)
		attachCommonService.getFileKeyFromContractAttachList(projectOrderId, contractAttachList);
		attachCommonService.getFileKeyFromContractAttachList(projectOrderId, preContractAttachList);

		LOGGER.info("diff备件，上一份合同备件：{}", JSON.toJSONString(preContractAttachList));
		LOGGER.info("diff备件，当前合同备件：{}", JSON.toJSONString(contractAttachList));

		// 根据attachType分组diff备件
		Map<Byte, List<ContractAttach>> contractAttachMap = contractAttachList.stream().collect(Collectors.groupingBy(ContractAttach::getAttachType));
		Map<Byte, List<ContractAttach>> preContractAttachMap = preContractAttachList.stream().collect(Collectors.groupingBy(ContractAttach::getAttachType));
		for (AttachTypeEnum attachTypeEnum : AttachTypeEnum.values()) {
			Byte attachType = attachTypeEnum.getCode();
			// 两份合同都没有该类型的备件，不用diff
			if (!contractAttachMap.containsKey(attachType) && !preContractAttachMap.containsKey(attachType)) {
				continue;
			}

			// 新合同有该附件旧合同无该附件 或者 旧合同有该附件新合同无该附件，需要diff
			// 如果新增备件类型需要diff，buildAttachFieldDiffDTOV2List方法中getAttachFieldKey方法需要添加对应的key
			if ((contractAttachMap.containsKey(attachType) && !preContractAttachMap.containsKey(attachType))
				|| (!contractAttachMap.containsKey(attachType) && preContractAttachMap.containsKey(attachType))) {
				fieldDiffDTOV2List.addAll(buildAttachFieldDiffDTOV2List(contractAttachList, preContractAttachList, attachType));
				continue;
			}

			List<ContractAttach> contractAttaches = contractAttachMap.get(attachType);
			List<ContractAttach> preContractAttaches = preContractAttachMap.get(attachType);

			// 新旧合同都有该附件，但数量不一致，需要diff
			if (contractAttaches.size() != preContractAttaches.size()) {
				fieldDiffDTOV2List.addAll(buildAttachFieldDiffDTOV2List(contractAttachList, preContractAttachList, attachType));
				continue;
			}

			// 数量一致 需要具体看每个附件的链接是否有改动
			if (isChangeAttachList(contractAttaches, preContractAttaches)) {
				fieldDiffDTOV2List.addAll(buildAttachFieldDiffDTOV2List(contractAttachList, preContractAttachList, attachType));
			}
		}

		/**
		 * 备件排序
		 */
		List<FieldDiffDTOV2> sortedFeildDiffDTOV2List = new ArrayList<>();
		for (AttachTypeEnum attachTypeEnum : AttachTypeEnum.sortedAttachTypeList) {
			for (FieldDiffDTOV2 fieldDiffDTOVO : fieldDiffDTOV2List) {
				String attachFieldName = AttachTypeEnum.getAttachFieldNameByCode(attachTypeEnum.getCode());
				if (fieldDiffDTOVO.getFieldName().equals(attachFieldName)) {
					sortedFeildDiffDTOV2List.add(fieldDiffDTOVO);
				}
			}
		}
		return sortedFeildDiffDTOV2List;
	}

	/**
	 * 判断两份附件列表是否有变更（根据url区分）
	 *
	 * @param contractAttaches    当前合同附件列表
	 * @param preContractAttaches 历史合同附件列表
	 * @return true:有变更 false:无变更
	 */
	private boolean isChangeAttachList(List<ContractAttach> contractAttaches, List<ContractAttach> preContractAttaches) {
		// 都是sdk的方式上传备件
		if (contractAttaches.stream().anyMatch(attach -> StringUtils.isNotBlank(attach.getFileKey())) && preContractAttaches.stream().anyMatch(attach -> StringUtils.isNotBlank(attach.getFileKey()))) {
			contractAttaches.sort(Comparator.comparing(ContractAttach::getFileKey));
			preContractAttaches.sort(Comparator.comparing(ContractAttach::getFileKey));
			// 比较fileKey
			for (int i = 0; i < contractAttaches.size(); i++) {
				if (!Objects.equals(contractAttaches.get(i).getFileKey(), preContractAttaches.get(i).getFileKey())) {
					return true;
				}
			}
			return false;
		}

		contractAttaches.sort(Comparator.comparing(ContractAttach::getUrl));
		preContractAttaches.sort(Comparator.comparing(ContractAttach::getUrl));

		for (int i = 0; i < contractAttaches.size(); i++) {
			if (!Objects.equals(contractAttaches.get(i).getUrl(), preContractAttaches.get(i).getUrl())) {
				return true;
			}
		}

		return false;
	}

	private List<FieldDiffDTOV2> buildAttachFieldDiffDTOV2List(List<ContractAttach> contractAttachList, List<ContractAttach> preContractAttachList, Byte attachType) {
		List<FieldDiffDTOV2> feildDiffDTOV2List = new ArrayList<>();

		// 获取对应类型的附件
		List<FieldValueItemDTO> contractAttaches = contractAttachList.stream()
			.filter(contractAttach -> contractAttach.getAttachType().equals(attachType))
			.map(contractAttach -> FieldValueItemDTO.builder()
				.type(contractBusinessService.getAttachFileKey(contractAttach.getUrl()))
				.value(attachCommonService.getContractAttachImageUrl(contractAttach))
				.build())
			.collect(Collectors.toList());
		List<FieldValueItemDTO> preContractAttaches = preContractAttachList.stream()
			.filter(contractAttach -> contractAttach.getAttachType().equals(attachType))
			.map(contractAttach -> FieldValueItemDTO.builder()
				.type(contractBusinessService.getAttachFileKey(contractAttach.getUrl()))
				.value(attachCommonService.getContractAttachImageUrl(contractAttach))
				.build())
			.collect(Collectors.toList());

		String attachFieldKey = AttachTypeEnum.getAttachFieldKey(attachType);
		// 如果未配置相关字段，不需要diff
		if (StringUtils.isBlank(attachFieldKey)) {
			return feildDiffDTOV2List;
		}

		FieldDiffDTOV2 fieldDiffDTOV2 = FieldDiffDTOV2.builder()
			.fieldKey(attachFieldKey)
			.fieldName(AttachTypeEnum.getAttachFieldNameByCode(attachType))
			.oldValue(preContractAttaches)
			.newValue(contractAttaches)
			.build();
		feildDiffDTOV2List.add(fieldDiffDTOV2);
		return feildDiffDTOV2List;
	}

	/**
	 * 计算合同和上一份变更/正签和通之间的差异,计算完之后，结果会入表
	 *
	 * @param contractCode
	 * @return
	 */
	public List<ContractFieldChangeRecord> calculateDiff(String contractCode) {
		Contract currentContract = contractService.getByContractCode(contractCode);
		Contract prevContract = contractService.getChangePrevEffectContract(currentContract.getId(), currentContract.getProjectOrderId());
		if (Objects.isNull(prevContract)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "计算补充协议差异内容失败，缺少上一份有效的正签/变更");
		}
		FormalContractExpandInfoDTO currentDetail = getContractDetail(currentContract, Boolean.TRUE);
		FormalContractExpandInfoDTO prevDetail = getContractDetail(prevContract, Boolean.FALSE);

		contractFieldChangeRecordService.deleteByContractCode(contractCode, false);
		List<FieldDiffDTO> fieldDiffDTOList = compareContract(prevDetail, currentDetail, currentContract.getProjectOrderId(), currentContract.getBusinessType(), currentContract.getChangeOrderId());
		List<ContractFieldChangeRecord> changeRecordList = fieldDiffDTOList.stream().map(
			fieldDiffDTO -> ContractFieldChangeRecord.builder()
				.contractCode(contractCode)
				.fieldKey(fieldDiffDTO.getFieldKey())
				.fieldName(fieldDiffDTO.getFieldName())
				.oldValue(Objects.isNull(fieldDiffDTO.getOldValue()) ? "" : fieldDiffDTO.getOldValue())
				.newValue(Objects.isNull(fieldDiffDTO.getNewValue()) ? "" : fieldDiffDTO.getNewValue())
				.delStatus(CommonEnum.NO.getCode())
				.ctime(new Date())
				.mtime(new Date())
				.build()
		).collect(Collectors.toList());

		if (CollectionUtils.isNotEmpty(changeRecordList)) {
			// 调整一下顺序，甲供材料放在税率后面
			// taxRate的位置
			int taxRateIndex = -1;
			// materialList的位置
			int materialListIndex = -1;
			for (int i = 0; i < changeRecordList.size(); i++) {
				if ("taxRate".equals(changeRecordList.get(i).getFieldKey())) {
					taxRateIndex = i;
				} else if ("materialList".equals(changeRecordList.get(i).getFieldKey())) {
					materialListIndex = i;
				}
			}

			if (taxRateIndex != -1 && materialListIndex != -1) {
				ContractFieldChangeRecord materialListRecord = changeRecordList.remove(materialListIndex);
				changeRecordList.add(taxRateIndex + 1, materialListRecord);
			}
			contractFieldChangeRecordService.insertBatch(changeRecordList);
		}
		return changeRecordList;
	}

	/**
	 * 根据请求参数计算合同和上一份变更/正签合同之间的差异
	 *
	 * @return
	 */
	public List<ContractFieldChangeRecord> calculateDiffByReq() {
		// 请求参数
		ContractReqDTO contractReq = ContractContextHandler.getContractReq();
		String changeOrderId = contractReq.getContractBaseInfo().getChangeOrderId();
		String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();

		// 查询上一份有效的正签/变更合同
		Contract prevContract = contractService.getChangePrevEffectContractByPid(projectOrderId);
		if (Objects.isNull(prevContract)) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "计算补充协议差异内容失败，缺少上一份有效的正签/变更", Level.WARN);
		}

		FormalContractExpandInfoDTO currentDetail = getContractDetailByReq(contractReq);
		FormalContractExpandInfoDTO prevDetail = getContractDetail(prevContract, Boolean.FALSE);

		List<FieldDiffDTO> fieldDiffDTOList = compareContract(prevDetail, currentDetail, projectOrderId, BusinessTypeEnum.HOUSE_CERTIFICATE.getCode(), changeOrderId);
		return fieldDiffDTOList.stream().map(
			fieldDiffDTO -> ContractFieldChangeRecord.builder()
				.fieldKey(fieldDiffDTO.getFieldKey())
				.fieldName(fieldDiffDTO.getFieldName())
				.oldValue(Objects.isNull(fieldDiffDTO.getOldValue()) ? "" : fieldDiffDTO.getOldValue())
				.newValue(Objects.isNull(fieldDiffDTO.getNewValue()) ? "" : fieldDiffDTO.getNewValue())
				.delStatus(CommonEnum.NO.getCode())
				.ctime(new Date())
				.mtime(new Date())
				.build()
		).collect(Collectors.toList());
	}

	/**
	 * 获取合同明细信息(需要对比的)
	 *
	 * @param contract
	 * @return
	 */
	private FormalContractExpandInfoDTO getContractDetail(Contract contract, Boolean isCurrentShow) {
		FormalContractExpandInfoDTO infoDTO = new FormalContractExpandInfoDTO();
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType());
		//字段
		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contract.getContractCode());
		Map<String, String> fieldsMap = contractFieldList.stream().collect(Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue, (v1, v2) -> v2));
		//用户
		List<ContractUser> contractUserList = contractUserService.getListByContractCode(contract.getContractCode());
		Map<Byte, ContractUser> userMap = contractUserList.stream().collect(Collectors.toMap(ContractUser::getRoleType, Function.identity(), (v1, v2) -> v2));
		ContractUser owner = userMap.getOrDefault(RoleTypeEnum.OWNER.getCode(), null);
		ContractUser agent = userMap.getOrDefault(RoleTypeEnum.AGENT.getCode(), null);
		ContractUser companyAgent = userMap.getOrDefault(RoleTypeEnum.COMPANY_AGENT.getCode(), null);
		ContractUser legal = userMap.getOrDefault(RoleTypeEnum.LEGAL.getCode(), null);
		if (legal != null && IsSignEnum.YES.getCode().equals(legal.getIsSign())) {
			companyAgent = null;
		}
		//甲供材料
		List<ContractMaterial> contractMaterialList = contractMaterialService.getListByContractCode(contract.getContractCode());
		//线下合同
		List<ContractAttach> offlineContract = contractAttachService.getListByContractCode(contract.getContractCode(),
			AttachTypeEnum.OFFLINE_CONTRACT.getCode());

		//1.签约主体
		infoDTO.setContractObjectType(Byte.parseByte(fieldsMap.getOrDefault("contractObjectType", "0")));
		infoDTO.setSignChannelType(contract.getSignChannelType());

		//2.客户信息
		if (Objects.nonNull(owner)) {
			infoDTO.setOwnerName(owner.getName());
			infoDTO.setOwnerPhone(owner.getPhone());
			infoDTO.setOwnerCertificateType(owner.getCertificateType());
			infoDTO.setOwnerCertificateNo(owner.getCertificateNo());
		}
		infoDTO.setOwnerAddress(fieldsMap.getOrDefault("ownerAddress", ""));

		//3.代理人信息
		infoDTO.setHasAgent(Byte.parseByte(fieldsMap.getOrDefault("haveAgent", "0")));
		if (Objects.nonNull(agent)) {
			infoDTO.setAgentName(agent.getName());
			infoDTO.setAgentPhone(agent.getPhone());
			infoDTO.setAgentCertificateType(agent.getCertificateType());
			infoDTO.setAgentCertificateNo(agent.getCertificateNo());
		}

		//4.公司信息
		infoDTO.setCompanyName(fieldsMap.getOrDefault("companyName", ""));
		infoDTO.setCompanyCreditCode(fieldsMap.getOrDefault("companyCreditCode", ""));
		infoDTO.setRegisteredAddress(fieldsMap.getOrDefault("registeredAddress", ""));
		if (Objects.nonNull(companyAgent)) {
			infoDTO.setCompanyAgentName(companyAgent.getName());
			infoDTO.setCompanyAgentPhone(companyAgent.getPhone());
			infoDTO.setCompanyAgentCertificateType(companyAgent.getCertificateType());
			infoDTO.setCompanyAgentCertificateNo(companyAgent.getCertificateNo());
		}

		//法人信息
		Byte signRole = Byte.parseByte(fieldsMap.getOrDefault("signRole", "0"));
		if (signRole.equals(RoleTypeEnum.OWNER.getCode()) || signRole.equals(RoleTypeEnum.AGENT.getCode())) {
			//如果签约人角色是业主或者代理人，无需diff展示
			signRole = null;
		}
		infoDTO.setSignRole(signRole);
		if (Objects.nonNull(legal)) {
			infoDTO.setLegalName(legal.getName());
			infoDTO.setLegalPhone(legal.getPhone());
			infoDTO.setLegalCertificateType(legal.getCertificateType());
			infoDTO.setLegalCertificateNo(legal.getCertificateNo());
		}

		//5.户型结构
		infoDTO.setParlorCnt(Integer.parseInt(fieldsMap.getOrDefault("parlorCnt", "0")));
		infoDTO.setRoomCnt(Integer.parseInt(fieldsMap.getOrDefault("roomCnt", "0")));
		infoDTO.setCookroomCnt(Integer.parseInt(fieldsMap.getOrDefault("cookroomCnt", "0")));
		infoDTO.setToiletCnt(Integer.parseInt(fieldsMap.getOrDefault("toiletCnt", "0")));
		infoDTO.setBalconyCnt(Integer.parseInt(fieldsMap.getOrDefault("balconyCnt", "0")));
		infoDTO.setStorageCnt(Integer.parseInt(fieldsMap.getOrDefault("storageCnt", "0")));
		infoDTO.setArea(fieldsMap.getOrDefault("area", ""));
		infoDTO.setInsideArea(fieldsMap.getOrDefault("insideArea", ""));
		infoDTO.setStructure(Integer.parseInt(fieldsMap.getOrDefault("structure", "0")));
		infoDTO.setCertificateAddress(isCurrentShow ? getCertificateAddress(fieldsMap) : fieldsMap.getOrDefault("certificateAddress", getCertificateAddress(fieldsMap)));

		//6.其他相关
		infoDTO.setProjectContractModeCode(Integer.parseInt(fieldsMap.getOrDefault("projectContractModeCode", "0")));
		infoDTO.setProjectContractModeName(fieldsMap.getOrDefault("projectContractModeName", ""));
		infoDTO.setPartRoomRange(fieldsMap.getOrDefault("partRoomRange", ""));
		infoDTO.setTaxRate(Integer.parseInt(fieldsMap.getOrDefault("taxRate", "0")));
		infoDTO.setDisputeDealMode(Integer.parseInt(fieldsMap.getOrDefault("disputeDealMode", "0")));
		infoDTO.setWaterProofGuaranteeYearEnum(Integer.parseInt(fieldsMap.getOrDefault("waterProofGuaranteeYearEnum", "0")));
		infoDTO.setOtherGuaranteeYearEnum(Integer.parseInt(fieldsMap.getOrDefault("otherGuaranteeYearEnum", "0")));
		infoDTO.setBeforeDeliveryDaysToWork(Integer.parseInt(fieldsMap.getOrDefault("beforeDeliveryDaysToWork", "0")));
		infoDTO.setTotalDurationEnum(Integer.parseInt(fieldsMap.getOrDefault("totalDurationEnum", "0")));
		infoDTO.setWaterElectricGuaranteeYear(Integer.parseInt(fieldsMap.getOrDefault("waterElectricGuaranteeYear", "0")));
		infoDTO.setWaterProofGuaranteeYear(Integer.parseInt(fieldsMap.getOrDefault("waterProofGuaranteeYear", "0")));
		infoDTO.setOtherGuaranteeYear(Integer.parseInt(fieldsMap.getOrDefault("otherGuaranteeYear", "0")));

		//9.设计费
		Integer needDesignerAmount = Integer.valueOf(fieldsMap.getOrDefault("needDesignerAmount", "0"));
		if (needDesignerAmount.equals(CommonEnum.YES.getCode().intValue())) {
			infoDTO.setAfterDiscountDesignerAmount(new BigDecimal(fieldsMap.getOrDefault("afterDiscountDesignerAmount", "0")));
			infoDTO.setPreDiscountDesignerAmount(new BigDecimal(fieldsMap.getOrDefault("preDiscountDesignerAmount", "0")));
		}

		//8.甲供材料清单
		List<MaterialItemVo> materialItemVoList = new LinkedList<>();
		for (ContractMaterial contractMaterial : contractMaterialList) {
			materialItemVoList.add(MaterialItemVo.builder()
				.count(contractMaterial.getCount())
				.description(contractMaterial.getDescription())
				.unit(contractMaterial.getUnit())
				.value(contractMaterial.getValue())
				.build());
		}
		infoDTO.setMaterialList(materialItemVoList);


		infoDTO.setPlanStartTime(fieldsMap.getOrDefault("planStartTime", "0"));
		//非2.5变更需比较报价金额、优惠金额
		if (!processV25) {
			//报价
			PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(contract.getProjectOrderId(), contract.getChangeOrderId());
			infoDTO.setContractAmount(planAllDTO.getPlanInfo().getContractPriceTotal());
			//仅2.0使用
			infoDTO.setComboCode(planAllDTO.getPlanInfo().getComboCode());
			infoDTO.setComboName(planAllDTO.getPlanInfo().getComboName());
			BigDecimal discountAmount = null;
			for (CouponDTO couponDTO : planAllDTO.getCouponList()) {
				if (CouponTypeEnum.DIRECT_COUPON.getCode().equals(couponDTO.getCouponType())) {
					discountAmount = couponDTO.getLapseAmount();
					break;
				}
			}
			infoDTO.setDiscountAmount(discountAmount);


		}

//		if(contractUnifyService.getModuleKeyList(contract.getProjectOrderId(), contract.getType()).contains(ContractModuleEnum.COLLECTION_PLAN_CONFIG_INFO.getKey())){
//			//收款计划,配置包含收款计划模块
//			infoDTO.setCollectionPlanConfigInfo(commonContractService.queryCollectionPlanByContract(contract));
//		}
		//2.5整装使用
		if (!BusinessTypeEnum.GROUP_DECORATE.getCode().equals(contract.getBusinessType())) {
			infoDTO.setUserSignType(Byte.parseByte(fieldsMap.getOrDefault("userSignType", "0")));
			//线下合同
			infoDTO.setAttachUrl(offlineContract.stream().map(item -> File.builder().url(item.getUrl()).build()).collect(Collectors.toList()));
			if (SignChannelTypeEnum.OFFLINE.getCode().equals(infoDTO.getSignChannelType())) {
				infoDTO.setAttachFileType(fieldsMap.getOrDefault("attachFileType", ""));
				//线下合同用户签署方式变更diff统一设置为未知
				infoDTO.setUserSignType(UserSignTypeEnum.DEFAULT.getCode());
			}
			infoDTO.setUserSignTime(fieldsMap.getOrDefault("userSignTime", ""));
			infoDTO.setCompanySignTime(fieldsMap.getOrDefault("companySignTime", ""));

			//相关备件字段
			String agentSign = fieldsMap.getOrDefault("agentSign", "");
			infoDTO.setAgentSign(StringUtils.isBlank(agentSign) ? null : Byte.parseByte(agentSign));
		}

		return infoDTO;
	}

