public void checkChangeOrder(ContractReqDTO contractReq) {
	String changeOrderId = contractReq.getContractBaseInfo().getChangeOrderId();
	if (org.apache.commons.lang3.StringUtils.isBlank(changeOrderId)) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "变更单号不可为空");
	}
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getContractBaseInfo().getContractType());
	if (processV25) {
		//todo 合并发起模式下：请求中控变更来校验
		return;
	}
	ChangeOrderBaseInfoDTO changeOrderBaseInfoDTO = changeOrderService.getByChangeOrderId(changeOrderId);
	if (!ChangeOrderStatusEnum.CONTRACT_CHANGING.getCode().equals(changeOrderBaseInfoDTO.getStatus().getCode())) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "变更单状态不是合同变更中,请刷新页面重试", Level.WARN);
	}
}

public void checkChangeContract(String projectOrderId, String changeOrderId) {
	List<Contract> contractList = contractService.getChangeContractList(projectOrderId, changeOrderId, ContractStatusEnum.allValidStatus);
	if (org.springframework.util.CollectionUtils.isEmpty(contractList)) {
		return;
	}
	CompletionBillInfoResp completionBillInfoResp = octopusRpc.allowFundChange(projectOrderId);
	if (!completionBillInfoResp.getCanChange()) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), completionBillInfoResp.getMessage(), Level.WARN);
	}
	// 过滤只校验变更合同
	contractList = contractList.stream()
		.filter(contract -> ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType()))
		.collect(Collectors.toList());

	if (contractList.size() > 1) {
		LOGGER.warn("该变更已有在途合同,projectOrderId:{},changeOrderId:{}", projectOrderId, changeOrderId);
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "该变更已有在途合同,不可重复创建", Level.WARN);
	}

	//2.5场景下，同一个变更单如果变更合同已经提交，不允许再次提交生成新的B变更协议
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, ContractTypeEnum.PACKAGE_CHANGE.getCode());
	if (processV25) {
		List<Contract> submitContractList = contractList.stream()
			.filter(contract -> !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()) && !ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus()))
			.collect(Collectors.toList());
		if (CollectionUtils.isNotEmpty(submitContractList)) {
			LOGGER.warn("该变更已有提交后的合同，不可重复创建,projectOrderId:{},changeOrderId:{}", projectOrderId, changeOrderId);
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "该变更已有提交后的合同，不可重复创建", Level.WARN);
		}
	}
}

