public List<FieldDiffDTOV2> buildQuotationModelDiff(String projectOrderId, String contractCode, Byte contractType, String changeOrderId, Byte businessType) {
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType);
	if (processV25) {
		return buildAtomChangeQuotationPdfDiff(projectOrderId, changeOrderId, contractCode);
	}
	boolean isChangePrice = changeContractService.changePriceScope(changeOrderId);
	//报价模块
	String filePrevUrl = "";
	String internalConfigurationsFilePrevUrl = "";
	List<FieldDiffDTOV2> feildDiffDTOV2List = new ArrayList<>();
	if (isChangePrice) {
		PlanAllDTO planAllDTO = quotationFeignService.querySnapshotPlan(projectOrderId, changeOrderId);
		if (CollectionUtils.isNotEmpty(planAllDTO.getPlanAttachmentList())) {
			for (PlanAttachmentDTO planAttachmentDTO : planAllDTO.getPlanAttachmentList()) {
				FieldDiffDTOV2 fieldDiffDTOV2 = FieldDiffDTOV2.builder()
					.oldValue(null)
					.newValue(Collections.singletonList(FieldValueItemDTO.builder()
						.type(FileTypeEnum.PDF.getKey())
						.value(planAttachmentDTO.getPrevUrl())
						.build()))
					.build();
				switch (planAttachmentDTO.getFileType()) {
					case PlanAttachment.报价单:
						filePrevUrl = planAttachmentDTO.getPrevUrl();
						fieldDiffDTOV2.setFieldName("报价单");
						fieldDiffDTOV2.setFieldKey("fileUrl");
						feildDiffDTOV2List.add(fieldDiffDTOV2);
						break;
					case PlanAttachment.套餐套内配置清单:
						internalConfigurationsFilePrevUrl = planAttachmentDTO.getPrevUrl();
						fieldDiffDTOV2.setFieldName("套内配置清单");
						fieldDiffDTOV2.setFieldKey("internalConfigurationsFileUrl");
						feildDiffDTOV2List.add(fieldDiffDTOV2);
						break;
					case PlanAttachment.加载配置清单:
						fieldDiffDTOV2.setFieldName("加载配置清单");
						fieldDiffDTOV2.setFieldKey("extraConfigurationsFileUrl");
						feildDiffDTOV2List.add(fieldDiffDTOV2);
						break;
					case PlanAttachment.套外个性化报价单:
						fieldDiffDTOV2.setFieldName("个性化报价单");
						fieldDiffDTOV2.setFieldKey("personalQuotionFileUrl");
						feildDiffDTOV2List.add(fieldDiffDTOV2);
						break;
					case PlanAttachment.基础图纸:
						fieldDiffDTOV2.setFieldName("基础图纸");
						fieldDiffDTOV2.setFieldKey("baseConstructionDrawFileUrl");
						feildDiffDTOV2List.add(fieldDiffDTOV2);
						break;
					default:
				}
			}
		}
		if (org.apache.commons.lang3.StringUtils.isBlank(internalConfigurationsFilePrevUrl)) {
			//兼容团装历史数据
			if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
				internalConfigurationsFilePrevUrl = filePrevUrl;
				FieldDiffDTOV2 fieldDiffDTOV2 = FieldDiffDTOV2.builder()
					.fieldKey("internalConfigurationsFileUrl")
					.fieldName("套内配置清单")
					.oldValue(null)
					.newValue(Collections.singletonList(FieldValueItemDTO.builder()
						.type(FileTypeEnum.PDF.getKey())
						.value(internalConfigurationsFilePrevUrl)
						.build()))
					.build();
				feildDiffDTOV2List = Collections.singletonList(fieldDiffDTOV2);
			}
		}
	}
	return feildDiffDTOV2List;
}

public QuoteChangeDiffBO getQuoteBillDiff(String projectOrderId, String changeOrderId) {
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
	Byte businessType = commonContractService.getBusinessType(projectInfoDTO);

	QuoteChangePreviewDTO preQuoteBill = null;
	QuoteChangePreviewDTO quoteBill = null;
	if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
		QuoteChangeDiffBO quoteBillDiff = buildQuoteChangeDiffBo(projectOrderId, changeOrderId);
		preQuoteBill = quoteBillDiff.getPreQuoteBill();
		quoteBill = quoteBillDiff.getQuoteBill();
	} else {
		LOGGER.info("变更信息并发请求开始，{}", changeOrderId);
		ParallelTasksContext parallelTasksContext = parallelTaskService.newParallelTasks();

		BudgeQuoteBill budgeQuoteBill = new BudgeQuoteBill();
		parallelTaskService.addNewTask(parallelTasksContext, () -> {
			getPreQuoteBill(budgeQuoteBill, projectOrderId, changeOrderId);
		});
		parallelTaskService.addNewTask(parallelTasksContext, () -> {
			getNewQuoteBill(budgeQuoteBill, changeOrderId);
		});
		parallelTaskService.execTasks(parallelTasksContext);
		parallelTaskService.awaitTasksResult(parallelTasksContext);
		LOGGER.info("变更信息并发请求结束，{}", changeOrderId);
		BudgetBillDTO.BudgetPreviewDTO preBudgetPreview = budgeQuoteBill.getPreQuoteBill();
		BudgetBillDTO.BudgetPreviewDTO quoteBudgetPreview = budgeQuoteBill.getQuoteBill();

		Integer preHouseType = Optional.ofNullable(preBudgetPreview.getPreviewBaseInfo()).map(BudgetBillDTO.PreviewBaseInfo::getOrderHouse).map(BudgetBillDTO.OrderHouseDTO::getHouseType).orElse(null);
		String preHouseTypeDesc = Optional.ofNullable(preBudgetPreview.getPreviewBaseInfo()).map(BudgetBillDTO.PreviewBaseInfo::getOrderHouse).map(BudgetBillDTO.OrderHouseDTO::getHouseTypeDesc).orElse(null);
		String preReconstructionHouseLayoutDesc = Optional.ofNullable(preBudgetPreview.getPreviewBaseInfo()).map(BudgetBillDTO.PreviewBaseInfo::getOrderHouse).map(BudgetBillDTO.OrderHouseDTO::getReconstructionHouseLayoutDesc).orElse(null);
		preQuoteBill = QuoteChangePreviewDTO.builder()
			.comboCodeList(Collections.singletonList(preBudgetPreview.getPreviewBaseInfo().getComboCode()))
			.comboNameList(Collections.singletonList(preBudgetPreview.getPreviewBaseInfo().getComboName()))
			.pricingAreaList(Collections.singletonList(preBudgetPreview.getPreviewBaseInfo().getPricingArea()))
			.hardTotalPriceAfterCoupon(preBudgetPreview.getBudgetBillPriceDTO().getPlanTotalPriceAfterCoupon())
			.houseType(preHouseType)
			.houseTypeDesc(preHouseTypeDesc)
			.reconstructionHouseLayoutDesc(preReconstructionHouseLayoutDesc)
			.remark(preBudgetPreview.getPreviewBaseInfo().getRemark())
			.build();

		if (quoteBudgetPreview != null) {
			Integer quoteHouseType = Optional.ofNullable(quoteBudgetPreview.getPreviewBaseInfo()).map(BudgetBillDTO.PreviewBaseInfo::getOrderHouse).map(BudgetBillDTO.OrderHouseDTO::getHouseType).orElse(null);
			String quoteHouseTypeDesc = Optional.ofNullable(quoteBudgetPreview.getPreviewBaseInfo()).map(BudgetBillDTO.PreviewBaseInfo::getOrderHouse).map(BudgetBillDTO.OrderHouseDTO::getHouseTypeDesc).orElse(null);
			String quoteReconstructionHouseLayoutDesc = Optional.ofNullable(quoteBudgetPreview.getPreviewBaseInfo()).map(BudgetBillDTO.PreviewBaseInfo::getOrderHouse).map(BudgetBillDTO.OrderHouseDTO::getReconstructionHouseLayoutDesc).orElse(null);
			quoteBill = QuoteChangePreviewDTO.builder()
				.comboCodeList(Collections.singletonList(quoteBudgetPreview.getPreviewBaseInfo().getComboCode()))
				.comboNameList(Collections.singletonList(quoteBudgetPreview.getPreviewBaseInfo().getComboName()))
				.pricingAreaList(Collections.singletonList(quoteBudgetPreview.getPreviewBaseInfo().getPricingArea()))
				.hardTotalPriceAfterCoupon(quoteBudgetPreview.getBudgetBillPriceDTO().getPlanTotalPriceAfterCoupon())
				.houseType(quoteHouseType)
				.houseTypeDesc(quoteHouseTypeDesc)
				.reconstructionHouseLayoutDesc(quoteReconstructionHouseLayoutDesc)
				.remark(quoteBudgetPreview.getPreviewBaseInfo().getRemark())
				.build();
		}
	}

	if (preQuoteBill == null) {
		throw new NrsBusinessException("获取报价信息失败");
	}

	return QuoteChangeDiffBO.builder()
		.preQuoteBill(preQuoteBill)
		.quoteBill(quoteBill)
		.build();
}

public QuoteChangeDiffBO buildQuoteChangeDiffBo(String projectOrderId, String changeOrderId) {
	Map<String, Map<String, String>> moduleParams = new HashMap<>();
	Map<String, String> params = new HashMap<>();
	params.put(HomeModelSupportParamEnum.projectChangeNo.name(), changeOrderId);
	moduleParams.put(HomeModelDefEnum.COST_CONTROL_BUDGET_STANDARD_CHANGE_COMBO.name(), params);
	moduleParams.put(HomeModelDefEnum.COST_CONTROL_CHANGE_PLAN_PRICE.name(), params);
	moduleParams.put(HomeModelDefEnum.COST_CONTROL_CHANGE_RENOVATE_HOUSE.name(), params);
	HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(projectOrderId, moduleParams);

	MainOrderModel.CostControl costControl = Optional.ofNullable(homeProject)
		.map(HomeProject::getMainOrder)
		.map(MainOrder::getCostControl).orElseThrow(() -> new NrsBusinessException("获取变更报价信息失败"));

	BudgetStandardChangeComboModule budgetStandardChangeComboModule = costControl.getBudgetStandardChangeComboModule();
	ChangePlanPriceModule changePlanPriceModule = costControl.getChangePlanPriceModule();
	ChangeRenovateHouseModule changeRenovateHouseModule = costControl.getChangeRenovateHouseModule();

	QuoteChangePreviewDTO preQuoteBill = new QuoteChangePreviewDTO();

	preQuoteBill.setComboCodeList(budgetStandardChangeComboModule.getBeforeChangeComboList().stream().filter(comboDTO -> comboDTO.getComboType().equals(PreviewContractTypeEnum.B合同.getCode()))
		.map(com.ke.utopia.nrs.home.model.protocol.base.dto.costcontrol.quotation.ComboDTO::getComboCode).collect(Collectors.toList()));
	preQuoteBill.setComboNameList(budgetStandardChangeComboModule.getBeforeChangeComboList().stream().filter(comboDTO -> comboDTO.getComboType().equals(PreviewContractTypeEnum.B合同.getCode()))
		.map(com.ke.utopia.nrs.home.model.protocol.base.dto.costcontrol.quotation.ComboDTO::getComboName).collect(Collectors.toList()));
	preQuoteBill.setPricingAreaList(budgetStandardChangeComboModule.getBeforeChangeComboList().stream().filter(comboDTO -> comboDTO.getComboType().equals(PreviewContractTypeEnum.B合同.getCode()))
		.map(com.ke.utopia.nrs.home.model.protocol.base.dto.costcontrol.quotation.ComboDTO::getPricingArea).collect(Collectors.toList()));
	com.ke.utopia.nrs.home.model.protocol.base.dto.costcontrol.quotation.HouseDTO beforeHouse = changeRenovateHouseModule.getBeforeHouse();
	preQuoteBill.setHouseType(beforeHouse.getHouseType());
	preQuoteBill.setHouseTypeDesc(HouseTypeEnum.getDescByCode(beforeHouse.getHouseType()));
	preQuoteBill.setReconstructionHouseLayoutDesc(beforeHouse.getReconstructionHouseLayoutDesc());
	com.ke.utopia.nrs.home.model.protocol.base.dto.costcontrol.quotation.PriceDTO beforeChangePrice = changePlanPriceModule.getBeforeChangePrice();
	preQuoteBill.setHardTotalPriceAfterCoupon(beforeChangePrice.getHardTotalPriceAfterCoupon());
	preQuoteBill.setPersonalTotalPriceAfterCoupon(beforeChangePrice.getPersonalTotalPriceAfterCoupon());

	QuoteChangePreviewDTO quoteBill = new QuoteChangePreviewDTO();
	quoteBill.setComboCodeList(budgetStandardChangeComboModule.getAfterChangeComboList().stream().filter(comboDTO -> comboDTO.getComboType().equals(PreviewContractTypeEnum.B合同.getCode()))
		.map(com.ke.utopia.nrs.home.model.protocol.base.dto.costcontrol.quotation.ComboDTO::getComboCode).collect(Collectors.toList()));
	quoteBill.setComboNameList(budgetStandardChangeComboModule.getAfterChangeComboList().stream().filter(comboDTO -> comboDTO.getComboType().equals(PreviewContractTypeEnum.B合同.getCode()))
		.map(com.ke.utopia.nrs.home.model.protocol.base.dto.costcontrol.quotation.ComboDTO::getComboName).collect(Collectors.toList()));
	quoteBill.setPricingAreaList(budgetStandardChangeComboModule.getAfterChangeComboList().stream().filter(comboDTO -> comboDTO.getComboType().equals(PreviewContractTypeEnum.B合同.getCode()))
		.map(com.ke.utopia.nrs.home.model.protocol.base.dto.costcontrol.quotation.ComboDTO::getPricingArea).collect(Collectors.toList()));
	HouseDTO afterHouse = changeRenovateHouseModule.getAfterHouse();
	quoteBill.setHouseType(afterHouse.getHouseType());
	quoteBill.setHouseTypeDesc(HouseTypeEnum.getDescByCode(afterHouse.getHouseType()));
	quoteBill.setReconstructionHouseLayoutDesc(afterHouse.getReconstructionHouseLayoutDesc());
