}

public List<FieldDiffDTOV2> buildAttachModelDiff(String projectOrderId, String contractCode, Byte businessType) {
	List<FieldDiffDTOV2> fieldDiffDTOV2List = new ArrayList<>();
	// 当前合同备件
	List<ContractAttach> contractAttachList = contractAttachService.getListCompatibleByContractCode(contractCode);
	Contract currentContract = contractService.getByContractCode(contractCode);
	// 上一份合同备件
	Contract preContract = contractService.getChangePrevEffectContract(currentContract.getId(), projectOrderId);
	List<ContractAttach> preContractAttachList = contractAttachService.getListCompatibleByContractCode(preContract.getContractCode());

	//根据备件id获取对应备件url(取值备件返回fileKey，fileKey为上传时原始url信息)
	attachCommonService.getFileKeyFromContractAttachList(projectOrderId, contractAttachList);
	attachCommonService.getFileKeyFromContractAttachList(projectOrderId, preContractAttachList);

	LOGGER.info("diff备件，上一份合同备件：{}", JSON.toJSONString(preContractAttachList));
	LOGGER.info("diff备件，当前合同备件：{}", JSON.toJSONString(contractAttachList));

	// 根据attachType分组diff备件
	Map<Byte, List<ContractAttach>> contractAttachMap = contractAttachList.stream().collect(Collectors.groupingBy(ContractAttach::getAttachType));
	Map<Byte, List<ContractAttach>> preContractAttachMap = preContractAttachList.stream().collect(Collectors.groupingBy(ContractAttach::getAttachType));
	for (AttachTypeEnum attachTypeEnum : AttachTypeEnum.values()) {
		Byte attachType = attachTypeEnum.getCode();
		// 两份合同都没有该类型的备件，不用diff
		if (!contractAttachMap.containsKey(attachType) && !preContractAttachMap.containsKey(attachType)) {
			continue;
		}

		// 新合同有该附件旧合同无该附件 或者 旧合同有该附件新合同无该附件，需要diff
		// 如果新增备件类型需要diff，buildAttachFieldDiffDTOV2List方法中getAttachFieldKey方法需要添加对应的key
		if ((contractAttachMap.containsKey(attachType) && !preContractAttachMap.containsKey(attachType))
			|| (!contractAttachMap.containsKey(attachType) && preContractAttachMap.containsKey(attachType))) {
			fieldDiffDTOV2List.addAll(buildAttachFieldDiffDTOV2List(contractAttachList, preContractAttachList, attachType));
			continue;
		}

		List<ContractAttach> contractAttaches = contractAttachMap.get(attachType);
		List<ContractAttach> preContractAttaches = preContractAttachMap.get(attachType);

		// 新旧合同都有该附件，但数量不一致，需要diff
		if (contractAttaches.size() != preContractAttaches.size()) {
			fieldDiffDTOV2List.addAll(buildAttachFieldDiffDTOV2List(contractAttachList, preContractAttachList, attachType));
			continue;
		}

		// 数量一致 需要具体看每个附件的链接是否有改动
		if (isChangeAttachList(contractAttaches, preContractAttaches)) {
			fieldDiffDTOV2List.addAll(buildAttachFieldDiffDTOV2List(contractAttachList, preContractAttachList, attachType));
		}
	}

	/**
	 * 备件排序
	 */
	List<FieldDiffDTOV2> sortedFeildDiffDTOV2List = new ArrayList<>();
	for (AttachTypeEnum attachTypeEnum : AttachTypeEnum.sortedAttachTypeList) {
		for (FieldDiffDTOV2 fieldDiffDTOVO : fieldDiffDTOV2List) {
			String attachFieldName = AttachTypeEnum.getAttachFieldNameByCode(attachTypeEnum.getCode());
			if (fieldDiffDTOVO.getFieldName().equals(attachFieldName)) {
				sortedFeildDiffDTOV2List.add(fieldDiffDTOVO);
			}
		}
	}
	return sortedFeildDiffDTOV2List;
}

private boolean isChangeAttachList(List<ContractAttach> contractAttaches, List<ContractAttach> preContractAttaches) {
	// 都是sdk的方式上传备件
	if (contractAttaches.stream().anyMatch(attach -> StringUtils.isNotBlank(attach.getFileKey())) && preContractAttaches.stream().anyMatch(attach -> StringUtils.isNotBlank(attach.getFileKey()))) {
		contractAttaches.sort(Comparator.comparing(ContractAttach::getFileKey));
		preContractAttaches.sort(Comparator.comparing(ContractAttach::getFileKey));
		// 比较fileKey
		for (int i = 0; i < contractAttaches.size(); i++) {
			if (!Objects.equals(contractAttaches.get(i).getFileKey(), preContractAttaches.get(i).getFileKey())) {
				return true;
			}
		}
		return false;
	}

	contractAttaches.sort(Comparator.comparing(ContractAttach::getUrl));
	preContractAttaches.sort(Comparator.comparing(ContractAttach::getUrl));

	for (int i = 0; i < contractAttaches.size(); i++) {
		if (!Objects.equals(contractAttaches.get(i).getUrl(), preContractAttaches.get(i).getUrl())) {
			return true;
		}
	}

	return false;
}

private List<FieldDiffDTOV2> buildAttachFieldDiffDTOV2List(List<ContractAttach> contractAttachList, List<ContractAttach> preContractAttachList, Byte attachType) {
	List<FieldDiffDTOV2> feildDiffDTOV2List = new ArrayList<>();

	// 获取对应类型的附件
	List<FieldValueItemDTO> contractAttaches = contractAttachList.stream()
		.filter(contractAttach -> contractAttach.getAttachType().equals(attachType))
		.map(contractAttach -> FieldValueItemDTO.builder()
			.type(contractBusinessService.getAttachFileKey(contractAttach.getUrl()))
			.value(attachCommonService.getContractAttachImageUrl(contractAttach))
			.build())
		.collect(Collectors.toList());
	List<FieldValueItemDTO> preContractAttaches = preContractAttachList.stream()
		.filter(contractAttach -> contractAttach.getAttachType().equals(attachType))
		.map(contractAttach -> FieldValueItemDTO.builder()
			.type(contractBusinessService.getAttachFileKey(contractAttach.getUrl()))
			.value(attachCommonService.getContractAttachImageUrl(contractAttach))
			.build())
		.collect(Collectors.toList());

	String attachFieldKey = AttachTypeEnum.getAttachFieldKey(attachType);
	// 如果未配置相关字段，不需要diff
	if (StringUtils.isBlank(attachFieldKey)) {
		return feildDiffDTOV2List;
	}

	FieldDiffDTOV2 fieldDiffDTOV2 = FieldDiffDTOV2.builder()
		.fieldKey(attachFieldKey)
		.fieldName(AttachTypeEnum.getAttachFieldNameByCode(attachType))
		.oldValue(preContractAttaches)
		.newValue(contractAttaches)
		.build();
	feildDiffDTOV2List.add(fieldDiffDTOV2);
	return feildDiffDTOV2List;
}

public List<ContractFieldChangeRecord> calculateDiff(String contractCode) {
	Contract currentContract = contractService.getByContractCode(contractCode);
	Contract prevContract = contractService.getChangePrevEffectContract(currentContract.getId(), currentContract.getProjectOrderId());
	if (Objects.isNull(prevContract)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "计算补充协议差异内容失败，缺少上一份有效的正签/变更");
	}
	FormalContractExpandInfoDTO currentDetail = getContractDetail(currentContract, Boolean.TRUE);
	FormalContractExpandInfoDTO prevDetail = getContractDetail(prevContract, Boolean.FALSE);

	contractFieldChangeRecordService.deleteByContractCode(contractCode, false);
	List<FieldDiffDTO> fieldDiffDTOList = compareContract(prevDetail, currentDetail, currentContract.getProjectOrderId(), currentContract.getBusinessType(), currentContract.getChangeOrderId());
	List<ContractFieldChangeRecord> changeRecordList = fieldDiffDTOList.stream().map(
		fieldDiffDTO -> ContractFieldChangeRecord.builder()
			.contractCode(contractCode)
			.fieldKey(fieldDiffDTO.getFieldKey())
			.fieldName(fieldDiffDTO.getFieldName())
			.oldValue(Objects.isNull(fieldDiffDTO.getOldValue()) ? "" : fieldDiffDTO.getOldValue())
			.newValue(Objects.isNull(fieldDiffDTO.getNewValue()) ? "" : fieldDiffDTO.getNewValue())
			.delStatus(CommonEnum.NO.getCode())
			.ctime(new Date())
			.mtime(new Date())
			.build()
	).collect(Collectors.toList());

	if (CollectionUtils.isNotEmpty(changeRecordList)) {
		// 调整一下顺序，甲供材料放在税率后面
		// taxRate的位置
		int taxRateIndex = -1;
		// materialList的位置
		int materialListIndex = -1;
		for (int i = 0; i < changeRecordList.size(); i++) {
			if ("taxRate".equals(changeRecordList.get(i).getFieldKey())) {
				taxRateIndex = i;
			} else if ("materialList".equals(changeRecordList.get(i).getFieldKey())) {
				materialListIndex = i;
			}
		}

		if (taxRateIndex != -1 && materialListIndex != -1) {
			ContractFieldChangeRecord materialListRecord = changeRecordList.remove(materialListIndex);
			changeRecordList.add(taxRateIndex + 1, materialListRecord);
		}
		contractFieldChangeRecordService.insertBatch(changeRecordList);
	}
	return changeRecordList;
}

public List<ContractFieldChangeRecord> calculateDiffByReq() {
	// 请求参数
	ContractReqDTO contractReq = ContractContextHandler.getContractReq();
	String changeOrderId = contractReq.getContractBaseInfo().getChangeOrderId();
	String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();

	// 查询上一份有效的正签/变更合同
	Contract prevContract = contractService.getChangePrevEffectContractByPid(projectOrderId);
	if (Objects.isNull(prevContract)) {
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "计算补充协议差异内容失败，缺少上一份有效的正签/变更", Level.WARN);
	}

	FormalContractExpandInfoDTO currentDetail = getContractDetailByReq(contractReq);
	FormalContractExpandInfoDTO prevDetail = getContractDetail(prevContract, Boolean.FALSE);

	List<FieldDiffDTO> fieldDiffDTOList = compareContract(prevDetail, currentDetail, projectOrderId, BusinessTypeEnum.HOUSE_CERTIFICATE.getCode(), changeOrderId);
	return fieldDiffDTOList.stream().map(
		fieldDiffDTO -> ContractFieldChangeRecord.builder()
			.fieldKey(fieldDiffDTO.getFieldKey())
			.fieldName(fieldDiffDTO.getFieldName())
			.oldValue(Objects.isNull(fieldDiffDTO.getOldValue()) ? "" : fieldDiffDTO.getOldValue())
			.newValue(Objects.isNull(fieldDiffDTO.getNewValue()) ? "" : fieldDiffDTO.getNewValue())
			.delStatus(CommonEnum.NO.getCode())
			.ctime(new Date())
			.mtime(new Date())
			.build()
	).collect(Collectors.toList());
}

	private FormalContractExpandInfoDTO getContractDetail(Contract contract, Boolean isCurrentShow) {
