		infoDTO.setInsideArea(fieldsMap.getOrDefault("insideArea", ""));
		infoDTO.setStructure(Integer.parseInt(fieldsMap.getOrDefault("structure", "0")));
		infoDTO.setCertificateAddress(isCurrentShow ? getCertificateAddress(fieldsMap) : fieldsMap.getOrDefault("certificateAddress", getCertificateAddress(fieldsMap)));

		//6.其他相关
		infoDTO.setProjectContractModeCode(Integer.parseInt(fieldsMap.getOrDefault("projectContractModeCode", "0")));
		infoDTO.setProjectContractModeName(fieldsMap.getOrDefault("projectContractModeName", ""));
		infoDTO.setPartRoomRange(fieldsMap.getOrDefault("partRoomRange", ""));
		infoDTO.setTaxRate(Integer.parseInt(fieldsMap.getOrDefault("taxRate", "0")));
		infoDTO.setDisputeDealMode(Integer.parseInt(fieldsMap.getOrDefault("disputeDealMode", "0")));
