@Service
@Slf4j
public class ContractButtonConfigService {

	@Resource
	private MultidimensionalConfigService configService;
	@Resource
	private ContractApolloConfig contractApolloConfig;
	@Resource
	private ContractFieldService contractFieldService;
	@Resource
	private ContractService contractService;
	@Resource
	private CommonApolloConfig commonApolloConfig;
	@Resource
	private ContractRelationService contractRelationService;

	private static final String HOME_CONTRACT_BUTTON_CONFIG_MODULE_KEY = "homeContractListButtonConfig";
	private static final String AUTH_LIST_CONTRACT_BUTTON_CONFIG = "authListContractButtonConfig";
	private static final String CONTRACT_PREVIEW_BUTTON_CONFIG = "contractPreviewButtonConfig";
	private static final String PC_CONTRACT_BUTTON_CONFIG_MODULE_KEY = "pcContractListButtonConfig";

	@PostConstruct
	public void init() {
		// 初始化自定义函数
		initFunction();
		// 合同列表按钮配置
		initContractListButtonConfig();
		// 授权列表按钮配置
		initAuthListButtonConfig();
		// 合同预览页按钮配置
		initContractPreviewButtonConfig();
		// PC端合同列表按钮配置
		initPcContractButtonConfig();
	}

	@SneakyThrows
	private void initFunction() {
		AviatorEvaluator.importFunctions(ContractFunction.class);
	}

	/**
	 * 合同home列表按钮配置，类型枚举：ContractButtonEnum
	 */
	private void initContractListButtonConfig() {
		// 维度定义
		configService.dimensionalInit(HOME_CONTRACT_BUTTON_CONFIG_MODULE_KEY, ContractButtonDimensional.class);

		// key: 合同类型_按钮类型 value：表达式
		HashMap<String, String> normalRouteMap = new HashMap<>();
		HashMap<String, String> routeMap = new HashMap<>();

		// 通用合同规则
		normalRouteMap.put("*_1", "contractStatus != 1 && contractStatus != 10 && hasContractAgreement");
		normalRouteMap.put("*_2", "contractStatus == 1");
		normalRouteMap.put("*_3", "include(seq.list(2,4,5,6), contractStatus) && ContractFunction.showUndoButton(contractCode,userConfirmNodeList)");
		normalRouteMap.put("*_4", "contractStatus == 3");
		normalRouteMap.put("*_5", "string.length(bpmNo) > 0 && include(seq.list(6,7,8), contractStatus)");
		normalRouteMap.put("*_6", "contractStatus == 1");
		normalRouteMap.put("*_7", "contractStatus != 1 && contractStatus != 10");
		// 认购、首期款合同有上一份已完成的合同展示去重签按钮
		normalRouteMap.put("*_8", "ContractFunction.showReSignButton(contractCode, contractType, contractStatus, contractList)");


		/* 具体合同类型特殊规则 */
		/* 设计合同 */
		// 1.0设计合同不展示去变更，2.0/2.5设计合同展示去变更
		routeMap.put("2_12", "!beijingOldOrder && include(seq.list(3,8), contractStatus) && ContractFunction.showChangeButton(contractList, contractCode)");

		/* 正签合同 */


		/* 变更合同 */
		// 变更不能编辑合同
		routeMap.put("4_2", "false");
		// 变更草稿态不能删除合同
		routeMap.put("4_6", "false");
		// 变更合同没有撤回按钮
		routeMap.put("4_3", "false");
		// 变更协议没有查看按钮
		routeMap.put("4_7", "false");

		/* 解约协议 */
		// 解约协议没有编辑按钮
		routeMap.put("5_2", "false");
		// 解约协议没有撤销并修改
		routeMap.put("5_3", "false");
		// 解约协议不能删除合同
		routeMap.put("5_6", "false");
		//解约协议查看按钮，不属于当前项目的解约协议不展示
		routeMap.put("5_7", "contractStatus != 1 && contractStatus != 10 && include(terminalContractCode,contractCode)");
		routeMap.put("5_1", "include(seq.list(3,8), contractStatus)");//预览并分享

		/* 整装首期款合同 */
        // 整装首期款合同 查看按钮已取消不展示
		normalRouteMap.put("6_7", "contractStatus != 1 && contractStatus != 9 && contractStatus != 10");


		/* 个性化合同 */
		// C单独发起的合同C合同需要展示编辑按钮，B+C发起的个性化合同不展示编辑按钮，变更合同不展示编辑按钮
		routeMap.put("8_2", "contractStatus == 1 && multipleQuotePersonalContract");
		// 如果是单独c和变更发起的c展示撤销修改按钮
		routeMap.put("8_3", "(multipleQuotePersonalContract || string.length(changeOrderId) != 0) && include(seq.list(2,4,5,6), contractStatus) && ContractFunction.showUndoButton(contractCode,userConfirmNodeList)");
		// 通过变更走的个性化合同没有删除按钮
		routeMap.put("8_6", "contractStatus == 1 && string.length(changeOrderId) == 0 && multipleQuotePersonalContract");
		// 个性化合同没有查看按钮
		routeMap.put("8_7", "false");

		/* 设计合同 */
		routeMap.put("2_2", "contractStatus == 1 && designContractSubmitAlone");
		// 如果是单独发起的设计合同展示撤销修改按钮
		routeMap.put("2_3", "include(seq.list(2,4,5,6), contractStatus) && ContractFunction.showUndoButton(contractCode,userConfirmNodeList) && designContractSubmitAlone");
		// 通过非单独发起的设计合同
		routeMap.put("2_6", "contractStatus == 1 && designContractSubmitAlone");
		// 单独发起的设计合同才有查看按钮
		routeMap.put("2_7", "designContractSubmitAlone");

		/* 设计变更协议 */
		// 设计变更协议展示去变更
		routeMap.put("11_12", "!beijingOldOrder && include(seq.list(3,8), contractStatus) && ContractFunction.showChangeButton(contractList, contractCode)");

		/* 补充协议 */
		// 编辑按钮：基于原规则，增加条件（补充协议单独发起）
		routeMap.put("29_2", "contractStatus == 1 && supplementSubmitAlone");
		// 撤销并修改：基于原规则，增加条件（补充协议单独发起）
		routeMap.put("29_3", "include(seq.list(2,4,5,6), contractStatus) && ContractFunction.showUndoButton(contractCode,userConfirmNodeList) && supplementSubmitAlone");
		// 申请用章：基于原规则，增加条件（补充协议单独发起）
		routeMap.put("29_4", "contractStatus == 3 && supplementSubmitAlone");
		// 审核详情：修改原规则，补充协议是先发起 bpm 审核，因此待签署、待确认时，也允许查看审核详情
		routeMap.put("29_5", "string.length(bpmNo) > 0 && include(seq.list(2,3,4,6,7,8), contractStatus)");
		// 删除按钮：基于原规则，增加条件（补充协议单独发起）
		routeMap.put("29_6", "contractStatus == 1 && supplementSubmitAlone");
		// 补充协议不展示去重签
		routeMap.put("29_8", "false");

		/* 和解协议 */
		// 审核详情：修改原规则，和解协议是先发起 bpm 审核，因此待签署、待确认时，也允许查看审核详情
		routeMap.put("30_5", "string.length(bpmNo) > 0 && include(seq.list(2,3,4,6,7,8), contractStatus)");
		// 和解协议不展示去重签
		routeMap.put("30_8", "false");

		/* 木作首期款协议 */
		//个性化首期款协议没有编辑按钮
		for (Byte contractType : ContractTypeEnum.PERSONALIZED_CONTRACT) {
			routeMap.put(contractType + "_2", "false");
		}

		configService.appendConfig(HOME_CONTRACT_BUTTON_CONFIG_MODULE_KEY, ContractButtonDimensional.builder().build(), "false", 0);

		for (Map.Entry<String, String> entry : normalRouteMap.entrySet()) {
			String key = entry.getKey();
			String value = entry.getValue();

			String[] split = key.split("_");
			String contractType = split[0];
			String buttonType = split[1];

			configService.appendConfig(HOME_CONTRACT_BUTTON_CONFIG_MODULE_KEY, ContractButtonDimensional.builder()
				.contractType("*".equals(contractType) ? null : Byte.valueOf(contractType))
				.buttonType(Integer.valueOf(buttonType))
				.build(), value, 10);
		}

		for (Map.Entry<String, String> entry : routeMap.entrySet()) {
			String key = entry.getKey();
			String value = entry.getValue();

			String[] split = key.split("_");
			String contractType = split[0];
			String buttonType = split[1];

			ContractButtonDimensional dimensional = ContractButtonDimensional.builder()
				.contractType("*".equals(contractType) ? null : Byte.valueOf(contractType))
				.buttonType(Integer.valueOf(buttonType))
				.build();
			configService.appendConfig(HOME_CONTRACT_BUTTON_CONFIG_MODULE_KEY, dimensional, value, 100);
		}

	}


