	public BusinessInfoDetail buildBusinessInfoDetail(Contract contract, ContractProjectInfoDetail projectInfoDetail, Map<String, String> fieldMap, List<BillCodeInfo> billCodeInfoList, List<SubOrderInfo> subOrderInfoList, List<ChangeOrderInfo> changeOrderInfoList) {
		List<ChangeListDTO> changeOrderList = ContractDetailContextHandler.getContext().getChangeOrderList();
		if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
			// 如果是草稿态、待签署、待确认 则需要实时更新报价单列表
			List<Integer> allowSubmitStatus = Arrays.asList(ContractStatusEnum.DRAFT.getCode(), ContractStatusEnum.PENDING_USER_CONFIRM.getCode(), ContractStatusEnum.PENDING_USER_SIGN.getCode());
			if (allowSubmitStatus.contains(contract.getStatus())) {
				if (ContractDetailContextHandler.getContractSourceDataBO() != null && CollectionUtil.isNotEmpty(ContractDetailContextHandler.getContractSourceDataBO().getPersonalContractDataList())) {
					List<ContractSourceDataBO.PersonalContractData> personalContractDataList = ContractDetailContextHandler.getContractSourceDataBO().getPersonalContractDataList();
					BindOrderInfoGroup group = BindOrderInfo.convert(contract.getProjectOrderId(), personalContractDataList);
					billCodeInfoList = group.getBillCodeInfos();
					changeOrderInfoList = group.getChangeOrderInfos();
					subOrderInfoList = group.getSubOrderInfos();
				}
			}
		}
		//如果是初审驳回或者存在复审的合同，返回最新的变更单号
		String projectChangeNo = null;
		if (CollectionUtil.isNotEmpty(changeOrderList)) {
			ChangeListDTO changeListDTO = changeOrderList.stream().filter(m -> FirstChangeReasonEnum.正签方案变更.getReasonId().equals(m.getFirstChangeReason()))
				.filter(m -> SecondChangeReasonEnum.风控审核驳回.getReasonId().equals(m.getSecondChangeReason()))
				.findFirst().orElse(null);
			if (changeListDTO != null) {
				projectChangeNo = changeListDTO.getProjectChangeNo();
			}
		}

		//处理品类信息&商品信息
		List<BrandInfo> brandInfoList = fieldMap.get("brandList") == null ? new ArrayList<>() : JSON.parseArray(fieldMap.get("brandList"), BrandInfo.class);
		String goodsInfo = fieldMap.get("goodsInfo") == null ? "" : fieldMap.get("goodsInfo");
		String decorateType = ObjectUtil.isEmpty(projectInfoDetail) ? "" : StrUtil.join("-",
			// 允许 level1 为空
			StrUtil.blankToDefault(projectInfoDetail.getDecorateFormLevel1Text(), null),
			StrUtil.blankToDefault(projectInfoDetail.getDecorateFormLevel2Text(), null)
		).trim();
		return BusinessInfoDetail.builder()
			.decorateType(decorateType)
			.fundName(fieldMap.get("fundName"))
			.brandList(brandInfoList)
			.projectChangeNo(projectChangeNo)
			.billCodeList(BillCodeInfo.getBillCodeList(billCodeInfoList))
			.billCodeInfoList(billCodeInfoList)
			.changeOrderInfoList(changeOrderInfoList)
			.subOrderInfoList(subOrderInfoList)
			.goodsInfo(goodsInfo)
			.build();
	}

	/**
	 * 构建合同基础信息详情
	 */
	public ContractBaseInfoDetail buildContractBaseInfoDetail(Contract contract, String projectOrderId, Byte contractType, String changeOrderId, Map<String, String> fieldMap, Boolean isFirstScreen) {
		ContractBaseInfoDetail baseInfoDetail = new ContractBaseInfoDetail();
		baseInfoDetail.setChangeOrderId(changeOrderId);
		baseInfoDetail.setAttachOcrOpenCity(attachCommonService.attachOcrOpenCity(projectOrderId));
		baseInfoDetail.setNeedLaunchRelationTerminalContract(contractBusinessService.needLaunchOrLaunchedTerminalContract(projectOrderId));
		PlanAllDTO planAllDTO = ContractDetailContextHandler.getContractSourceDataBO().getPlanAllDTO();
		boolean processV25 = ContractDetailContextHandler.getContext().isProcessV25();
		Byte businessType = ContractDetailContextHandler.getContext().getBusinessType();
		baseInfoDetail.setFormalMergeLaunch(processV25);
		baseInfoDetail.setProcessV25(processV25);
		// 从项目信息获取城市编码
		ProjectInfoDTO projectInfo = ContractDetailContextHandler.getProjectInfo();
		Integer gbCode = projectInfo.getCustomerHouse().getGbCode();

		baseInfoDetail.setContractTypeName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contractType, businessType));
		baseInfoDetail.setDurationCalculateIsOpen(contractApolloConfig.durationCalculateIsOpen(gbCode));
		baseInfoDetail.setUseAddressFromDictionary(contractApolloConfig.useAddressFromDictionary(businessType, gbCode));
		baseInfoDetail.setNewMaterialModeOpen(contractApolloConfig.getNewMaterialModeOpen());
		baseInfoDetail.setNeedRealNameVerifyInConfirm(contractApolloConfig.getNeedRealNameVerifyInConfirmContractTypes().contains(contractType));
		baseInfoDetail.setFormalUseNewProcess(contractBusinessService.formalUseNewProcess(businessType, processV25, gbCode));
		baseInfoDetail.setSupplementIsOpen(contractUnifyService.supplementIsOpen(projectOrderId));
		//设计费标准开城
		if (ContractTypeEnum.DESIGN_FEE_PACKAGE_TYPES.contains(contractType) || ContractTypeEnum.DESIGN_FEE_DESIGN_TYPES.contains(contractType)) {
			baseInfoDetail.setStandardDesignFeeOpen(contractUnifyService.designFeeCalculateIsOpen(projectOrderId));
		}

		//设计费正式包信息返回
		if (contractUnifyService.designFeeFromQuote(projectOrderId) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			DesignQuoteFeeDTO designQuoteFeeDTO = ContractDetailContextHandler.getContext().getDesignQuoteFeeDTO();
			baseInfoDetail.setHaveDesignQuote(designQuoteFeeDTO.isHaveDesignQuote());
			MiniPayChannelAppNameEnum miniProgramType = commonBusinessService.getMiniProgramType(projectOrderId);
			baseInfoDetail.setMiniProgramType(miniProgramType != null ? miniProgramType.getMiniProgramType() : null);
			baseInfoDetail.setMergeDesignContract(designQuoteFeeDTO.isHaveDesignQuote() && MiniPayChannelAppNameEnum.被窝.equals(miniProgramType));
		}
		// 设计合同和设计变更合同
		boolean mergeLaunchDesignContract = contractUnifyService.isMergeLaunchDesignContract(projectOrderId);
		if (mergeLaunchDesignContract && ContractTypeEnum.DESIGN_FEE_DESIGN_TYPES.contains(contractType)) {
			baseInfoDetail.setHaveDesignQuote(Boolean.TRUE);
		}
		baseInfoDetail.setDesignAmountSourceType((ContractTypeEnum.DESIGN.getCode().equals(contractType) || ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contractType) || (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && baseInfoDetail.isHaveDesignQuote()) ) && contractApolloConfig.getStandardDesignFeeCityCodes().contains(gbCode) ?
			ContractFieldSourceTypeEnum.AREA_CALCULATE.getSourceType() : ContractFieldSourceTypeEnum.INPUT.getSourceType());
		if (contract == null) {
			// 有已签署/已确认的同一主体个性化合同，不发起B+C
			if (!isFirstScreen && Objects.equals(ContractTypeEnum.PACKAGE_FORMAL.getCode(), contractType)) {
				String organizationCode = planAllDTO.getPlanInfo().getOrganizationCode();
				Contract personalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode()).stream()
					.filter(item -> ContractStatusEnum.validStatusWithoutDraft.contains(item.getStatus()))
					.filter(m -> m.getCompanyCode().equals(organizationCode))
					.findFirst()
					.orElse(null);
				List<ContractSourceDataBO.PersonalContractData> personalContractDataList = ContractDetailContextHandler.getContext().getContractSourceDataBO().getPersonalContractDataList();
				baseInfoDetail.setHavePersonalQuote(!CollectionUtils.isEmpty(personalContractDataList));
				baseInfoDetail.setContractMode(getInitDetailContractMode(personalContract, gbCode));
			}
			baseInfoDetail.setProjectOrderId(projectOrderId);
			baseInfoDetail.setContractType(contractType);
			baseInfoDetail.setStatus(ContractStatusEnum.DRAFT.getCode());
			baseInfoDetail.setReSign(reSign(projectOrderId, contractType));
			//是否支持公对公协议
			baseInfoDetail.setSupportCompanyOnlineSign(openCompanySignOnlineForDetail(projectOrderId, isFirstScreen, contractType));
			//是否全案签约开城
			baseInfoDetail.setSupportFullServiceSign(commonContractService.supportFullServiceSign(gbCode, businessType));
			return baseInfoDetail;
		} else {
			String contractMode = fieldMap.get(ContractBaseInfoReq.Fields.contractMode);
			baseInfoDetail.setContractMode(StringUtils.isNotBlank(contractMode) ? Integer.valueOf(contractMode) : null);
			baseInfoDetail.setProjectOrderId(contract.getProjectOrderId());
			baseInfoDetail.setContractType(contract.getType());
			baseInfoDetail.setContractCode(contract.getContractCode());
			baseInfoDetail.setStatus(contract.getStatus());
			if (processV25 && (contract.getType().equals(ContractTypeEnum.PACKAGE_FORMAL.getCode()) || contract.getType().equals(ContractTypeEnum.PERSONAL.getCode()))) {
				List<RelateContract> relateContractList = homeAndPcCommonService.getRelateContractList(contract);
				baseInfoDetail.setRelateContracts(relateContractList);
				ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
				baseInfoDetail.setPrimaryRelatedContractCode(contractRelation != null ? contractRelation.getContractCode() : null);
				List<ContractSourceDataBO.PersonalContractData> personalContractDataList = ContractDetailContextHandler.getContext().getContractSourceDataBO().getPersonalContractDataList();
				baseInfoDetail.setHavePersonalQuote(!CollectionUtils.isEmpty(personalContractDataList));
			}
		}
		//设置当前合同是否是重签
		baseInfoDetail.setReSign(reSign(projectOrderId, contractType));
		if (ObjectUtil.isNotEmpty(changeOrderId)) {
			ChangeOrderBaseInfoDTO changeOrderBaseInfoDTO = changeOrderService.getByChangeOrderId(changeOrderId);
			if (ObjectUtil.isNotEmpty(changeOrderBaseInfoDTO)) {
				baseInfoDetail.setChangeOrderType(changeOrderBaseInfoDTO.getChangeOrderType().getCode());
			}
		}
		//获取合同链接
		baseInfoDetail.setContractUrl(getContractUrlInfo(contract));
		//是否支持公对公协议
		baseInfoDetail.setSupportCompanyOnlineSign(openCompanySignOnlineForDetail(projectOrderId, isFirstScreen, contractType));
		//是否全案签约开城
		baseInfoDetail.setSupportFullServiceSign(commonContractService.supportFullServiceSign(gbCode, businessType));

		return baseInfoDetail;
	}

	/**
	 * 合同详情初始化时是否为全案
	 */
	private Integer getInitDetailContractMode(Contract personalContract, Integer gbCode) {
		Byte businessType = ContractDetailContextHandler.getContext().getBusinessType();
		ContractSourceDataBO contractSourceDataBO = ContractDetailContextHandler.getContractSourceDataBO();
		//开城+有个性化报价+不存在个性化合同
		Integer contractMode = null;
		boolean noSignPersonalContract = personalContract == null;
		int multiplePersonalQuoteSize = commonContractService.haveMultiplePersonalQuoteSize(contractSourceDataBO);
		boolean supportFullService = contractApolloConfig.getFullServiceOpenCityList().contains(gbCode);
		if (noSignPersonalContract && multiplePersonalQuoteSize == 1 && supportFullService && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			contractMode = ContractModeEnum.FULL_SERVICE.getCode();
		}
		return contractMode;
	}


	/**
	 * 获取合同链接信息
	 */
	private List<FileInfo> getContractUrlInfo(Contract contract) {
		List<FileInfo> contractUrl = new ArrayList<>();
		if (contract == null) {
			return contractUrl;
		}
		//判断是否线上签约
		if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
			//线上签约
			String onlineContractUrl = homeAndPcCommonService.getContractUrl(contract);
			if (StringUtils.isNotBlank(onlineContractUrl)) {
				contractUrl.add(FileInfo.builder()
					.type(FileTypeEnum.PDF.getKey())
					.contractType(contract.getType())
					.url(onlineContractUrl).build());
			}
		} else {
			//线下
			List<String> attachUrlList = homeAndPcCommonService.getAttachUrl(contract);
			String attachFileKey = contractBusinessService.getAttachFileKey(attachUrlList);
			attachUrlList.forEach(attachUrl -> {
				contractUrl.add(FileInfo.builder()
					.type(attachFileKey)
					.contractType(contract.getType())
					.url(attachUrl).build());
			});
		}
		return contractUrl;
	}

	/**
	 * 构造合同流程信息
	 * 相关PRD:<a href="https://https://wiki.lianjia.com/pages/viewpage.action?pageId=1282314099">2.5-正签审核状态【合同页展示部分】</a>
	 *
	 * @param contract 如果是页面初始化，contract为null
	 * @return 流程信息
	 */
	public ProcessInfo buildProcessInfoDetail(@Nullable Contract contract) {
		try {
			// 如果没有合同 初始化状态不返回流程信息
			if (contract == null) {
				return null;
			}

			// 如果非正签合同 不返回流程信息
			if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
				return null;
			}

			// 如果整装模式 不返回流程信息
			if (!BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType())) {
				return null;
			}


			// 如果非已签署状态 不返回流程信息
			if (!ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
				return null;
			}

			ProcessInfo processInfo = new ProcessInfo();
			AuditDetailDto auditDetailDTO = Optional.ofNullable(ContractDetailContextHandler.getContext()).map(ContractDetailContext::getAuditDetailDTO)
				.orElse(auditRpc.getAuditInfo(contract.getProjectOrderId()));
			List<ChangeListDTO> changeOrderList = Optional.ofNullable(ContractDetailContextHandler.getContext()).map(ContractDetailContext::getChangeOrderList)
				.orElse(atomChangeRpc.getChangeList(contract.getProjectOrderId()));

			// 没有查询到审核信息 不返回流程信息
			if (auditDetailDTO == null) {
				return null;
			}

			Integer processAuditStatus = computeProcessStatus(auditDetailDTO, changeOrderList);
			LOGGER.info("计算流程状态:{}", processAuditStatus);

			// 说明变更单状态没有匹配到，不返回流程信息
			if (processAuditStatus == null) {
				return null;
			}

			// 构造流程节点
			processInfo.setCurrentNodeId(processAuditStatus.toString());
			processInfo.setNodeList(buildProcessInfoNodeList(processAuditStatus, auditDetailDTO, changeOrderList));
			processInfo.setStatus(processAuditStatus);
			processInfo.setLabelText(buildProcessInfoLabText(processAuditStatus, auditDetailDTO));
			processInfo.setTips(buildProcessInfoTips(processAuditStatus, auditDetailDTO));
			processInfo.setAuditFinishNodeDesc(processInfo.getNodeList().stream().filter(node -> ProcessNodeTypeEnum.DONE.getNodeType().toString().equals(node.getNodeId())).findFirst()
				.map(ProcessInfo.Node::getNodeDesc).orElse(null));
			processInfo.setChangeOrderDetailSchema(buildChangeOrderDetailSchema(processAuditStatus, contract.getProjectOrderId(), changeOrderList, auditDetailDTO.getAuditStatus()));
			return processInfo;
		} catch (Exception e) {
			LOGGER.error("构造合同流程信息异常，合同code：{}", contract.getContractCode(), e);
		}
		return null;
	}

	private String buildChangeOrderDetailSchema(Integer processAuditStatus, String projectOrderId, List<ChangeListDTO> changeOrderList, Integer auditStatus) {
		if (Arrays.asList(ProcessStatusEnum.AUDIT_REVIEW.getStatus(), ProcessStatusEnum.AUDIT_REVIEW_PASS.getStatus(), ProcessStatusEnum.AUDIT_REJECT.getStatus()).contains(processAuditStatus)) {
			List<ChangeListDTO> auditRejectChangeOrderList = getAuditRejectChangeOrder(changeOrderList);
			ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
			// /home-saas-25/pages/changeProcess/changeDetail?projectOrderId=项目单号&projectChangeNo=变更单号&customerCommissionCode=客源code
			return commonApolloConfig.getStewardDomain() +
				String.format("/home-saas-25/pages/changeProcess/changeDetail?projectOrderId=%s&projectChangeNo=%s&customerCommissionCode=%s",
					projectOrderId, auditRejectChangeOrderList.get(0).getProjectChangeNo(), projectInfoDTO.getCustomerCommission().getCustomerCommissionCode());
		}

		return null;
	}

	private String buildProcessInfoTips(Integer processAuditStatus, AuditDetailDto auditDetailDTO) {
		ProcessStatusEnum processStatusEnum = ProcessStatusEnum.getByStatus(processAuditStatus);
		if (processStatusEnum == null) {
			return null;
		}

		String waitAuditDesc = "";
		if (auditDetailDTO != null && !Optional.ofNullable(auditDetailDTO.getAuditUserName()).orElse("").isEmpty()
			&& !Optional.ofNullable(auditDetailDTO.getAuditUserCode()).orElse("").isEmpty()) {
			waitAuditDesc = "，审核人：" + auditDetailDTO.getAuditUserName() + "（" + auditDetailDTO.getAuditUserCode() + "）";
		}

		switch (processStatusEnum) {
			case WAIT_AUDIT:
				if (auditDetailDTO != null && AuditStatusEnum.WAIT_DISTRIBUTE.getValue() == auditDetailDTO.getAuditStatus()) {
					return "风控待审核：待分配审核员，了解进度联系城市ssc中台";
				}
				return "风控审核状态：待审核" + waitAuditDesc;
			case AUDITING:
				return "风控审核状态：待审核" + waitAuditDesc;
			case AUDIT_REJECT:
			case AUDIT_REVIEW:
			case AUDIT_REVIEW_PASS:
				return "正签审核驳回自动发起变更，可查看进度";
			default:
				return null;
		}
	}

	private String buildProcessInfoLabText(Integer processAuditStatus, AuditDetailDto auditDetailDTO) {
		ProcessStatusEnum processStatusEnum = ProcessStatusEnum.getByStatus(processAuditStatus);
		if (processStatusEnum == null) {
			return null;
		}

		switch (processStatusEnum) {
			case WAIT_AUDIT:
			case AUDITING:
				return "风控待审核";
			case AUDIT_REJECT:
				if (AuditStatusEnum.WAIT_DISTRIBUTE.getValue() == auditDetailDTO.getAuditStatus() || AuditStatusEnum.WAIT_CHECK.getValue() == auditDetailDTO.getAuditStatus()
					|| AuditStatusEnum.CHECKING.getValue() == auditDetailDTO.getAuditStatus()) {
					return "风控复审中";
				}

				return "风控审核驳回";
			case AUDIT_REVIEW:
			case AUDIT_REVIEW_PASS:
				return "风控复审中";
			case AUDIT_PASS:
			case DONE:
				return "风控审核完成";
			default:
				return null;
		}
	}

	public AmountInfo buildAmountInfoDetail(Map<String, String> fieldMap) {
		String quoteTotalAmount = fieldMap.get("quoteTotalAmount");
		String dueTotalAmount = fieldMap.get("dueTotalAmount");
		BigDecimal paidAmount = Optional.ofNullable(ContractDetailContextHandler.getContext())
			.map(ContractDetailContext::getRelateFundInfo)
			.map(FundInfo::getPaidAmount)
			.orElse(BigDecimal.ZERO);
		return AmountInfo.builder()
			.quoteTotalAmount(quoteTotalAmount == null ? BigDecimal.ZERO : new BigDecimal(quoteTotalAmount))
			.dueTotalAmount(dueTotalAmount == null ? BigDecimal.ZERO : new BigDecimal(dueTotalAmount))
			.paidAmount(paidAmount)
			.build();
	}

	private List<ProcessInfo.Node> buildProcessInfoNodeList(Integer processAuditStatus, AuditDetailDto auditDetailDTO, List<ChangeListDTO> changeOrderList) {
		List<ChangeListDTO> changeListDTOList = changeOrderList.stream().filter(m -> FirstChangeReasonEnum.正签方案变更.getReasonId().equals(m.getFirstChangeReason()))
			.filter(m -> SecondChangeReasonEnum.风控审核驳回.getReasonId().equals(m.getSecondChangeReason())).collect(Collectors.toList());

		boolean isWaitDistribute = AuditStatusEnum.WAIT_DISTRIBUTE.getValue() == auditDetailDTO.getAuditStatus();
		boolean isReviewAudit = SubmitTypeEnum.RECHECK.getName().equals(auditDetailDTO.getSubmitTypeName());

		List<ProcessInfo.Node> nodeList = new ArrayList<>();
		List<ButtonItemVo> buttonList = null;
		if (!CollectionUtils.isEmpty(changeListDTOList) && Arrays.asList(ProcessStatusEnum.AUDIT_REVIEW.getStatus(), ProcessStatusEnum.AUDIT_REVIEW_PASS.getStatus(), ProcessStatusEnum.AUDIT_REJECT.getStatus()).contains(processAuditStatus)) {
			String projectOrderId = auditDetailDTO.getProjectOrderId();
			String projectChangeNo = changeListDTOList.get(0).getProjectChangeNo();
			buttonList = Collections.singletonList(ButtonItemVo.builder()
				.type(PcButtonEnum.CHANGE_ORDER.getType())
				.name(PcButtonEnum.CHANGE_ORDER.getName())
				.schema(String.format(contractApolloConfig.getChangeOrderPageSchema(), projectOrderId, projectChangeNo))
				.build());
		}

		//241126修改 待审核节点显示审核人或固定文案
		String waitAuditDesc = "待分配审核员\n了解进度联系城市ssc中台";
		// 检查审核人姓名和代码是否存在且不为空
		if (AuditStatusEnum.WAIT_DISTRIBUTE.getValue() != auditDetailDTO.getAuditStatus() && !Optional.ofNullable(auditDetailDTO.getAuditUserName()).orElse("").isEmpty() && !Optional.ofNullable(auditDetailDTO.getAuditUserCode()).orElse("").isEmpty()) {
			waitAuditDesc = "审核人：" + auditDetailDTO.getAuditUserName() + "（" + auditDetailDTO.getAuditUserCode() + "）";
		}
		nodeList.add(ProcessInfo.Node.builder()
			.nodeId(ProcessNodeTypeEnum.WAIT_AUDIT.getNodeType().toString())
			.nodeTitle(ProcessStatusEnum.WAIT_AUDIT.getDesc())
			.nodeStatus(ProcessNodeStatusEnum.computeNodeStatus(ProcessNodeTypeEnum.WAIT_AUDIT.getNodeType(), processAuditStatus, isReviewAudit, isWaitDistribute))
			.nodeDesc(waitAuditDesc)
			.build());

		Integer nodeStatus = ProcessNodeStatusEnum.computeNodeStatus(ProcessNodeTypeEnum.AUDIT.getNodeType(), processAuditStatus, isReviewAudit, isWaitDistribute);
		String nodeTitle = ProcessNodeStatusEnum.FAILED.getStatus().equals(nodeStatus) ? "审核驳回" : "审核中";
		// 变更单审批通过之后，审核节点改成 「初审驳回后，进行复审」
		if (isReviewAudit && processAuditStatus >= ProcessStatusEnum.AUDITING.getStatus()) {
			nodeTitle = "审核驳回，进行复审";
		}
		nodeList.add(ProcessInfo.Node.builder()
			.nodeId(ProcessNodeTypeEnum.AUDIT.getNodeType().toString())
			.nodeStatus(nodeStatus)
			.nodeTitle(nodeTitle)
			.nodeDesc(getNodeDesc(ProcessNodeTypeEnum.AUDIT.getNodeType(), processAuditStatus, auditDetailDTO.getAuditStatus()))
			.buttonList(buttonList)
			.build());


		String doneDesc = "";
		// 审核完成节点显示风控审核时间
		if (ProcessStatusEnum.DONE.getStatus().equals(processAuditStatus) && !CollectionUtils.isEmpty(auditDetailDTO.getProcessHistoryList()) && AuditStatusEnum.PASS.getValue() == auditDetailDTO.getProcessHistoryList()
			.get(auditDetailDTO.getProcessHistoryList().size() - 1).getAuditStatus()) {
			doneDesc = "审核完成时间：" + auditDetailDTO.getProcessHistoryList()
				.get(auditDetailDTO.getProcessHistoryList().size() - 1).getProcessTime();
		}
		// 审核完成节点显示变更单完成时间或空
		if (ProcessStatusEnum.DONE.getStatus().equals(processAuditStatus) && !CollectionUtils.isEmpty(changeListDTOList)) {
			ChangeListDTO changeListDTO = changeListDTOList.get(0);
			String projectOrderId = auditDetailDTO.getProjectOrderId();
			ProjectResponse projectResponse = orderStandardQueryRpc.orderStandardOutput(Collections.singletonList(projectOrderId), Collections.singletonList(HomeModelDefEnum.COST_CONTROL_CHANGE.name()));
			List<ChangeModule.IChange> changeList = projectResponse.getProjectMap().get(projectOrderId).getCostControl().getChangeModule().getChangeList();
			if (!CollectionUtils.isEmpty(changeList)) {
				LocalDateTime finishTime = changeList.stream()
					.filter(change -> changeListDTO.getProjectChangeNo().equals(change.getProjectChangeNo()))
					.findFirst().map(ChangeModule.IChange::getFinishTime).orElse(null);
				if (finishTime != null) {
					doneDesc = "审核完成时间：" + DateUtil.formatLocalDateTime(finishTime);
				}
			}
		}

		nodeList.add(ProcessInfo.Node.builder()
			.nodeId(ProcessNodeTypeEnum.DONE.getNodeType().toString())
			.nodeTitle("审核通过")
			.nodeStatus(ProcessNodeStatusEnum.computeNodeStatus(ProcessNodeTypeEnum.DONE.getNodeType(), processAuditStatus, isReviewAudit, isWaitDistribute))
			.nodeDesc(doneDesc)
			.build());
		return nodeList;
	}

	private String getNodeDesc(Integer nodeType, Integer processStatus, Integer auditStatus) {
		if (nodeType == null || processStatus == null) {
			return null;
		}

		if (ProcessNodeTypeEnum.WAIT_AUDIT.getNodeType().equals(nodeType)) {
			return "提交完成";
		} else if (ProcessNodeTypeEnum.AUDIT.getNodeType().equals(nodeType)) {

			if (ProcessStatusEnum.AUDIT_PASS.getStatus().equals(processStatus) ||
				ProcessStatusEnum.DONE.getStatus().equals(processStatus) ||
				ProcessStatusEnum.AUDIT_REVIEW_PASS.getStatus().equals(processStatus)) {
				return "审核通过";
			} else if (ProcessStatusEnum.AUDIT_REJECT.getStatus().equals(processStatus)) {
				if (AuditStatusEnum.WAIT_DISTRIBUTE.getValue() == auditStatus) {
					return "待分配复审人";
				} else if (AuditStatusEnum.REJECT.getValue() == auditStatus) {
					return "正签审核驳回会自动生成变更单";
				}
			} else if (ProcessStatusEnum.AUDITING.getStatus().equals(processStatus)) {
				return "审核中请等待...";
			}

		} else if (ProcessNodeTypeEnum.DONE.getNodeType().equals(nodeType)) {
			return "正签审核完成";
		}

		return null;
	}

	/**
	 * 计算流程状态
	 *
	 * @param auditDetailDTO  风控审核信息
	 * @param changeOrderList 变更单列表
	 * @return 流程状态
	 */
	private Integer computeProcessStatus(AuditDetailDto auditDetailDTO, List<ChangeListDTO> changeOrderList) {
		List<ChangeListDTO> changeListDTOList = getAuditRejectChangeOrder(changeOrderList);

		if (AuditStatusEnum.WAIT_DISTRIBUTE.getValue() == auditDetailDTO.getAuditStatus() ||
			AuditStatusEnum.WAIT_CHECK.getValue() == auditDetailDTO.getAuditStatus() ||
			AuditStatusEnum.CANCEL.getValue() == auditDetailDTO.getAuditStatus()
		) {
			return CollectionUtils.isEmpty(changeListDTOList) ? ProcessStatusEnum.WAIT_AUDIT.getStatus() : ProcessStatusEnum.AUDIT_REJECT.getStatus();
		}

		if (AuditStatusEnum.CHECKING.getValue() == auditDetailDTO.getAuditStatus()) {
			return CollectionUtils.isEmpty(changeListDTOList) ? ProcessStatusEnum.AUDITING.getStatus() : ProcessStatusEnum.AUDIT_REVIEW.getStatus();
		}

		if (AuditStatusEnum.PASS.getValue() == auditDetailDTO.getAuditStatus()) {
			// 初审通过
			if (SubmitTypeEnum.FIRST_AUDIT.getName().equals(auditDetailDTO.getSubmitTypeName())) {
				return ProcessStatusEnum.DONE.getStatus();
			}

			// 复审通过
			if (changeListDTOList.size() == 1) {
				// 只有一个变更单，说明是正签变更
				ChangeListDTO changeOrderDTO = changeListDTOList.get(0);
				// 根据变更单状态判断流程状态
				if (ChangeBusinessStatusEnum.FINISHED.getCode().equals(changeOrderDTO.getStatus())) {
					return ProcessStatusEnum.DONE.getStatus();
				} else {
					return ProcessStatusEnum.AUDIT_REVIEW_PASS.getStatus();
				}
			}

			LOGGER.error("风控审核驳回后，变更单数量不为1，变更单为：{}", JSON.toJSONString(changeListDTOList));
			// 变更单大于1，说明正签变更已完成
			return ProcessStatusEnum.DONE.getStatus();
		}

		if (AuditStatusEnum.REJECT.getValue() == auditDetailDTO.getAuditStatus()) {
			// 如果是审核驳回，会创建变更单，通过变更单判断流程状态是复审中 还是复审通过
			if (CollectionUtils.isEmpty(changeListDTOList)) {
				return ProcessStatusEnum.AUDIT_REJECT.getStatus();
			}

			if (changeListDTOList.size() == 1) {
				// 只有一个变更单，说明是正签变更
				ChangeListDTO changeOrderDTO = changeListDTOList.get(0);
				// 根据变更单状态判断流程状态
				if (ChangeBusinessStatusEnum.FINISHED.getCode().equals(changeOrderDTO.getStatus())) {
					return ProcessStatusEnum.DONE.getStatus();
				} else if (ChangeBusinessStatusEnum.APPLYING.getCode().equals(changeOrderDTO.getStatus()) ||
					ChangeBusinessStatusEnum.UNDER_CHANGE.getCode().equals(changeOrderDTO.getStatus())
				) {
					return ProcessStatusEnum.AUDIT_REJECT.getStatus();
				} else if (changeOrderIsAudit(changeOrderDTO)) {
					return ProcessStatusEnum.AUDIT_REVIEW.getStatus();
				} else if (ChangeBusinessStatusEnum.WAIT_HOMEOWNER.getCode().equals(changeOrderDTO.getStatus()) ||
					ChangeBusinessStatusEnum.WAIT_SIGN.getCode().equals(changeOrderDTO.getStatus()) ||
					ChangeBusinessStatusEnum.WAIT_PAY.getCode().equals(changeOrderDTO.getStatus()) ||
					ChangeBusinessStatusEnum.WAIT_COST.getCode().equals(changeOrderDTO.getStatus())
				) {
					return ProcessStatusEnum.AUDIT_REVIEW_PASS.getStatus();
				}

			}
			LOGGER.error("风控审核驳回后，变更单数量不为1，变更单为：{}", JSON.toJSONString(changeListDTOList));
			// 变更单大于1，说明正签变更已完成
			return ProcessStatusEnum.DONE.getStatus();
		}

		return null;
	}

	private List<ChangeListDTO> getAuditRejectChangeOrder(List<ChangeListDTO> changeOrderList) {
		return changeOrderList.stream()
			.filter(m -> !ChangeBusinessStatusEnum.CANCEL.getCode().equals(m.getStatus()))
			.filter(m -> FirstChangeReasonEnum.正签方案变更.getReasonId().equals(m.getFirstChangeReason()))
			.filter(m -> SecondChangeReasonEnum.风控审核驳回.getReasonId().equals(m.getSecondChangeReason()))
			.collect(Collectors.toList());
	}

	private boolean changeOrderIsAudit(ChangeListDTO changeOrderDTO) {
		if (ChangeBusinessStatusEnum.LAUNCHED.getCode().equals(changeOrderDTO.getStatus()) ||
			ChangeBusinessStatusEnum.WAIT_AUDIT.getCode().equals(changeOrderDTO.getStatus())) {
			return true;
		}

		for (ChangeBusinessStatusEnum changeBusinessStatusEnum : ChangeBusinessStatusEnum.audit()) {
			if (changeBusinessStatusEnum.getCode().equals(changeOrderDTO.getStatus())) {
				return true;
			}
		}
		return false;
	}


	/**
	 * 构建合同项目信息详情
	 */
	public ContractProjectInfoDetail buildContractProjectInfoDetail(Contract contract, Byte contractType, String projectOrderId, Map<String, String> fieldMap) {
		ContractProjectInfoDetail projectInfoDetail = new ContractProjectInfoDetail();
		ProjectInfoDTO projectInfoDTO = ContractDetailContextHandler.getProjectInfo();
		//翻新全案工期单位开关设置
		projectInfoDetail.setReformDurationUnitSwitch(getReformDurationUnitSwitch());
		// 零售项目信息
		if (!ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(projectInfoDTO.getDecorateBusinessType())) {
			// 构建整装设计师信息
			ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
			projectInfoDetail.setDesignerUcId(designer == null ? 0 : designer.getUcId());
			projectInfoDetail.setDesignerName(designer == null ? "" : designer.getName());
			projectInfoDetail.setDesigner(projectInfoDetail.getDesignerName().concat("(").concat(String.valueOf(projectInfoDetail.getDesignerUcId() % 100000000).concat(")")));
		}
		ProjectCustomerHouseDTO houseDTO = projectInfoDTO.getCustomerHouse();
		String address = homeAndPcCommonService.getSafeAddress(projectInfoDTO);
		String centerControlType = homeAndPcCommonService.getCenterControlType(projectOrderId);
		Byte businessType = commonContractService.getBusinessType(projectInfoDTO);
		List<ZqCustomerPhoneVo> customerPhoneVoList = homeAndPcCommonService.getPhoneList(projectInfoDTO);
		projectInfoDetail.setCustomerName(homeAndPcCommonService.getName(projectInfoDTO));
		projectInfoDetail.setCustomerPhone(homeAndPcCommonService.getPhone(projectInfoDTO));
		projectInfoDetail.setCustomerCommissionCode(projectInfoDTO.getCustomerCommission().getCustomerCommissionCode());
		projectInfoDetail.setCustomerPhoneVoList(CollectionUtils.isEmpty(customerPhoneVoList) ? null : customerPhoneVoList);
		projectInfoDetail.setAddress(address);
		projectInfoDetail.setBusinessType(businessType);
		projectInfoDetail.setCompanyCode(projectInfoDTO.getCustomerCommission().getCompanyCode());
		projectInfoDetail.setDecorateFormLevel1(
			Objects.nonNull(projectInfoDTO.getCustomerCommission().getDecorateType()) ? projectInfoDTO.getCustomerCommission().getDecorateType()
				.intValue() : null);
		projectInfoDetail.setDecorateFormLevel1Text(projectInfoDTO.getCustomerCommission().getDecorateTypeDesc());
		projectInfoDetail.setDecorateFormLevel2(
			Objects.nonNull(projectInfoDTO.getCustomerCommission().getDecorateId()) ? projectInfoDTO.getCustomerCommission().getDecorateId()
				.intValue() : null);
		projectInfoDetail.setDecorateFormLevel2Text(projectInfoDTO.getCustomerCommission().getDecorateIdDesc());
		projectInfoDetail.setCenterControlType(centerControlType);
		BeanUtils.copyProperties(houseDTO, projectInfoDetail);

		//房屋类型如果是未知，返回给前端处理为null
		Integer houseType = (projectInfoDetail.getHouseType() == null || Objects.equals(projectInfoDetail.getHouseType(),
			HouseTypeEnum.UNKONWN.getCode())) ? null : projectInfoDetail.getHouseType();
		projectInfoDetail.setHouseType(houseType);
		//户型结构如果是未知，返回给前端处理为null
		Integer houseBuildType = (projectInfoDetail.getHouseBuildType() == null || HouseBuildTypeEnum.UNKNOWN.getCode()
			.equals(projectInfoDetail.getHouseBuildType())) ? null : projectInfoDetail.getHouseBuildType();
		projectInfoDetail.setHouseBuildType(houseBuildType);
		projectInfoDetail.setCancelOrderAmount(getCancelOrderAmount(projectOrderId));

		ProjectInfoRealTimeQueryInfo projectInfoRealTimeQueryInfo = new ProjectInfoRealTimeQueryInfo();
		ApartmentInfo apartmentInfo = new ApartmentInfo();
		BeanUtils.copyProperties(projectInfoDetail, projectInfoRealTimeQueryInfo);
		BeanUtils.copyProperties(projectInfoDetail, apartmentInfo);
		List<OptionsVo> advanceRates = null;
		// 「整装首期款合同」从收款计划获取首期款比例
		if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
			advanceRates = getAdvanceRates(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), projectInfoDTO.getCustomerCommission().getCompanyCode());
		}
		if (contract == null) {
			dealProjectInfoFromAttachInfo(projectInfoDetail);
			// 设计合同特殊处理
			fillDesignContractInfo(projectOrderId, projectInfoDetail, contract, contractType);
			// 如果是整装首期款合同，则 advanceRates != null
			if (advanceRates != null) {
				// 如果没有草稿合同，则为 advanceRate 设置默认值
				projectInfoDetail.setAdvanceRate((BigDecimal) advanceRates.get(0).getValue());
			}
		} else {
			BeanUtil.fillBeanWithMap(fieldMap, projectInfoDetail, true);
			// 整装需要工期，零售不需要
			if (!ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(projectInfoDTO.getDecorateBusinessType())) {
				ConstructScheduleVo constructScheduleVo = new ConstructScheduleVo();
				BeanUtil.fillBeanWithMap(fieldMap, constructScheduleVo, true);
				if (StringUtils.isNotBlank(fieldMap.get("constructionStageDetailDTO"))) {
					constructScheduleVo.setConstructionStageDetailDTO(JsonUtil.toObject(fieldMap.get("constructionStageDetailDTO"),
						new TypeReference<List<ConstructScheduleVo.ConstructionStageDetailDTO>>() {
						}));
				}
				if (StringUtils.isNotBlank(fieldMap.get("personalCrafts"))) {
					constructScheduleVo.setPersonalCrafts(JsonUtil.toObject(fieldMap.get("personalCrafts"), new TypeReference<List<String>>() {
					}));
				}
				projectInfoDetail.setConstructSchedule(constructScheduleVo);

				// 如果合同是草稿态，则实时获取最新的设计师信息
				if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
					// 构建整装设计师信息
					ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
					projectInfoDetail.setDesignerUcId(designer == null ? 0 : designer.getUcId());
					projectInfoDetail.setDesignerName(designer == null ? "" : designer.getName());
					projectInfoDetail.setDesigner(projectInfoDetail.getDesignerName().concat("(").concat(String.valueOf(projectInfoDetail.getDesignerUcId() % 100000000).concat(")")));
				}

			}
			projectInfoDetail.setAmount(contract.getAmount());

			// 设计合同特殊处理
			fillDesignContractInfo(projectOrderId, projectInfoDetail, contract, fieldMap);

			//正签合同草稿阶段，设计师姓名&系统号、城市、字段始终从客源获取
			if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType()) && ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
				BeanUtils.copyProperties(projectInfoRealTimeQueryInfo, projectInfoDetail);
			}
		}
		//如果为合并发起模式，房屋类型从报价获取
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType);
			Integer houseTypeFromPlanAllDto = ContractDetailContextHandler.getPlanAllDTO() == null ? null
				: ContractDetailContextHandler.getPlanAllDTO().getReconstructionHouseLayout().getHouseType();
			//报价返回的房屋类型为有效时才使用
			if (processV25 && !HouseTypeEnum.UNKONWN.getCode().equals(houseTypeFromPlanAllDto)) {
				projectInfoDetail.setHouseType(houseTypeFromPlanAllDto);
			}
			if (HouseTypeEnum.UNKONWN.getCode().equals(projectInfoDetail.getHouseType())) {
				projectInfoDetail.setHouseType(null);
			}
			//2.5正签合同草稿阶段，原始户型字段始终从客源获取
			if (contract != null && ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()) && processV25) {
				//2.5建筑面积实时从客源取，不从草稿取
				projectInfoDetail.setArea(houseDTO.getArea());
				Integer gbCode = commonContractService.getCityMapping(projectInfoDTO.getCustomerHouse().getGbCode(), projectOrderId);
				if (CityEnum.BEIJING.getGbCode() == gbCode) {
					//原始户型字段草稿态始终从客源获取
					BeanUtils.copyProperties(apartmentInfo, projectInfoDetail);
				}
			}
		}
		//首期款合同需要返回预估合同额使用的面积类型
		if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
			projectInfoDetail.setUserAreaType(commonContractService.getExpectAmountUseAreaType(projectOrderId));
			projectInfoDetail.setAdvanceRates(advanceRates);

		}
		// 草稿态正签合同，设计费信息实时从报价获取
		if (contractUnifyService.designFeeFromQuote(projectOrderId) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && (ObjectUtil.isEmpty(contract) || ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()))) {
			DesignQuoteFeeDTO designQuoteFeeDTO = ContractDetailContextHandler.getContext().getDesignQuoteFeeDTO();
			if (ObjectUtil.isNotEmpty(designQuoteFeeDTO) && designQuoteFeeDTO.isHaveDesignQuote()) {
				projectInfoDetail.setPreDiscountDesignerAmount(designQuoteFeeDTO.getPreDiscountDesignerAmount());
				projectInfoDetail.setAfterDiscountDesignerAmount(designQuoteFeeDTO.getAfterDiscountDesignerAmount());
				projectInfoDetail.setDesignerPsLevelName(designQuoteFeeDTO.getPsLevelName());
				projectInfoDetail.setDesignerLevelName(getDesignerLevelName(projectInfoDetail.getGbCode(), designQuoteFeeDTO.getPsLevelName()));
				projectInfoDetail.setValuationArea(designQuoteFeeDTO.getValuationArea());
				projectInfoDetail.setHouseBuildType(designQuoteFeeDTO.getHouseBuildType());
				projectInfoDetail.setHouseBuildTypeDesc(ObjectUtil.isEmpty(designQuoteFeeDTO.getHouseBuildType()) ? null : HouseBuildTypeEnum.getEnumByCode(designQuoteFeeDTO.getHouseBuildType()).getDesc());
			}
		}
		if (ContractDetailContextHandler.getContext().isProcessV25() && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(ContractDetailContextHandler.getContext().getBusinessType())
			&& (contract == null || ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			//总工期从apollo获取
			projectInfoDetail.setTotalDuration(contractApolloConfig.getTotalDurationByGbCode(projectInfoDetail.getGbCode()));
			//原始户型从报价获取
			if (ContractDetailContextHandler.getPlanAllDTO() != null) {
				HouseLayoutInfoDTO reconstructionHouseLayout = ContractDetailContextHandler.getPlanAllDTO().getReconstructionHouseLayout();
				projectInfoDetail.setParlorCnt(reconstructionHouseLayout.getLivingRoomNum());
				projectInfoDetail.setRoomCnt(reconstructionHouseLayout.getBedroomNum());
				projectInfoDetail.setCookroomCnt(reconstructionHouseLayout.getKitchenNum());
				projectInfoDetail.setToiletCnt(reconstructionHouseLayout.getToiletNum());
				projectInfoDetail.setBalconyCnt(reconstructionHouseLayout.getBalconyNum());
				projectInfoDetail.setStorageCnt(reconstructionHouseLayout.getStoreroomNum());
			}
		}
		return projectInfoDetail;
	}

	private boolean getReformDurationUnitSwitch() {
		LocalDateTime targetTime = null;
		LocalDateTime now = null;
		try {
			String reformDurationUnitSwitchTime = contractApolloConfig.getReformDurationUnitSwitchTime();
			DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
			targetTime = LocalDateTime.parse(reformDurationUnitSwitchTime, formatter);
			now = LocalDateTime.now();
		} catch (Exception e) {
			LOGGER.error("获取合同翻新工期单位开关时间异常", e);
			return false;
		}
		return now.isAfter(targetTime);
	}


	private List<OptionsVo> getAdvanceRates(String projectOrderId, Integer gbCode, String companyCode) {
		// 北京特殊处理，返回首期款比例为 0.2 和 0.6
		if (CityEnum.BEIJING.getGbCode() == gbCode) {
			LOGGER.info("「首期款比例调整」北京特殊处理，返回 20%，60%");
			return Arrays.asList(new OptionsVo(CollectionRateEnum.ZERO_TWO), new OptionsVo(CollectionRateEnum.ZERO_SIX));
		} else if (contractApolloConfig.isAdvanceRateOpenCity(gbCode)) {
			// 对于其他城市：如果开城，则获取「收款计划」的首期款比例
			// 首期款比例默认设置为 20%
			List<OptionsVo> advanceRates = Collections.singletonList(new OptionsVo(CollectionRateEnum.ZERO_TWO));
			List<CollectionPlanConfigInfo> collectionProgressConfigList;
			try {
				Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
				// 获取收款计划
				collectionProgressConfigList = payConfigService.getProjectCollectionProgressConfig(projectOrderId, companyCode, businessType);
			} catch (NrsBusinessException e) {
				LOGGER.info("「首期款比例调整」查询收款计划抛出异常，返回默认值 20%");
				return advanceRates;
			}
			// 判空
			if (collectionProgressConfigList.isEmpty() || collectionProgressConfigList.get(0) == null || collectionProgressConfigList.get(0).getContent().isEmpty()) {
				LOGGER.info("「首期款比例调整」未查询到首期款比例，返回默认值 20%");
				// 未查询到首期款比例，设置为默认比例 20%
				return advanceRates;
			}
			// 从收款计划中获取「首开尾」的首期款比例
			BigDecimal rate = collectionProgressConfigList.get(0).getContent().get(0).getRate();
			LOGGER.info("「首期款比例调整」从收款计划获取:{}", rate);
			return Collections.singletonList(OptionsVo.getByValue(rate));
		} else {
			// 未开城，设置为默认比例 20%
			LOGGER.info("「首期款比例调整」首期款比例功能未开城，返回默认值 20%");
			return Collections.singletonList(new OptionsVo(CollectionRateEnum.ZERO_TWO));
		}
	}

	private void fillDesignContractInfo(String projectOrderId, ContractProjectInfoDetail projectInfoDetail, Contract contract, Map<String, String> fieldMap) {
		//历史设计合同的设计服务费金额是直接存合同上的需特殊处理兼容
		if (ContractTypeEnum.DESIGN.getCode().equals(contract.getType()) && !fieldMap.containsKey("afterDiscountDesignerAmount") && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			projectInfoDetail.setAfterDiscountDesignerAmount(contract.getAmount());
		}

		fillDesignContractInfo(projectOrderId, projectInfoDetail, contract, contract.getType());
	}

	public void fillDesignContractInfo(String projectOrderId, ContractProjectInfoDetail projectInfoDetail, @Nullable Contract contract, Byte contractType) {
		// 如果是草稿状态的设计合同，需要实时带出设计师职级信息&标准设计服务费
		if (contract != null && !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			return;
		}

		// 全国设计费计算开城
		if (ContractTypeEnum.DESIGN_FEE_DESIGN_TYPES.contains(contractType) && contractUnifyService.designFeeCalculateIsOpen(projectOrderId)) {
			// 1、根据项目单号查询客源获取设计师ucId
			Long designerUcId = baseAuditChannel.queryProjectDesignerUcId(projectOrderId);

			// 2、根据设计师ucId请求服务者中心查询人员信息
			MidPersonBaseInfoDTO midPersonBaseInfoDTO = ceresRpc.getPersonInfo(designerUcId);

			String psLevelName = midPersonBaseInfoDTO.getPsLevelName();
			String designerLevelName = getDesignerLevelName(projectInfoDetail.getGbCode(), psLevelName);
			projectInfoDetail.setDesignerLevelName(designerLevelName);
			projectInfoDetail.setDesignerPsLevelName(psLevelName);
			// 设计服务费不再 detail 下发，前端手动查询
			return;
		}


		if ((ContractTypeEnum.DESIGN_FEE_DESIGN_TYPES.contains(contractType) && contractApolloConfig.getStandardDesignFeeCityCodes().contains(projectInfoDetail.getGbCode()))) {
			DesignSignPriceInfo designSignPriceInfo = ContractDetailContextHandler.getContext().getDesignSignPriceInfo();
			if (designSignPriceInfo == null) {
				throw new NrsBusinessException(ResponseCodeEnum.DESIGN_CONTRACT_LEVEL_TOAST.getCode(), ResponseCodeEnum.DESIGN_CONTRACT_LEVEL_TOAST.getMsg(), Level.WARN);
			}

			String psLevelName = designSignPriceInfo.getPsLevelName();
			String designerLevelName = contractApolloConfig.getDesignerLevelNameMap().get(psLevelName);
			if (StringUtils.isBlank(designerLevelName)) {
				throw new NrsBusinessException(ResponseCodeEnum.DESIGN_CONTRACT_LEVEL_TOAST.getCode(), ResponseCodeEnum.DESIGN_CONTRACT_LEVEL_TOAST.getMsg(), Level.WARN);
			}

			// 设计师职级名称
			projectInfoDetail.setDesigner(String.format("%s(%s)", designSignPriceInfo.getDesignerName(), designSignPriceInfo.getDesignerUserCode()));
			projectInfoDetail.setDesignerLevelName(designerLevelName);
			projectInfoDetail.setDesignerPsLevelName(psLevelName);

			// 上下文中没有获取到金额，但是有职级信息，说明从客源带入了面积，需要重新计算设计服务费
			if (!StringUtils.isBlank(projectInfoDetail.getArea())) {
				if (designSignPriceInfo.getStandardDesignFeeAmount() == null) {
					BudgetDesignFee designFeeConfig = quotationFeignService.getDesignFeeConfig(psLevelName, new BigDecimal(projectInfoDetail.getArea()));
					designSignPriceInfo.setStandardDesignFeeAmount(designFeeConfig.getDesignFee());
				}

				// 标准设计服务费
				projectInfoDetail.setPreDiscountDesignerAmount(designSignPriceInfo.getStandardDesignFeeAmount());
			}
		}
	}

	/**
	 * 根据城市Code和设计师职级获取职级中文名称
