	/**
	 * 承包约定信息
	 */
	public PromiseInfoDetail buildPromiseInfoDetail(Contract contract, Map<String, String> fieldMap, String projectOrderId, Byte contractType) {
		PromiseInfoDetail promiseInfoDetail = new PromiseInfoDetail();
		promiseInfoDetail.setConstructionDrawMode(
			StringUtils.isNotBlank(fieldMap.get("constructionDrawMode")) ? Integer.parseInt(fieldMap.get("constructionDrawMode")) : ConstructionDrawModeEnum.DELEGATE.getCode());
		promiseInfoDetail.setProjectContractModeCode(
			StringUtils.isNotBlank(fieldMap.get("projectContractModeCode")) ? Integer.parseInt(fieldMap.get("projectContractModeCode")) : ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS_V2.getCode());
		promiseInfoDetail.setBeforeDeliveryDaysToWork(
			StringUtils.isNotBlank(fieldMap.get("beforeDeliveryDaysToWork")) ? Integer.parseInt(fieldMap.get("beforeDeliveryDaysToWork")) : BeforeDeliveryDaysToWorkEnum.THIRTY.getCode());
		if (Objects.equals(promiseInfoDetail.getProjectContractModeCode(), ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS_V2.getCode())) {
			promiseInfoDetail.setTaxRate(9);
		}
		//获取有效的设计合同
		List<Contract> validContractList = contractService.getContractList(projectOrderId, ContractTypeEnum.DESIGN.getCode(), ContractStatusEnum.validStatusWithoutDraft);
		promiseInfoDetail.setNeedDesignerAmount(StringUtils.isNotBlank(fieldMap.get("needDesignerAmount")) ? Integer.parseInt(fieldMap.get("needDesignerAmount")) : CommonEnum.NO.getCode().intValue());
		if (CollectionUtil.isNotEmpty(validContractList)) {
			promiseInfoDetail.setNeedDesignerAmount(CommonEnum.NO.getCode().intValue());
		} else {
			promiseInfoDetail.setAfterDiscountDesignerAmount(StringUtils.isNotBlank(fieldMap.get("afterDiscountDesignerAmount")) ? new BigDecimal(fieldMap.get("afterDiscountDesignerAmount")) : BigDecimal.ZERO);
		}
		boolean processV25 = ContractDetailContextHandler.getContext().isProcessV25();
		Byte businessType = ContractDetailContextHandler.getContext().getBusinessType();
		// 团装2.5销售合同默认下发非杭州处理方式
		if (processV25 && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			promiseInfoDetail.setDisputeDealMode(DisputeDealModeEnum.COMMON.getCode());
		} else {
			promiseInfoDetail.setDisputeDealMode(DisputeDealModeEnum.HANGZHOU.getCode());
		}

		List<MaterialItemVo> materialItemVoList = new LinkedList<>();
		Map<Integer, MaterialOptionsVo> materialOptionsMap = contractApolloConfig.getMaterialOptionsMap();
		DesignQuoteFeeDTO designQuoteFeeDTO = ContractDetailContextHandler.getContext().getDesignQuoteFeeDTO();
		if (contract == null) {
			//todo 甲供材料清单枚举放代码中 @崔玉宝
			materialItemVoList.add(MaterialItemVo.builder().description("动力-电费（元）").value(1).categoryCode("basicFee").categoryName("基础费用").build());
			materialItemVoList.add(MaterialItemVo.builder().description("动力-水费（元）").value(2).categoryCode("basicFee").categoryName("基础费用").build());
			promiseInfoDetail.setMaterialList(materialItemVoList);
			if (contractUnifyService.designFeeFromQuote(projectOrderId) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
				if (ObjectUtil.isNotEmpty(designQuoteFeeDTO) && designQuoteFeeDTO.isHaveDesignQuote()) {
					promiseInfoDetail.setNeedDesignerAmount(1);
					promiseInfoDetail.setAfterDiscountDesignerAmount(designQuoteFeeDTO.getAfterDiscountDesignerAmount());
					promiseInfoDetail.setPreDiscountDesignerAmount(designQuoteFeeDTO.getPreDiscountDesignerAmount());
					promiseInfoDetail.setDesignerPsLevelName(designQuoteFeeDTO.getPsLevelName());
					ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
					promiseInfoDetail.setDesignerLevelName(getDesignerLevelName(projectInfoDTO.getCustomerHouse().getGbCode(), designQuoteFeeDTO.getPsLevelName()));
				} else {
					promiseInfoDetail.setNeedDesignerAmount(0);
				}
			}
			return promiseInfoDetail;
		}
		BeanUtil.fillBeanWithMap(fieldMap, promiseInfoDetail, true);
		if (contractUnifyService.designFeeFromQuote(projectOrderId) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
			if (ObjectUtil.isNotEmpty(designQuoteFeeDTO) && designQuoteFeeDTO.isHaveDesignQuote()) {
				promiseInfoDetail.setNeedDesignerAmount(1);
				promiseInfoDetail.setAfterDiscountDesignerAmount(designQuoteFeeDTO.getAfterDiscountDesignerAmount());
				promiseInfoDetail.setPreDiscountDesignerAmount(designQuoteFeeDTO.getPreDiscountDesignerAmount());
				promiseInfoDetail.setDesignerPsLevelName(designQuoteFeeDTO.getPsLevelName());
				ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
				promiseInfoDetail.setDesignerLevelName(getDesignerLevelName(projectInfoDTO.getCustomerHouse().getGbCode(), designQuoteFeeDTO.getPsLevelName()));
			} else {
				promiseInfoDetail.setNeedDesignerAmount(0);
			}

		}
		List<ContractMaterial> materialList = contractMaterialService.getListByContractCode(contract.getContractCode());
		for (ContractMaterial contractMaterial : materialList) {
			//起草中合同不返回自定义的材料信息;起草中合同不返回已删除的材料类型的材料信息
			if (ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()) && (0 == contractMaterial.getValue() || !materialOptionsMap.containsKey(
				contractMaterial.getValue()))) {
				continue;
			}
			materialItemVoList.add(MaterialItemVo.builder()
				.description(contractMaterial.getDescription())
				.count(contractMaterial.getCount())
				.value(contractMaterial.getValue())
				.unit(contractMaterial.getUnit())
				.categoryName(materialOptionsMap.get(contractMaterial.getValue()) == null ? null : materialOptionsMap.get(contractMaterial.getValue()).getCategoryName())
				.categoryCode(materialOptionsMap.get(contractMaterial.getValue()) == null ? null : materialOptionsMap.get(contractMaterial.getValue()).getCategoryCode())
				.build());
		}
		if (CollectionUtils.isEmpty(materialItemVoList)) {
			materialItemVoList.add(MaterialItemVo.builder().description("动力-电费（元）").value(1).categoryCode("basicFee").categoryName("基础费用").build());
			materialItemVoList.add(MaterialItemVo.builder().description("动力-水费（元）").value(2).categoryCode("basicFee").categoryName("基础费用").build());
		}
		promiseInfoDetail.setMaterialList(materialItemVoList);
		return promiseInfoDetail;
	}

