	/**
	 * 构建合同优惠信息详情
	 */
	public ActivityInfo buildActivityInfoDetail(List<String> moduleKeyList, String projectOrderId, String changeOrderId) {
		if (!moduleKeyList.contains(ContractModuleEnum.ACTIVITY_INFO.getKey())) {
			return null;
		}
		PlanAllDTO planAllDTO = ContractDetailContextHandler.getPlanAllDTO();
		ContractPlanAllDTO contractPlanAllDTO = new ContractPlanAllDTO(planAllDTO);
		ActivityInfo activityInfo = new ActivityInfo();
		if (planAllDTO != null) {
			if (planAllDTO.getPlanInfo() != null && planAllDTO.getPlanInfo().getQuotePrice() != null
				&& planAllDTO.getPlanInfo().getContractPriceTotal() != null) {
				BigDecimal lapseAmount = planAllDTO.getPlanInfo().getQuotePrice().subtract(planAllDTO.getPlanInfo().getContractPriceTotal());
				//优惠总金额
				activityInfo.setLapseAmount(lapseAmount);
			}
			if (!CollectionUtils.isEmpty(planAllDTO.getActivityList())) {
				ActivityDTO activity = planAllDTO.getActivityList().get(0);
				//活动名称
				activityInfo.setActivityName(activity.getActivityName());
				activityInfo.setActivityCode(activity.getActivityCode());
				//活动时间
				activityInfo.setActivityTime(activity.getActivityStartTimeStr().concat("~").concat(activity.getActivityEndTimeStr()));
				activityInfo.setActivityDesc(activity.getActivityDesc());
			}
			//优惠信息
			activityInfo.setCouponList(planAllDTO.getCouponList());
		}
		//套餐优惠
		activityInfo.setPackageModelName(contractPlanAllDTO.getPackageModelName());
		//券包内容
		activityInfo.setPackageContent(contractPlanAllDTO.getPackageContent());
		return activityInfo;
	}

	/**
	 * 构建合同报价信息详情
	 */
	public QuotationInfo buildQuotationDetail(List<String> moduleKeyList, String projectOrderId, String changeOrderId, Byte businessType, Byte contractType, Map<String, String> fieldMap) {
		if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			return null;
		}
		if (!moduleKeyList.contains(ContractModuleEnum.QUOTATION.getKey()) && StringUtils.isBlank(changeOrderId)) {
			return null;
		}
		//合同变更协议&合并发起的模式：如果变更范围不包括报价,则页面不展示报价信息
		if (!CollectionUtils.isEmpty(ContractDetailContextHandler.getAtomChangeScopeList()) &&
			!ContractDetailContextHandler.getAtomChangeScopeList().contains(ChangeScopeEnum.QUOTATION.getCode())) {
			return null;
		}
		//首期合同获取预报价信息
		if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
			if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
				//预报价信息
				return getPreQuotationInfo(projectOrderId, fieldMap);
			} else if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
				//合同草稿中获取信息
				return getRenovationQuotationInfo(projectOrderId, fieldMap);
			}
			return null;
		}
		PlanAllDTO planAllDTO = ContractDetailContextHandler.getPlanAllDTO();
		PlanInfoDTO planInfoDTO = planAllDTO.getPlanInfo();
		List<File> fileUrl = new ArrayList<>();
		List<File> internalConfigurationsFileUrl = new ArrayList<>();
		List<File> extraConfigurationsFileUrl = new ArrayList<>();
		List<File> personalQuotationFileUrl = new ArrayList<>();
		List<File> baseConstructionDrawFileUrl = new ArrayList<>();
		List<File> personalDrawFileUrl = new ArrayList<>();
		List<File> configurationsFileUrl = new ArrayList<>();
		String personalComboName = planInfoDTO.getComboName();
		if (!CollectionUtils.isEmpty(planAllDTO.getPlanAttachmentList())) {
			for (PlanAttachmentDTO planAttachmentDTO : planAllDTO.getPlanAttachmentList()) {
				switch (planAttachmentDTO.getFileType()) {
					case PlanAttachment.报价单:
						fileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
						break;
					case PlanAttachment.套餐套内配置清单:
						internalConfigurationsFileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
						break;
					case PlanAttachment.加载配置清单:
						extraConfigurationsFileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
						break;
					case PlanAttachment.套外个性化报价单:
						personalQuotationFileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
						break;
					case PlanAttachment.基础图纸:
						baseConstructionDrawFileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
						break;
					case PlanAttachment.个性化图纸:
						personalDrawFileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
						break;
					case PlanAttachment.商品清单:
						configurationsFileUrl.add(File.builder().url(planAttachmentDTO.getFileUrl()).previewUrl(planAttachmentDTO.getFileUrl()).build());
						break;
					default:
				}
			}
		}
		BigDecimal comboPrice = planInfoDTO.getComboPrice();
		BigDecimal personalTotalPrice = planInfoDTO.getPersonalTotalPrice();
		boolean processV25 = ContractDetailContextHandler.getContext().isProcessV25();
		//兼容团装历史数据
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && internalConfigurationsFileUrl.isEmpty() && !processV25) {
			internalConfigurationsFileUrl = fileUrl;
			comboPrice = planInfoDTO.getQuotePrice();
		}
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25) {
			//团装2.5图纸
			DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = ContractDetailContextHandler.getContext().getDrawingDTO();
			if (deliverDrawingDTO != null && !CollectionUtils.isEmpty(deliverDrawingDTO.getDrawingDetailDTOList())) {
				List<String> drawingList = deliverDrawingDTO.getDrawingDetailDTOList().stream()
					.filter(item -> ObjectUtil.equals(item.getExtensionType(), DrawingEnum.ConstructionFileExtensionEnum.PDF.getCode()))
					.filter(item -> ObjectUtil.equals(PlanAttachment.全屋图纸, item.getFileBizType()))
					.map(DrawingDTO.DrawingDetailDTO::getUrl)
					.collect(Collectors.toList());
				baseConstructionDrawFileUrl = drawingList.stream().map(item -> File.builder().url(item).previewUrl(item).build()).collect(Collectors.toList());
			}
		}
		BigDecimal discountAmount = Optional.ofNullable(planAllDTO.getCouponList()).orElse(Collections.emptyList()).stream()
			.filter(couponDTO -> CouponTypeEnum.DIRECT_COUPON.getCode().equals(couponDTO.getCouponType()))
			.map(CouponDTO::getLapseAmount)
			.findFirst()
			.orElse(null);
		return QuotationInfo.builder()
			//有用
			.comboCode(planInfoDTO.getComboCode())
			.comboName(planInfoDTO.getComboName())
			.contractPrice(planInfoDTO.getContractPriceTotal())
			.planTotalPrice(planInfoDTO.getNewestPlanPriceTotal())
			.pricingArea(getPricingArea())
			.remark(planInfoDTO.getRemark())
			.quotePrice(planInfoDTO.getQuotePrice())
			.quotationCompanyCode(planInfoDTO.getOrganizationCode())
			.quotationCompanyName(planInfoDTO.getOrganizationName())
			.fileUrl(fileUrl)
			.internalConfigurationsFileUrl(internalConfigurationsFileUrl)
			.baseConstructionDrawFileUrl(baseConstructionDrawFileUrl)
			.personalDrawFileUrl(personalDrawFileUrl)
			.extraConfigurationsFileUrl(extraConfigurationsFileUrl)
			.personalQuotionFileUrl(personalQuotationFileUrl)
			.houseLayout(Optional.ofNullable(planAllDTO).map(PlanAllDTO::getReconstructionHouseLayout)
				.map(HouseLayoutInfoDTO::getHouseLayoutDesc).orElse(null))
			.comboPrice(comboPrice)
			.personalTotalPrice(personalTotalPrice)
			.discountAmount(discountAmount)
			.configurationsFileUrl(configurationsFileUrl)
			.personalComboName(personalComboName)
			.build();
	}

	private String getPricingArea() {
		Byte businessType = ContractDetailContextHandler.getContext().getBusinessType();
		boolean processV25 = ContractDetailContextHandler.getContext().isProcessV25();
		if (!commonContractService.querySnapPlanInfoFromMainOrder(businessType, processV25)) {
			return Optional.ofNullable(ContractDetailContextHandler.getPlanAllDTO())
				.map(PlanAllDTO::getPlanInfo)
				.map(PlanInfoDTO::getPricingArea)
				.map(BigDecimal::toPlainString)
				.orElse("");
		}
		List<ComboDTO> comboDTOList = ContractDetailContextHandler.getContext().getComboDTOList();
		if (CollectionUtils.isEmpty(comboDTOList)) {
			return "";
		}
		return comboDTOList.stream().map(ComboDTO::getPricingArea).filter(Objects::nonNull).map(BigDecimal::toPlainString).collect(Collectors.joining(","));
	}


	/**
	 * 获取预报价信息
	 */
	public QuotationInfo getPreQuotationInfo(String projectOrderId, Map<String, String> fieldMap) {
		LightQuotationDTO.LightQuotationItem lightQuotationItem = ContractDetailContextHandler.getContext().getPreQuotationDTO();
		if (lightQuotationItem == null) {
			return null;
		}
		List<File> preQuotationFileUrl = new ArrayList<>();
		preQuotationFileUrl.add(File.builder().url(lightQuotationItem.getDecoratePdfFile()).build());
		// 判断fieldMap是否为空
		BigDecimal dbAdvanceAmount = null;
		BigDecimal advanceRate = null;
		if (!CollectionUtils.isEmpty(fieldMap)) {
			dbAdvanceAmount = fieldMap.get("advanceAmount") == null ? null : new BigDecimal(fieldMap.get("advanceAmount"));
			// 如果预估合同额数据库存的跟最新的不一致，不返回首期款金额，需要重新输入首期款金额
			BigDecimal dbExpectContractAmount = fieldMap.get("expectContractAmount") == null ? null : new BigDecimal(fieldMap.get("expectContractAmount"));
			if (dbAdvanceAmount != null && dbExpectContractAmount != null && dbExpectContractAmount.compareTo(lightQuotationItem.getHardTotalPrice()) != 0) {
				dbAdvanceAmount = null;
			}
			// 如果数据库里存有 advanceRate 字段，则取出
			advanceRate = fieldMap.get("advanceRate") == null ? null : new BigDecimal(fieldMap.get("advanceRate"));
		}
		ProjectInfoDTO projectInfoDTO = ContractDetailContextHandler.getProjectInfo();
		List<OptionsVo> advanceRates = getAdvanceRates(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), projectInfoDTO.getCustomerCommission().getCompanyCode());
		// 如果数据库里没有 advanceRate 值，则表明是新初始化的合同，从收款计划中获取
		if (advanceRate == null) {
			advanceRate = (BigDecimal) advanceRates.get(0).getValue();
		}
		return QuotationInfo.builder()
			.comboCode(lightQuotationItem.getComboBaseInfo().getComboCode())
			.comboName(lightQuotationItem.getComboBaseInfo().getComboName())
			.pricingArea(lightQuotationItem.getPricingArea() == null ? null : lightQuotationItem.getPricingArea().toPlainString())
			.expectContractAmount(lightQuotationItem.getHardTotalPrice())
			.preQuotationFileUrl(preQuotationFileUrl)
			.advanceAmount(dbAdvanceAmount)
			.advanceRates(advanceRates)
			.advanceRate(advanceRate)
			.build();
	}

	/**
	 * 获取翻新全案报价信息
	 */
	public QuotationInfo getRenovationQuotationInfo(String projectOrderId, Map<String, String> fieldMap) {
		ProjectInfoDTO projectInfoDTO = ContractDetailContextHandler.getProjectInfo();
		List<OptionsVo> advanceRates = getAdvanceRates(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), projectInfoDTO.getCustomerCommission().getCompanyCode());
		BigDecimal advanceRateConfig = (BigDecimal) advanceRates.get(0).getValue();
		if (CollectionUtil.isEmpty(fieldMap)) {
			return QuotationInfo.builder()
				.advanceRate(advanceRateConfig)
				.advanceRates(advanceRates)
				.build();
		} else {
			BigDecimal advanceRate = fieldMap.get("advanceRate") == null ? null : new BigDecimal(fieldMap.get("advanceRate"));
			if (advanceRate == null) {
				advanceRate = advanceRateConfig;
			}
			BigDecimal advanceAmount = fieldMap.get("advanceAmount") == null ? null : new BigDecimal(fieldMap.get("advanceAmount"));
			BigDecimal expectContractAmount = fieldMap.get("expectContractAmount") == null ? null : new BigDecimal(fieldMap.get("expectContractAmount"));
			String preQuotationFileUrlStr = fieldMap.get("preQuotationFileUrl") == null ? null : fieldMap.get("preQuotationFileUrl");
			//将String转换为报价单对应的结构
			List<File> preQuotationFileUrl = JSON.parseArray(preQuotationFileUrlStr, File.class);
			return QuotationInfo.builder()
				.advanceRate(advanceRate)
				.advanceAmount(advanceAmount)
				.expectContractAmount(expectContractAmount)
				.preQuotationFileUrl(preQuotationFileUrl)
				.advanceRates(advanceRates)
				.build();
		}
	}

