	public PersonalQuotation buildPersonalQuotationDetail(Contract contract, List<String> moduleKeyList, QuotationInfo quotationInfo, Byte contractType, Map<String, String> fieldMap) {
		if (!moduleKeyList.contains(ContractModuleEnum.PERSONAL_QUOTATION.getKey())) {
			return null;
		}
		List<ContractSourceDataBO.PersonalContractData> personalContractDataList =
			Optional.ofNullable(ContractDetailContextHandler.getContractSourceDataBO())
				.map(ContractSourceDataBO::getPersonalContractDataList)
				.orElseGet(ArrayList::new);
		BigDecimal personalTotalPrice = personalContractDataList.stream()
			.map(data -> data.getPersonalContractPrice() == null ? BigDecimal.ZERO : data.getPersonalContractPrice())
			.reduce(BigDecimal.ZERO, BigDecimal::add);
		String personalComboName = personalContractDataList.stream()
			.map(ContractSourceDataBO.PersonalContractData::getComboName)
			.filter(comboName -> comboName != null && !comboName.isEmpty()) // 过滤掉 null 和 空字符串
			.collect(Collectors.joining(","));
		List<File> personalFileUrlTemp = personalContractDataList.stream()
			.map(data -> {
				if (data.getQuoteInfo() != null) {
					return File.builder()
						.url(data.getQuoteInfo().getPrevUrl())
						.previewUrl(data.getQuoteInfo().getPrevUrl())
						.build();
				}
				return null;
			})
			.filter(Objects::nonNull) // 过滤掉 null
			.collect(Collectors.toList());
		List<File> personalDrawFileUrl = Optional.ofNullable(ContractDetailContextHandler.getContext())
			.map(ContractDetailContext::getDrawingDTO)
			.map(DrawingDTO.DeliverDrawingDTO::getDrawingDetailDTOList)
			.filter(CollectionUtil::isNotEmpty)
			.map(list -> list.stream()
				.map(DrawingDTO.DrawingDetailDTO::getUrl)
				.map(path -> File.builder().url(path).previewUrl(path).build())
				.collect(Collectors.toList()))
			.orElse(Collections.emptyList());

		String salesCompanyName = personalContractDataList.stream().map(ContractSourceDataBO.PersonalContractData::getOrganizationName).filter(StringUtils::isNotBlank)
			.distinct()
			.collect(Collectors.joining(","));

		PersonalQuotation personalQuotation = PersonalQuotation.builder()
			.personalQuotionFileUrl(personalFileUrlTemp)
			.personalTotalPrice(personalTotalPrice)
			.personalDrawFileUrl(personalDrawFileUrl)
			.personalComboName(personalComboName)
			.build();
		personalQuotation.setSalesCompanyName(salesCompanyName);
		return personalQuotation;
	}

	/**
	 * 当前合同是否是重签
	 */
	private boolean reSign(String projectOrderId, Byte contractType) {
		if (ContractTypeEnum.isAllowMultipleLaunch(contractType)) {
			return false;
		}
		List<Contract> contractList = contractService.getContractList(projectOrderId, contractType);
		if (CollectionUtils.isEmpty(contractList)) {
			return false;
		}
		List<Integer> finalContractStatus = Arrays.asList(ContractStatusEnum.USER_CONFIRMED.getCode(), ContractStatusEnum.FINISH.getCode());
		List<Contract> contractListFilter = contractList.stream().filter(item -> finalContractStatus.contains(item.getStatus()))
			.collect(Collectors.toList());
		return !CollectionUtils.isEmpty(contractListFilter);
	}

