	/**
	 * 根据备件信息初始化合同备件信息
	 */
	private void dealContractAttachFromAttachInfo(ContractAttachInfoDetail contractAttachInfo, List<ContractAttach> contractAttachList) {
		//如果合同备件信息有值，则不需要从备件信息中获取
		if (!CollectionUtils.isEmpty(contractAttachList)) {
			return;
		}
		AttachInfoDetail attachInfoDetail = ContractDetailContextHandler.getContext().getAttachInfoDetail();
		if (attachInfoDetail == null || !attachInfoDetail.isUpload()) {
			return;
		}
		List<File> userCertificateUnify = attachInfoDetail.getIdentityInfo().getUserCertificateUnify();
		List<File> agentCertificateUnify = attachInfoDetail.getIdentityInfo().getAgentCertificateUnify();
		List<File> agentCertificate = attachInfoDetail.getIdentityInfo().getAgentCertificate();
		List<File> companyAgentCertificateUnify = attachInfoDetail.getIdentityInfo().getCompanyAgentCertificateUnify();
		List<File> companyLicense = attachInfoDetail.getIdentityInfo().getCompanyLicense();
		List<File> houseCertificate = attachInfoDetail.getHouseInfo().getHouseCertificate();
		List<File> legalCertificateUnify = attachInfoDetail.getIdentityInfo().getLegalCertificateUnify();
		contractAttachInfo.setUserCertificateUnify(CollectionUtils.isEmpty(userCertificateUnify) ? Lists.emptyList() : userCertificateUnify);
		contractAttachInfo.setAgentCertificateUnify(CollectionUtils.isEmpty(agentCertificateUnify) ? Lists.emptyList() : agentCertificateUnify);
		contractAttachInfo.setAgentCertificate(CollectionUtils.isEmpty(agentCertificate) ? Lists.emptyList() : agentCertificate);
		contractAttachInfo.setCompanyAgentCertificateUnify(CollectionUtils.isEmpty(companyAgentCertificateUnify) ? Lists.emptyList() : companyAgentCertificateUnify);
		contractAttachInfo.setCompanyLicense(CollectionUtils.isEmpty(companyLicense) ? Lists.emptyList() : companyLicense);
		contractAttachInfo.setHouseCertificate(CollectionUtils.isEmpty(houseCertificate) ? Lists.emptyList() : houseCertificate);
		contractAttachInfo.setLegalCertificateUnify(CollectionUtils.isEmpty(legalCertificateUnify) ? Lists.emptyList() : legalCertificateUnify);

		CopyOptions copyOptions = CopyOptions.create().ignoreNullValue();
		BeanUtil.copyProperties(attachInfoDetail.getIdentityInfo(), contractAttachInfo, copyOptions);
		BeanUtil.copyProperties(attachInfoDetail.getHouseInfo(), contractAttachInfo, copyOptions);
		contractAttachInfo.setFirstLaneSyncAttachMap(attachInfoDetail.getFirstLaneSyncAttachMap());
	}

	/**
	 * 从前一个项目初始化合同备件信息
	 */
	private void dealContractAttachFromPreProject(ContractAttachInfoDetail contractAttachInfo, String projectOrderId, Byte contractType) {
		if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			return;
		}
		if (attachCommonService.attachOcrOpenCity(projectOrderId) && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(ContractDetailContextHandler.getContext().getBusinessType())) {
			//如果是备件ocr开城城市，则不需要从前一个项目获取合同备件信息
			return;
		}
		String previousOrderNo = commonBusinessService.getPreviousOrderNo(projectOrderId);
		if (StringUtils.isBlank(previousOrderNo)) {
			return;
		}
		Contract latestContract = contractService.getLatestContract(previousOrderNo, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		if (latestContract == null || !ContractStatusEnum.inEndStatus(latestContract.getStatus())) {
			return;
		}
		List<ContractAttach> contractAttachList = contractAttachService.getListByContractCode(latestContract.getContractCode());
		//处理contractAttachList，根据备件id获取对应的备件url
		attachCommonService.getUrlFromContractAttachList(latestContract.getProjectOrderId(), contractAttachList);
		List<ContractField> contractFieldList = contractFieldService.getListByContractCode(latestContract.getContractCode());
		Map<String, String> fieldMap = Maps.newHashMap();
		contractFieldList.forEach(contractField -> fieldMap.put(contractField.getFieldKey(), contractField.getFieldValue()));
		BeanUtil.fillBeanWithMap(fieldMap, contractAttachInfo, true);
		for (ContractAttach contractAttach : contractAttachList) {
			Byte attachType = contractAttach.getAttachType();
			if (AttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
				contractAttachInfo.getUserCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.HOUSE_CERTIFICATE.getCode().equals(attachType)) {
				contractAttachInfo.getHouseCertificate().add(File.builder().certificateId(contractAttach.getCertificateId())
					.documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
				contractAttachInfo.getAgentCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.AGENT_CERTIFICATE.getCode().equals(attachType)) {
				contractAttachInfo.getAgentCertificate().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.OTHER.getCode().equals(attachType)) {
				contractAttachInfo.getOther().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.COMPANY_LICENSE.getCode().equals(attachType)) {
				contractAttachInfo.getCompanyLicense().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
				contractAttachInfo.getCompanyAgentCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.LEGAL_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
				contractAttachInfo.getLegalCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			if (AttachTypeEnum.OTHER_OWNER_SHIP.getCode().equals(attachType)) {
				contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
		}
		//团装2.5房屋权属证明类型为【其他权属证明】
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(ContractDetailContextHandler.getContext().getBusinessType())
			&& ContractDetailContextHandler.getContext().isProcessV25()) {
			contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
		}
	}


	/**
	 * 根据备件信息初始化合同签约信息
	 */
	private void dealSignInfoFromAttachInfo(ContractSignInfoDetail signInfoDetail) {
		AttachInfoDetail attachInfoDetail = ContractDetailContextHandler.getContext().getAttachInfoDetail();
		if (attachInfoDetail == null || !attachInfoDetail.isUpload()) {
