	if (!CollectionUtils.isEmpty(contractAttachInfoDetail.getDeedTicket())) {
		String documentCode = contractAttachInfoDetail.getDeedTicket().get(0).getDocumentCode();
		signInfoDetail.setDeedTicketDocumentCode(documentCode);
	}
	if (!CollectionUtils.isEmpty(contractAttachInfoDetail.getSpecialHouse())) {
		String documentCode = contractAttachInfoDetail.getSpecialHouse().get(0).getDocumentCode();
		signInfoDetail.setSpecialHouseDocumentCode(documentCode);
	}
	if (!CollectionUtils.isEmpty(contractAttachInfoDetail.getCompanyLicense())) {
		String documentCode = contractAttachInfoDetail.getCompanyLicense().get(0).getDocumentCode();
		signInfoDetail.setCompanyLicenseDocumentCode(documentCode);
	}
	if (!CollectionUtils.isEmpty(contractAttachInfoDetail.getAgentCertificate())) {
		String documentCode = contractAttachInfoDetail.getAgentCertificate().get(0).getDocumentCode();
		signInfoDetail.setAgentCertificateDocumentCode(documentCode);
	}
	if (!CollectionUtils.isEmpty(contractAttachInfoDetail.getOther())) {
		String documentCode = contractAttachInfoDetail.getOther().get(0).getDocumentCode();
		signInfoDetail.setOtherDocumentCode(documentCode);
	}
	if (!CollectionUtils.isEmpty(contractAttachInfoDetail.getGroupTerminalCertificate())) {
		String documentCode = contractAttachInfoDetail.getGroupTerminalCertificate().get(0).getDocumentCode();
		signInfoDetail.setGroupTerminalCertificateDocumentCode(documentCode);
	}
	if (!CollectionUtils.isEmpty(contractAttachInfoDetail.getUserCertificateUnify())) {
		List<String> documentCodes = contractAttachInfoDetail.getUserCertificateUnify().stream().map(File::getDocumentCode).collect(Collectors.toList());
		signInfoDetail.setUserCertificateUnifyDocumentCode(IdentityCardInfo.buildIdentityCardInfoByDocumentCodes(documentCodes));
	}
	if (!CollectionUtils.isEmpty(contractAttachInfoDetail.getAgentCertificateUnify())) {
		List<String> documentCodes = contractAttachInfoDetail.getAgentCertificateUnify().stream().map(File::getDocumentCode).collect(Collectors.toList());
		signInfoDetail.setAgentCertificateUnifyDocumentCode(IdentityCardInfo.buildIdentityCardInfoByDocumentCodes(documentCodes));
