public BusinessInfoDetail buildBusinessInfoDetail(Contract contract, ContractProjectInfoDetail projectInfoDetail, Map<String, String> fieldMap, List<BillCodeInfo> billCodeInfoList, List<SubOrderInfo> subOrderInfoList, List<ChangeOrderInfo> changeOrderInfoList) {
	List<ChangeListDTO> changeOrderList = ContractDetailContextHandler.getContext().getChangeOrderList();
	if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
		// 如果是草稿态、待签署、待确认 则需要实时更新报价单列表
		List<Integer> allowSubmitStatus = Arrays.asList(ContractStatusEnum.DRAFT.getCode(), ContractStatusEnum.PENDING_USER_CONFIRM.getCode(), ContractStatusEnum.PENDING_USER_SIGN.getCode());
		if (allowSubmitStatus.contains(contract.getStatus())) {
			if (ContractDetailContextHandler.getContractSourceDataBO() != null && CollectionUtil.isNotEmpty(ContractDetailContextHandler.getContractSourceDataBO().getPersonalContractDataList())) {
				List<ContractSourceDataBO.PersonalContractData> personalContractDataList = ContractDetailContextHandler.getContractSourceDataBO().getPersonalContractDataList();
				BindOrderInfoGroup group = BindOrderInfo.convert(contract.getProjectOrderId(), personalContractDataList);
				billCodeInfoList = group.getBillCodeInfos();
				changeOrderInfoList = group.getChangeOrderInfos();
				subOrderInfoList = group.getSubOrderInfos();
			}
		}
	}
	//如果是初审驳回或者存在复审的合同，返回最新的变更单号
	String projectChangeNo = null;
	if (CollectionUtil.isNotEmpty(changeOrderList)) {
		ChangeListDTO changeListDTO = changeOrderList.stream().filter(m -> FirstChangeReasonEnum.正签方案变更.getReasonId().equals(m.getFirstChangeReason()))
			.filter(m -> SecondChangeReasonEnum.风控审核驳回.getReasonId().equals(m.getSecondChangeReason()))
			.findFirst().orElse(null);
		if (changeListDTO != null) {
			projectChangeNo = changeListDTO.getProjectChangeNo();
		}
	}

	//处理品类信息&商品信息
	List<BrandInfo> brandInfoList = fieldMap.get("brandList") == null ? new ArrayList<>() : JSON.parseArray(fieldMap.get("brandList"), BrandInfo.class);
	String goodsInfo = fieldMap.get("goodsInfo") == null ? "" : fieldMap.get("goodsInfo");
	String decorateType = ObjectUtil.isEmpty(projectInfoDetail) ? "" : StrUtil.join("-",
		// 允许 level1 为空
		StrUtil.blankToDefault(projectInfoDetail.getDecorateFormLevel1Text(), null),
		StrUtil.blankToDefault(projectInfoDetail.getDecorateFormLevel2Text(), null)
	).trim();
	return BusinessInfoDetail.builder()
		.decorateType(decorateType)
		.fundName(fieldMap.get("fundName"))
		.brandList(brandInfoList)
		.projectChangeNo(projectChangeNo)
		.billCodeList(BillCodeInfo.getBillCodeList(billCodeInfoList))
		.billCodeInfoList(billCodeInfoList)
		.changeOrderInfoList(changeOrderInfoList)
		.subOrderInfoList(subOrderInfoList)
		.goodsInfo(goodsInfo)
		.build();
}

public ContractBaseInfoDetail buildContractBaseInfoDetail(Contract contract, String projectOrderId, Byte contractType, String changeOrderId, Map<String, String> fieldMap, Boolean isFirstScreen) {
	ContractBaseInfoDetail baseInfoDetail = new ContractBaseInfoDetail();
	baseInfoDetail.setChangeOrderId(changeOrderId);
	baseInfoDetail.setAttachOcrOpenCity(attachCommonService.attachOcrOpenCity(projectOrderId));
	baseInfoDetail.setNeedLaunchRelationTerminalContract(contractBusinessService.needLaunchOrLaunchedTerminalContract(projectOrderId));
	PlanAllDTO planAllDTO = ContractDetailContextHandler.getContractSourceDataBO().getPlanAllDTO();
	boolean processV25 = ContractDetailContextHandler.getContext().isProcessV25();
	Byte businessType = ContractDetailContextHandler.getContext().getBusinessType();
	baseInfoDetail.setFormalMergeLaunch(processV25);
	baseInfoDetail.setProcessV25(processV25);
	// 从项目信息获取城市编码
	ProjectInfoDTO projectInfo = ContractDetailContextHandler.getProjectInfo();
	Integer gbCode = projectInfo.getCustomerHouse().getGbCode();

	baseInfoDetail.setContractTypeName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contractType, businessType));
	baseInfoDetail.setDurationCalculateIsOpen(contractApolloConfig.durationCalculateIsOpen(gbCode));
	baseInfoDetail.setUseAddressFromDictionary(contractApolloConfig.useAddressFromDictionary(businessType, gbCode));
	baseInfoDetail.setNewMaterialModeOpen(contractApolloConfig.getNewMaterialModeOpen());
	baseInfoDetail.setNeedRealNameVerifyInConfirm(contractApolloConfig.getNeedRealNameVerifyInConfirmContractTypes().contains(contractType));
	baseInfoDetail.setFormalUseNewProcess(contractBusinessService.formalUseNewProcess(businessType, processV25, gbCode));
	baseInfoDetail.setSupplementIsOpen(contractUnifyService.supplementIsOpen(projectOrderId));
	//设计费标准开城
	if (ContractTypeEnum.DESIGN_FEE_PACKAGE_TYPES.contains(contractType) || ContractTypeEnum.DESIGN_FEE_DESIGN_TYPES.contains(contractType)) {
		baseInfoDetail.setStandardDesignFeeOpen(contractUnifyService.designFeeCalculateIsOpen(projectOrderId));
	}

	//设计费正式包信息返回
	if (contractUnifyService.designFeeFromQuote(projectOrderId) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		DesignQuoteFeeDTO designQuoteFeeDTO = ContractDetailContextHandler.getContext().getDesignQuoteFeeDTO();
		baseInfoDetail.setHaveDesignQuote(designQuoteFeeDTO.isHaveDesignQuote());
		MiniPayChannelAppNameEnum miniProgramType = commonBusinessService.getMiniProgramType(projectOrderId);
		baseInfoDetail.setMiniProgramType(miniProgramType != null ? miniProgramType.getMiniProgramType() : null);
		baseInfoDetail.setMergeDesignContract(designQuoteFeeDTO.isHaveDesignQuote() && MiniPayChannelAppNameEnum.被窝.equals(miniProgramType));
	}
	// 设计合同和设计变更合同
	boolean mergeLaunchDesignContract = contractUnifyService.isMergeLaunchDesignContract(projectOrderId);
	if (mergeLaunchDesignContract && ContractTypeEnum.DESIGN_FEE_DESIGN_TYPES.contains(contractType)) {
		baseInfoDetail.setHaveDesignQuote(Boolean.TRUE);
	}
	baseInfoDetail.setDesignAmountSourceType((ContractTypeEnum.DESIGN.getCode().equals(contractType) || ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contractType) || (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && baseInfoDetail.isHaveDesignQuote()) ) && contractApolloConfig.getStandardDesignFeeCityCodes().contains(gbCode) ?
		ContractFieldSourceTypeEnum.AREA_CALCULATE.getSourceType() : ContractFieldSourceTypeEnum.INPUT.getSourceType());
	if (contract == null) {
		// 有已签署/已确认的同一主体个性化合同，不发起B+C
		if (!isFirstScreen && Objects.equals(ContractTypeEnum.PACKAGE_FORMAL.getCode(), contractType)) {
			String organizationCode = planAllDTO.getPlanInfo().getOrganizationCode();
			Contract personalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PERSONAL.getCode()).stream()
				.filter(item -> ContractStatusEnum.validStatusWithoutDraft.contains(item.getStatus()))
				.filter(m -> m.getCompanyCode().equals(organizationCode))
				.findFirst()
				.orElse(null);
			List<ContractSourceDataBO.PersonalContractData> personalContractDataList = ContractDetailContextHandler.getContext().getContractSourceDataBO().getPersonalContractDataList();
			baseInfoDetail.setHavePersonalQuote(!CollectionUtils.isEmpty(personalContractDataList));
			baseInfoDetail.setContractMode(getInitDetailContractMode(personalContract, gbCode));
		}
		baseInfoDetail.setProjectOrderId(projectOrderId);
		baseInfoDetail.setContractType(contractType);
		baseInfoDetail.setStatus(ContractStatusEnum.DRAFT.getCode());
		baseInfoDetail.setReSign(reSign(projectOrderId, contractType));
		//是否支持公对公协议
		baseInfoDetail.setSupportCompanyOnlineSign(openCompanySignOnlineForDetail(projectOrderId, isFirstScreen, contractType));
		//是否全案签约开城
		baseInfoDetail.setSupportFullServiceSign(commonContractService.supportFullServiceSign(gbCode, businessType));
		return baseInfoDetail;
	} else {
		String contractMode = fieldMap.get(ContractBaseInfoReq.Fields.contractMode);
		baseInfoDetail.setContractMode(StringUtils.isNotBlank(contractMode) ? Integer.valueOf(contractMode) : null);
		baseInfoDetail.setProjectOrderId(contract.getProjectOrderId());
		baseInfoDetail.setContractType(contract.getType());
		baseInfoDetail.setContractCode(contract.getContractCode());
		baseInfoDetail.setStatus(contract.getStatus());
		if (processV25 && (contract.getType().equals(ContractTypeEnum.PACKAGE_FORMAL.getCode()) || contract.getType().equals(ContractTypeEnum.PERSONAL.getCode()))) {
			List<RelateContract> relateContractList = homeAndPcCommonService.getRelateContractList(contract);
			baseInfoDetail.setRelateContracts(relateContractList);
			ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
			baseInfoDetail.setPrimaryRelatedContractCode(contractRelation != null ? contractRelation.getContractCode() : null);
			List<ContractSourceDataBO.PersonalContractData> personalContractDataList = ContractDetailContextHandler.getContext().getContractSourceDataBO().getPersonalContractDataList();
			baseInfoDetail.setHavePersonalQuote(!CollectionUtils.isEmpty(personalContractDataList));
		}
	}
	//设置当前合同是否是重签
	baseInfoDetail.setReSign(reSign(projectOrderId, contractType));
	if (ObjectUtil.isNotEmpty(changeOrderId)) {
		ChangeOrderBaseInfoDTO changeOrderBaseInfoDTO = changeOrderService.getByChangeOrderId(changeOrderId);
		if (ObjectUtil.isNotEmpty(changeOrderBaseInfoDTO)) {
			baseInfoDetail.setChangeOrderType(changeOrderBaseInfoDTO.getChangeOrderType().getCode());
		}
	}
	//获取合同链接
	baseInfoDetail.setContractUrl(getContractUrlInfo(contract));
	//是否支持公对公协议
	baseInfoDetail.setSupportCompanyOnlineSign(openCompanySignOnlineForDetail(projectOrderId, isFirstScreen, contractType));
	//是否全案签约开城
	baseInfoDetail.setSupportFullServiceSign(commonContractService.supportFullServiceSign(gbCode, businessType));

	return baseInfoDetail;
}

private Integer getInitDetailContractMode(Contract personalContract, Integer gbCode) {
	Byte businessType = ContractDetailContextHandler.getContext().getBusinessType();
	ContractSourceDataBO contractSourceDataBO = ContractDetailContextHandler.getContractSourceDataBO();
	//开城+有个性化报价+不存在个性化合同
	Integer contractMode = null;
	boolean noSignPersonalContract = personalContract == null;
	int multiplePersonalQuoteSize = commonContractService.haveMultiplePersonalQuoteSize(contractSourceDataBO);
	boolean supportFullService = contractApolloConfig.getFullServiceOpenCityList().contains(gbCode);
	if (noSignPersonalContract && multiplePersonalQuoteSize == 1 && supportFullService && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
		contractMode = ContractModeEnum.FULL_SERVICE.getCode();
	}
	return contractMode;
}

private List<FileInfo> getContractUrlInfo(Contract contract) {
	List<FileInfo> contractUrl = new ArrayList<>();
	if (contract == null) {
		return contractUrl;
	}
	//判断是否线上签约
	if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
		//线上签约
		String onlineContractUrl = homeAndPcCommonService.getContractUrl(contract);
		if (StringUtils.isNotBlank(onlineContractUrl)) {
			contractUrl.add(FileInfo.builder()
				.type(FileTypeEnum.PDF.getKey())
				.contractType(contract.getType())
				.url(onlineContractUrl).build());
		}
	} else {
		//线下
		List<String> attachUrlList = homeAndPcCommonService.getAttachUrl(contract);
		String attachFileKey = contractBusinessService.getAttachFileKey(attachUrlList);
		attachUrlList.forEach(attachUrl -> {
			contractUrl.add(FileInfo.builder()
				.type(attachFileKey)
				.contractType(contract.getType())
				.url(attachUrl).build());
		});
	}
	return contractUrl;
}

public ProcessInfo buildProcessInfoDetail(@Nullable Contract contract) {
	try {
		// 如果没有合同 初始化状态不返回流程信息
		if (contract == null) {
			return null;
		}

		// 如果非正签合同 不返回流程信息
		if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
			return null;
		}

		// 如果整装模式 不返回流程信息
		if (!BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType())) {
			return null;
		}


		// 如果非已签署状态 不返回流程信息
		if (!ContractStatusEnum.FINISH.getCode().equals(contract.getStatus())) {
			return null;
		}

		ProcessInfo processInfo = new ProcessInfo();
		AuditDetailDto auditDetailDTO = Optional.ofNullable(ContractDetailContextHandler.getContext()).map(ContractDetailContext::getAuditDetailDTO)
			.orElse(auditRpc.getAuditInfo(contract.getProjectOrderId()));
		List<ChangeListDTO> changeOrderList = Optional.ofNullable(ContractDetailContextHandler.getContext()).map(ContractDetailContext::getChangeOrderList)
			.orElse(atomChangeRpc.getChangeList(contract.getProjectOrderId()));

		// 没有查询到审核信息 不返回流程信息
		if (auditDetailDTO == null) {
			return null;
		}

		Integer processAuditStatus = computeProcessStatus(auditDetailDTO, changeOrderList);
		LOGGER.info("计算流程状态:{}", processAuditStatus);

		// 说明变更单状态没有匹配到，不返回流程信息
		if (processAuditStatus == null) {
			return null;
		}

		// 构造流程节点
		processInfo.setCurrentNodeId(processAuditStatus.toString());
		processInfo.setNodeList(buildProcessInfoNodeList(processAuditStatus, auditDetailDTO, changeOrderList));
		processInfo.setStatus(processAuditStatus);
		processInfo.setLabelText(buildProcessInfoLabText(processAuditStatus, auditDetailDTO));
		processInfo.setTips(buildProcessInfoTips(processAuditStatus, auditDetailDTO));
		processInfo.setAuditFinishNodeDesc(processInfo.getNodeList().stream().filter(node -> ProcessNodeTypeEnum.DONE.getNodeType().toString().equals(node.getNodeId())).findFirst()
			.map(ProcessInfo.Node::getNodeDesc).orElse(null));
		processInfo.setChangeOrderDetailSchema(buildChangeOrderDetailSchema(processAuditStatus, contract.getProjectOrderId(), changeOrderList, auditDetailDTO.getAuditStatus()));
		return processInfo;
	} catch (Exception e) {
		LOGGER.error("构造合同流程信息异常，合同code：{}", contract.getContractCode(), e);
	}
	return null;
}

private String buildChangeOrderDetailSchema(Integer processAuditStatus, String projectOrderId, List<ChangeListDTO> changeOrderList, Integer auditStatus) {
	if (Arrays.asList(ProcessStatusEnum.AUDIT_REVIEW.getStatus(), ProcessStatusEnum.AUDIT_REVIEW_PASS.getStatus(), ProcessStatusEnum.AUDIT_REJECT.getStatus()).contains(processAuditStatus)) {
		List<ChangeListDTO> auditRejectChangeOrderList = getAuditRejectChangeOrder(changeOrderList);
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
		// /home-saas-25/pages/changeProcess/changeDetail?projectOrderId=项目单号&projectChangeNo=变更单号&customerCommissionCode=客源code
		return commonApolloConfig.getStewardDomain() +
			String.format("/home-saas-25/pages/changeProcess/changeDetail?projectOrderId=%s&projectChangeNo=%s&customerCommissionCode=%s",
				projectOrderId, auditRejectChangeOrderList.get(0).getProjectChangeNo(), projectInfoDTO.getCustomerCommission().getCustomerCommissionCode());
	}

	return null;
}

private String buildProcessInfoTips(Integer processAuditStatus, AuditDetailDto auditDetailDTO) {
	ProcessStatusEnum processStatusEnum = ProcessStatusEnum.getByStatus(processAuditStatus);
	if (processStatusEnum == null) {
		return null;
	}

	String waitAuditDesc = "";
	if (auditDetailDTO != null && !Optional.ofNullable(auditDetailDTO.getAuditUserName()).orElse("").isEmpty()
		&& !Optional.ofNullable(auditDetailDTO.getAuditUserCode()).orElse("").isEmpty()) {
		waitAuditDesc = "，审核人：" + auditDetailDTO.getAuditUserName() + "（" + auditDetailDTO.getAuditUserCode() + "）";
	}

	switch (processStatusEnum) {
		case WAIT_AUDIT:
			if (auditDetailDTO != null && AuditStatusEnum.WAIT_DISTRIBUTE.getValue() == auditDetailDTO.getAuditStatus()) {
				return "风控待审核：待分配审核员，了解进度联系城市ssc中台";
			}
			return "风控审核状态：待审核" + waitAuditDesc;
		case AUDITING:
			return "风控审核状态：待审核" + waitAuditDesc;
		case AUDIT_REJECT:
		case AUDIT_REVIEW:
		case AUDIT_REVIEW_PASS:
			return "正签审核驳回自动发起变更，可查看进度";
		default:
			return null;
	}
}

private String buildProcessInfoLabText(Integer processAuditStatus, AuditDetailDto auditDetailDTO) {
	ProcessStatusEnum processStatusEnum = ProcessStatusEnum.getByStatus(processAuditStatus);
	if (processStatusEnum == null) {
		return null;
	}

	switch (processStatusEnum) {
		case WAIT_AUDIT:
		case AUDITING:
			return "风控待审核";
		case AUDIT_REJECT:
			if (AuditStatusEnum.WAIT_DISTRIBUTE.getValue() == auditDetailDTO.getAuditStatus() || AuditStatusEnum.WAIT_CHECK.getValue() == auditDetailDTO.getAuditStatus()
				|| AuditStatusEnum.CHECKING.getValue() == auditDetailDTO.getAuditStatus()) {
				return "风控复审中";
			}

			return "风控审核驳回";
		case AUDIT_REVIEW:
		case AUDIT_REVIEW_PASS:
			return "风控复审中";
		case AUDIT_PASS:
		case DONE:
			return "风控审核完成";
		default:
			return null;
	}
}

