public ActivityInfo buildActivityInfoDetail(List<String> moduleKeyList, String projectOrderId, String changeOrderId) {
	if (!moduleKeyList.contains(ContractModuleEnum.ACTIVITY_INFO.getKey())) {
		return null;
	}
	PlanAllDTO planAllDTO = ContractDetailContextHandler.getPlanAllDTO();
	ContractPlanAllDTO contractPlanAllDTO = new ContractPlanAllDTO(planAllDTO);
	ActivityInfo activityInfo = new ActivityInfo();
	if (planAllDTO != null) {
		if (planAllDTO.getPlanInfo() != null && planAllDTO.getPlanInfo().getQuotePrice() != null
			&& planAllDTO.getPlanInfo().getContractPriceTotal() != null) {
			BigDecimal lapseAmount = planAllDTO.getPlanInfo().getQuotePrice().subtract(planAllDTO.getPlanInfo().getContractPriceTotal());
			//优惠总金额
			activityInfo.setLapseAmount(lapseAmount);
		}
		if (!CollectionUtils.isEmpty(planAllDTO.getActivityList())) {
			ActivityDTO activity = planAllDTO.getActivityList().get(0);
			//活动名称
			activityInfo.setActivityName(activity.getActivityName());
			activityInfo.setActivityCode(activity.getActivityCode());
			//活动时间
			activityInfo.setActivityTime(activity.getActivityStartTimeStr().concat("~").concat(activity.getActivityEndTimeStr()));
			activityInfo.setActivityDesc(activity.getActivityDesc());
		}
		//优惠信息
		activityInfo.setCouponList(planAllDTO.getCouponList());
	}
	//套餐优惠
	activityInfo.setPackageModelName(contractPlanAllDTO.getPackageModelName());
	//券包内容
	activityInfo.setPackageContent(contractPlanAllDTO.getPackageContent());
	return activityInfo;
}

public QuotationInfo buildQuotationDetail(List<String> moduleKeyList, String projectOrderId, String changeOrderId, Byte businessType, Byte contractType, Map<String, String> fieldMap) {
	if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
		return null;
	}
	if (!moduleKeyList.contains(ContractModuleEnum.QUOTATION.getKey()) && StringUtils.isBlank(changeOrderId)) {
		return null;
	}
	//合同变更协议&合并发起的模式：如果变更范围不包括报价,则页面不展示报价信息
	if (!CollectionUtils.isEmpty(ContractDetailContextHandler.getAtomChangeScopeList()) &&
		!ContractDetailContextHandler.getAtomChangeScopeList().contains(ChangeScopeEnum.QUOTATION.getCode())) {
		return null;
	}
	//首期合同获取预报价信息
	if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			//预报价信息
			return getPreQuotationInfo(projectOrderId, fieldMap);
		} else if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
			//合同草稿中获取信息
			return getRenovationQuotationInfo(projectOrderId, fieldMap);
		}
		return null;
	}
	PlanAllDTO planAllDTO = ContractDetailContextHandler.getPlanAllDTO();
	PlanInfoDTO planInfoDTO = planAllDTO.getPlanInfo();
	List<File> fileUrl = new ArrayList<>();
	List<File> internalConfigurationsFileUrl = new ArrayList<>();
	List<File> extraConfigurationsFileUrl = new ArrayList<>();
	List<File> personalQuotationFileUrl = new ArrayList<>();
	List<File> baseConstructionDrawFileUrl = new ArrayList<>();
	List<File> personalDrawFileUrl = new ArrayList<>();
	List<File> configurationsFileUrl = new ArrayList<>();
	String personalComboName = planInfoDTO.getComboName();
	if (!CollectionUtils.isEmpty(planAllDTO.getPlanAttachmentList())) {
		for (PlanAttachmentDTO planAttachmentDTO : planAllDTO.getPlanAttachmentList()) {
			switch (planAttachmentDTO.getFileType()) {
				case PlanAttachment.报价单:
					fileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
					break;
				case PlanAttachment.套餐套内配置清单:
					internalConfigurationsFileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
					break;
				case PlanAttachment.加载配置清单:
					extraConfigurationsFileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
					break;
				case PlanAttachment.套外个性化报价单:
					personalQuotationFileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
					break;
				case PlanAttachment.基础图纸:
					baseConstructionDrawFileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
					break;
				case PlanAttachment.个性化图纸:
					personalDrawFileUrl.add(File.builder().url(planAttachmentDTO.getPrevUrl()).previewUrl(planAttachmentDTO.getPrevUrl()).build());
					break;
				case PlanAttachment.商品清单:
					configurationsFileUrl.add(File.builder().url(planAttachmentDTO.getFileUrl()).previewUrl(planAttachmentDTO.getFileUrl()).build());
					break;
				default:
			}
		}
	}
	BigDecimal comboPrice = planInfoDTO.getComboPrice();
	BigDecimal personalTotalPrice = planInfoDTO.getPersonalTotalPrice();
	boolean processV25 = ContractDetailContextHandler.getContext().isProcessV25();
	//兼容团装历史数据
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && internalConfigurationsFileUrl.isEmpty() && !processV25) {
		internalConfigurationsFileUrl = fileUrl;
		comboPrice = planInfoDTO.getQuotePrice();
	}
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25) {
		//团装2.5图纸
		DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = ContractDetailContextHandler.getContext().getDrawingDTO();
		if (deliverDrawingDTO != null && !CollectionUtils.isEmpty(deliverDrawingDTO.getDrawingDetailDTOList())) {
			List<String> drawingList = deliverDrawingDTO.getDrawingDetailDTOList().stream()
				.filter(item -> ObjectUtil.equals(item.getExtensionType(), DrawingEnum.ConstructionFileExtensionEnum.PDF.getCode()))
				.filter(item -> ObjectUtil.equals(PlanAttachment.全屋图纸, item.getFileBizType()))
				.map(DrawingDTO.DrawingDetailDTO::getUrl)
				.collect(Collectors.toList());
			baseConstructionDrawFileUrl = drawingList.stream().map(item -> File.builder().url(item).previewUrl(item).build()).collect(Collectors.toList());
		}
	}
	BigDecimal discountAmount = Optional.ofNullable(planAllDTO.getCouponList()).orElse(Collections.emptyList()).stream()
		.filter(couponDTO -> CouponTypeEnum.DIRECT_COUPON.getCode().equals(couponDTO.getCouponType()))
		.map(CouponDTO::getLapseAmount)
		.findFirst()
		.orElse(null);
	return QuotationInfo.builder()
		//有用
		.comboCode(planInfoDTO.getComboCode())
		.comboName(planInfoDTO.getComboName())
		.contractPrice(planInfoDTO.getContractPriceTotal())
		.planTotalPrice(planInfoDTO.getNewestPlanPriceTotal())
		.pricingArea(getPricingArea())
		.remark(planInfoDTO.getRemark())
		.quotePrice(planInfoDTO.getQuotePrice())
		.quotationCompanyCode(planInfoDTO.getOrganizationCode())
		.quotationCompanyName(planInfoDTO.getOrganizationName())
		.fileUrl(fileUrl)
		.internalConfigurationsFileUrl(internalConfigurationsFileUrl)
		.baseConstructionDrawFileUrl(baseConstructionDrawFileUrl)
		.personalDrawFileUrl(personalDrawFileUrl)
		.extraConfigurationsFileUrl(extraConfigurationsFileUrl)
		.personalQuotionFileUrl(personalQuotationFileUrl)
		.houseLayout(Optional.ofNullable(planAllDTO).map(PlanAllDTO::getReconstructionHouseLayout)
			.map(HouseLayoutInfoDTO::getHouseLayoutDesc).orElse(null))
		.comboPrice(comboPrice)
		.personalTotalPrice(personalTotalPrice)
		.discountAmount(discountAmount)
		.configurationsFileUrl(configurationsFileUrl)
		.personalComboName(personalComboName)
		.build();
}

private String getPricingArea() {
	Byte businessType = ContractDetailContextHandler.getContext().getBusinessType();
	boolean processV25 = ContractDetailContextHandler.getContext().isProcessV25();
	if (!commonContractService.querySnapPlanInfoFromMainOrder(businessType, processV25)) {
		return Optional.ofNullable(ContractDetailContextHandler.getPlanAllDTO())
			.map(PlanAllDTO::getPlanInfo)
			.map(PlanInfoDTO::getPricingArea)
			.map(BigDecimal::toPlainString)
			.orElse("");
	}
	List<ComboDTO> comboDTOList = ContractDetailContextHandler.getContext().getComboDTOList();
	if (CollectionUtils.isEmpty(comboDTOList)) {
		return "";
	}
	return comboDTOList.stream().map(ComboDTO::getPricingArea).filter(Objects::nonNull).map(BigDecimal::toPlainString).collect(Collectors.joining(","));
}

public QuotationInfo getPreQuotationInfo(String projectOrderId, Map<String, String> fieldMap) {
	LightQuotationDTO.LightQuotationItem lightQuotationItem = ContractDetailContextHandler.getContext().getPreQuotationDTO();
	if (lightQuotationItem == null) {
		return null;
	}
	List<File> preQuotationFileUrl = new ArrayList<>();
	preQuotationFileUrl.add(File.builder().url(lightQuotationItem.getDecoratePdfFile()).build());
	// 判断fieldMap是否为空
	BigDecimal dbAdvanceAmount = null;
	BigDecimal advanceRate = null;
	if (!CollectionUtils.isEmpty(fieldMap)) {
		dbAdvanceAmount = fieldMap.get("advanceAmount") == null ? null : new BigDecimal(fieldMap.get("advanceAmount"));
		// 如果预估合同额数据库存的跟最新的不一致，不返回首期款金额，需要重新输入首期款金额
		BigDecimal dbExpectContractAmount = fieldMap.get("expectContractAmount") == null ? null : new BigDecimal(fieldMap.get("expectContractAmount"));
		if (dbAdvanceAmount != null && dbExpectContractAmount != null && dbExpectContractAmount.compareTo(lightQuotationItem.getHardTotalPrice()) != 0) {
			dbAdvanceAmount = null;
		}
		// 如果数据库里存有 advanceRate 字段，则取出
		advanceRate = fieldMap.get("advanceRate") == null ? null : new BigDecimal(fieldMap.get("advanceRate"));
	}
	ProjectInfoDTO projectInfoDTO = ContractDetailContextHandler.getProjectInfo();
	List<OptionsVo> advanceRates = getAdvanceRates(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), projectInfoDTO.getCustomerCommission().getCompanyCode());
	// 如果数据库里没有 advanceRate 值，则表明是新初始化的合同，从收款计划中获取
	if (advanceRate == null) {
		advanceRate = (BigDecimal) advanceRates.get(0).getValue();
	}
	return QuotationInfo.builder()
		.comboCode(lightQuotationItem.getComboBaseInfo().getComboCode())
		.comboName(lightQuotationItem.getComboBaseInfo().getComboName())
		.pricingArea(lightQuotationItem.getPricingArea() == null ? null : lightQuotationItem.getPricingArea().toPlainString())
		.expectContractAmount(lightQuotationItem.getHardTotalPrice())
		.preQuotationFileUrl(preQuotationFileUrl)
		.advanceAmount(dbAdvanceAmount)
		.advanceRates(advanceRates)
		.advanceRate(advanceRate)
		.build();
}

public QuotationInfo getRenovationQuotationInfo(String projectOrderId, Map<String, String> fieldMap) {
	ProjectInfoDTO projectInfoDTO = ContractDetailContextHandler.getProjectInfo();
	List<OptionsVo> advanceRates = getAdvanceRates(projectOrderId, projectInfoDTO.getCustomerHouse().getGbCode(), projectInfoDTO.getCustomerCommission().getCompanyCode());
	BigDecimal advanceRateConfig = (BigDecimal) advanceRates.get(0).getValue();
	if (CollectionUtil.isEmpty(fieldMap)) {
		return QuotationInfo.builder()
			.advanceRate(advanceRateConfig)
			.advanceRates(advanceRates)
			.build();
	} else {
		BigDecimal advanceRate = fieldMap.get("advanceRate") == null ? null : new BigDecimal(fieldMap.get("advanceRate"));
		if (advanceRate == null) {
			advanceRate = advanceRateConfig;
		}
		BigDecimal advanceAmount = fieldMap.get("advanceAmount") == null ? null : new BigDecimal(fieldMap.get("advanceAmount"));
		BigDecimal expectContractAmount = fieldMap.get("expectContractAmount") == null ? null : new BigDecimal(fieldMap.get("expectContractAmount"));
		String preQuotationFileUrlStr = fieldMap.get("preQuotationFileUrl") == null ? null : fieldMap.get("preQuotationFileUrl");
		//将String转换为报价单对应的结构
		List<File> preQuotationFileUrl = JSON.parseArray(preQuotationFileUrlStr, File.class);
		return QuotationInfo.builder()
			.advanceRate(advanceRate)
			.advanceAmount(advanceAmount)
			.expectContractAmount(expectContractAmount)
			.preQuotationFileUrl(preQuotationFileUrl)
			.advanceRates(advanceRates)
			.build();
	}
}

public DrawingInfo buildDrawingDetail(List<String> moduleKeyList, String changeOrderId, Byte contractType) {
	if (!moduleKeyList.contains(ContractModuleEnum.DRAWING.getKey()) && StringUtils.isBlank(changeOrderId)) {
		return null;
	}
	//合同变更协议&合并发起的模式：如果变更范围不包括施工图纸,则页面不展示施工图纸
	if (!CollectionUtils.isEmpty(ContractDetailContextHandler.getAtomChangeScopeList()) &&
		!ContractDetailContextHandler.getAtomChangeScopeList().contains(ChangeScopeEnum.DRAWING.getCode())) {
		return null;
	}
	return DrawingInfo.builder()
		.drawingUrl(Collections.singletonList(File.builder().previewUrl(ContractDetailContextHandler.getDrawingUrl()).build()))
		.build();
}

public CollectionPlanConfigInfo buildCollectionPlanConfigInfo(List<String> moduleKeyList, Contract contract, String changeOrderId) {
	if (!moduleKeyList.contains(ContractModuleEnum.COLLECTION_PLAN_CONFIG_INFO.getKey())) {
		return null;
	}
	CollectionPlanConfigInfo collectionPlanConfigInfo = commonContractService.queryCollectionPlanByContract(contract);
	if (collectionPlanConfigInfo == null) {
		return null;
	}
	PlanAllDTO planAllDTO = ContractDetailContextHandler.getPlanAllDTO();
	collectionPlanConfigInfo = fundBaseService.calculateCollectionPlan(collectionPlanConfigInfo,
		planAllDTO.getPlanInfo().getContractPriceTotal());
	return collectionPlanConfigInfo;
}

public ContractAttachInfoDetail buildContractAttachInfo(List<String> moduleKeyList, Contract contract, List<ContractAttach> contractAttachList, ContractSignInfoDetail signInfoDetail, Map<String, String> fieldMap, String projectOrderId, Byte contractType) {
	if (!moduleKeyList.contains(ContractModuleEnum.CONTRACT_ATTACH_INFO.getKey())) {
		return null;
	}
	if (CollectionUtils.isEmpty(contractAttachList)) {
		contractAttachList = new ArrayList<>();
	}
	boolean attachOcrOpenCity = attachCommonService.attachOcrOpenCity(projectOrderId);
	contractAttachList = contractAttachList.stream().filter(contractAttach -> !AttachTypeEnum.OFFLINE_CONTRACT.getCode().equals(contractAttach.getAttachType())).collect(Collectors.toList());
	ContractAttachInfoDetail contractAttachInfo = new ContractAttachInfoDetail();
	if (contract == null) {
		//附件是否上传完成
		contractAttachInfo.setUploadStatus(false);
		//根据备件信息初始化合同备件信息
		dealContractAttachFromAttachInfo(contractAttachInfo, contractAttachList);
		contractAttachInfo.setHaveHouseProve(contractAttachInfo.getHaveHouseProve() == null ? HaveHouseProveEnum.HOUSE_PROVE.getCode() : contractAttachInfo.getHaveHouseProve());
		//设置默认值
		contractAttachInfo.setAgentSign(contractAttachInfo.getAgentSign() == null ? CommonEnum.YES.getCode() : contractAttachInfo.getAgentSign());
		//团装2.5房屋权属证明类型为【其他权属证明】
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(ContractDetailContextHandler.getContext().getBusinessType())
			&& ContractDetailContextHandler.getContext().isProcessV25()) {
			contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
		}
		//从前一下个项目获取合同备件信息
		dealContractAttachFromPreProject(contractAttachInfo, projectOrderId, contractType);
		return contractAttachInfo;
	}
	//根据备件信息初始化合同备件信息
	dealContractAttachFromAttachInfo(contractAttachInfo, contractAttachList);
	BeanUtil.fillBeanWithMap(fieldMap, contractAttachInfo, true);

	//处理contractAttachList，根据备件id获取对应的备件url
	attachCommonService.getUrlFromContractAttachList(contract.getProjectOrderId(), contractAttachList);
	for (ContractAttach contractAttach : contractAttachList) {
		Byte attachType = contractAttach.getAttachType();
		if (AttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
			contractAttachInfo.getUserCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.HOUSE_CERTIFICATE.getCode().equals(attachType)) {
			contractAttachInfo.getHouseCertificate().add(File.builder().certificateId(contractAttach.getCertificateId())
				.documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
			contractAttachInfo.getAgentCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.AGENT_CERTIFICATE.getCode().equals(attachType)) {
			contractAttachInfo.getAgentCertificate().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.OTHER.getCode().equals(attachType)) {
			contractAttachInfo.getOther().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.TERMINAL_CERTIFICATE.getCode().equals(attachType)) {
			contractAttachInfo.getGroupTerminalCertificate().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.COMPANY_LICENSE.getCode().equals(attachType)) {
			contractAttachInfo.getCompanyLicense().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
			contractAttachInfo.getCompanyAgentCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.LEGAL_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
			contractAttachInfo.getLegalCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.OTHER_OWNER_SHIP.getCode().equals(attachType)) {
			if (attachOcrOpenCity) {
				//备件ocr开城后，其他权属证明放到房产证
				contractAttachInfo.getHouseCertificate().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.HOUSE_TRADE_CONTRACT.getCode().equals(attachType)) {
			if (!attachOcrOpenCity) {
				contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
				contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			contractAttachInfo.getHouseTradeContract().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.HOUSE_SUBSCRIBE_CONTRACT.getCode().equals(attachType)) {
			if (!attachOcrOpenCity) {
				contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
				contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			contractAttachInfo.getHouseSubscribeContract().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.DEED_TICKET.getCode().equals(attachType)) {
			if (!attachOcrOpenCity) {
				contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
				contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			contractAttachInfo.getDeedTicket().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.SPECIAL_HOUSE_PROVE.getCode().equals(attachType)) {
			if (!attachOcrOpenCity) {
				contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
				contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
			}
			contractAttachInfo.getSpecialHouse().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
	}
	//由于历史数据（2023-03-23之前）中存在证件信息只存放在contract_user表中，所以如果attach表中不存在证件信息时需要从contract_user表中获取证件信息
	List<ContractUser> contractUserList = contractUserService.getListByContractCode(contract.getContractCode());
	for (ContractUser contractUser : contractUserList) {
		if (contractAttachInfo.getUserCertificateUnify().isEmpty() && contractUser.getRoleType().equals(UserTypeEnum.OWNER.getCode())) {
			if (StringUtils.isNotBlank(contractUser.getCertificateImg1())) {
				contractAttachInfo.getUserCertificateUnify().add(File.builder().url(contractUser.getCertificateImg1()).build());
				contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode())
					.url(contractUser.getCertificateImg1()).build());
			}
			if (StringUtils.isNotBlank(contractUser.getCertificateImg2())) {
				contractAttachInfo.getUserCertificateUnify().add(File.builder().url(contractUser.getCertificateImg2()).build());
				contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode())
					.url(contractUser.getCertificateImg2()).build());
			}
		}
		if (contractAttachInfo.getAgentCertificateUnify().isEmpty() && contractUser.getRoleType().equals(UserTypeEnum.AGENT.getCode())) {
			if (StringUtils.isNotBlank(contractUser.getCertificateImg1())) {
				contractAttachInfo.getAgentCertificateUnify().add(File.builder().url(contractUser.getCertificateImg1()).build());
				contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode())
					.url(contractUser.getCertificateImg1()).build());
			}
			if (StringUtils.isNotBlank(contractUser.getCertificateImg2())) {
				contractAttachInfo.getAgentCertificateUnify().add(File.builder().url(contractUser.getCertificateImg2()).build());
				contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode())
					.url(contractUser.getCertificateImg2()).build());
			}
		}
		if (contractAttachInfo.getCompanyAgentCertificateUnify().isEmpty() && contractUser.getRoleType()
			.equals(UserTypeEnum.COMPANY_AGENT.getCode())) {
			if (StringUtils.isNotBlank(contractUser.getCertificateImg1())) {
				contractAttachInfo.getCompanyAgentCertificateUnify().add(File.builder().url(contractUser.getCertificateImg1()).build());
				contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode())
					.url(contractUser.getCertificateImg1()).build());
			}
			if (StringUtils.isNotBlank(contractUser.getCertificateImg2())) {
				contractAttachInfo.getCompanyAgentCertificateUnify().add(File.builder().url(contractUser.getCertificateImg2()).build());
				contractAttachList.add(ContractAttach.builder().attachType(AttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode())
					.url(contractUser.getCertificateImg2()).build());
			}
		}
	}
	Byte haveHouseProve = Objects.isNull(fieldMap.get("haveHouseProve")) ? null : Byte.valueOf(String.valueOf(fieldMap.get("haveHouseProve")));
	Byte signRole = Objects.isNull(fieldMap.get("signRole")) ? null : Byte.valueOf(String.valueOf(fieldMap.get("signRole")));
	Byte signChannelType = Objects.isNull(fieldMap.get("signChannelType")) ? null : Byte.valueOf(String.valueOf(fieldMap.get("signChannelType")));
	CheckAttachUploadStatusParam checkAttachUploadStatusParam = CheckAttachUploadStatusParam.builder()
		.projectOrderId(projectOrderId)
		.contractObjectType(signInfoDetail.getContractObjectType())
		.haveAgent(signInfoDetail.getHaveAgent())
		.contractAttachList(contractAttachList)
		.agentSign(contractAttachInfo.getAgentSign())
		.haveHouseProve(haveHouseProve)
		.signRole(signRole)
		.signChannelType(signChannelType)
		.supportCompanyOnlineSign(commonContractService.openCompanySignOnline(contract.getProjectOrderId()))
		.build();
	//附件是否上传完成
	contractAttachInfo.setUploadStatus(contractUnifyService.checkAttach(checkAttachUploadStatusParam));
	contractAttachInfo.setHaveHouseProve(contractAttachInfo.getHaveHouseProve() == null ? HaveHouseProveEnum.HOUSE_PROVE.getCode() : contractAttachInfo.getHaveHouseProve());
	if (contractAttachInfo.getAgentSign() == null) {
		contractAttachInfo.setAgentSign(signInfoDetail.getHaveAgent());
	}
	//团装2.5房屋权属证明类型为【其他权属证明】
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(ContractDetailContextHandler.getContext().getBusinessType())
		&& ContractDetailContextHandler.getContext().isProcessV25()) {
		contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
	}
	contractAttachInfo.setFirstLaneSyncAttachMap(buildFirstLaneSyncAttachMap(projectOrderId, null, contractAttachList, fieldMap,contractType));
	return contractAttachInfo;
}

public PersonalCollectionPlanInfo buildPersonalCollectionPlanInfo(List<String> moduleKeyList) {
	if (!moduleKeyList.contains(ContractModuleEnum.PERSONAL_COLLECTION_PLAN_INFO.getKey())) {
		return null;
	}
	ContractSourceDataBO contractSourceDataBO = ContractDetailContextHandler.getContractSourceDataBO();
	List<ContractSourceDataBO.PersonalContractData> personalContractDataList = contractSourceDataBO.getPersonalContractDataList();
	if (CollectionUtils.isEmpty(personalContractDataList)) {
		return null;
	}
	BigDecimal personalTotalPrice = personalContractDataList.stream()
		.map(data -> data.getPersonalContractPrice() == null ? BigDecimal.ZERO : data.getPersonalContractPrice())
		.reduce(BigDecimal.ZERO, BigDecimal::add);
	return PersonalCollectionPlanInfo.builder()
		.lastPayNode("合同签订当天")
		.rate("100%")
		.price(personalTotalPrice)
		.build();
}

public List<ZqCustomerPhoneVo> getCustomerPhoneVoList(ContractSignInfoDetail signInfo, Boolean isDetail) {
