public PersonalQuotation buildPersonalQuotationDetail(Contract contract, List<String> moduleKeyList, QuotationInfo quotationInfo, Byte contractType, Map<String, String> fieldMap) {
	if (!moduleKeyList.contains(ContractModuleEnum.PERSONAL_QUOTATION.getKey())) {
		return null;
	}
	List<ContractSourceDataBO.PersonalContractData> personalContractDataList =
		Optional.ofNullable(ContractDetailContextHandler.getContractSourceDataBO())
			.map(ContractSourceDataBO::getPersonalContractDataList)
			.orElseGet(ArrayList::new);
	BigDecimal personalTotalPrice = personalContractDataList.stream()
		.map(data -> data.getPersonalContractPrice() == null ? BigDecimal.ZERO : data.getPersonalContractPrice())
		.reduce(BigDecimal.ZERO, BigDecimal::add);
	String personalComboName = personalContractDataList.stream()
		.map(ContractSourceDataBO.PersonalContractData::getComboName)
		.filter(comboName -> comboName != null && !comboName.isEmpty()) // 过滤掉 null 和 空字符串
		.collect(Collectors.joining(","));
	List<File> personalFileUrlTemp = personalContractDataList.stream()
		.map(data -> {
			if (data.getQuoteInfo() != null) {
				return File.builder()
					.url(data.getQuoteInfo().getPrevUrl())
					.previewUrl(data.getQuoteInfo().getPrevUrl())
					.build();
			}
			return null;
		})
		.filter(Objects::nonNull) // 过滤掉 null
		.collect(Collectors.toList());
	List<File> personalDrawFileUrl = Optional.ofNullable(ContractDetailContextHandler.getContext())
		.map(ContractDetailContext::getDrawingDTO)
		.map(DrawingDTO.DeliverDrawingDTO::getDrawingDetailDTOList)
		.filter(CollectionUtil::isNotEmpty)
		.map(list -> list.stream()
			.map(DrawingDTO.DrawingDetailDTO::getUrl)
			.map(path -> File.builder().url(path).previewUrl(path).build())
			.collect(Collectors.toList()))
		.orElse(Collections.emptyList());

	String salesCompanyName = personalContractDataList.stream().map(ContractSourceDataBO.PersonalContractData::getOrganizationName).filter(StringUtils::isNotBlank)
		.distinct()
		.collect(Collectors.joining(","));

	PersonalQuotation personalQuotation = PersonalQuotation.builder()
		.personalQuotionFileUrl(personalFileUrlTemp)
		.personalTotalPrice(personalTotalPrice)
		.personalDrawFileUrl(personalDrawFileUrl)
		.personalComboName(personalComboName)
		.build();
	personalQuotation.setSalesCompanyName(salesCompanyName);
	return personalQuotation;
}

private boolean reSign(String projectOrderId, Byte contractType) {
	if (ContractTypeEnum.isAllowMultipleLaunch(contractType)) {
		return false;
	}
	List<Contract> contractList = contractService.getContractList(projectOrderId, contractType);
	if (CollectionUtils.isEmpty(contractList)) {
		return false;
	}
	List<Integer> finalContractStatus = Arrays.asList(ContractStatusEnum.USER_CONFIRMED.getCode(), ContractStatusEnum.FINISH.getCode());
	List<Contract> contractListFilter = contractList.stream().filter(item -> finalContractStatus.contains(item.getStatus()))
		.collect(Collectors.toList());
	return !CollectionUtils.isEmpty(contractListFilter);
}

private void dealProjectInfoFromAttachInfo(ContractProjectInfoDetail contractProjectInfoDetail) {
	AttachInfoDetail attachInfoDetail = ContractDetailContextHandler.getContext().getAttachInfoDetail();
	if (attachInfoDetail == null || !attachInfoDetail.isUpload()) {
		return;
	}

	if (UploadTypeEnum.MIDDLE_GROUND.getCode().equals(attachInfoDetail.getUploadType())) {
		return;
	}

	//覆盖面积、房本地址
	BeanUtils.copyProperties(attachInfoDetail.getHouseInfo(), contractProjectInfoDetail);
}

private void dealContractAttachFromAttachInfo(ContractAttachInfoDetail contractAttachInfo, List<ContractAttach> contractAttachList) {
	//如果合同备件信息有值，则不需要从备件信息中获取
	if (!CollectionUtils.isEmpty(contractAttachList)) {
		return;
	}
	AttachInfoDetail attachInfoDetail = ContractDetailContextHandler.getContext().getAttachInfoDetail();
	if (attachInfoDetail == null || !attachInfoDetail.isUpload()) {
		return;
	}
	List<File> userCertificateUnify = attachInfoDetail.getIdentityInfo().getUserCertificateUnify();
	List<File> agentCertificateUnify = attachInfoDetail.getIdentityInfo().getAgentCertificateUnify();
	List<File> agentCertificate = attachInfoDetail.getIdentityInfo().getAgentCertificate();
	List<File> companyAgentCertificateUnify = attachInfoDetail.getIdentityInfo().getCompanyAgentCertificateUnify();
	List<File> companyLicense = attachInfoDetail.getIdentityInfo().getCompanyLicense();
	List<File> houseCertificate = attachInfoDetail.getHouseInfo().getHouseCertificate();
	List<File> legalCertificateUnify = attachInfoDetail.getIdentityInfo().getLegalCertificateUnify();
	contractAttachInfo.setUserCertificateUnify(CollectionUtils.isEmpty(userCertificateUnify) ? Lists.emptyList() : userCertificateUnify);
	contractAttachInfo.setAgentCertificateUnify(CollectionUtils.isEmpty(agentCertificateUnify) ? Lists.emptyList() : agentCertificateUnify);
	contractAttachInfo.setAgentCertificate(CollectionUtils.isEmpty(agentCertificate) ? Lists.emptyList() : agentCertificate);
	contractAttachInfo.setCompanyAgentCertificateUnify(CollectionUtils.isEmpty(companyAgentCertificateUnify) ? Lists.emptyList() : companyAgentCertificateUnify);
	contractAttachInfo.setCompanyLicense(CollectionUtils.isEmpty(companyLicense) ? Lists.emptyList() : companyLicense);
	contractAttachInfo.setHouseCertificate(CollectionUtils.isEmpty(houseCertificate) ? Lists.emptyList() : houseCertificate);
	contractAttachInfo.setLegalCertificateUnify(CollectionUtils.isEmpty(legalCertificateUnify) ? Lists.emptyList() : legalCertificateUnify);

	CopyOptions copyOptions = CopyOptions.create().ignoreNullValue();
	BeanUtil.copyProperties(attachInfoDetail.getIdentityInfo(), contractAttachInfo, copyOptions);
	BeanUtil.copyProperties(attachInfoDetail.getHouseInfo(), contractAttachInfo, copyOptions);
	contractAttachInfo.setFirstLaneSyncAttachMap(attachInfoDetail.getFirstLaneSyncAttachMap());
}

private void dealContractAttachFromPreProject(ContractAttachInfoDetail contractAttachInfo, String projectOrderId, Byte contractType) {
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return;
	}
	if (attachCommonService.attachOcrOpenCity(projectOrderId) && BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(ContractDetailContextHandler.getContext().getBusinessType())) {
		//如果是备件ocr开城城市，则不需要从前一个项目获取合同备件信息
		return;
	}
	String previousOrderNo = commonBusinessService.getPreviousOrderNo(projectOrderId);
	if (StringUtils.isBlank(previousOrderNo)) {
		return;
	}
	Contract latestContract = contractService.getLatestContract(previousOrderNo, ContractTypeEnum.PACKAGE_FORMAL.getCode());
	if (latestContract == null || !ContractStatusEnum.inEndStatus(latestContract.getStatus())) {
		return;
	}
	List<ContractAttach> contractAttachList = contractAttachService.getListByContractCode(latestContract.getContractCode());
	//处理contractAttachList，根据备件id获取对应的备件url
	attachCommonService.getUrlFromContractAttachList(latestContract.getProjectOrderId(), contractAttachList);
	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(latestContract.getContractCode());
	Map<String, String> fieldMap = Maps.newHashMap();
	contractFieldList.forEach(contractField -> fieldMap.put(contractField.getFieldKey(), contractField.getFieldValue()));
	BeanUtil.fillBeanWithMap(fieldMap, contractAttachInfo, true);
	for (ContractAttach contractAttach : contractAttachList) {
		Byte attachType = contractAttach.getAttachType();
		if (AttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
			contractAttachInfo.getUserCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.HOUSE_CERTIFICATE.getCode().equals(attachType)) {
			contractAttachInfo.getHouseCertificate().add(File.builder().certificateId(contractAttach.getCertificateId())
				.documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
			contractAttachInfo.getAgentCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.AGENT_CERTIFICATE.getCode().equals(attachType)) {
			contractAttachInfo.getAgentCertificate().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.OTHER.getCode().equals(attachType)) {
			contractAttachInfo.getOther().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.COMPANY_LICENSE.getCode().equals(attachType)) {
			contractAttachInfo.getCompanyLicense().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
			contractAttachInfo.getCompanyAgentCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.LEGAL_CERTIFICATE_UNIFY.getCode().equals(attachType)) {
			contractAttachInfo.getLegalCertificateUnify().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
		if (AttachTypeEnum.OTHER_OWNER_SHIP.getCode().equals(attachType)) {
			contractAttachInfo.getOtherOwnerShip().add(File.builder().certificateId(contractAttach.getCertificateId()).documentCode(contractAttach.getDocumentCode()).url(contractAttach.getUrl()).build());
		}
	}
	//团装2.5房屋权属证明类型为【其他权属证明】
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(ContractDetailContextHandler.getContext().getBusinessType())
		&& ContractDetailContextHandler.getContext().isProcessV25()) {
		contractAttachInfo.setHaveHouseProve(HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode());
	}
}

private void dealSignInfoFromAttachInfo(ContractSignInfoDetail signInfoDetail) {
	AttachInfoDetail attachInfoDetail = ContractDetailContextHandler.getContext().getAttachInfoDetail();
	if (attachInfoDetail == null || !attachInfoDetail.isUpload()) {
		return;
	}
	BeanUtils.copyProperties(attachInfoDetail.getIdentityInfo(), signInfoDetail);
	if (UploadTypeEnum.S3.getCode().equals(attachInfoDetail.getUploadType())) {
		//覆盖面积、房本地址
		BeanUtils.copyProperties(attachInfoDetail.getHouseInfo(), signInfoDetail);
	} else {
		signInfoDetail.setHouseCertificateNo(attachInfoDetail.getHouseInfo().getHouseCertificateNo());
		signInfoDetail.setHouseCertificateAddress(attachInfoDetail.getHouseInfo().getHouseCertificateAddress());
		signInfoDetail.setHouseOwnerName(attachInfoDetail.getHouseInfo().getHouseOwnerName());
	}


	//公对公只能是线下签约
	if (ContractObjectTypeEnum.COMPANY.getCode().equals(signInfoDetail.getContractObjectType())) {
		signInfoDetail.setSignChannelType(SignChannelTypeEnum.OFFLINE.getCode());
		signInfoDetail.setHaveAgent(HaveAgentEnum.NO.getCode());
	}
}

public List<ContractPreQuotationDTO> getPreQuotationList(String projectOrderId) {
	List<ContractPreQuotationDTO> preQuotationList = Lists.emptyList();
	List<LightQuotationDTO.LightQuotationItem> quotationItemList = atomBudgetRpc.getPreQuotationListByProject(projectOrderId);
	if (CollectionUtils.isEmpty(quotationItemList)) {
		return preQuotationList;
	}
	preQuotationList = quotationItemList.stream().map(item -> ContractPreQuotationDTO.builder()
		.billCode(item.getBillCode())
		.comboName(item.getComboBaseInfo().getComboName())
		.cuName(item.getCuName())
		.mtime(DateUtils.asDate(item.getMtime()))
		.remark(item.getRemark())
		.status(item.getStatus())
		.statusDesc(item.getStatusDesc())
		.decorateTotalPrice(item.getHardTotalPrice())
		.build()).collect(Collectors.toList());
	return preQuotationList;
}

public ContractQuotationDetail quotationDetail(String projectOrderId, String billCode) {
	LightQuotationDTO.LightQuotationItem preQuotation = getAdvanceQuote(projectOrderId, Collections.singletonList(billCode));
	if (preQuotation == null) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "所选预报价不是已提交/正式版状态，请回到合同列表重新选择", Level.WARN);
	}
	String preQuotationPdf = preQuotation.getDecoratePdfFile();
	if (StringUtils.isBlank(preQuotationPdf)) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "预报价单pdf为空", Level.ERROR);
	}
	List<File> preQuotationFileUrl = Lists.newArrayList();
	preQuotationFileUrl.add(File.builder().url(preQuotationPdf).build());
	return ContractQuotationDetail.builder()
		.billCode(preQuotation.getBillCode())
		.comboCode(preQuotation.getComboBaseInfo().getComboCode())
		.comboName(preQuotation.getComboBaseInfo().getComboName())
		.expectContractAmount(preQuotation.getHardTotalPrice())
		.pricingArea(preQuotation.getPricingArea())
		.preQuotationFileUrl(preQuotationFileUrl)
		.build();
}

public LightQuotationDTO.LightQuotationItem getAdvanceQuote(String projectOrderId, List<String> billCodeList) {
	//未开城，不用从预报价获取
	if (Boolean.FALSE.equals(contractUnifyService.advanceSupportPreQuotation(projectOrderId, ContractTypeEnum.ADVANCE.getCode()))) {
		return null;
	}
	if (CollectionUtils.isEmpty(billCodeList) || StringUtils.isBlank(billCodeList.get(0))) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "参数异常，预报价单号为空", Level.ERROR);
	}
	//校验预报价单是否有效
	LightQuotationDTO.LightQuotationItem preQuotation = atomBudgetRpc.getPreQuotationByBillCode(billCodeList.get(0));
	if (preQuotation == null) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_INVOKE.getCode(), "所选预报价不是已提交/正式版状态，请回到合同列表重新选择", Level.WARN);
	}
	if (
		preQuotation.getPricingArea() == null ||
			preQuotation.getComboBaseInfo() == null || StringUtils.isBlank(preQuotation.getComboBaseInfo().getComboCode()) || StringUtils.isBlank(preQuotation.getComboBaseInfo().getComboName()) ||
			preQuotation.getHardTotalPrice() == null) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_INVOKE.getCode(), "所选预报价信息不完整，请回到合同列表重新选择", Level.ERROR);
	}
	return preQuotation;
}

private BigDecimal getCancelOrderAmount(String projectOrderId) {
	CancelOrderBaseInfoDTO cancelOrderBaseInfoDTO = cancelOrderService.getLastRecordByProjectOrderId(projectOrderId);
	return cancelOrderBaseInfoDTO == null ? BigDecimal.ZERO : cancelOrderBaseInfoDTO.getCancelOrderAmount();
}

private void dealFormalContractDetail(Byte contractType, ProjectInfoDTO projectInfoDTO, ContractSignInfoDetail signInfoDetail) {
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) || projectInfoDTO == null) {
		return;
	}
	String previousOrderNo = commonBusinessService.getPreviousOrderNo(projectInfoDTO.getProjectOrderId());
	if (StringUtils.isBlank(previousOrderNo)) {
		return;
	}
	Contract latestContract = contractService.getLatestContract(previousOrderNo, ContractTypeEnum.PACKAGE_FORMAL.getCode());
	if (latestContract == null || !ContractStatusEnum.inEndStatus(latestContract.getStatus())) {
		return;
	}
	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(latestContract.getContractCode());
	Map<String, String> fieldMap = Maps.newHashMap();
	contractFieldList
		.forEach(contractField -> {
			if (StringUtils.isNotBlank(contractField.getFieldValue())) {
				fieldMap.put(contractField.getFieldKey(), contractField.getFieldValue());
			}
		});
	BeanUtil.fillBeanWithMap(fieldMap, signInfoDetail, true);
}

public boolean openCompanySignOnlineForDetail(String projectOrderId, Boolean isFirstScreen, Byte contractType) {
	String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(projectOrderId);
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(convertProjectOrderId);
	if (Objects.isNull(projectInfoDTO)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "项目信息不存在");
	}
	boolean openCompanySignOnline = commonContractService.openCompanySignOnline(projectInfoDTO);
	if (isFirstScreen) {
		return openCompanySignOnline;
	}
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return openCompanySignOnline;
	}
	//正签&非首屏
	ContractSourceDataBO contractSourceDataBO = ContractDetailContextHandler.getContext().getContractSourceDataBO();
	if (contractSourceDataBO == null || CollectionUtils.isEmpty(contractSourceDataBO.getPersonalContractDataList()) || contractSourceDataBO.getPlanAllDTO() == null) {
		return openCompanySignOnline;
	}
	//正签分公司code
	String organizationCode = contractSourceDataBO.getPlanAllDTO().getPlanInfo().getOrganizationCode();
	List<String> organizationCodeList = Optional.ofNullable(contractSourceDataBO.getPersonalContractDataList())
		.orElse(Collections.emptyList())
		.stream()
		.map(ContractSourceDataBO.PersonalContractData::getOrganizationCode)
		.filter(Objects::nonNull)
		.collect(Collectors.toList());
	organizationCodeList.add(organizationCode);
	organizationCodeList = organizationCodeList.stream().distinct().collect(Collectors.toList());
	if (organizationCodeList.size() > 1) {
		return false;
	}
	return openCompanySignOnline;
}

private void dealSignInfoFromLatestFormal(String projectOrderId, ContractSignInfoDetail signInfoDetail) {
	Contract latestFormalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode())
		.stream()
		.filter(item -> Objects.equals(ContractStatusEnum.FINISH.getCode(), item.getStatus()))
		.findFirst().orElse(null);

	if (latestFormalContract == null) {
		throw new NrsBusinessException("未获取到最新已签署的正签合同，无法发起补充协议或和解协议");
	}

	String contractCode = latestFormalContract.getContractCode();

	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contractCode)
		.stream().filter(item -> StringUtils.isNotBlank(item.getFieldValue())).collect(Collectors.toList());
	Map<String, String> fieldMapTemp = Maps.newHashMap();
	contractFieldList.forEach(contractField -> fieldMapTemp.put(contractField.getFieldKey(), contractField.getFieldValue()));
	fieldMapTemp.remove("companySignTime");
	fieldMapTemp.remove("userSignTime");
	fieldMapTemp.remove("launchSupplementType");
	BeanUtil.fillBeanWithMap(fieldMapTemp, signInfoDetail, true);
}

public SupplementItemInfo buildSupplementItemInfo(Contract contract, Map<String, String> fieldMap) {
	SupplementItemInfo supplementItemInfo = new SupplementItemInfo();
	if (contract != null) {
		// 取出已保存数据进行回填
		BeanUtil.fillBeanWithMap(fieldMap, supplementItemInfo, true);

		//合同是正式套餐&线下签约的&为合并发起模式的，需要获取补充协议的附件
		if (contract.getType().equals(ContractTypeEnum.PACKAGE_FORMAL.getCode()) && contract.getSignChannelType()
			.equals(SignChannelTypeEnum.OFFLINE.getCode())) {
			List<String> relationContractList = contractRelationService.getRelationList(contract.getContractCode())
				.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
			List<Contract> contractList = contractService.getListByContractCodes(relationContractList, false);
			Contract supplementContract = contractList.stream().filter(item -> item.getType().equals(ContractTypeEnum.SUPPLEMENT.getCode()))
				.findFirst()
				.orElse(null);
			if (supplementContract != null) {
				supplementItemInfo.setSupplementAttachUrl(contractBusinessService.getOfflineContractByCode(supplementContract.getContractCode()));
			}
		}
	}
	return supplementItemInfo;
}

public SettlementItemInfo buildSettlementItemInfo(Contract contract, Map<String, String> fieldMap) {
	SettlementItemInfo settlementItemInfo = new SettlementItemInfo();
	if (contract != null) {
		// 取出已保存数据进行回填
		BeanUtil.fillBeanWithMap(fieldMap, settlementItemInfo, true);
	}
	return settlementItemInfo;
}

