public boolean mergeLaunchDesign() {
	// 设计费报价未开城
	ContractReqDTO contractReq = ContractContextHandler.getContext().getContractReq();
	DesignQuoteFeeDTO designQuoteFeeDTO = ContractContextHandler.getContext().getDesignQuoteFeeDTO();
	if (!contractUnifyService.designFeeFromQuote(contractReq.getContractBaseInfo().getProjectOrderId())) {
