	public Map<String, Object> getSignUserInfo() {
		HashMap<String, Object> result = new HashMap<>();
		ContractSignInfoReq signInfo = ContractContextHandler.getContractReq().getSignInfo();
		String ownerAddress = StringUtils.isBlank(signInfo.getOwnerAddress()) ? "" : signInfo.getOwnerAddress();
		String agentName = StringUtils.isBlank(signInfo.getAgentName()) ? "/" : signInfo.getAgentName();
		String agentIdNo = StringUtils.isBlank(signInfo.getAgentCertificateNo()) ? "/" : signInfo.getAgentCertificateNo();
		String agentPhone = StringUtils.isBlank(signInfo.getAgentPhone()) ? "/" : signInfo.getAgentPhone();
		String customerIdNo = StringUtils.isBlank(signInfo.getOwnerCertificateNo()) ? "/" : signInfo.getOwnerCertificateNo();
		String companyAgentCertificateNo = StringUtils.isBlank(signInfo.getCompanyAgentCertificateNo()) ? "/" : signInfo.getCompanyAgentCertificateNo();
		String companyAgentPhone = StringUtils.isBlank(signInfo.getCompanyAgentPhone()) ? "/" : signInfo.getCompanyAgentPhone();
		//客户住所地址
		result.put("ownerAddress", ownerAddress);
		Map<String, String> decryptMap = cipherService.decrypt(
			Stream.of(signInfo.getOwnerPhone(),
					agentIdNo,
					agentPhone,
					customerIdNo, companyAgentCertificateNo, companyAgentPhone)
				.filter(StringUtils::isNotBlank)
				.distinct()
				.collect(Collectors.toList())
		);
		//客户姓名
		result.put("jiafangXingming", signInfo.getOwnerName());
		//客户手机
		result.put("firstPartyConnectPhone", decryptMap.getOrDefault(signInfo.getOwnerPhone(), signInfo.getOwnerPhone()));
		//客户证件号
		result.put("customerIdNo", decryptMap.getOrDefault(customerIdNo, customerIdNo));

		Byte haveAgent = signInfo.getHaveAgent();
		if (HaveAgentEnum.NO.getCode().equals(haveAgent)) {
			//无代理人
			result.put("agentName", "/");
			result.put("agentIdNo", "/");
			result.put("agentPhone", "/");
		} else {
			//代理人身份证号
			result.put("agentIdNo", decryptMap.getOrDefault(agentIdNo, agentIdNo));
			//代理人手机
			result.put("agentPhone", decryptMap.getOrDefault(agentPhone, agentPhone));
			//代理人姓名 没有的话 用 /
			result.put("agentName", agentName);
		}

		if (ContractObjectTypeEnum.COMPANY.getCode().equals(signInfo.getContractObjectType())) {
			//客户姓名
			result.put("jiafangXingming", signInfo.getCompanyName());
			//客户手机
			result.put("firstPartyConnectPhone", "/");
			//客户证件号
			result.put("customerIdNo", signInfo.getCompanyCreditCode());
			if (RoleTypeEnum.COMPANY_AGENT.getCode().equals(signInfo.getSignRole())) {
				//代理人身份证号
				result.put("agentIdNo", decryptMap.getOrDefault(companyAgentCertificateNo, companyAgentCertificateNo));
				//代理人手机
				result.put("agentPhone", decryptMap.getOrDefault(companyAgentPhone, companyAgentPhone));
				//代理人姓名 没有的话用 /
				result.put("agentName", signInfo.getCompanyAgentName());
			}
		}
		return result;
	}

