		List<FormalPackageContractFreeformDTO.Photo> photos = new ArrayList<>();
		List<FormalPackageContractFreeformDTO.PhotoInfo> photoInfos = new ArrayList<>();
		for (String comboCode : comboCodesByPlanAllDTO) {
			List<String> ruleUrls = comboInfoService.getDecorateRule(projectOrderId, contractType, comboCode).getImgUrls();
			String signDate = DateUtils.getDateStr(new Date());
			List<FormalPackageContractFreeformDTO.Photo> singleComboPhotos = ruleUrls.stream()
				.map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(Collectors.toList());
			photos.addAll(singleComboPhotos);

			List<FormalPackageContractFreeformDTO.PhotoInfo> singleComboPhotoInfos = ruleUrls.stream()
				.map(src -> new FormalPackageContractFreeformDTO.PhotoInfo(src, signDate, false)).collect(Collectors.toList());
