	private String getImageUrlByType(List<PlanAttachmentDTO> list, Integer fileType, String fileName) {
		if (CollectionUtils.isEmpty(list)) {
			return "";
		}
		PlanAttachmentDTO attachmentDTO = list.stream().filter(planAttachmentDTO -> planAttachmentDTO.getFileType().equals(fileType)).findFirst()
			.orElse(null);
		if (attachmentDTO == null) {
			return "";
		}
		List<String> imageUrls = new ArrayList<>();
		try {
			imageUrls = pdfToImageService.pdf2ImagePublicParallel(attachmentDTO.getFileUrl());
		} catch (NrsBusinessException e) {
			if (e.getCode() == ResponseCodeEnum.PDF_PAGES_LIMIT.getCode()) {
				throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(),
					String.format("%s数过多，请检查%s样式并调整控制在%s页及以内", fileName, fileName, limitPages),
					Level.WARN);
			}
			if (e.getCode() == ResponseCodeEnum.PDF_URL_ERROR.getCode()) {
				throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(),
					String.format("%s异常，请检查是否上传成功", fileName),
					Level.WARN);
			}
		}
		String signDate = DateUtils.getDateStr(new Date());
		List<FormalPackageContractFreeformDTO.Photo> photos = imageUrls.stream()
			.map(src -> new FormalPackageContractFreeformDTO.Photo(src, signDate)).collect(
				Collectors.toList());
		return JsonUtil.toJsonString(photos);
	}

	private String getMultipleImageUrlByType(List<PlanAttachmentDTO> list, Integer fileType, String fileName) {
