	public Map<String, Object> getGuaranteeInfo() {
		HashMap<String, Object> result = new HashMap<>();
		GuaranteeReq guaranteeInfo = ContractContextHandler.getContractReq().getGuaranteeInfo();
		String otherGuaranteeYear = Objects.isNull(guaranteeInfo) || Objects.isNull(guaranteeInfo.getOtherGuaranteeYear())
			? "" : guaranteeInfo.getOtherGuaranteeYear().toString();
		String waterElectricGuaranteeYear = Objects.isNull(guaranteeInfo) || Objects.isNull(guaranteeInfo.getWaterElectricGuaranteeYear())
			? "" : guaranteeInfo.getWaterElectricGuaranteeYear().toString();
		String waterProofGuaranteeYear = Objects.isNull(guaranteeInfo) || Objects.isNull(guaranteeInfo.getWaterProofGuaranteeYear())
			? "" : guaranteeInfo.getWaterProofGuaranteeYear().toString();

		//兼容枚举的情况
		if (Objects.nonNull(guaranteeInfo) && Objects.nonNull(guaranteeInfo.getWaterProofGuaranteeYearEnum())) {
			waterProofGuaranteeYear = guaranteeInfo.getWaterProofGuaranteeYearEnum().toString();
		}
		if (Objects.nonNull(guaranteeInfo) && Objects.nonNull(guaranteeInfo.getOtherGuaranteeYearEnum())) {
			otherGuaranteeYear = guaranteeInfo.getOtherGuaranteeYearEnum().toString();
		}
		//其他装修部位的保修期限为【 】年
		result.put("otherGuaranteeYear", otherGuaranteeYear);
		//对埋设在墙体、地面内的电气网络管线和给排水管道保修期限
		result.put("waterElectricGuaranteeYear", waterElectricGuaranteeYear);
		//有防水要求的卫生间防渗漏工程保修【】年
		result.put("waterProofGuaranteeYear", waterProofGuaranteeYear);
		return result;
	}

