		Map<String, String> decryptMap = cipherService.decrypt(
			Stream.of(signInfo.getOwnerPhone(), signInfo.getOwnerCertificateNo(),
					signInfo.getAgentPhone(), signInfo.getAgentCertificateNo(),
					signInfo.getCompanyAgentCertificateNo(),signInfo.getCompanyAgentPhone())
				.filter(StringUtils::isNotBlank)
				.distinct()
