	private static final Set<Byte> CUSTOM_ATTACH_TYPES = Collections.unmodifiableSet(
		new HashSet<>(Arrays.asList(
			ContractTypeEnum.ADVANCE.getCode(),
			ContractTypeEnum.PACKAGE_FORMAL.getCode(),
			ContractTypeEnum.PERSONAL.getCode()
		))
