public Map<String, Object> getContractAmount() {
	HashMap<String, Object> result = new HashMap<>();
	Byte contractType = ContractContextHandler.getContractReq().getContractBaseInfo().getContractType();
	if (Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.FULL_SERVICE_SUMMARY.getCode()).contains(contractType)) {
