		result.put("planDeveloperAndClientTotalPrice", planDeveloperAndClientTotalPrice);
		result.put("planDeveloperAndClientTotalPriceText", new MoneyConvertUtil(String.valueOf(planDeveloperAndClientTotalPrice)).convert());
	} else {
		//合同金额
