		result.put("contractAmountText",
			new MoneyConvertUtil(String.valueOf(ContractContextHandler.getContractReq().getProjectInfo().getAmount())).convert());
	}
	return result;
}

public Map<String, Object> getContractAdvanceAmount() {
	HashMap<String, Object> result = new HashMap<>();
	BigDecimal advanceAmount, expectContractAmount;
	BigDecimal advanceToBAmount = BigDecimal.ZERO;
	ContractReqDTO contractReq = ContractContextHandler.getContractReq();
	Byte businessType = contractReq.getProjectInfo().getBusinessType();
	if (contractUnifyService.getAdvanceFromQuotation(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getContractBaseInfo().getContractType(), businessType)) {
		//从用户输入的报价模块获取
		advanceAmount = ContractContextHandler.getContractReq().getQuotation().getAdvanceAmount();
		expectContractAmount = ContractContextHandler.getContractReq().getQuotation().getExpectContractAmount();
	} else {
		//从用户输入的项目模块获取
		advanceAmount = ContractContextHandler.getContractReq().getProjectInfo().getAdvanceAmount();
		expectContractAmount = ContractContextHandler.getContractReq().getProjectInfo().getExpectContractAmount();
		advanceToBAmount = ContractContextHandler.getContractReq().getProjectInfo().getAdvanceToBAmount();
		if (advanceToBAmount == null) {
			advanceToBAmount = BigDecimal.ZERO;
		}
	}
	//合同金额
	result.put("advanceAmount", String.valueOf(advanceAmount));
	//合同金额大写
	result.put("advanceAmountText", new MoneyConvertUtil(String.valueOf(advanceAmount)).convert());
	//预计合同金额
	result.put("expectContractAmount", String.valueOf(expectContractAmount));
	//预计合同金额大写
	result.put("expectContractAmountText", new MoneyConvertUtil(String.valueOf(expectContractAmount)).convert());
	//B支付和B+C支付字段
	BigDecimal advanceToBCAmount = advanceToBAmount.add(expectContractAmount);
	result.put("advanceToBAmount", String.valueOf(advanceToBAmount));
	result.put("advanceToBAmountText", new MoneyConvertUtil(String.valueOf(advanceToBAmount)).convert());
	result.put("advanceToBCAmount", String.valueOf(advanceToBCAmount));
	result.put("advanceToBCAmountText", new MoneyConvertUtil(String.valueOf(advanceToBCAmount)).convert());
	return result;
}

