public Map<String, Object> getSignUserInfoV2() {
	HashMap<String, Object> result = new HashMap<>();
	ContractSignInfoReq signInfo = ContractContextHandler.getContractReq().getSignInfo();
	String ownerAddress = StringUtils.isBlank(signInfo.getOwnerAddress()) ? "" : signInfo.getOwnerAddress();
	String customerIdNo = StringUtils.isBlank(signInfo.getOwnerCertificateNo()) ? "/" : signInfo.getOwnerCertificateNo();
	String ownerCertificateType = CertificateTypeEnum.getNameByCode(signInfo.getOwnerCertificateType());

	String companyAgentIdNo = StringUtils.isBlank(signInfo.getCompanyAgentCertificateNo()) ? "/" : signInfo.getCompanyAgentCertificateNo();
	String companyAgentName = StringUtils.isBlank(signInfo.getCompanyAgentName()) ? "/" : signInfo.getCompanyAgentName();
	String companyAgentPhone = StringUtils.isBlank(signInfo.getCompanyAgentPhone()) ? "/" : signInfo.getCompanyAgentPhone();
	Map<String, String> decryptMap = cipherService.decrypt(
		Stream.of(signInfo.getOwnerPhone(),
				companyAgentIdNo,
				companyAgentPhone,
				customerIdNo)
			.filter(StringUtils::isNotBlank)
			.distinct()
			.collect(Collectors.toList())
	);
	if (ContractObjectTypeEnum.PERSON.getCode().equals(signInfo.getContractObjectType())) {
		//客户住所地址
		result.put("wanLianJiaFangLianXiDiZhi", ownerAddress);
		//客户姓名
		result.put("wangLianJiaFangXingMing", signInfo.getOwnerName());
		//客户手机
		result.put("wanLianJiaFangLianXiFangShi", decryptMap.getOrDefault(signInfo.getOwnerPhone(), signInfo.getOwnerPhone()));
		//客户证件号
		result.put("wanLianJiaFangShenFenZhengHao", decryptMap.getOrDefault(customerIdNo, customerIdNo));
		//客户证件类型
		result.put("wangLianJiaFangZhengJianLeiXing", ownerCertificateType);
	}


	if (ContractObjectTypeEnum.COMPANY.getCode().equals(signInfo.getContractObjectType())) {
		if (RoleTypeEnum.COMPANY_AGENT.getCode().equals(signInfo.getSignRole()) || signInfo.getSignRole() == null) {
			//代理人身份证号
			result.put("wanLianWeiTuoDaiLiRenShenFenZhengHao", decryptMap.getOrDefault(companyAgentIdNo, companyAgentIdNo));
			//代理人手机
			result.put("wanLianWeiTuoDaiLiRenLianXiDianHua", decryptMap.getOrDefault(companyAgentPhone, companyAgentPhone));
			//代理人姓名 没有的话 用 /
			result.put("wanLianWeiTuoDaiLiRenXingMing", companyAgentName);
			//客户证件类型
			String companyAgentCertificateType = CertificateTypeEnum.getNameByCode(signInfo.getCompanyAgentCertificateType());
			result.put("WeiTuoDaiLiRenZhengJianLeiXing", companyAgentCertificateType);
		}
	}

	return result;
}

