public Map<String, Object> getPersonalBudgetUrlV2() {
	HashMap<String, Object> result = new HashMap<>();
	Byte contractType = ContractContextHandler.getContractReq().getContractBaseInfo().getContractType();
	Contract contract = ContractContextHandler.getContext().getContract();
	//由于个性化主材合同和个性化首期款合同共用一套模板，仅个性化主材合同与图纸报价需要报价单信息
	List<Byte> dealContractLis = Arrays.asList(ContractTypeEnum.PERSONAL.getCode(), ContractTypeEnum.DRAWING_QUOTATION.getCode());
	if (!dealContractLis.contains(contractType)) {
		return result;
	}
	Integer contractMode = ContractContextHandler.getContractReq().getContractBaseInfo().getContractMode();
	//个性化主材合同并且是全案模式，个性化报价单不需要附带到合同中
	if (ContractTypeEnum.PERSONAL.getCode().equals(contractType) && ContractModeEnum.FULL_SERVICE.getCode().equals(contractMode)) {
		return result;
	}
	Byte businessType = ContractContextHandler.getContext().getBusinessType();
	boolean processV25 = ContractContextHandler.getContext().isProcessV25();
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25 && contract.getAmount().compareTo(BigDecimal.ZERO) == 0) {
		return result;
	}

	List<ContractSourceDataBO.PersonalContractData> personalContractDataList =
		ContractContextHandler.getContext().getContractSourceDataBO().getPersonalContractDataList()
			.stream().filter(item -> ObjectUtil.equals(item.getOrganizationCode(), contract.getCompanyCode()))
			.collect(Collectors.toList());
	List<String> budgetUrls = new ArrayList<>();



	for (ContractSourceDataBO.PersonalContractData personalContractData : personalContractDataList) {
		ContractSourceDataBO.QuoteInfo quoteInfo = personalContractData.getQuoteInfo();
		BindOrderInfo bindOrderInfo = BindOrderInfo.convert(contract.getProjectOrderId(), personalContractData);
		//当报价单金额为0时，需要校验个性化报价单是否包含C部分，如果不包含C部分，说明当前报价单仅包含B（供应商承担）套餐，则无需附带报价单
		boolean needCheckCPart = commonBusinessService.isBOrBCPaymentType(contract.getProjectOrderId())
			&& BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)
			&& personalContractData.getPersonalContractPrice().compareTo(BigDecimal.ZERO) == 0;
		LOGGER.info("个性化报价单，是否需要校验C部分，needCheckCPart:{}, projectOrderId:{}, companyCode:{}, bindOrderInfo:{}", needCheckCPart, contract.getProjectOrderId(), contract.getCompanyCode(), JSON.toJSONString(bindOrderInfo));
		// —— ① 需要校验 C 部分报价
		if (needCheckCPart) {
			boolean hasCPart = contractSigningSourceRouter.route(bindOrderInfo.getBindType()).hasCPart(bindOrderInfo);
			if (!hasCPart) {
				LOGGER.info("个性化报价单不包含C部分，跳过，projectOrderId:{}, companyCode:{}, bindOrderInfo:{}", contract.getProjectOrderId(), contract.getCompanyCode(), JSON.toJSONString(bindOrderInfo));
				continue;
			}
		}
		// —— ② 报价单文件校验
		if (quoteInfo == null || StringUtils.isBlank(quoteInfo.getFileUrl())) {
			LOGGER.error("个性化报价单生成失败，无法发起签约，projectOrderId:{}, companyCode:{}, data:{}", contract.getProjectOrderId(), contract.getContractCode(), JsonUtil.toJsonString(personalContractDataList));
			throw new NrsBusinessException("个性化报价单为空，无法发起签约，请先工单联系运营");
		}
		// —— ③ 加入列表
		budgetUrls.add(quoteInfo.getFileUrl());
	}
	List<String> imageUrls = new ArrayList<>();
	for (String budgetUrl : budgetUrls) {
		try {
			imageUrls.addAll(pdfToImageService.pdf2ImagePublicParallel(budgetUrl));
		} catch (NrsBusinessException e) {
			if (e.getCode() == ResponseCodeEnum.PDF_PAGES_LIMIT.getCode()) {
				throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(),
					String.format("%s数过多，请检查%s样式并调整控制在%s页及以内", "定软电报价单", "定软电报价单", limitPages),
					Level.WARN);
			}
		}
	}
	String signDate = DateUtils.getDateStr(new Date());
	List<FormalPackageContractFreeformDTO.PhotoInfo> photos = imageUrls.stream()
		.map(src -> new FormalPackageContractFreeformDTO.PhotoInfo(src, signDate, false)).collect(
			Collectors.toList());
	if (CollectionUtils.isNotEmpty(photos)) {
		//设置photos最后一页盖章
		photos.get(photos.size() - 1).setSign(true);
	}
	result.put("personalBudgetUrl", JsonUtil.toJsonString(photos));
	return result;
}

