public Map<String, Object> getAgentUserInfo() {
	HashMap<String, Object> result = new HashMap<>();
	ContractSignInfoReq signInfo = ContractContextHandler.getContractReq().getSignInfo();
	//代理人姓名
	String agentName = "/";
	//代理人证件类型
	String agentIdNoType = "/";
	//代理人证件号
	String agentIdNo = "/";
	//代理人手机号
	String agentPhone = "/";
	//主体类型
	Byte contractObjectType = signInfo.getContractObjectType();
	//个人签约是否有代理人
	Byte haveAgent = signInfo.getHaveAgent();
	//个人签约&有代理人
	if (ContractObjectTypeEnum.PERSON.getCode().equals(contractObjectType) && HaveAgentEnum.YES.getCode().equals(haveAgent)) {
		agentName = signInfo.getAgentName();
		agentIdNoType = CertificateTypeEnum.getNameByCode(signInfo.getAgentCertificateType());
		agentIdNo = signInfo.getAgentCertificateNo();
		agentPhone = signInfo.getAgentPhone();
	} else if (ContractObjectTypeEnum.COMPANY.getCode().equals(contractObjectType)) {
		if (signInfo.getSignRole() == null || RoleTypeEnum.COMPANY_AGENT.getCode().equals(signInfo.getSignRole())) {
			agentName = signInfo.getCompanyAgentName();
			agentIdNoType = CertificateTypeEnum.getNameByCode(signInfo.getCompanyAgentCertificateType());
			agentIdNo = signInfo.getCompanyAgentCertificateNo();
			agentPhone = signInfo.getCompanyAgentPhone();
		}
	}
	//解密
	Map<String, String> decryptMap = cipherService.decrypt(
		Stream.of(agentIdNo, agentPhone)
			.filter(StringUtils::isNotBlank)
			.distinct()
			.collect(Collectors.toList())
	);
	result.put("agentName", agentName);
	result.put("agentIdNoType", agentIdNoType);
	result.put("agentIdNo", decryptMap.getOrDefault(agentIdNo, agentIdNo));
	result.put("agentPhone", decryptMap.getOrDefault(agentPhone, agentPhone));
	return result;
}

public Map<String, Object> getFirstPartUserInfo() {
	HashMap<String, Object> result = new HashMap<>();
	//代理人信息
	result.put("firstAgentPartName", "/");
	result.put("firstAgentCertificateType", "/");
	result.put("firstAgentPartCertificateNo", "/");
	result.put("firstAgentPartPhone", "/");
	ContractSignInfoReq signInfo = ContractContextHandler.getContractReq().getSignInfo();
	//解密
	Map<String, String> decryptMap = cipherService.decrypt(
		Stream.of(signInfo.getOwnerPhone(), signInfo.getOwnerCertificateNo(),
				signInfo.getAgentPhone(), signInfo.getAgentCertificateNo(),
				signInfo.getCompanyAgentCertificateNo(),signInfo.getCompanyAgentPhone())
			.filter(StringUtils::isNotBlank)
			.distinct()
			.collect(Collectors.toList())
	);
	if (ContractObjectTypeEnum.PERSON.getCode().equals(signInfo.getContractObjectType())) {
		//业主
		result.put("firstPartName", signInfo.getOwnerName());
		result.put("firstPartPhone", decryptMap.getOrDefault(signInfo.getOwnerPhone(), signInfo.getOwnerPhone()));
		result.put("firstPartCertificateNo", decryptMap.getOrDefault(signInfo.getOwnerCertificateNo(), signInfo.getOwnerCertificateNo()));
		result.put("firstCertificateType", CertificateTypeEnum.getNameByCode(signInfo.getOwnerCertificateType()));
		if (HaveAgentEnum.YES.getCode().equals(signInfo.getHaveAgent())) {
			result.put("firstAgentPartName", signInfo.getAgentName());
			result.put("firstAgentCertificateType", CertificateTypeEnum.getNameByCode(signInfo.getAgentCertificateType()));
			result.put("firstAgentPartCertificateNo", decryptMap.getOrDefault(signInfo.getAgentCertificateNo(), signInfo.getAgentCertificateNo()));
			result.put("firstAgentPartPhone", decryptMap.getOrDefault(signInfo.getAgentPhone(), signInfo.getAgentPhone()));
		}
	} else if (ContractObjectTypeEnum.COMPANY.getCode().equals(signInfo.getContractObjectType())) {
		result.put("firstPartName", signInfo.getCompanyName());
		result.put("firstPartCertificateNo", signInfo.getCompanyCreditCode());
		result.put("firstCertificateType", "营业执照");
		if (RoleTypeEnum.COMPANY_AGENT.getCode().equals(signInfo.getSignRole())) {
			result.put("firstAgentPartName", signInfo.getCompanyAgentName());
