public String createPdfByFreeform(Contract contract, ContractCityCompanyInfo config, boolean finalVersion) {
	//获取协议平台字段配置
	List<ContractProtocolConfig> contractProtocolConfigs = contractProtocolConfigService.getContractProtocolConfig(config.getFormKey(),
		config.getFormId());
	Set<String> dealFunctions = contractProtocolConfigs.stream().map(ContractProtocolConfig::getDealFunction)
		.filter(StringUtils::isNotBlank).collect(Collectors.toSet());
	LOGGER.info("pdf生成的处理方法为：{},threadId:{}", dealFunctions, Thread.currentThread().getId());
	Map<String, Object> formData = buildFormData(dealFunctions);
	//检查用户生成pdf的数据为空情况,最终版本的合同需要校验
	if (finalVersion) {
		checkCreatePdfData(contractProtocolConfigs, formData);
	}
	//检查合同协议配置的表单字段在协议平台配置的表单字段一致性
	checkFormFieldConfig(config.getFormId());

	LOGGER.info("pdf生成时，最终的formData为：{},,threadId:{}", JSON.toJSONString(formData), Thread.currentThread().getId());
	return contractBusinessService.generatePdf(contract, formData);

}

public Map<String, Object> buildFormData(Set<String> dealFunctions){
	/**
	 * 数据库dealFunction配置了每个字段的获取方法名，contractPdfBuildService封装了所有方法的实现
	 * 通过反射，获取请求协议平台的每个字段的值
	 */
	Map<String, Object> formData = new HashMap<>();
	for (String dealFunction : dealFunctions) {
		try {
			if (StringUtils.isBlank(dealFunction)) {
				continue;
			}
			Method method = contractPdfBuildService.getClass().getMethod(dealFunction, null);
			Map invokeResult = (Map) method.invoke(contractPdfBuildService, null);
			formData.putAll(invokeResult);
			LOGGER.info("pdf生成时，调用方法{}返回结果为：{},,threadId:{}", dealFunction, invokeResult, Thread.currentThread().getId());
		} catch (NoSuchMethodException e) {
			LOGGER.error("pdf生成时，调用方法不存在,方法名：{},threadId:{}", dealFunction, Thread.currentThread().getId(), e);
			if (!KeUtils.isEnvironmentActive("test")) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), e.getMessage());
			}
		} catch (Exception e) {
			Throwable actualException = e.getCause(); // 获取包装的实际异常
			String errorMessage = actualException == null ? e.getMessage() : actualException.getMessage(); // 获取实际异常的消息
			if (!(actualException instanceof NrsBusinessException && ((NrsBusinessException) actualException).getLevel() == Level.WARN)) {
				LOGGER.error("pdf生成时，调用方法异常,方法名：{},threadId:{}", dealFunction, Thread.currentThread().getId(), e);
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), errorMessage);
			} else {
				LOGGER.info("pdf生成时，调用方法异常,方法名：{},threadId:{},e:{}", dealFunction, Thread.currentThread().getId(), e);
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), errorMessage, Level.WARN);
			}
		}
	}
	return formData;
}

public String createPdfBySelfGeneration(Contract contract, ContractCityCompanyInfo config, boolean finalVersion) {
	try {
		//模拟异常，测试兜底逻辑
		if (contractApolloConfig.inErrorTestProjectOrderIds(contract.getProjectOrderId())) {
			throw new NrsBusinessException("模拟异常，测试兜底逻辑");
		}
		CreateContractPdfBySelfStrategy pdfBySelfStrategy = contractPdfBySelfStrategyFactory.getContractPdfBySelfStrategy(contract.getType(),contract.getBusinessType());
		return pdfBySelfStrategy.createPdf(contract, config, finalVersion);
	} catch (Exception e) {
		//图纸数量和大小超出系统上限 不再请求协议平台生成合同
		if (e instanceof NrsBusinessException && ResponseCodeEnum.DRAWING_LIMIT_ERROR.getCode().equals(((NrsBusinessException) e).getCode())) {
			throw new NrsBusinessException(ResponseCodeEnum.DRAWING_LIMIT_ERROR.getCode(), e.getMessage(), Level.WARN);
		}
		ContractContext context = ContractContextHandler.getContext();
		Byte businessType = context.getBusinessType();
		//仅整装支持使用兜底生成逻辑
		if (!BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			LOGGER.error("自主生成pdf异常，projectOrderId:{}", contract.getProjectOrderId(), e);
			throw new NrsBusinessException(e.getMessage());
		}
		LOGGER.error("发起签约自主生成pdf异常，兜底使用协议平台生成pdf，projectOrderId:{}，contractType:{}", contract.getProjectOrderId(), contract.getType(), e);
		contract.setPdfGenerationMode(PdfGenerationModeEnum.FORMATTED.getCode());
		return createPdfByFreeform(contract, config, finalVersion);
	}
}

private void checkCreatePdfData(List<ContractProtocolConfig> contractProtocolConfigs, Map<String, Object> formData) {
	for (ContractProtocolConfig contractProtocolConfig : contractProtocolConfigs) {
		//允许为空的字段不校验
		if (CommonEnum.YES.getCode().equals(contractProtocolConfig.getAllowBlank())) {
			continue;
		}
		String fieldKey = contractProtocolConfig.getFormFieldKey();
		Object fieldValue = formData.get(fieldKey);
		if (fieldValue == null || StringUtils.isBlank(String.valueOf(fieldValue))) {
			String errorMsg = String.format("合同生成pdf，组装数据后有必填字段为空，字段key：%s，字段value：%s", fieldKey, fieldValue);
			LOGGER.error(errorMsg);
			throw new NrsBusinessException(ResponseCodeEnum.CONTRACT_FIELD_MISS.getCode(),
				String.format(ResponseCodeEnum.CONTRACT_FIELD_MISS.getMsg(), contractProtocolConfig.getFormFieldName()),
				Level.ERROR
			);
		}
	}
	LOGGER.info("合同生成pdf，组装数据必填字段为空校验完成，数据正常");
}

private void checkFormFieldConfig(Integer formId) {
	try {
		Set<String> freeformDeficiencyFields = commonContractService.getFreeformDeficiencyFields(Long.valueOf(formId));
		if (!CollectionUtils.isEmpty(freeformDeficiencyFields)) {
			LOGGER.error("合同发起，检查formId字段配置信息发现异常发现异常,formId:{},缺失字段：{}", formId, freeformDeficiencyFields);
			//先跑一段时间，没问题后再打开，抛出异常
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "合同字段缺失，请联系运营检查配置", Level.WARN);
		}
		LOGGER.info("合同发起，合同协议配置的表单字段在协议平台配置的表单字段一致性校验完成，数据正常");
	} catch (Exception e) {
		LOGGER.error("合同发起，检查formId字段配置信息发生异常,formId:{}", formId);
	}
}

