	 *
	 * @param contractReq
	 * @return
	 */
	@ContractDataPrepare
	public ContractSubmitResDTO saveDraft(ContractReqDTO contractReq) {
		//预校验报价类型
		contractUnifyService.comboTypePreCheck(contractReq);
		//对公签约多主体校验
		contractUnifyService.checkCompanySignMultipleCompany(contractReq);
		//正签合并发起销售合同校验
		contractUnifyService.formalPersonalContractCheck(contractReq);
		List<ContractReqDTO> contractReqDTOList = buildContractReqList(contractReq);
		//保存草稿合同
		List<Contract> contractList = ((ContractSaveDraftService) AopContext.currentProxy()).saveDraftContractList(contractReqDTOList);
		return ContractSubmitResDTO.builder()
			.contractCode(contractList.stream().map(Contract::getContractCode).findFirst().orElse(null))
			.build();
	}


    public List<ContractReqDTO> buildContractReqList(ContractReqDTO baseContractReq) {
		Byte contractType = baseContractReq.getContractBaseInfo().getContractType();
        if(!ContractTypeEnum.PERSONAL.getCode().equals(contractType)){
			return CollectionUtil.newArrayList(baseContractReq);
		}
		if (ContractContextHandler.getContractSourceDataBO()==null||CollectionUtil.isEmpty(ContractContextHandler.getContractSourceDataBO().getPersonalContractDataList())){
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "个性化报价数据未获取成功", Level.WARN);
		}
		List<ContractReqDTO> contractReqTempList = new ArrayList<>();
		List<ContractSourceDataBO.PersonalContractData> personalContractDataList = ContractContextHandler.getContractSourceDataBO().getPersonalContractDataList();
		//按主体分组
		Map<String, List<ContractSourceDataBO.PersonalContractData>> personalContractDataMap = personalContractDataList.stream()
			.collect(Collectors.groupingBy(ContractSourceDataBO.PersonalContractData::getOrganizationCode));
		personalContractDataMap.forEach((organizationCode, personalContractDataListByOrg) -> {
			ContractReqDTO personalContractReqTemp = CommonUtil.deepCopy(baseContractReq, ContractReqDTO.class);
			personalContractReqTemp.getContractBaseInfo().setSubmitCompanyCode(organizationCode);

			// 构造单据 info
			BindOrderInfoGroup group = BindOrderInfo.convert(baseContractReq.getContractBaseInfo().getProjectOrderId(), personalContractDataListByOrg);
			personalContractReqTemp.getBusinessInfo().setBillCodeInfoList(group.getBillCodeInfos());
			personalContractReqTemp.getBusinessInfo().setSubOrderInfoList(group.getSubOrderInfos());
			personalContractReqTemp.getBusinessInfo().setChangeOrderInfoList(group.getChangeOrderInfos());

			// 构造商品信息
			List<BindOrderInfo> bindOrderInfos = group.getBindOrderInfos();
			Map<String, String> goodsInfoByOrderNo = bindOrderInfos.stream()
				.map(bindOrderInfo -> contractSigningSourceRouter.route(bindOrderInfo.getBindType()).buildGoodsInfo(bindOrderInfo))
				.flatMap(map -> map.entrySet().stream())
				.collect(Collectors.toMap(
					Map.Entry::getKey,
					Map.Entry::getValue,
					(v1, v2) -> v2
				));

			personalContractReqTemp.getBusinessInfo().setGoodsInfo(String.join(",", goodsInfoByOrderNo.values()));
			contractReqTempList.add(personalContractReqTemp);
		});
		return contractReqTempList;
	}

	@Transactional
	public List<Contract> saveDraftContractList(List<ContractReqDTO> contractReqList) {
		List<Contract> contractList = new ArrayList<>();
		for (ContractReqDTO contractReq : contractReqList) {
			//保存草稿合同
			Contract contract = saveDraftContract(contractReq);
			contractList.add(contract);
		}
		return contractList;
	}





	/**
	 * 保存草稿，生成草稿合同
	 *
	 * @param contractReq
	 * @return
	 */
	@Transactional
	public Contract saveDraftContract(ContractReqDTO contractReq) {
		//校验参数合法性
		contractUnifyService.checkParamLegitimacy(contractReq);
		//构建合同数据
		Contract contract = contractUnifyService.buildDraftContract(contractReq);
		//当前发起合同数据保存
		contractUnifyService.saveDraftCoreContractDb(contract, contractReq);
		//与当前合同一起合并发起的合同类型
		List<Byte> mergeLaunchTypeList = contractMergeLaunchComputer.computeContractType(contract.getType());
		//与当前合同合并发起的合同数据保存
		List<String> relationContractCodeList = contractUnifyServiceSelf.mergeLaunchSaveContract(contractReq, mergeLaunchTypeList);
		//记录合同关联关系
		contractSubmitService.bindContractRelation(contract, relationContractCodeList, ContractRelationEnum.MERGE_LAUNCH);
		//记录合同和单据的关联关系
		BindOrderInfoGroup group = BindOrderInfoGroup.convert(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getBusinessInfo());
		quotationRelationCommonService.bindCodeRelationWithClear(contract, group);
		return contract;
	}


}

