	@ContractDataPrepare
	public ContractSubmitResDTO submit(ContractReqDTO contractReq) {
		LOGGER.info("合同提交开始，请求参数：{}", JSON.toJSONString(contractReq));
		ProjectInfoDTO projectInfo = ContractContextHandler.getProjectInfo();
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		//个性化合同校验
		personalContractCheckV2(contractReq);
		//正签合并发起设计合同校验
		contractUnifyService.formalDesignContractCheck(contractReq);
		// 正签合并发起前置校验
		contractUnifyService.formalMergeLaunchCheck(contractReq, projectInfo.getProjectOrderId());
		//补充协议/和解协议发起前置校验
		contractUnifyService.supplementContractLaunchCheck(contractReq, projectInfo.getProjectOrderId());
		//对公签约多主体校验
		contractUnifyService.checkCompanySignMultipleCompany(contractReq);
		//预校验报价类型
		contractUnifyService.comboTypePreCheck(contractReq);
		//检查合同是否可以创建
		contractUnifyService.preSignCheck(contractType, projectInfo, Boolean.TRUE,
			ContractPreCheckBo.builder()
				.buildingId(contractReq.getProjectInfo().getBuildingId())
				.resblockId(contractReq.getProjectInfo().getResblockId())
				.changeOrderId(contractReq.getContractBaseInfo().getChangeOrderId())
				.build());
		//校验参数合法性
		contractUnifyService.checkParamLegitimacy(contractReq);
		// 请求数据预先填充（工期、设计费）
		preFillReqData(contractReq);
		// 合同字段校验
		contractUnifyService.contractFieldCheck(contractReq, projectInfo);
		terminalFundAmountCheck(projectInfo.getProjectOrderId(), contractType);

		//扣减产能
		decrQuota(contractReq);
		List<ContractReqDTO> contractReqDTOList = contractSaveDraftService.buildContractReqList(contractReq);
		//当前发起的合同类型，构建合同草稿数据&保存
		List<ContractSubmitCore> mainContractSubmitCoreList = ((ContractSubmitService) AopContext.currentProxy()).saveDraftContractList(contractReqDTOList);
		String contractPollKey = contractUnifyService.getContractPollKey(projectInfo.getProjectOrderId(), contractType);
		//创建合同pdf&发起合同
		List<Contract> contracts = submitLaunch(mainContractSubmitCoreList, contractPollKey);
		return ContractSubmitResDTO.builder()
			.contractCode(mainContractSubmitCoreList.stream().map(ContractSubmitCore::getContract).map(Contract::getContractCode).findFirst().orElse(null))
			.contractUrl(contracts.stream().map(core -> FileInfo.builder()
				.type(FileTypeEnum.PDF.getKey())
				.contractType(core.getType())
				.url(homeAndPcCommonService.getContractUrl(core))
				.build()).collect(Collectors.toList()))
			.contractResultPollingKey(contractPollKey)
			.estimatedLaunchTime(ContractTypeEnum.getEnumByCode(contractType).getEstimatedLaunchTime())
			.build();
	}


	/**
	 * 合同提交前提前保存合同草稿（可批量生成的合同类型不进行保存，会影响合同生成）
	 */
	@Transactional
	public void buildAndSaveContractDraft(ContractReqDTO contractReq) {
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		if (ContractTypeEnum.CAN_BATCH_SUBMIT_LIST.contains(contractType)) {
			return;
		}
		//构建合同数据&保存
		Contract contract = contractUnifyService.buildDraftContract(contractReq);
		contractService.saveOrUpdateContract(contract);
		//记录合同和报价单的关联关系
		BindOrderInfoGroup group = BindOrderInfoGroup.convert(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getBusinessInfo());
		quotationRelationCommonService.bindCodeRelationWithClear(contract, group);

	}

	@Transactional
	public List<ContractSubmitCore> saveDraftContractList(List<ContractReqDTO> contractReqDTOList) {
		List<ContractSubmitCore> contractSubmitCoreList = new ArrayList<>();
		for (ContractReqDTO contractReqDTO : contractReqDTOList) {
			buildAndSaveContractDraft(contractReqDTO);
			//构造提交状态合同
			Contract contract = buildSubmitContract(contractReqDTO);
			ContractSubmitCore contractSubmitCore = ContractSubmitCore.builder()
				.contractReq(contractReqDTO)
				.contract(contract)
				.build();
			contractSubmitCoreList.add(contractSubmitCore);
		}
		return contractSubmitCoreList;
	}

	/**
	 * 获取需要合并发起的所有合同类型
	 */
	public List<Byte> getSubmitContractTypeList(Byte contractType, List<Byte> relationContractTypes) {
		List<Byte> contractTypeList = new ArrayList<>(relationContractTypes);
		contractTypeList.add(contractType);
		return contractTypeList;
	}

	/**
	 * 发起合同
	 *
	 * @param mainContractSubmitCoreList 当前需要发起的合同
	 * @return 当合同为同步发起时，返回发起的合同信息
	 */
	public List<Contract> submitLaunch(List<ContractSubmitCore> mainContractSubmitCoreList, String contractPollKey) {
		Byte contractType = ContractContextHandler.getContractReq().getContractBaseInfo().getContractType();
		String projectOrderId = ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId();
		List<Contract> mainContractList = mainContractSubmitCoreList.stream().map(ContractSubmitCore::getContract).collect(Collectors.toList());
		//获取需要合并发起的合同类型
		List<Byte> relationContractTypes = contractMergeLaunchComputer.computeContractType(contractType);
		LOGGER.info("订单号：{},合同类型：{},需要合并发起的合同类型：{}", projectOrderId, contractType, relationContractTypes);
		//需要发起的合同类型
		List<Byte> contractTypeList = getSubmitContractTypeList(contractType, relationContractTypes);
		List<String> submitLockKey = contractTypeList.stream().map(item -> LockConstant.getContractLaunchingKey(projectOrderId, item)).collect(Collectors.toList());
		List<Contract> resultContractList = new ArrayList<>();
		ContractContext context = ContractContextHandler.getContext();
		HeaderParam headerContext = HeaderContext.getContext();
		CompletableFuture<Void> launchFuture = CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				List<String> mainContractCodeList = mainContractList.stream().map(Contract::getContractCode).collect(Collectors.toList());
				LOGGER.info("异步发起合同开始，contractType:{}，mainContractCodeList:{}，threadId:{}", contractTypeList, mainContractCodeList, Thread.currentThread().getId());
				launchContractBefore(context, headerContext, submitLockKey);
				//pdf生成
				List<ContractSubmitCore> contractSubmitCoreList = contractSubmitServiceSelf.parallelGreatPdf(mainContractSubmitCoreList, contractTypeList);
				//数据保存
				contractSubmitServiceSelf.submitContractDealData(ContractLaunchDataSaveParam.builder()
					.mainContractList(mainContractList)
					.contractPollKey(contractPollKey)
					.contractSubmitCoreList(contractSubmitCoreList)
					.relationContractTypes(relationContractTypes)
					.build());
				resultContractList.addAll(contractSubmitCoreList.stream().map(ContractSubmitCore::getContract).collect(Collectors.toList()));
				launchContractAfter(submitLockKey, mainContractList);
				LOGGER.info("异步发起合同结束，contractType:{}，mainContractCodeList:{}，threadId:{}", contractTypeList, mainContractCodeList, Thread.currentThread().getId());
			} catch (Exception e) {
				Throwable cause = e.getCause();
				if (!(cause instanceof NrsBusinessException && ((NrsBusinessException) cause).getLevel() == Level.WARN)) {
					LOGGER.error("异步发起合同异常,projectOrderId:{},threadId:{}", projectOrderId, Thread.currentThread().getId(), e);
				}
				launchContractException(mainContractSubmitCoreList, e, contractPollKey, submitLockKey);
			}
		}), contractSubmitExternalExecutor);
		if (contractSubmitSync(contractType)) {
			try {
				launchFuture.get();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			} catch (Exception e) {
				Throwable cause = e.getCause();
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), cause == null ? e.getMessage() : cause.getMessage());
			}
		}
		return resultContractList;
	}

	/**
	 * 发起合同前后处理
	 */
	private void launchContractBefore(ContractContext context, HeaderParam headerContext, List<String> submitLockKey) {
		String projectOrderId = context.getContractReq().getContractBaseInfo().getProjectOrderId();
		Byte contractType = context.getContractReq().getContractBaseInfo().getContractType();
		//合同发起加锁（授权协议书不加锁，授权协议书后台批量生成的）
		if (!ContractTypeEnum.CAN_BATCH_SUBMIT_LIST.contains(contractType)) {
			lockService.lockElseThrow(submitLockKey);
		}

		// 提前生成款项 正签保存收款计划需要查询款项
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			fundBaseService.createFund(projectOrderId);
		}

		// 清空contract_file_info_record表数据
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			contractFileInfoService.clearOldRecord(projectOrderId, ContractFileTypeEnum.getAllCodes());
		}

		//设置合同发起ThreadLocal到当前线程
		ContractContext contextTemp = CommonUtil.deepCopy(context, ContractContext.class);
		ContractContextHandler.setContext(contextTemp);
		try {
			HeaderContext.setContext(headerContext);
		} catch (Exception e) {
			throw new RuntimeException(e);
		}

		// 实时检查套餐内的材料配送清单是否与最新数据保持一致；若不一致，重新生成
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) || ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
			List<String> comboCodes = contractPdfBuildService.getComboCodesByContractType(contractType, context.getContractReq(), ContractContextHandler.getPlanAllDTO());
			// 生成材料配送清单 pdf
			try {
				comboInfoMaterialGenerator.generateAndReplaceMaterialList(comboCodes);
			} catch (Exception e) {
				LOGGER.error("生成材料配送清单失败，不阻塞合同发起流程. comboCodes: {}", comboCodes, e);
			}
		}
	}

	/**
	 * 发起合同结束后处理
	 */
	private void launchContractAfter(List<String> submitLockKey, List<Contract> mainContractList) {
		try {
			Byte contractType = ContractContextHandler.getContractReq().getContractBaseInfo().getContractType();
			// 构造不需要回写客源的合同类型列表
			List<Byte> noRewriteCustomerContractTypes = Arrays.asList(
				ContractTypeEnum.TERMINAL.getCode(),
				ContractTypeEnum.ACCREDIT.getCode()
			);

			if (!noRewriteCustomerContractTypes.contains(contractType)) {
				//客源回写信息,不在列表中的回写
				String ip = null;
				Long userId = null;
				try {
					//观察一下有获取失败的情况，获取失败不影响同步客源
					ip = StringUtils.isNotBlank(HeaderContext.getContext().getIp()) ? HeaderContext.getContext().getIp() : null;
					userId = HeaderContext.getUserId();
				} catch (Exception e) {
					LOGGER.error("发起签约获取ip or 操作人id失败，projectOrderId:{}", ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId(), e);
				}
				contractUnifyService.rewriteCustomer(ContractContextHandler.getContractReq(), userId, ip);
			}
			for (Contract contract : mainContractList) {
				//如果是解约协议单独发起场景，需要判断是否在合同关联关系表中存在关联关系，存在则删除
				if (ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
					ContractRelation contractRelation = contractRelationService.getByRelateContractCode(contract.getContractCode());
					if (contractRelation != null) {
						contractRelationService.deleteRelationByContractCodes(Lists.newArrayList(contract.getContractCode()));
						LOGGER.info("解约协议单独发起，删除存在的合同关联关系，contractCode:{}", contract.getContractCode());
					}
				}
				String projectOrderId = ContractContextHandler.getContractReq().getContractBaseInfo().getProjectOrderId();
				if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
					ContractProcessModeChangeInfo contractProcessModeChangeInfo = formalReSignService.getContractProcessModeChangeInfo(projectOrderId);
					if (contractProcessModeChangeInfo.isHaveHistoricalContract()) {
						List<Contract> formalContractList = contractService.getContractList(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode()).stream().sorted(Comparator.comparing(Contract::getId)).collect(Collectors.toList());
						Contract beforeFormalContract = formalContractList.get(0);
						if (ContractStatusEnum.FINISH.getCode().equals(beforeFormalContract.getStatus())) {
							contractService.updateContractStatus(beforeFormalContract.getContractCode(), ContractStatusEnum.CANCEL.getCode());
							quotationRelationCommonService.cancelContractRelations(beforeFormalContract.getContractCode());
							LOGGER.info("当前场景为2.0->2.5,已有2.0正式合同,生成2.5正式套餐合同后，原2.0正签合同取消，contractCode:{}", beforeFormalContract.getContractCode());
						}
					}
				}
			}
		} finally {
			//清除threadLocal
			delSubmitThreadLocal();
			//合同发起解锁
			lockService.unLock(submitLockKey);
		}
	}

	/**
	 * 发起合同异常处理
	 */
	private void launchContractException(List<ContractSubmitCore> mainContractSubmitCoreList, Throwable e, String contractPollKey, List<String> submitLockKey) {
		try {
			String errorMessage = "";
			for (ContractSubmitCore contractSubmitCore : mainContractSubmitCoreList) {
				Contract contract = contractSubmitCore.getContract();
				Throwable cause = e.getCause();
				errorMessage = contractUnifyService.getContractSubmitErrorMessage(e);
				//pdf生成失败,允许重试
				boolean retrySubmit = cause instanceof NrsBusinessException && ((NrsBusinessException) cause).getCode() == ResponseCodeEnum.PDF_CREATE_ERROR.getCode();
				//保存发起结果到redis
				contractUnifyService.saveContractSubmitToRedis(Lists.emptyList(), ContractSubmitStatusEnum.FAIL, contractPollKey, errorMessage, retrySubmit);
				//非批量发起的合同才保存草稿，批量发起的不能复用草稿
				if (!ContractTypeEnum.CAN_BATCH_SUBMIT_LIST.contains(contract.getType())) {
					//保存草稿
					contractUnifyService.saveDraftContract(contractSubmitCore.getContractReq());
					//记录合同发起失败信息
					contractService.updateContractErrorMessage(contract.getContractCode(), errorMessage);
				}
			}
			LOGGER.error("发起合同异常报警", e);
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), errorMessage);
		} finally {
			//异常情况也清除threadLocal
			delSubmitThreadLocal();
			lockService.unLock(submitLockKey);
		}
	}

	/**
	 * 清除合同发起ThreadLocal
	 */
	private void delSubmitThreadLocal() {
		ContractContextHandler.clearContext();
		HeaderContext.clearContext();
	}

	/**
	 * 并行生成pdf,发生异常重试一次
	 */
	@Retryable(value = Exception.class, maxAttempts = 2, backoff = @Backoff(value = 3000, multiplier = 1))
	public List<ContractSubmitCore> parallelGreatPdf(List<ContractSubmitCore> mainContractSubmitCoreList, List<Byte> contractTypeList) {
		List<Contract> mainContractList = mainContractSubmitCoreList.stream().map(ContractSubmitCore::getContract).collect(Collectors.toList());
		List<ContractSubmitCore> contractSubmitCoreList = new ArrayList<>(mainContractSubmitCoreList);
		ContractReqDTO contractReq = ContractContextHandler.getContractReq();
		if (contractTypeList.size() > 1) {
			//设置合并发起标识
			ContractContextHandler.getContext().setMergeLaunch(true);
		}
		//为合并发起准备参数
		List<ContractReqDTO> contractReqTempList = new ArrayList<>();
		List<ContractReqDTO> personalContractReqTempList = new ArrayList<>();
		for (Byte contractType : contractTypeList) {
			if (contractType.equals(mainContractSubmitCoreList.get(0).getContract().getType())) {
				continue;
			}
			ContractReqDTO contractReqTemp = CommonUtil.deepCopy(contractReq, ContractReqDTO.class);
			contractReqTemp.getContractBaseInfo().setContractType(contractType);
			if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.TERMINAL.getCode())) {
				contractReqTemp = commonContractService.buildMergeTerminalContractReq(contractReqTemp);
			}
			// 构建合并发起补充协议参数
			if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.SUPPLEMENT.getCode())) {
				contractReqTemp = commonContractService.buildMergeSupplementContractReq(contractReqTemp);
			}
			if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.DRAWING.getCode())) {
				contractReqTemp.getSignInfo().setAttachUrl(contractReq.getSignInfo().getDrawingAttachUrl());
			}
			if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.PERSONAL.getCode())) {
				personalContractReqTempList = contractUnifyService.buildPersonalContractReqList(contractReq);
			}
			if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.DESIGN.getCode())) {
				contractReqTemp = commonContractService.buildMergeDesignContractReq(contractReqTemp);
			}
			// 授权书默认协议确认
			if (contractReqTemp.getContractBaseInfo().getContractType().equals(ContractTypeEnum.AUTH_AGENT.getCode())) {
				contractReqTemp.getSignInfo().setUserSignType(UserSignTypeEnum.CONFIRM.getCode());
			}
			if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
				contractReqTempList.addAll(personalContractReqTempList);
			} else {
				contractReqTempList.add(contractReqTemp);
			}
		}
		for (ContractReqDTO contractReqDTO : contractReqTempList) {
			//构造合同
			Contract contractTemp = buildSubmitContract(contractReqDTO);
			contractSubmitCoreList.add(ContractSubmitCore.builder()
				.contractReq(contractReqDTO)
				.contract(contractTemp)
				.build());
		}
		//异步生成pdf
		for (ContractSubmitCore contractSubmitCore : contractSubmitCoreList) {
			ContractContext context = ContractContextHandler.getContext();
			context.setContractSubmitCoreList(contractSubmitCoreList);
			CompletableFuture<Void> pdfFuture = CompletableFuture.runAsync(RunnableWrapper.of(() -> {
				LOGGER.info("异步生成pdf开始,contractType:{},contractCode:{},threadId:{}", contractSubmitCore.getContract().getType(), contractSubmitCore.getContract().getContractCode(), Thread.currentThread().getId());
				ContractContext contextTemp = CommonUtil.deepCopy(context, ContractContext.class);
				contextTemp.setContractReq(contractSubmitCore.getContractReq());
				ContractContextHandler.setContext(contextTemp);
				//合并发起模式下 解约协议需要处理数据域中的数据,发起的是关联项目的解约协议
				if (ContractTypeEnum.TERMINAL.getCode().equals(contractSubmitCore.getContract().getType()) && ContractContextHandler.getContext().isMergeLaunch()) {
					dealTerminalContractCoreData();
				}
				try {
					contractUnifyService.createOnlinePdf(contractSubmitCore.getContract(), true);
				} catch (Exception e) {
					//记录生成pdf失败日志
					contractLogService.createLog(mainContractList.get(0).getContractCode(), LogTypeEnum.CREATE_PDF_ERROR.getCode(), LogTypeEnum.CREATE_PDF_ERROR.getName(), e.getMessage(), contractSubmitCore.getContract().getModifyUserId(), contractSubmitCore.getContract().getModifyUserName());
					throw e;
				} finally {
					//清除threadLocal
					ContractContextHandler.clearContext();
				}
				LOGGER.info("异步生成pdf结束,contractType:{},contractCode:{},threadId:{}", contractSubmitCore.getContract().getType(), contractSubmitCore.getContract().getContractCode(), Thread.currentThread().getId());
			}), contractSubmitExternalExecutor);
			contractSubmitCore.setPdfFuture(pdfFuture);
		}

		CompletableFuture<Void> allOf = CompletableFuture.allOf(
			contractSubmitCoreList.stream().map(ContractSubmitCore::getPdfFuture).toArray(CompletableFuture[]::new));
		//等待所有线程执行完毕
		allOf.join();
		return contractSubmitCoreList;
	}

	/**
	 * 个性化合同校验
	 */
	public void personalContractCheckV2(ContractReqDTO contractReq) {
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		String changeOrderId = StringUtils.isNotBlank(contractReq.getContractBaseInfo().getChangeOrderId()) ? contractReq.getContractBaseInfo().getChangeOrderId() : "";
		if (!ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			return;
		}
		if (StringUtils.isNotBlank(changeOrderId)) {
			//查询变更范围，不包含报价不处理
			ChangeApplyInfoDTO changeApplyInfoDTO = atomChangeRpc.getChangeApplyInfo(changeOrderId);
			List<Integer> changeScopeList = changeApplyInfoDTO.getChangeScopeList();
			if (!changeScopeList.contains(ChangeScopeEnum.QUOTATION.getCode())) {
				throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "变更单变更范围不包含报价，请检查", Level.WARN);
			}
			//如果变更单不包含个性化报价,则不处理
			if (!atomBudgetRpc.containPersonQuotation(changeOrderId)) {
				throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "变更单不包含个性化报价，请检查", Level.WARN);
			}
		}

		// 校验业主手机号不能为外部导购（白名单内的订单跳过校验）
		String ownerPhone = contractReq.getSignInfo().getOwnerPhone();
		String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();
		// 白名单内的订单跳过校验
		if (!contractApolloConfig.isInOwnerPhoneWhitelist(projectOrderId)) {
			workerTypeCheckService.checkWorkerType(
				ownerPhone,
				"当前签约手机号为外部导购手机号，请修改为客户手机号发起签约",
				com.ke.ceres.enumeration.WorkTypeEnum.APP_GUIDE
			);
		}
	}

	/**
	 * 处理工期
	 */
	public void dealConstructSchedule(ContractReqDTO contractReq) {
		Byte businessType = commonContractService.getBusinessType(ContractContextHandler.getProjectInfo());
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		Integer gbCode = contractReq.getProjectInfo().getGbCode();
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
				// 整装获取工期数据
				dealConstructScheduleInHouse(contractReq);
			} else if (contractApolloConfig.durationCalculateIsOpen(gbCode) && BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
				// 增加 apollo 开关，开关打开后，需要同步提 SQL 更新前端工期编辑框为不可编辑
				// 翻新获取工期数据
				dealConstructScheduleInReform(contractReq);
			}
		}
	}

	/**
	 * 处理整装 & 正签场景的工期数据
	 */
	private void dealConstructScheduleInHouse(ContractReqDTO contractReq) {
		if (!BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(commonContractService.getBusinessType(ContractContextHandler.getProjectInfo()))
			|| !ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractReq.getContractBaseInfo().getContractType())) {
			return;
		}
		ProjectInfoDTO projectInfo = ContractContextHandler.getProjectInfo();
		boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectInfo.getProjectOrderId(), contractReq.getContractBaseInfo().getContractType())
			&& BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(commonBusinessService.getBusinessType(projectInfo.getProjectOrderId()));
		String area = contractReq.getProjectInfo().getArea();
		if (houseProcessV25) {
			//2.5建筑面积实时从客源取，不从草稿取
			area = String.valueOf(ContractContextHandler.getProjectInfo().getCustomerHouse().getArea());
		}
		ConstructScheduleVo constructScheduleVo = pcContractService.calculateSchedule(projectInfo.getProjectOrderId(),
			contractReq.getContractBaseInfo().getContractType(), area,
			contractReq.getProjectInfo().getPlanStartTime(), contractReq.getProjectInfo().getToiletCnt(),
			contractReq.getProjectInfo().getHouseType(), contractReq.getProjectInfo().getHouseBuildType());
		Integer gbCode = projectInfo.getCustomerHouse().getGbCode();
		//2.5合并发起模式的，工期未获取成功的不允许发起合同
		if (houseProcessV25 && (constructScheduleVo == null || constructScheduleVo.getTotalPeriod() == null
			|| constructScheduleVo.getTotalPeriod() <= 0)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "工期异常，请联系工期系统运营");
		}
		if (constructScheduleVo == null || constructScheduleVo.getTotalPeriod() == null || constructScheduleVo.getTotalPeriod() <= 0) {
			LOGGER.error("发起签约获取到总工期<=0，projectOrderId:{},constructScheduleVo:{}", projectInfo.getProjectOrderId(), constructScheduleVo);
			fillTotalDuration(contractReq, 0);
		}
		if (constructScheduleVo != null && constructScheduleVo.getTotalPeriod() != null && constructScheduleVo.getTotalPeriod() > 0) {
			LOGGER.info("设置工期，projectOrderId：{},总工期：{}", projectInfo.getProjectOrderId(), constructScheduleVo.getTotalPeriod().intValue());
			fillTotalDuration(contractReq, constructScheduleVo.getTotalPeriod().intValue());
		}
		if (constructScheduleVo != null) {
			String durationUniqueCode = constructScheduleVo.getUniqueCode();
			// 存储工期唯一编码到 BusinessInfo 下，在保存合同数据时，存入 contract_field 表
			fillDurationUniqueCode(contractReq, durationUniqueCode);
		}
		contractReq.getProjectInfo().setConstructSchedule(constructScheduleVo);
	}

	/**
	 * 处理翻新 & 正签的工期数据
	 *
	 * @param contractReq
	 */
	private void dealConstructScheduleInReform(ContractReqDTO contractReq) {
		String projectOrderId = ContractContextHandler.getProjectInfo().getProjectOrderId();
		ScheduleCalculateDTO scheduleCalculateDTO = constructScheduleFeignService.calculateSchedule(projectOrderId);
		//工期未获取成功的不允许发起合同
		if (scheduleCalculateDTO == null || scheduleCalculateDTO.getTotalPeriod() == null
			|| scheduleCalculateDTO.getTotalPeriod() <= 0) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "工期异常，请联系工期系统运营");
		}
		if (scheduleCalculateDTO.getTotalPeriod() != null && scheduleCalculateDTO.getTotalPeriod() > 0) {
			LOGGER.info("设置工期，projectOrderId：{},总工期：{}", projectOrderId, scheduleCalculateDTO.getTotalPeriod().intValue());
			fillTotalDuration(contractReq, scheduleCalculateDTO.getTotalPeriod().intValue());
		}
		// 如果工期
		String durationUniqueCode = scheduleCalculateDTO.getUniqueCode();
		// 存储工期唯一编码到 BusinessInfo 下，在保存合同数据时，存入 contract_field 表
		fillDurationUniqueCode(contractReq, durationUniqueCode);
	}

	private void fillDurationUniqueCode(ContractReqDTO contractReq, String durationUniqueCode) {
		contractReq.getBusinessInfo().setDurationUniqueCode(durationUniqueCode);
	}

	private void fillTotalDuration(ContractReqDTO contractReq, Integer totalDuration) {
		contractReq.getProjectInfo().setTotalDuration(totalDuration);
