	public void bindContractRelation(Contract mainContract, List<String> relationContractCode, ContractRelationEnum relationEnum) {
		if (CollectionUtils.isEmpty(relationContractCode)) {
			return;
		}
		//获取主合同已经存在的有关联关系的合同（如，草稿中绑定的），发起签约时，已绑定的合同如果已经不需要再合并发起，需要将关联关系删除，如果合同为草稿态，需要删除对应关联合同
		List<ContractRelation> relationList = contractRelationService.getRelationList(mainContract.getContractCode());
		//库中已有的关联合同编号
		Set<String> relationContractCodeSet = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toSet());
		for (String hasRelationContractCode : relationContractCodeSet) {
			if (!relationContractCode.contains(hasRelationContractCode)) {
				Contract contract = contractService.getByContractCode(hasRelationContractCode);
				if (contract != null && ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
					homeAndPcCommonService.deleteContract(hasRelationContractCode, Long.valueOf(Constant.SYSTEM_CREATE_UCID));
				}
				// 解除关联关系
				contractRelationService.deleteRelationByContractCodes(Collections.singletonList(hasRelationContractCode));
				LOGGER.info("删除不属于当前合同的关联关系的合同,删除关联合同编号:{}", hasRelationContractCode);
			}
		}
		List<ContractRelation> batchInsertList = new ArrayList<>();
		for (String relaContractCode : relationContractCode) {
			if (relationContractCodeSet.contains(relaContractCode)) {
				continue;
			}
			batchInsertList.add(ContractRelation.builder()
				.contractCode(mainContract.getContractCode())
				.relateContractCode(relaContractCode)
				.relationType(relationEnum.getCode())
				.ctime(new Date())
				.mtime(new Date())
				.delStatus(CommonEnum.NO.getCode())
				.build());
		}
		if (!CollectionUtils.isEmpty(batchInsertList)) {
			contractRelationService.insertList(batchInsertList);
		}
	}

