public Contract buildSubmitContract(ContractReqDTO contractReq) {
	//构建合同数据
	Contract contract = contractUnifyService.buildDraftContract(contractReq);
	//设置合同状态&设置对用户可见
	contract.setStatus(getContractSubmitStatus(contract));
	boolean userCanSee = userCanSeeAfterSubmit(contract);
	contract.setUserQueryStatus(userCanSee ? UserQueryStatusEnum.VALID.getCode() : UserQueryStatusEnum.INVALID.getCode());
	//线下合同在提交签约的时候：自动用户签署完成
	contract.setUserSignStatus(SignChannelTypeEnum.OFFLINE.getCode().equals(contractReq.getSignInfo().getSignChannelType())
		? CommonEnum.YES.getCode()
		: CommonEnum.NO.getCode());
	return contract;
}

public Integer getContractSubmitStatus(Contract contract) {
	// 设计合同、设计变更场景：设计费超底时，提交后状态流转到「待提交审核」
	if (designFeeAuditService.isDesignFeeExceedBottomOnSubmit(contract)) {
		return ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode();
	}

	if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType())) {
		//合并发起模式发起流转到待用户签署
		if (ContractContextHandler.getContext().isMergeLaunch()) {
			boolean offline = SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType());
			return offline ? ContractStatusEnum.FINISH.getCode() : ContractStatusEnum.PENDING_USER_SIGN.getCode();
		}
		//退单流程中解约协议发起后流转到审批中，退单审批通过后合同流转到已签署
		return ContractStatusEnum.AUDITING.getCode();
	}


	//线上or线下
	if (contract.getSignChannelType().equals(SignChannelTypeEnum.ONLINE.getCode())) {
		List<Byte> companySignAfterSubmitType = ContractTypeEnum.companySignAfterSubmitType();
		boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType()) && BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType());
		if (houseProcessV25 && companySignAfterSubmitType.contains(contract.getType()) && UserSignTypeEnum.SIGN.getCode().equals(contract.getUserSignType())) {
			return ContractStatusEnum.PENDING_COMPANY_SIGN.getCode();
		}
		if (contract.getAuditType().equals(AuditTypeEnum.BEFORE_SIGN.getCode())) {
			return ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode();
		} else {
			//签署方式
			if (contract.getUserSignType().equals(UserSignTypeEnum.SIGN.getCode())) {
				return ContractStatusEnum.PENDING_USER_SIGN.getCode();
			} else {
				return ContractStatusEnum.PENDING_USER_CONFIRM.getCode();
			}
		}
	} else {
		//线下
		if (contract.getAuditType().equals(AuditTypeEnum.NONE.getCode())) {
			return ContractStatusEnum.FINISH.getCode();
		} else {
			return ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode();
		}
	}
}

private boolean userCanSeeAfterSubmit(Contract contract) {
	//退单流程解约协议发起后流转到审批中，退单审批通过后用户才可见
	if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType())) {
		//合并发起模式发起可见
		return ContractContextHandler.getContext().isMergeLaunch();
	}
	// 补充/和解协议审核通过后，用户才可见
	if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contract.getType()) || ContractTypeEnum.SETTLEMENT.getCode().equals(contract.getType())) {
		return false;
	}
	if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
		return true;
	}
	// 不可见的合同类型返回false
	if (ContractTypeEnum.getUserNoVisibleContractTypes().contains(contract.getType())) {
		return false;
	}
	boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(contract.getProjectOrderId(), contract.getType()) && BusinessTypeEnum.getHouseCertificate25ModeList().contains(contract.getBusinessType());
	if (!houseProcessV25) {
		return !AuditTypeEnum.BEFORE_SIGN.getCode().equals(contract.getAuditType());
	}

	// 2.5提交后会盖公司章，无需盖章C端用户返回可见
	if (ContractTypeEnum.noNeedCompanySignAfterType().contains(contract.getType())) {
		return true;
	}

	// 2.5提交后会盖公司章（仅正式签署），合同提交后C端用户不可见合同类型
	List<Byte> canNotSeeAfterSubmitType = ContractTypeEnum.companySignAfterSubmitType();
	return !canNotSeeAfterSubmitType.contains(contract.getType()) || !UserSignTypeEnum.SIGN.getCode().equals(contract.getUserSignType());
}

@Transactional
public void submitContractDealData(ContractLaunchDataSaveParam contractLaunchDataSaveParam) {
	List<ContractSubmitCore> contractSubmitCoreList = contractLaunchDataSaveParam.getContractSubmitCoreList();
	String contractPollKey = contractLaunchDataSaveParam.getContractPollKey();
	List<String> mainContractCodeList = contractLaunchDataSaveParam.getMainContractList().stream().map(Contract::getContractCode).collect(Collectors.toList());
	//目前仅用于正签合同关联关系绑定，且这个场景仅有一个正签主合同
	Contract mainContract = contractLaunchDataSaveParam.getMainContractList().get(0);
	for (ContractSubmitCore contractSubmitCore : contractSubmitCoreList) {
		Contract contract = contractSubmitCore.getContract();
		ContractReqDTO contractReq = contractSubmitCore.getContractReq();
		//再次检查检查合同唯一性，防止并发
		List<Contract> contractList = contractService.getContractList(contract.getProjectOrderId(), contract.getType());
		contractUnifyService.checkContractUnique(contract.getProjectOrderId(), contract.getType(), contractList);
		//合同核心数据入库
		contractUnifyService.saveCoreContractDb(contract, contractReq);
		//合同节点信息处理
		contractUnifyService.updateOrSaveContractNode(contract, contractReq);
		//绑定合同与单据的关联关系
		BindOrderInfoGroup group = BindOrderInfoGroup.convert(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getBusinessInfo());
		quotationRelationCommonService.bindCodeRelationWithClear(contract, group);
		//日志&消息
		contractUnifyService.doAfterSubmit(contract);
	}
	List<Contract> contractList = contractSubmitCoreList.stream().map(ContractSubmitCore::getContract).collect(Collectors.toList());
	List<String> relationContractCode = contractList.stream().map(Contract::getContractCode).filter(contractCode -> !mainContractCodeList.contains(contractCode)).collect(Collectors.toList());
	//记录合同关联关系
	bindContractRelation(mainContract, relationContractCode, ContractRelationEnum.MERGE_LAUNCH);
	//记录主合同关系
	recordMainContractRelation(contractLaunchDataSaveParam.getMainContractList());
	//删除不属于当前合同的关联关系的合同
	deleteNoRelationContract(mainContract);
	//销售合同单独发起，删除历史与正签关联关系
	deletePersonalHistoryRelation(contractLaunchDataSaveParam.getMainContractList());
	//合同提交成功后，保存合同发起结果到redis
	contractUnifyService.saveContractSubmitToRedis(contractList, ContractSubmitStatusEnum.SUCCESS, contractPollKey, null, false);
}

