	/**
	 * 判断是否完成预报价
	 *
	 * @param projectOrderId
	 * @return
	 */
	private Boolean advanceQuoteFinishRes(String projectOrderId, Byte contractType) {
		// 如果没开城不用校验直接通过
		if (Boolean.FALSE.equals(advanceSupportPreQuotation(projectOrderId, contractType))) {
			return true;
		}
		// 是否存在可签约状态的预报价
		List<LightQuotationDTO.LightQuotationItem> preQuotationListByProject = atomBudgetRpc.getPreQuotationListByProject(projectOrderId);
		return preQuotationListByProject != null && !CollectionUtils.isEmpty(preQuotationListByProject) &&
			preQuotationListByProject.stream().anyMatch(item -> AtomBudgetRpc.CAN_SIGN_PRE_QUOTATION_STATUS.contains(item.getStatus()));
	}

	/**
	 * 判断零售配套是否完成
	 *
	 * @param decorateCommissionCode
	 * @return
	 */
	private Boolean retailSupportFinishRes(String projectOrderId, String decorateCommissionCode, Integer gbCode, Map<String, NodeFillInfo> preSignCheckSecondNodeFillInfo, ContractPreCheckBo contractPreCheckBo) {
		List<String> customerCommissionCodes = customerRpc.getCustomerCommissionCodes(decorateCommissionCode);

		//获取配置规则
		ContractConfigRuleDTO contractConfigRule = contractConfigService.queryOrDefaultConfigRule(gbCode);
		LOGGER.info("retailSupportFinishRes contractConfigRule:{}", JSON.toJSONString(contractConfigRule));

		//楼盘、楼栋白名单校验
		if (contractConfigService.checkInWhiteList(projectOrderId, contractConfigRule, contractPreCheckBo, decorateCommissionCode)) {
			return Boolean.TRUE;
		}


		//查询报价合同信息
		PlanAllDTO planAllDTO = homeOrderDataConversionService.contractSourceDateNoThrow(projectOrderId, null).getPlanAllDTO();
		//正签的报价信息查不到时，特殊toast提示：'请完成正式报价后再发起签约'
		if (Objects.isNull(planAllDTO) || Objects.isNull(planAllDTO.getPlanInfo()) || Objects.isNull(planAllDTO.getPlanInfo().getComboCode())) {
			throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "请完成正式报价后再发起签约", Level.WARN);
		}

		BigDecimal planContractAmount = planAllDTO.getPlanInfo().getContractPriceTotal();
		//查询订单合同信息
		OrderTotalFundDTO orderTotalFundDTO = initOrderTotalFundDTO();
		if (!CollectionUtils.isEmpty(customerCommissionCodes)) {
			orderTotalFundDTO = orderCenterRpc.queryRetailOrderFund(customerCommissionCodes, FundQuerySceneEnum.RETAIL_AMOUNT_FOR_PART_DECORATION.getCode());
		}
		BigDecimal orderAmount = orderTotalFundDTO.getAmountForPartDecoration() == null ? BigDecimal.ZERO : orderTotalFundDTO.getAmountForPartDecoration();

		//规则1-1:局改施工合同+零售合同金额>$配置规则$
		preSignCheckSecondNodeFillInfo.put(PreSignCheckSubNode.SUM_OF_REFORM_AND_RETAIL_CONTRACT_AMOUNT_ONE.getSecondNodeKey(), checkTotalContractAmountExceedingConfiguredRule(contractConfigRule.getRetailAndBureauChangeAmountSum(), planContractAmount, orderAmount));

		//规则1-2:零售合同金额占比>$配置规则$  即[A/(A+B) > 配置规则/100] = [A*100-配置规则*(A+B)>0] A为零售合同金额 B为整装合同金额
		preSignCheckSecondNodeFillInfo.put(PreSignCheckSubNode.RETAIL_CONTRACT_AMOUNT_RATIO_ONE.getSecondNodeKey(), checkRetailContractAmountExceedingConfiguredRatio(contractConfigRule.getRetailAmountRatio(), planContractAmount, orderAmount));

		//规则2-1:局改施工合同+零售合同金额>$配置规则$
		preSignCheckSecondNodeFillInfo.put(PreSignCheckSubNode.SUM_OF_REFORM_AND_RETAIL_CONTRACT_AMOUNT_TWO.getSecondNodeKey(), checkTotalContractAmountExceedingConfiguredRule(contractConfigRule.getRetailAndBureauChangeAmountSum2(), planContractAmount, orderAmount));

		//规则2-2:零售合同金额占比>$配置规则$  即[A/(A+B) > 配置规则/100] = [A*100-配置规则*(A+B)>0] A为零售合同金额 B为整装合同金额
		preSignCheckSecondNodeFillInfo.put(PreSignCheckSubNode.RETAIL_CONTRACT_AMOUNT_RATIO_TWO.getSecondNodeKey(), checkRetailContractAmountExceedingConfiguredRatio(contractConfigRule.getRetailAmountRatio2(), planContractAmount, orderAmount));

		Boolean resRule1 = preSignCheckSecondNodeFillInfo.get(PreSignCheckSubNode.SUM_OF_REFORM_AND_RETAIL_CONTRACT_AMOUNT_ONE.getSecondNodeKey()).getStatus();
		Boolean resRule2 = preSignCheckSecondNodeFillInfo.get(PreSignCheckSubNode.RETAIL_CONTRACT_AMOUNT_RATIO_ONE.getSecondNodeKey()).getStatus();
		Boolean resRule3 = preSignCheckSecondNodeFillInfo.get(PreSignCheckSubNode.SUM_OF_REFORM_AND_RETAIL_CONTRACT_AMOUNT_TWO.getSecondNodeKey()).getStatus();
		Boolean resRule4 = preSignCheckSecondNodeFillInfo.get(PreSignCheckSubNode.RETAIL_CONTRACT_AMOUNT_RATIO_TWO.getSecondNodeKey()).getStatus();
		preSignCheckSecondNodeFillInfo.get(PreSignCheckSubNode.RETAIL_CONTRACT_AMOUNT_AND_RATIO_ONE.getSecondNodeKey()).setStatus(resRule1 && resRule2);
		preSignCheckSecondNodeFillInfo.get(PreSignCheckSubNode.RETAIL_CONTRACT_AMOUNT_AND_RATIO_TWO.getSecondNodeKey()).setStatus(resRule3 && resRule4);
		LOGGER.info("retailSupportFinishRes projectOrderId:{},preSignCheckSecondNodeFillInfo:{}", projectOrderId, JSON.toJSONString(preSignCheckSecondNodeFillInfo));
		return (resRule1 && resRule2) || (resRule3 && resRule4);
	}

