	/**
	 * 获取团装销售合同可以发起签约的报价单code列表
	 * @param projectOrderId
	 * @return
	 */
	@Deprecated
	public List<String> getPersonalContractCanSelectBillCodeList(String projectOrderId) {
		//根据协同报价单查询组合单信息
		List<CompositInfoWithBillCode> compositInfoWithBillCodes = contractOrderCenterRpc.queryOrderByHomeOrderNo(projectOrderId);
		//过滤出非取消的
		compositInfoWithBillCodes = compositInfoWithBillCodes.stream().filter(item -> !CompositOrderStateEnum.CANCELED.getValue().equals(item.getOrderStatus())).collect(Collectors.toList());
		if (CollectionUtils.isEmpty(compositInfoWithBillCodes)) {
			LOGGER.info("发起销售合同获取到组合单信息为空 projectOrderId:{}", projectOrderId);
			return new ArrayList<>();
		}
		//所有可以签约报价单
		List<String> billCodeList = compositInfoWithBillCodes.stream().map(CompositInfoWithBillCode::getBillCode).collect(Collectors.toList());

		//查询所有绑定关系
		List<ContractQuotationRelation> relationListByBillCodeList = quotationRelationCommonService.getRelationListByBillCodeList(billCodeList);
		//绑定了协同报价单的草稿态销售合同code
		List<String> draftContractCodeList = quotationRelationCommonService.getContractListByBillCodeList(billCodeList).stream().filter(item -> ContractStatusEnum.DRAFT.getCode().equals(item.getStatus()))
			.map(Contract::getContractCode).collect(Collectors.toList());
		//过滤出已发起&已完结的绑定关系的BillCode，这些不能发起签约
		List<String> contractQuotationRelationBillCodeList = relationListByBillCodeList.stream().filter(item -> !draftContractCodeList.contains(item.getContractCode())).map(ContractQuotationRelation::getBillCode).collect(Collectors.toList());

		List<String> canSelectBillCode = new ArrayList<>();
		for (CompositInfoWithBillCode compositInfoWithBillCode : compositInfoWithBillCodes) {
			if (contractQuotationRelationBillCodeList.contains(compositInfoWithBillCode.getBillCode())) {
				//已绑定的报价单不允许再次选择
				continue;
			}
			canSelectBillCode.add(compositInfoWithBillCode.getBillCode());
		}
		return canSelectBillCode;
	}


	/**
	 * 判断是否有已提交正式协同C报价
	 */
	private boolean haveCQuoteCanSign(String projectOrderId, ContractCheckNodeRes contractCheckNodeRes) {
		//不可签约的报价单
		List<String> notSignBillCodeList = formalMultipleCompanyService.getNotSupportSignBillCodeList(projectOrderId);
		//根据协同报价单查询组合单信息
		List<CompositInfoWithBillCode> compositInfoWithBillCodes = contractOrderCenterRpc.queryOrderByHomeOrderNo(projectOrderId);
		//过滤出非取消的
		compositInfoWithBillCodes = compositInfoWithBillCodes.stream().filter(item -> !CompositOrderStateEnum.CANCELED.getValue().equals(item.getOrderStatus())).collect(Collectors.toList());
		if (compositInfoWithBillCodes.isEmpty()) {
			return false;
		}
		//报价单号列表
		List<String> billCodeList = new ArrayList<>();
		for (CompositInfoWithBillCode compositInfoWithBillCode : compositInfoWithBillCodes) {
			billCodeList.add(compositInfoWithBillCode.getBillCode());
		}
		//查询绑定关系
		List<ContractQuotationRelation> relationListByBillCodeList = quotationRelationCommonService.getRelationListByBillCodeList(billCodeList);
		//过滤出已发起&已完结的合同的绑定关系，这些不能发起签约
		List<ContractQuotationRelation> relationList = new ArrayList<>();
		for (ContractQuotationRelation contractQuotationRelation : relationListByBillCodeList) {
			Contract contract = contractService.getByContractCode(contractQuotationRelation.getContractCode());
			if (ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus()) && StringUtils.isBlank(contract.getChangeOrderId())) {
				relationList.add(contractQuotationRelation);
			}
		}
		List<String> relationStrList = relationList.stream().map(item -> item.getBillCode() + "_" + item.getCompanyCode()).collect(Collectors.toList());
		List<SignOrderResDTO> signOrderResDTOList = new ArrayList<>();
		for (CompositInfoWithBillCode compositInfoWithBillCode : compositInfoWithBillCodes) {
			if (relationStrList.contains(compositInfoWithBillCode.getBillCode() + "_" + compositInfoWithBillCode.getMdmCode()) || CompositOrderStateEnum.CANCELED.getValue().equals(compositInfoWithBillCode.getOrderStatus())) {
				//已绑定的报价单、已取消订单不允许再次选择
				continue;
			}
			SignOrderResDTO signOrderResDTO = SignOrderResDTO.builder()
				.billCode(compositInfoWithBillCode.getBillCode())
				.companyCode(compositInfoWithBillCode.getMdmCode())
				.orderAmount(compositInfoWithBillCode.getCustomerDueAmount())
				.orderCreateTime(compositInfoWithBillCode.getOrderCreateTime())
				.goodsInfo(compositInfoWithBillCode.getGoodsInfo())
				.build();
			signOrderResDTOList.add(signOrderResDTO);
		}
		//可签约的报价单
		List<String> canSignBillCodeList = signOrderResDTOList.stream().map(SignOrderResDTO::getBillCode).collect(Collectors.toList());
		LOGGER.info("是否有已提交正式协同C报价 projectOrderId:{},canSignBillCodeList:{},notSignBillCodeList:{}", projectOrderId, JSON.toJSONString(canSignBillCodeList), JSON.toJSONString(notSignBillCodeList));
		contractCheckNodeRes.setFilterBillCodeList(notSignBillCodeList);
		return CollectionUtil.isNotEmpty(signOrderResDTOList);
