	/**
	 * 组装子级节点信息 填充文案信息
	 *
	 * @param secondNodeList
	 * @param projectInfo
	 * @param contractType
	 * @return
	 */
	public List<SubNode> convertToRelateSecondNode(List<PreSignCheckSubNode> secondNodeList, ProjectInfoDTO projectInfo, Byte contractType, Map<String, NodeFillInfo> preSignCheckSecondNodeFillInfo, CoordinationProjectInfo coordinationProjectOrder) {
		List<SubNode> resNodeList = new ArrayList<>();
		for (PreSignCheckSubNode secondNode : secondNodeList) {
			if (shouldSkipNode(secondNode, projectInfo)) {
				continue;
			}

			String skipUrl = generateSkipUrl(secondNode, projectInfo, contractType, coordinationProjectOrder);
			NodeFillInfo nodeFillInfo = preSignCheckSecondNodeFillInfo.getOrDefault(secondNode.getSecondNodeKey(), new NodeFillInfo());
			String secondNodeDesc = updateSecondNodeDesc(secondNode, nodeFillInfo, projectInfo);
			Byte status = determineStatus(secondNode, nodeFillInfo);
			String statusDes = status != null ? ConfigStatusEnum.getEnumByCode(status).getDesc() : null;
			resNodeList.add(buildSubNode(secondNode, secondNodeDesc, skipUrl, status, statusDes));
		}
		return resNodeList;
	}


	/**
	 * 判断是否应跳过节点
	 *
	 * @param secondNode  预签检查子节点
	 * @param projectInfo 项目信息
	 * @return 如果应跳过节点则返回true，否则返回false
	 */
	private boolean shouldSkipNode(PreSignCheckSubNode secondNode, ProjectInfoDTO projectInfo) {
		return PreSignCheckSubNode.SKIP_MEASUREMENT_OR_MEETING.equals(secondNode) &&
			//不开开关 或者 在城市黑名单：不展示跳过量房打卡或到店服务
			(Boolean.FALSE.equals(contractApolloConfig.getSkipClockAndScanCheck()) || contractApolloConfig.getSkipBlackCityCodes().contains(projectInfo.getCustomerHouse().getGbCode()));
	}

	/**
	 * 生成跳转URL
	 *
	 * @param secondNode   预签检查子节点
	 * @param projectInfo  项目信息
	 * @param contractType 合同类型
	 * @return 生成的跳转URL
	 */
	private String generateSkipUrl(PreSignCheckSubNode secondNode, ProjectInfoDTO projectInfo, Byte contractType, CoordinationProjectInfo coordinationProjectOrder) {
		if (PreSignCheckSubNode.PARAM_CUSTOMER_COMMISSION_CODE.contains(secondNode)) {
			return String.format(secondNode.getSkipUrl(), projectInfo.getCustomerCommission().getCustomerCommissionCode());
		} else if (PreSignCheckSubNode.PARAM_PROJECT_ORDER_ID.contains(secondNode)) {
			return String.format(secondNode.getSkipUrl(), coordinationProjectOrder.getProjectOrderId());
		} else if (PreSignCheckSubNode.PARAM_PROJECT_ORDER_ID_AND_CONTRACT_TYPE.contains(secondNode)) {
			return String.format(secondNode.getSkipUrl(), coordinationProjectOrder.getProjectOrderId(), contractType);
		}
		if (PreSignCheckSubNode.GO_TO_QUOTE.equals(secondNode)) {
			//获取零售客源code
			String customerCommissionCode = projectInfo.getCustomerCommission().getCustomerCommissionCode();
			if (!ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(projectInfo.getDecorateBusinessType())) {
				List<String> customerCommissionCodes = customerRpc.getCustomerCommissionCodes(projectInfo.getCustomerCommission().getCustomerCommissionCode());
				if (CollectionUtils.isEmpty(customerCommissionCodes)) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前项目未绑定零售客源，请绑定后重试");
				}
				customerCommissionCode = customerCommissionCodes.get(0);
			}
			//无变更C报价跳转去报价页面
			return String.format(contractApolloConfig.getHomeGoToQuotationUrl(), coordinationProjectOrder.getProjectOrderId(), customerCommissionCode);
		}

		if (PreSignCheckSubNode.ADVANCE_QUOTATION.equals(secondNode)) {
			if ("LUBAN-CRM".equals(HeaderContext.getContext().getAppId())) {
				return String.format(contractApolloConfig.getPcGoToPreQuotationListUrl(), coordinationProjectOrder.getProjectOrderId());
			} else {
				return String.format(contractApolloConfig.getHomeGoToPreQuotationListUrl(), projectInfo.getCustomerCommission().getCustomerCommissionCode());
			}
		}
		if (PreSignCheckSubNode.GROUP_COMPLETE_BUDGET.equals(secondNode) || PreSignCheckSubNode.GROUP_GO_TO_QUOTE.equals(secondNode)) {
			if ("LUBAN-CRM".equals(HeaderContext.getContext().getAppId())) {
				return "";
			} else {
				return String.format(contractApolloConfig.getHomeGoToQuotationListUrl(), coordinationProjectOrder.getProjectOrderId(), "");
			}
		}

		return "";
	}

	/**
	 * 更新子节点描述
	 *
	 * @param secondNode   预签检查子节点
	 * @param nodeFillInfo 节点填充信息
	 * @param projectInfo  项目信息
	 * @return 更新后的子节点描述
	 */
	private String updateSecondNodeDesc(PreSignCheckSubNode secondNode, NodeFillInfo nodeFillInfo, ProjectInfoDTO projectInfo) {
		String secondNodeDesc = secondNode.getSecondNodeDesc();
		ContractConfigRuleDTO contractConfigRule = contractConfigService.queryOrDefaultConfigRule(projectInfo.getCustomerHouse().getGbCode());

		switch (secondNode) {
			case RETAIL_CONTRACT_AMOUNT_AND_RATIO_ONE:
				return String.format(secondNodeDesc, contractConfigRule.getRetailAndBureauChangeAmountSum(), contractConfigRule.getRetailAmountRatio() + "%");
			case SUM_OF_REFORM_AND_RETAIL_CONTRACT_AMOUNT_ONE:
				return String.format(secondNodeDesc, nodeFillInfo.getContractTotalAmount()) + (nodeFillInfo.getStatus() ? "" : "，<b>不足" + contractConfigRule.getRetailAndBureauChangeAmountSum() + "<b>");
			case RETAIL_CONTRACT_AMOUNT_RATIO_ONE:
				return String.format(secondNodeDesc, nodeFillInfo.getRetailContractAmount(), nodeFillInfo.getRetailContractAmountRatio()) + "%" + (nodeFillInfo.getStatus() ? "" : "，<b>不足" + contractConfigRule.getRetailAmountRatio() + "%<b>");
			case RETAIL_CONTRACT_AMOUNT_AND_RATIO_TWO:
				return String.format(secondNodeDesc, contractConfigRule.getRetailAndBureauChangeAmountSum2(), contractConfigRule.getRetailAmountRatio2() + "%");
			case SUM_OF_REFORM_AND_RETAIL_CONTRACT_AMOUNT_TWO:
				return String.format(secondNodeDesc, nodeFillInfo.getContractTotalAmount()) + (nodeFillInfo.getStatus() ? "" : "，<b>不足" + contractConfigRule.getRetailAndBureauChangeAmountSum2() + "<b>");
			case RETAIL_CONTRACT_AMOUNT_RATIO_TWO:
				return String.format(secondNodeDesc, nodeFillInfo.getRetailContractAmount(), nodeFillInfo.getRetailContractAmountRatio()) + "%" + (nodeFillInfo.getStatus() ? "" : "，<b>不足" + contractConfigRule.getRetailAmountRatio2() + "%</b>");
			default:
				return secondNodeDesc;
		}
	}


	/**
	 * 设置节点状态
	 *
	 * @param secondNode   预签检查子节点
	 * @param nodeFillInfo 节点填充信息
	 * @return 设置状态码
	 */
	private Byte determineStatus(PreSignCheckSubNode secondNode, NodeFillInfo nodeFillInfo) {
		if (PreSignCheckSubNode.CONTRACT_RETAIL_CONFIG.contains(secondNode)) {
			return Boolean.TRUE.equals(nodeFillInfo.getStatus()) ? ConfigStatusEnum.COMPLETED.getCode() : ConfigStatusEnum.TO_COMPLETE.getCode();
		}
		//其它节点暂未设值状态
		return null;
	}


	/**
	 * 构建子节点
	 *
	 * @param subNode        预签检查子节点
	 * @param secondNodeDesc 第二节点描述
	 * @param skipUrl        跳过URL
	 * @param status         节点状态
	 * @param statusDes      状态描述
	 * @return 构建的子节点对象
	 */
	private SubNode buildSubNode(PreSignCheckSubNode subNode, String secondNodeDesc, String skipUrl, Byte status, String statusDes) {
		return SubNode.builder()
			.secondNodeKey(subNode.getSecondNodeKey())
			.secondNodeDesc(secondNodeDesc)
			.btnText(subNode.getBtnText())
			.skipUrl(skipUrl)
			.btnToast(subNode.getBtnToast())
			.id(subNode.getId())
			.status(status)
			.statusDesc(statusDes)
			.parentId(subNode.getParentId())
			.build();
	}


