	public void contractFieldCheck(ContractReqDTO contractReq, ProjectInfoDTO projectInfo) {
		// 查询contract_field表获取要校验的字段
		Integer gbCode = projectInfo.getCustomerHouse().getGbCode();
		String companyCode = projectInfo.getCustomerCommission().getCompanyCode();
		Byte businessType = commonContractService.getBusinessType(projectInfo);
		companyCode = commonBusinessService.getCompanyCodeByCoordinationProjectOrderId(projectInfo.getProjectOrderId(), gbCode, companyCode, contractReq.getContractBaseInfo().getContractType());
		// 合同模板统一使用整装/零售项目单号获取
		String convertProjectOrderId = commonBusinessService.convertProjectOrderId(projectInfo.getProjectOrderId(), contractReq.getContractBaseInfo().getContractType());
		Integer fieldConfigVersion = contractConfigVersionService.getFieldConfigVersion(convertProjectOrderId);
		List<ContractFieldConfig> fieldConfigs = getFieldConfigAdapt(convertProjectOrderId, gbCode, companyCode, businessType, contractReq.getContractBaseInfo().getContractType(), fieldConfigVersion);

		// 使用map去重 key:checkFunction value:ContractFieldConfig
		Map<String, ContractFieldConfig> checkFunctionMap = fieldConfigs.stream()
			.filter(config -> StringUtils.isNotBlank(config.getCheckFunction()))
			.collect(Collectors.toMap(ContractFieldConfig::getCheckFunction, Function.identity(), (key1, key2) -> key1));

		if (CollectionUtils.isEmpty(checkFunctionMap)) {
			return;
		}
		for (Map.Entry<String, ContractFieldConfig> entry : checkFunctionMap.entrySet()) {
			// 校验方法
			String checkFunction = entry.getKey();
			ContractFieldConfig fieldConfig = entry.getValue();
			//存在校验条件，则进行判断是否需要校验
			if (StringUtils.isNotBlank(fieldConfig.getCheckCondition())) {
				Object moduleValue = CommonUtil.getObjectFieldData(fieldConfig.getModuleKey(), contractReq);
				if (Objects.isNull(moduleValue)) {
					String errorMsg = String.format("%s模块信息不能为空", fieldConfig.getModuleKey());
					throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), errorMsg, Level.WARN);
				}
				String displayCondition = fieldConfig.getCheckCondition();
				//条件计算结果，true为当前字段需要校验非空，false为当前字段不需要校验非空
				boolean checkConditionCompute = true;
				String[] conditions = displayCondition.split("&&");
				for (String condition : conditions) {
					//配置的多个条件，只要有一个不通过则不需要校验
					if (!conditionCheck(condition, contractReq)) {
						checkConditionCompute = false;
						break;
					}
				}
				if (!checkConditionCompute) {
					continue;
				}
			}
			boolean invokeCheckFunctionResult = contractFieldCheckService.checkContractField(contractReq, checkFunction);
			if (!invokeCheckFunctionResult) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "参数校验失败，请检查并修正相关" + entry.getValue().getFieldName() + "信息", Level.WARN);
			}
		}
	}

