	/**
	 * @param contract
	 * @param moduleKeyList
	 */
	public void dbDeleteByModule(Contract contract, List<String> moduleKeyList) {
		boolean attachOcrOpenCity = attachCommonService.attachOcrOpenCity(contract.getProjectOrderId());

		List<String> deleteFieldKeys = new LinkedList<>();
		deleteFieldKeys.add(ContractBaseInfoReq.Fields.contractMode);
		deleteFieldKeys.add(BusinessInfoDetail.Fields.billCodeList);
		deleteFieldKeys.add(BusinessInfoDetail.Fields.billCodeInfoList);
		deleteFieldKeys.add(BusinessInfoDetail.Fields.subOrderInfoList);
		deleteFieldKeys.add(BusinessInfoDetail.Fields.changeOrderInfoList);
		// 翻新全案场景下，正签没有配置 BusinessInfo 模块，手动添加需要删除/保存的字段
		deleteFieldKeys.add(BusinessInfoDetail.Fields.durationUniqueCode);
		if (moduleKeyList.contains(ContractModuleEnum.CONTRACT_PROJECT_INFO.getKey())) {
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(ContractProjectInfoReq.class));
		}
		if (moduleKeyList.contains(ContractModuleEnum.SIGN_INFO.getKey())) {
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(ContractSignInfoReq.class));
			//删除线下合同
			List<ContractAttach> contractAttachList = contractAttachService.getListByContractCode(contract.getContractCode(), AttachTypeEnum.OFFLINE_CONTRACT.getCode());
			if (!CollectionUtils.isEmpty(contractAttachList)) {
				contractAttachService.softDeleteByContractCodeAndType(contract.getContractCode(), AttachTypeEnum.OFFLINE_CONTRACT.getCode());
			}

			//删除user
			List<ContractUser> contractUserList = contractUserService.getListByContractCode(contract.getContractCode());
			if (!CollectionUtils.isEmpty(contractUserList)) {
				contractUserService.deleteByContractCode(contract.getContractCode(), false);
			}
		}
		if (moduleKeyList.contains(ContractModuleEnum.CONTRACT_PROJECT_INFO.getKey())) {
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(ContractProjectInfoReq.class));
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(ConstructScheduleVo.class));
		}
		if (moduleKeyList.contains(ContractModuleEnum.PROMISE_INFO.getKey())) {
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(PromiseInfoReq.class));
			//删除甲供材料清单
			List<ContractMaterial> contractMaterialList = contractMaterialService.getListByContractCode(contract.getContractCode());
			if (!CollectionUtils.isEmpty(contractMaterialList)) {
				contractMaterialService.softDeleteByContractCode(contract.getContractCode());
			}
		}
		if (moduleKeyList.contains(ContractModuleEnum.GUARANTEE_INFO.getKey())) {
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(GuaranteeReq.class));
		}
		if (moduleKeyList.contains(ContractModuleEnum.CONTRACT_ATTACH_INFO.getKey()) || (moduleKeyList.contains(ContractModuleEnum.SIGN_INFO.getKey()) && attachOcrOpenCity)) {
			List<ContractAttach> contractAttachList = contractAttachService.getListByContractCodeExcludeType(contract.getContractCode(), AttachTypeEnum.OFFLINE_CONTRACT.getCode());
			if (!CollectionUtils.isEmpty(contractAttachList)) {
				contractAttachService.softDeleteByContractCodeExcludeType(contract.getContractCode(), AttachTypeEnum.OFFLINE_CONTRACT.getCode());
			}
			//删除备件ocr
			List<ContractAttachOcr> contractAttachOcrList = contractAttachOcrService.getListByContractCode(contract.getContractCode());
			if (!CollectionUtils.isEmpty(contractAttachOcrList)) {
				contractAttachOcrService.softDeleteByContractCode(contract.getContractCode());
			}
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(ContractAttachInfo.class));
		}
		if (moduleKeyList.contains(ContractModuleEnum.BUSINESS_INFO.getKey())) {
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(BusinessInfoDetail.class));
		}
		if (moduleKeyList.contains(ContractModuleEnum.AMOUNT_INFO.getKey())) {
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(AmountInfo.class));
		}
		if (moduleKeyList.contains(ContractModuleEnum.QUOTATION.getKey()) && ContractTypeEnum.NEED_SAVE_QUOTATION.contains(contract.getType())) {
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(QuotationInfo.class));
		}
		if (moduleKeyList.contains(ContractModuleEnum.SUPPLEMENT_ITEM_INFO.getKey())) {
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(SupplementItemInfo.class));
		}
		if (moduleKeyList.contains(ContractModuleEnum.SETTLEMENT_ITEM_INFO.getKey())) {
			deleteFieldKeys.addAll(CommonUtil.getFieldNames(SettlementItemInfo.class));
		}
		Map<String, String> fieldMap = contractFieldService.getFieldMap(contract.getContractCode());
		boolean existFields = CollectionUtils.containsAny(fieldMap.keySet(), deleteFieldKeys);
		if (existFields) {
			contractFieldService.deleteByContractCodeAndKeys(contract.getContractCode(), deleteFieldKeys);
		}
	}

