	public Contract buildDraftContract(ContractReqDTO contractReq) {
		Integer gbCode = ContractContextHandler.getProjectInfo().getCustomerHouse().getGbCode();
		String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(contractReq.getContractBaseInfo().getProjectOrderId());
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(convertProjectOrderId);
		List<Contract> contractList = contractService.getContractList(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getContractBaseInfo().getContractType());
		Contract draftContract = null;
		String changeOrderId = StringUtils.isNotBlank(contractReq.getContractBaseInfo().getChangeOrderId()) ? contractReq.getContractBaseInfo().getChangeOrderId() : "";
		//草稿合同
		if (ContractTypeEnum.PERSONAL.getCode().equals(contractReq.getContractBaseInfo().getContractType()) && contractApolloConfig.getCheckPersonalContract()) {
			BindOrderInfoGroup group = BindOrderInfoGroup.convert(convertProjectOrderId, contractReq.getBusinessInfo());
			// 除了基于报价单获取草稿合同，也基于 S 单获取草稿合同
			BindOrderInfoGroup subOrderGroup = buildSubOrderGroupOfBill(group);
			//查询报价单列表关联的合同
			draftContract = quotationRelationCommonService.getContractByBindCodes(Stream.concat(group.getTotalBindOrderNos().stream(), subOrderGroup.getTotalBindOrderNos().stream()).collect(Collectors.toList()), contractReq.getContractBaseInfo().getSubmitCompanyCode(), changeOrderId);
			if (draftContract == null) {
				//兼容历史草稿合同发起：1、查询和报价单没有关联的草稿C合同；2、传入合同code和该份合同相同则说明是基于该份合同发起的销售合同
				Contract unrelatedPersonalContract = quotationRelationCommonService.getUnrelatedPersonalContract(contractReq.getContractBaseInfo().getProjectOrderId(), ContractStatusEnum.DRAFT.getCode());
				draftContract = unrelatedPersonalContract != null && unrelatedPersonalContract.getContractCode().equals(contractReq.getContractBaseInfo().getContractCode()) ? unrelatedPersonalContract : null;
			}
		} else {
			draftContract = contractList.stream().filter(contract -> ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())).findFirst().orElse(null);
		}
		//有效的合同
		List<Contract> effectiveContractList = contractList.stream()
			.filter(contract -> !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus()))
			.filter(contract -> !ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())).collect(Collectors.toList());
		//如果当前合同类型只允许存在一份有效合同，且已经存在生效合同，不允许再次创建草稿合同
		if (!ContractTypeEnum.allowedMultiple(contractReq.getContractBaseInfo().getContractType()) && !CollectionUtils.isEmpty(effectiveContractList)) {
			if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractReq.getContractBaseInfo().getContractType()) && formalReSignService.formalContractUnique(contractList)) {
				LOGGER.info("当前场景为2.0->2.5,已有2.0正式合同,允许生成2.5正式套餐合同");
			} else {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "已有其他在途已发起合同,不可重复创建", Level.WARN);
			}
		}
		Contract contract;
		ContractCityCompanyInfo contractCityCompanyInfo = getContractCityCompanyInfo(contractReq);
		String companyCode = contractCityCompanyInfo.getCompanyCode();
		//如果是测试验证公司编码，转换为真实公司编码
		if (companyCode.equals(contractApolloConfig.getCompanyCodeMode2_5())) {
			ProjectInfo projectInfo = projectInfoService.getByProjectOrderId(convertProjectOrderId);
			companyCode = commonBusinessService.getCompanyCodeFromQuotation(projectInfo, contractReq.getContractBaseInfo().getContractType(), contractReq);
		}
		if (ObjectUtil.isNotEmpty(draftContract)) {
			contract = CommonUtil.deepCopy(draftContract, Contract.class);
			contract.setGbCode(gbCode);
			contract.setCompanyCode(companyCode);
			contract.setBusinessType(commonContractService.getBusinessType(projectInfoDTO));
			contract.setUserSignType(contractReq.getSignInfo().getUserSignType());
			contract.setModifyUserId(HeaderContext.getUserId().toString());
			contract.setModifyUserName(ContractContextHandler.getOperatorName());
			contract.setSignChannelType(contractReq.getSignInfo().getSignChannelType());
			contract.setPdfGenerationMode(computerPdfGenerationMode(contractReq.getContractBaseInfo().getProjectOrderId(), gbCode, contractReq.getContractBaseInfo().getContractType()));
			contract.setAuditType(contractCityCompanyInfo.getAuditType().byteValue());
			contract.setUserSignStatus(SignChannelTypeEnum.OFFLINE.getCode().equals(contractReq.getSignInfo().getSignChannelType())
				? CommonEnum.YES.getCode()
				: CommonEnum.NO.getCode());
		} else {
			contract = Contract.builder()
				.contractCode(RandomCodeUtils.generateContractCode())
				.contractNo(RandomCodeUtils.generateContractNo())
				.userSignType(contractReq.getSignInfo().getUserSignType())
				.type(contractReq.getContractBaseInfo().getContractType())
				.gbCode(gbCode)
				.signChannelType(contractReq.getSignInfo().getSignChannelType())
				.projectOrderId(contractReq.getContractBaseInfo().getProjectOrderId())
				.changeOrderId(contractReq.getContractBaseInfo().getChangeOrderId())
				.businessType(commonContractService.getBusinessType(projectInfoDTO))
				.pdfGenerationMode(computerPdfGenerationMode(contractReq.getContractBaseInfo().getProjectOrderId(), gbCode, contractReq.getContractBaseInfo().getContractType()))
				.auditType(contractCityCompanyInfo.getAuditType().byteValue())
				.companyCode(companyCode)
				.userSignStatus(SignChannelTypeEnum.OFFLINE.getCode().equals(contractReq.getSignInfo().getSignChannelType())
					? CommonEnum.YES.getCode()
					: CommonEnum.NO.getCode())
				.createUserId(HeaderContext.getUserId().toString())
				.createUserName(ContractContextHandler.getOperatorName())
				.modifyUserId(HeaderContext.getUserId().toString())
				.modifyUserName(ContractContextHandler.getOperatorName())
				.build();
		}
		//设置合同金额
		contract.setAmount(getContractAmount(contractReq));
		//设置合同状态
		contract.setStatus(ContractStatusEnum.DRAFT.getCode());
		//线下合同的签署类型只能为正式签署
		if (SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType())) {
			contract.setUserSignType(UserSignTypeEnum.SIGN.getCode());
		}
		LOGGER.info("contract build after:{}", JSON.toJSONString(contract));
		return contract;
	}

	/**
	 * 获取合同pdf生成方式
	 */
	public Integer computerPdfGenerationMode(String projectOrderId, Integer gbCode, Byte contractType) {
		if (ContractTypeEnum.DRAWING.getCode().equals(contractType) && contractApolloConfig.getDrawingLaunchConfig().inOpenCity(gbCode)) {
			return PdfGenerationModeEnum.UNFORMATTED.getCode();
		}
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && contractApolloConfig.getFormalLaunchConfig().inOpenCity(gbCode)) {
			Integer contractMode = ContractContextHandler.getContractReq().getContractBaseInfo().getContractMode();
			boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId);
			if (!(ContractModeEnum.FULL_SERVICE.getCode().equals(contractMode)) && processV25) {
				LOGGER.info("正式套餐合同使用无版式方式生成合同，projectOrderId:{}，contractMode：{}，processV25:{}", projectOrderId, contractMode, processV25);
				return PdfGenerationModeEnum.UNFORMATTED.getCode();
			}
		}
		return PdfGenerationModeEnum.FORMATTED.getCode();
	}


	public void saveContractUser(Contract contract, ContractReqDTO contractReqDTO, List<String> moduleKeyList) {
		if (!moduleKeyList.contains(ContractModuleEnum.SIGN_INFO.getKey())) {
			return;
		}
		String contractCode = contract.getContractCode();
		List<ContractUser> list = new ArrayList<>();
		ContractSignInfoReq signInfo = contractReqDTO.getSignInfo();
		Byte agentSign;
		// 补充/和解协议没有 contractAttachInfo 模块，代理人信息从 signInfo 取
		if (ContractTypeEnum.AGENT_FROM_SIGN_INFO.contains(contract.getType())) {
			agentSign = contractReqDTO.getSignInfo().getHaveAgent();
		} else {
			agentSign = contractReqDTO.getContractAttachInfo() == null ? null : contractReqDTO.getContractAttachInfo().getAgentSign();
		}
		//如果是个人合同， 合同人员有业主 或 业主&代理人
		if (ContractObjectTypeEnum.PERSON.getCode().equals(signInfo.getContractObjectType())) {
			//业主
			ContractUser owner = new ContractUser();
			owner.setContractCode(contractCode);
			owner.setCertificateType(signInfo.getOwnerCertificateType());
			owner.setName(signInfo.getOwnerName());
			owner.setRoleType(UserTypeEnum.OWNER.getCode());
			owner.setPhone(signInfo.getOwnerPhone());
			owner.setCertificateNo(signInfo.getOwnerCertificateNo());
			list.add(owner);
			//有代理人
			if (HaveAgentEnum.YES.getCode().equals(signInfo.getHaveAgent())) {
				ContractUser agent = new ContractUser();
				agent.setContractCode(contractCode);
				agent.setCertificateType(signInfo.getAgentCertificateType());
				agent.setName(signInfo.getAgentName());
				agent.setRoleType(UserTypeEnum.AGENT.getCode());
				agent.setPhone(signInfo.getAgentPhone());
				agent.setCertificateNo(signInfo.getAgentCertificateNo());
				list.add(agent);
			}
		}

		//公司经办人
		if (ContractObjectTypeEnum.COMPANY.getCode().equals(signInfo.getContractObjectType())) {
			if (ContractTypeEnum.ACCREDIT.getCode().equals(contractReqDTO.getContractBaseInfo().getContractType())) {
				list.addAll(getAccreditContractUser(contractCode, signInfo));
			} else {
				//公对公线上有法人信息
				if (!StringUtils.isAnyBlank(signInfo.getLegalName(), signInfo.getLegalPhone())) {
					ContractUser legal = new ContractUser();
					legal.setContractCode(contractCode);
					legal.setCertificateType(signInfo.getLegalCertificateType());
					legal.setName(signInfo.getLegalName());
					legal.setRoleType(UserTypeEnum.LEGAL.getCode());
					legal.setPhone(signInfo.getLegalPhone());
					legal.setCertificateNo(signInfo.getLegalCertificateNo());
					list.add(legal);
					//签约人是法人，法人信息赋予公司代理人
					if (RoleTypeEnum.LEGAL.getCode().equals(signInfo.getSignRole())) {
						ContractUser companyAgent = new ContractUser();
						BeanUtils.copyProperties(legal, companyAgent);
						companyAgent.setRoleType(UserTypeEnum.COMPANY_AGENT.getCode());
						list.add(companyAgent);
					}
				}
				if (signInfo.getSignRole() == null || RoleTypeEnum.COMPANY_AGENT.getCode().equals(signInfo.getSignRole())) {
					ContractUser companyAgent = new ContractUser();
					companyAgent.setContractCode(contractCode);
					companyAgent.setCertificateType(signInfo.getCompanyAgentCertificateType());
					companyAgent.setName(signInfo.getCompanyAgentName());
					companyAgent.setRoleType(UserTypeEnum.COMPANY_AGENT.getCode());
					companyAgent.setPhone(signInfo.getCompanyAgentPhone());
					companyAgent.setCertificateNo(signInfo.getCompanyAgentCertificateNo());
					list.add(companyAgent);
				}
			}
		}
		for (ContractUser user : list) {
			user.setCreateUserId(HeaderContext.getUserId().toString());
			user.setCreateUserName(ContractContextHandler.getOperatorName());
			user.setModifyUserName(ContractContextHandler.getOperatorName());
			user.setModifyUserId(HeaderContext.getUserId().toString());
			user.setName(StringUtils.trim(user.getName()));
			contractUserService.insertContractUser(user);
		}
		pcContractService.addSignUserV2(contractCode,
			contractReqDTO.getContractBaseInfo().getProjectOrderId(),
			contractReqDTO.getContractBaseInfo().getContractType(),
			contractReqDTO.getSignInfo(),
			agentSign
		);
	}


	/**
