	 * @return
	 */
	private List<ContractUser> getAccreditContractUser(String contractCode, ContractSignInfoReq signInfo) {
		List<ContractUser> list = new ArrayList<>();
		ContractUser legal = new ContractUser();
		legal.setContractCode(contractCode);
		legal.setCertificateType(signInfo.getLegalCertificateType());
		legal.setName(signInfo.getLegalName());
		legal.setRoleType(UserTypeEnum.LEGAL.getCode());
		legal.setPhone(signInfo.getLegalPhone());
		legal.setCertificateNo(signInfo.getLegalCertificateNo());
		list.add(legal);
		if (StringUtils.isAnyBlank(signInfo.getCompanyAgentName(), signInfo.getCompanyAgentPhone(), signInfo.getCompanyAgentCertificateNo())) {
			LOGGER.error("公对公授权协议书合同用户信息缺失，合同编号：{}", contractCode);
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "公对公授权协议书合同用户信息缺失");
		}
		ContractUser companyAgent = new ContractUser();
		companyAgent.setContractCode(contractCode);
		companyAgent.setCertificateType(signInfo.getCompanyAgentCertificateType());
		companyAgent.setName(signInfo.getCompanyAgentName());
		companyAgent.setRoleType(UserTypeEnum.COMPANY_AGENT.getCode());
		companyAgent.setPhone(signInfo.getCompanyAgentPhone());
		companyAgent.setCertificateNo(signInfo.getCompanyAgentCertificateNo());
		list.add(companyAgent);
		return list;
	}

	public void saveContractField(String contractCode, ContractReqDTO contractReqDTO, List<String> moduleKeyList) {
		Map<String, Object> toSave = new HashMap<>();
		if (contractReqDTO.getContractBaseInfo().getContractMode() != null) {
			toSave.put(ContractBaseInfoReq.Fields.contractMode, contractReqDTO.getContractBaseInfo().getContractMode());
		}
		if (contractReqDTO.getBusinessInfo() != null && !CollectionUtils.isEmpty(contractReqDTO.getBusinessInfo().getBillCodeList())) {
			toSave.put(BusinessInfoDetail.Fields.billCodeList, contractReqDTO.getBusinessInfo().getBillCodeList());
		}
		if (contractReqDTO.getBusinessInfo() != null && !CollectionUtils.isEmpty(contractReqDTO.getBusinessInfo().getBillCodeInfoList())) {
			toSave.put(BusinessInfoDetail.Fields.billCodeInfoList, contractReqDTO.getBusinessInfo().getBillCodeInfoList());
		}
		if (contractReqDTO.getBusinessInfo() != null && !CollectionUtils.isEmpty(contractReqDTO.getBusinessInfo().getSubOrderInfoList())) {
			toSave.put(BusinessInfoDetail.Fields.subOrderInfoList, contractReqDTO.getBusinessInfo().getSubOrderInfoList());
		}
		if (contractReqDTO.getBusinessInfo() != null && !CollectionUtils.isEmpty(contractReqDTO.getBusinessInfo().getChangeOrderInfoList())) {
			toSave.put(BusinessInfoDetail.Fields.changeOrderInfoList, contractReqDTO.getBusinessInfo().getChangeOrderInfoList());
		}
		// 翻新全案场景下，正签没有配置 BusinessInfo 模块，手动添加需要删除/保存的字段
		if (contractReqDTO.getBusinessInfo() != null && StringUtils.isNotBlank(contractReqDTO.getBusinessInfo().getDurationUniqueCode())) {
			toSave.put(BusinessInfoDetail.Fields.durationUniqueCode, contractReqDTO.getBusinessInfo().getDurationUniqueCode());
		}
		if (moduleKeyList.contains(ContractModuleEnum.CONTRACT_PROJECT_INFO.getKey())) {
			//项目信息
			toSave.putAll(CommonUtil.objectConvertMap(JsonUtil.toJsonString(contractReqDTO.getProjectInfo())));
		}
		if (moduleKeyList.contains(ContractModuleEnum.PROMISE_INFO.getKey())) {
			//承包约定
			toSave.putAll(CommonUtil.objectConvertMap(JsonUtil.toJsonString(contractReqDTO.getPromiseInfo())));
		}
		if (moduleKeyList.contains(ContractModuleEnum.GUARANTEE_INFO.getKey()) && contractReqDTO.getGuaranteeInfo() != null) {
			//保修
			toSave.putAll(CommonUtil.objectConvertMap(JsonUtil.toJsonString(contractReqDTO.getGuaranteeInfo())));
		}
		if (moduleKeyList.contains(ContractModuleEnum.SIGN_INFO.getKey())) {
			//签约信息
			toSave.putAll(CommonUtil.objectConvertMap(JsonUtil.toJsonString(contractReqDTO.getSignInfo())));
		}
		//业务信息
		if (moduleKeyList.contains(ContractModuleEnum.BUSINESS_INFO.getKey())) {
			toSave.putAll(CommonUtil.objectConvertMap(JsonUtil.toJsonString(contractReqDTO.getBusinessInfo())));
		}
		//金额信息
		if (moduleKeyList.contains(ContractModuleEnum.AMOUNT_INFO.getKey())) {
			toSave.putAll(CommonUtil.objectConvertMap(JsonUtil.toJsonString(contractReqDTO.getAmountInfo())));
		}
		//备件信息
		if (moduleKeyList.contains(ContractModuleEnum.CONTRACT_ATTACH_INFO.getKey())) {
			toSave.putAll(CommonUtil.objectConvertMap(JsonUtil.toJsonString(contractReqDTO.getContractAttachInfo())));
		}
		//报价信息
		if (moduleKeyList.contains(ContractModuleEnum.QUOTATION.getKey()) && ContractTypeEnum.NEED_SAVE_QUOTATION.contains(contractReqDTO.getContractBaseInfo().getContractType())) {
			toSave.putAll(CommonUtil.objectConvertMap(JsonUtil.toJsonString(contractReqDTO.getQuotation())));
		}
		// 补充协议条款内容
		if (moduleKeyList.contains(ContractModuleEnum.SUPPLEMENT_ITEM_INFO.getKey()) && contractReqDTO.getSupplementItemInfo() != null) {
			toSave.putAll(CommonUtil.objectConvertMap(JsonUtil.toJsonString(contractReqDTO.getSupplementItemInfo())));
		}
		// 和解协议条款内容
		if (moduleKeyList.contains(ContractModuleEnum.SETTLEMENT_ITEM_INFO.getKey()) && contractReqDTO.getSettlementItemInfo() != null) {
			toSave.putAll(CommonUtil.objectConvertMap(JsonUtil.toJsonString(contractReqDTO.getSettlementItemInfo())));
		}
		List<ContractField> fieldList = new ArrayList<>();
		for (Map.Entry<String, Object> entry : toSave.entrySet()) {
			//甲供材料、工期信息、线下合同、备件另外处理
			List<String> noSaveField = ContractAttachInfo.getAttachFieldNameList();
			noSaveField.addAll(Arrays.asList("materialList", "constructSchedule", "attachUrl", "drawingAttachUrl", "personalAttachUrl", "terminalAttachUrl"));
			Contract contract = contractService.getByContractCode(contractCode);
			if (!ContractTypeEnum.PERSONAL.getCode().equals(contract.getType())) {
				noSaveField.add("goodsInfo");
			}
			if (noSaveField.contains(entry.getKey())) {
				continue;
			}
			if (Objects.nonNull(entry.getValue())) {
				ContractField field = ContractField.builder()
					.contractCode(contractCode)
					.fieldKey(entry.getKey())
					.fieldValue(entry.getValue() instanceof String ? entry.getValue().toString() : JSON.toJSONString(entry.getValue()))
					.build();
				fieldList.add(field);
			}
		}
		//工期信息
		Map<String, Object> schedule = CommonUtil.objectConvertMap(
			contractReqDTO.getProjectInfo() == null ? null : JsonUtil.toJsonString(contractReqDTO.getProjectInfo().getConstructSchedule()));
		if (schedule != null) {
			List<ContractField> finalFieldList = fieldList;
			schedule.forEach((fieldKey, fieldValue) -> {
				finalFieldList.add(ContractField.builder()
					.contractCode(contractCode)
					.fieldKey(fieldKey)
					.fieldValue(JsonUtil.toJsonString(fieldValue))
					.build());
			});
		}

		List<String> filterFieldKey = ContractSignInfoReq.attachFilterFieldNameList();
		fieldList = fieldList.stream().filter(field -> !filterFieldKey.contains(field.getFieldKey())).collect(Collectors.toList());


		for (ContractField contractField : fieldList) {
			contractField.setDelStatus(CommonEnum.NO.getCode());
			contractField.setCtime(new Date());
			contractField.setMtime(new Date());
			contractField.setCreateUserId(HeaderContext.getUserId().toString());
			contractField.setModifyUserId(HeaderContext.getUserId().toString());
			contractField.setCreateUserName(ContractContextHandler.getOperatorName());
			contractField.setModifyUserName(ContractContextHandler.getOperatorName());
		}
		if (!CollectionUtils.isEmpty(fieldList)) {
			contractFieldService.saveBatch(fieldList);
		}
	}


