	public void doAfterSubmit(Contract contract) {
		//日志&消息
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.SUBMIT.getCode(), LogTypeEnum.SUBMIT.getName(), "",
			contract.getModifyUserId(), contract.getModifyUserName());
		contractLogService.createLog(contract.getContractCode(), LogTypeEnum.STATUS_CHANGE.getCode(), LogTypeEnum.STATUS_CHANGE.getName(),
			contract.getStatus().toString());
		contractNodeService.updateOrCreate(contract.getContractCode(), NodeTypeEnum.SUBMIT.getCode());
		eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_SUBMIT, contract.getContractCode());

		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())
			//todo 信明权  变更合同不用记录房屋信息上传吧
//			ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType())
		) {
			//记录附件齐全
			boolean uploadStatus = pcContractService.checkAttach(contract.getContractCode());
			if (uploadStatus) {//提交合同如果附件齐全，也需要记录日志和节点
				//附件上传完毕，如果附件齐全，侧添加日志信息
				contractBusinessService.remarkSupplementLog(contract);
				//添加合同节点
				contractBusinessService.remarkSupplementNode(contract.getContractCode());
			}
		}
		//线下的直接完成&无需审核的，发送完成消息
		if (ContractStatusEnum.FINISH.getCode().equals(contract.getStatus()) && contract.getAuditType().equals(AuditTypeEnum.NONE.getCode())) {
			eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_FINISH, contract.getContractCode());
		}
		//变更合同、签后审核、线下合同，提交合同之后跳过签约阶段，直接签署完成
		if (ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contract.getType()) && SignChannelTypeEnum.OFFLINE.getCode().equals(contract.getSignChannelType()) && AuditTypeEnum.AFTER.getCode().equals(contract.getAuditType())) {
			eventService.publish(commonContractService.getContractEvent(contract), EventType.CONTRACT_USER_SIGN, contract.getContractCode());
		}
	}


