	public BigDecimal getContractAmount(ContractReqDTO contractReq) {
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		Byte businessType = contractReq.getProjectInfo().getBusinessType();
		//从报价获取合同金额的合同类型
		List<Byte> contractTypes = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.PACKAGE_CHANGE.getCode());
		if (contractTypes.contains(contractType)) {
			return ContractContextHandler.getPlanAllDTO().getPlanInfo().getContractPriceTotal();
		} else if (ContractTypeEnum.DESIGN.getCode().equals(contractType) || ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contractType)) {
			return contractReq.getProjectInfo().getAfterDiscountDesignerAmount();
		} else if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
			if (getAdvanceFromQuotation(contractReq.getContractBaseInfo().getProjectOrderId(), ContractTypeEnum.ADVANCE.getCode(), businessType)) {
				return contractReq.getQuotation().getAdvanceAmount();
			}
			return contractReq.getProjectInfo().getAdvanceAmount();
		} else if (ContractTypeEnum.PERSONAL.getCode().equals(contractType)) {
			return getPersonalContractAmount(contractReq);
		} else if (ContractTypeEnum.getContractAmountZeroTypes().contains(contractType)) {
			return BigDecimal.ZERO;
		} else if (ContractTypeEnum.belongToPersonalizedContract(contractType)) {
			return contractReq.getAmountInfo().getDueTotalAmount();
		} else if (ContractTypeEnum.TERMINAL.getCode().equals(contractType)) {
			return getTerminalContractAmount(contractReq.getContractBaseInfo().getProjectOrderId());
		}
		return contractReq.getProjectInfo().getAmount();
	}


	/**
	 * 获取解约协议合同金额
	 *
	 * @param projectOrderId
	 * @return
	 */
	private BigDecimal getTerminalContractAmount(String projectOrderId) {
		if (ContractContextHandler.getContext().isMergeLaunch()) {
			CancelOrderBaseInfoDTO cancelOrderBaseInfoDTO = commonContractService.buildMergeLaunchCancelOrderDTO(projectOrderId);
			return cancelOrderBaseInfoDTO.getCancelOrderAmount().abs();
		}
		List<CancelOrderBaseInfoDTO> cancelOrderRecordList = cancelOrderRecordService.getListByProjectOrderId(projectOrderId).stream()
			.filter(t -> t.getStatus().equals(CancelOrderStatusEnum.AWAIT_SIGN_LAUNCH.getStatus()))
			.collect(Collectors.toList());
		if (cancelOrderRecordList.isEmpty()) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "没有处于待发起签约中的退单");
		}
		return cancelOrderRecordList.get(0).getCancelOrderAmount().abs();
	}

	/**
	 * 获取销售合同金额
	 *
	 * @return
	 */
	private BigDecimal getPersonalContractAmount(ContractReqDTO contractReq) {
		String submitCompanyCode = contractReq.getContractBaseInfo().getSubmitCompanyCode();
		return ContractContextHandler.getContractSourceDataBO().getPersonalContractDataList().stream()
			.filter(item -> item.getOrganizationCode().equals(submitCompanyCode))
			.map(ContractSourceDataBO.PersonalContractData::getPersonalContractPrice)
			.reduce(BigDecimal.ZERO, BigDecimal::add);
	}


	/**
	 * 检查备件是否上传完成  true:完成 false:未完成
	 */
	public boolean checkAttach(CheckAttachUploadStatusParam checkAttachUploadStatusParam) {
		if (checkAttachUploadStatusParam.getAgentSign() == null) {
			//兼容历史发起的合同没有agentSign字段，历史有代理人就代表代理人直接签约
			checkAttachUploadStatusParam.setAgentSign(checkAttachUploadStatusParam.getHaveAgent());
		}
		Map<Byte, List<String>> attachMap = checkAttachUploadStatusParam.getContractAttachList().stream()
			.filter(attach -> StringUtils.isNotBlank(attach.getUrl()) || StringUtils.isNotBlank(attach.getCertificateId()) || StringUtils.isNotBlank(attach.getDocumentCode()))
			.collect(Collectors.groupingBy(
				ContractAttach::getAttachType,
				Collectors.mapping(ContractAttach::getUrl, Collectors.toList())
			));
		if (CollectionUtils.isEmpty(attachMap.get(AttachTypeEnum.HOUSE_CERTIFICATE.getCode())) && CollectionUtils.isEmpty(attachMap.get(AttachTypeEnum.OTHER_OWNER_SHIP.getCode()))) {
			if (Arrays.asList(HaveHouseProveEnum.HOUSE_PROVE.getCode(), HaveHouseProveEnum.OTHER_OWNER_SHIP.getCode()).contains(checkAttachUploadStatusParam.getHaveHouseProve())
				|| checkAttachUploadStatusParam.getHaveHouseProve() == null) {
				return false;
			}
		}
		//公对公需要 经办人证件 公司营业执照
		if (ContractObjectTypeEnum.COMPANY.getCode().equals(checkAttachUploadStatusParam.getContractObjectType())) {
			//公对公必有公司营业执照
			if (CollectionUtils.isEmpty(attachMap.get(AttachTypeEnum.COMPANY_LICENSE.getCode()))) {
				return false;
			}
			//对公签约已开城需要法定代表人证件
			if (checkAttachUploadStatusParam.getSupportCompanyOnlineSign() && CollectionUtils.isEmpty(attachMap.get(AttachTypeEnum.LEGAL_CERTIFICATE_UNIFY.getCode()))) {
				return false;
			}
			//【公对公线下&没开城】或【公对公线上代理人签约】需要代理人证件
			if ((SignChannelTypeEnum.OFFLINE.getCode().equals(checkAttachUploadStatusParam.getSignChannelType()) && !checkAttachUploadStatusParam.getSupportCompanyOnlineSign()) ||
				RoleTypeEnum.COMPANY_AGENT.getCode().equals(checkAttachUploadStatusParam.getSignRole())) {
				return !CollectionUtils.isEmpty(attachMap.get(AttachTypeEnum.COMPANY_AGENT_CERTIFICATE_UNIFY.getCode()));
			}
		} else {
			if (CollectionUtils.isEmpty(attachMap.get(AttachTypeEnum.USER_CERTIFICATE_UNIFY.getCode()))) {
				return false;
			}
			//有代理人需要代理人证件
			if (CommonEnum.YES.getCode().equals(checkAttachUploadStatusParam.getHaveAgent())) {
				if (CollectionUtils.isEmpty(attachMap.get(AttachTypeEnum.AGENT_CERTIFICATE_UNIFY.getCode()))) {
					return false;
				}
				boolean attachOcrOpenCity = attachCommonService.attachOcrOpenCity(checkAttachUploadStatusParam.getProjectOrderId());
				if (attachOcrOpenCity) {
					return true;
				}
				//有代理人委托证明为true需要代理人委托证明
				if (CommonEnum.YES.getCode().equals(checkAttachUploadStatusParam.getAgentSign())) {
					return !CollectionUtils.isEmpty(attachMap.get(AttachTypeEnum.AGENT_CERTIFICATE.getCode()));
				}
			}
		}
		return true;
	}


	/**
	 * 合同编辑页的预览页：只返回线上签约的合同，直接请求协议平台生成临时PDF-URL，类似于线下合同请求S3生成URL
	 * 支持异步生成预览合同
	 */
	public ContractSubmitResDTO previewAsync(ContractReqDTO contractReq) {
		List<FileInfo> contractUrl = new ArrayList<>();
		Byte contractType = contractReq.getContractBaseInfo().getContractType();
		String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();
		String contractPollKey = getContractPollKey(projectOrderId, contractType);
		HeaderParam headerContext = HeaderContext.getContext();
		CompletableFuture<Void> launchFuture = CompletableFuture.runAsync(RunnableWrapper.of(() -> {
			try {
				LOGGER.info("异步发起合同预览开始，projectOrderId:{}，threadId:{}", projectOrderId, Thread.currentThread().getId());
				previewContractBefore(headerContext);
				ContractSubmitResDTO contractSubmitResDTO = contractUnifyServiceSelf.preview(contractReq);
				contractUrl.addAll(contractSubmitResDTO.getContractUrl());
				previewContractAfter(contractSubmitResDTO, contractPollKey);
				LOGGER.info("异步发起合同预览结束，projectOrderId:{}，threadId:{}", projectOrderId, Thread.currentThread().getId());
			} catch (Exception e) {
				LOGGER.info("异步发起合同预览异常，projectOrderId:{}，threadId:{},e:{}", projectOrderId, Thread.currentThread().getId(), e);
				previewContractException(e, contractPollKey);
			}
		}), contractSubmitExternalExecutor);
		if (contractSubmitSync(contractType)) {
			try {
				launchFuture.get();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			} catch (Exception e) {
				Throwable cause = e.getCause();
				throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), cause == null ? e.getMessage() : cause.getMessage());
			}
		}
		return ContractSubmitResDTO.builder()
			.contractUrl(contractUrl)
			.contractCode("")
			.estimatedLaunchTime(ContractTypeEnum.getEnumByCode(contractType).getEstimatedLaunchTime())
			.contractResultPollingKey(contractPollKey)
			.build();
	}


