	/**
	 * 预览合同异常处理
	 */
	public void previewContractException(Throwable e, String contractPollKey) {
		try {
			Throwable cause = e.getCause();
			//pdf生成失败,允许重试
			boolean retrySubmit = cause instanceof NrsBusinessException && ((NrsBusinessException) cause).getCode() == ResponseCodeEnum.PDF_CREATE_ERROR.getCode();
			String errorMessage = "";
			if (cause instanceof NrsBusinessException && ResponseCodeEnum.CONTRACT_ERROR_USER_HAND.contains(((NrsBusinessException) cause).getCode())) {
				errorMessage = cause.getMessage();
			} else {
				String tempMessage = cause == null ? e.getMessage() : cause.getMessage();
				errorMessage = "合同生成失败，失败原因：" + tempMessage + "，如有疑问，请联系【我的客服】处理";
			}
			//保存发起结果到redis
			saveContractSubmitToRedis(Lists.emptyList(), ContractSubmitStatusEnum.FAIL, contractPollKey, errorMessage, retrySubmit);
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), errorMessage, Level.WARN);
		} finally {
			HeaderContext.clearContext();
		}
	}

