	}

	/**
	 * 无在途和解协议
	 */
	public boolean hasNoProgressingSettlement(String projectOrderId) {
		List<Contract> settlementList = contractService.getContractList(projectOrderId, ContractTypeEnum.SETTLEMENT.getCode(), ContractStatusEnum.inProgressStatusWithoutDraft);
		// 如果存在在途补充协议，则不允许创建补充协议
