					.toast("所选组合单关联报价单状态无法发起签约，请重新选择")
					.build();
			}
		}
	}

	//获取主合同所有关联C合同绑定的报价单列表a
	//获取参数传入的报价单列表b
	//用列表b-列表a=报价的列表c
	//获取报价单列表c关联的合同列表，如果列表不为空，则说明选择的报价单已经关联了C合同，无法发起签约
	List<String> a = new ArrayList<>();
	List<String> b = billCodeInfoList.stream().map(item -> item.getBillCode() + "_" + item.getCompanyCode()).collect(Collectors.toList());
	List<String> c = new ArrayList<>();
	if (StringUtils.isNotBlank(contractCode)) {
		List<ContractRelation> relationList = contractRelationService.getRelationList(contractCode);
		if (CollectionUtil.isNotEmpty(relationList)) {
			List<String> relationContractCodeList = relationList.stream().map(ContractRelation::getRelateContractCode)
				.collect(Collectors.toList());
			List<Contract> relationContractList = contractService.getListByContractCodes(relationContractCodeList, false);
			List<Contract> relationPersonalContractList = relationContractList.stream().filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))
				.filter(contract -> ContractStatusEnum.inPositiveStatus.contains(contract.getStatus()))
				.collect(Collectors.toList());
			for (Contract contract : relationPersonalContractList) {
				//查询合同关联的报价单
				List<BillCodeInfo> billCodeInfoListByContractCode = quotationRelationCommonService.getBindOrderInfoGroupByContractCode(contract.getContractCode()).getBillCodeInfos();

				List<String> billCodeInfoStrList = billCodeInfoListByContractCode.stream()
					.map(item -> item.getBillCode() + "_" + item.getCompanyCode())
					.collect(Collectors.toList());
				a.addAll(billCodeInfoStrList);
			}
		}
	}
	LOGGER.info("checkFormalList billCodeList,列表a:{}，列表b:{}", JSON.toJSONString(a), JSON.toJSONString(b));
	//列表b-列表a，剩下的是需要新绑定的
	c = b.stream()
		.filter(e -> !a.contains(e))
		.collect(Collectors.toList());
	LOGGER.info("checkFormalList billCodeList,需要新绑定的报价单列表c:{}", JSON.toJSONString(c));
	if (CollectionUtil.isNotEmpty(c)) {
		//将c转为List<BillCodeInfo>
		List<BillCodeInfo> billCodeInfoListC = c.stream()
			.map(item -> {
				String[] split = item.split("_");
				return BillCodeInfo.builder()
					.billCode(split[0])
					.companyCode(split[1])
					.build();
			})
			.collect(Collectors.toList());
		List<String> billCodeListC = billCodeInfoListC.stream().map(BillCodeInfo::getBillCode).collect(Collectors.toList());
		List<String> relationListByBillCodeList = quotationRelationCommonService.getRelationListByBillCodeList(billCodeListC)
			.stream().map(item -> item.getBillCode() + "_" + item.getCompanyCode()).collect(Collectors.toList());
		//如果有交集，说明所选报价单已经关联了其他合同
		if (CollectionUtil.isNotEmpty(CollectionUtil.intersection(c, relationListByBillCodeList))) {
			LOGGER.info("checkFormalList,所选报价单已关联合同，请重新选择,列表b：{}，列表c：{}，列表c已绑定的合同：{}", JSON.toJSONString(b), JSON.toJSONString(c), JSON.toJSONString(relationListByBillCodeList));
			return ContractSecondaryCheckRes.builder()
				.checkRes(Boolean.FALSE)
				.toast("所选报价单已关联合同,请重新选择")
				.build();
		}
	}
	return ContractSecondaryCheckRes.builder()
		.checkRes(Boolean.TRUE)
		.build();
}

public ContractSecondaryCheckRes checkFormalListV2(Byte contractType, String contractCode, BindOrderInfoGroup group) {
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return ContractSecondaryCheckRes.success();
	}

	if (CollectionUtils.isEmpty(group.getBindOrderInfos())) {
		List<SignableOrderInfoGroup> signableOrderInfos = formalMultipleCompanyService.getFormalQuotationListV2(group.getProjectOrderId());
		if (CollectionUtils.isEmpty(signableOrderInfos)) {
			//正签发起，没有可选择的C报价单，返回true，直接进入合同发起页面
			return ContractSecondaryCheckRes.builder()
				.checkRes(Boolean.TRUE)
				.build();
		}
		//正签发起，有可选择的C报价单，返回false，跳弹窗页，选择要发起的C报价单
		return ContractSecondaryCheckRes.builder()
			.checkRes(Boolean.FALSE)
			.build();
	}

	// 校验绑定单据状态
	boolean hasInvalidStatusOrder = group.getBindOrderInfos().stream().anyMatch(bindOrderInfo -> contractSigningSourceRouter.route(bindOrderInfo.getBindType()).hasInvalidStatusOrders(bindOrderInfo));
	if (hasInvalidStatusOrder) {
		return ContractSecondaryCheckRes.fail("所选组合单关联报价单状态无法发起签约，请重新选择");
	}

	// 正签发起场景，判断报价单是否已被其他合同绑定
	if (quotationRelationCommonService.hasBoundOtherPositiveContractInFormal(group, contractCode))
		return ContractSecondaryCheckRes.fail("所选报价单已关联合同,请重新选择");
	return ContractSecondaryCheckRes.success();
}

