public void checkProjectContractModeCode(ContractReqDTO contractReq) {
	// 圣都模式 整装、局装、翻新全案校验工程承包方式不能为2
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	Byte businessType = contractReq.getProjectInfo().getBusinessType();
	Integer gbCode = contractReq.getProjectInfo().getGbCode();
	if (!BusinessTypeEnum.getNonGroupDecorateModeList().contains(businessType) || !ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return;
	}
	MiniPayChannelAppNameEnum miniProgramType = commonBusinessService.getMiniProgramType(gbCode);
	if (!MiniPayChannelAppNameEnum.圣都.getAppName().equals(miniProgramType.getAppName())) {
		return;
	}
	Integer projectContractModeCode = contractReq.getPromiseInfo().getProjectContractModeCode();
	if (ProjectContractModeEnum.B_LABOR_PART_MATERIALS_A_PART_MATERIALS.getCode().equals(projectContractModeCode)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "当前项目承包方式对应税率不支持，请调整后提交");
	}
}

	public ContractCheckNodeRes preSignCheck(Byte contractType, ProjectInfoDTO projectInfo, Boolean allToast, ContractPreCheckBo contractPreCheckBo) {
		LOGGER.info("preSignCheck签前校验开始");
		Byte businessType = commonContractService.getBusinessType(projectInfo);
		//合同没有配置，提示配置合同信息
		String companyCode = projectInfo.getCustomerCommission().getCompanyCode();
		List<ContractCityCompanyInfo> config = contractCityCompanyConfigService.getConfig(projectInfo.getProjectOrderId(), projectInfo.getCustomerHouse().getGbCode(), companyCode, businessType, contractType);
		if (CollectionUtils.isEmpty(config)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, String.format("城市:%s,分公司:%s缺少合同配置", projectInfo.getCustomerHouse().getGbCode(), companyCode));
		}
		//项目信息转换为协同项目单号
		CoordinationProjectInfo coordinationProjectOrder = commonBusinessService.getCoordinationProjectOrder(projectInfo.getProjectOrderId());
		List<Contract> contractList = contractService.getContractList(coordinationProjectOrder.getProjectOrderId());
		// 首期款合同
		// 需要校验是否有正签套餐合同：有进行中/已完成的整装正式套餐合同，无法进行创建
		if (ContractTypeEnum.ADVANCE.getCode().equals(contractType) && contractList.stream().anyMatch(contract -> ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType()))) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "已有进行中/已完成的整装正式套餐合同，无法进行创建", Level.WARN);
		}
		//整装合同校验是否存在在途结算单
		if (ContractTypeEnum.WHOLE_FUND_LIST.contains(contractType)) {
			//校验是否有在途的结算单：有进行中的整装结算单，请先完成当前结算单再进行创建
			CompletionBillInfoResp completionBillInfoResp = octopusRpc.allowFundChange(projectInfo.getProjectOrderId());
			if (!completionBillInfoResp.getCanChange()) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), completionBillInfoResp.getMessage(), Level.WARN);
			}
		}

		// 补充协议 & 和解协议需要进行签前校验
		if (ContractTypeEnum.SUPPLEMENT.getCode().equals(contractType)) {
			supplementCheckList(projectInfo.getProjectOrderId());
		} else if (ContractTypeEnum.SETTLEMENT.getCode().equals(contractType)) {
			settlementCheckList(projectInfo.getProjectOrderId());
		}

		// 翻新全案 & 正签，需要校验预堪任务状态是否已经完成
		if (contractApolloConfig.preSurveyCheckIsOpen(projectInfo.getCustomerHouse().getGbCode()) && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
			HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(projectInfo.getProjectOrderId(), Collections.singletonList(HomeModelDefEnum.CONSTRUCTION_PRE_SURVEY.name()));
			Integer preSurveyStatus = Optional.ofNullable(homeProject)
				.map(HomeProject::getMainOrder)
				.map(MainOrder::getConstruction)
				.map(MainOrderModel.Construction::getPreSurveyModule)
				.map(PreSurveyModule::getPreSurveyBaseInfoList)
				.filter(list -> !list.isEmpty())
				.map(list -> list.get(0))
				.map(PreSurveyModule.IPreSurveyBaseInfo::getStatus)
				.orElse(null);
			LOGGER.info("projectOrderId: {}, 预堪任务状态: {}", projectInfo.getProjectOrderId(), preSurveyStatus);
			// 如果预堪任务状态未完成，需要拦截
			if (!PreSurveyStatusEnum.SKIPPED_COMPLETED.getCode().equals(preSurveyStatus) && !PreSurveyStatusEnum.COMPLETED.getCode().equals(preSurveyStatus)) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "请先完成预堪", Level.WARN);
			}
		}

		// 正签套餐合同
		if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			//校验是否有在途的首期款合同：有进行中的整装首期款合同，请先完成当前合同再进行创建
			if (contractList.stream().anyMatch(contract -> ContractTypeEnum.ADVANCE.getCode().equals(contract.getType()) && ContractStatusEnum.isInProgressStatus(contract.getStatus()))) {
				throw new NrsBusinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL.getCode(), "有进行中的硬装首期款合同，请先完成当前合同再进行创建", Level.WARN);
			}
			//正签合同校验装修类型是不是【其他】
			if (CommissionDecorateTypeEnum.OTHERS.getCode().equals(projectInfo.getCustomerCommission().getDecorateType())) {
				throw new NrsBusinessException(ResponseCodeEnum.DECORATE_TYPE_OTHER.getCode(), "装修类型不能为其他");
			}
		}
		//设计合同
		// 需要检验正签合同是否约定设计费：如果约定设计费，则提示
		if (ContractTypeEnum.DESIGN.getCode().equals(contractType)) {
			designContractCheck(contractList);
		}
		List<String> userList = new ArrayList<>();
		// 纯零售项目不校验人员信息
		if (!ProjectDecorateBusinessTypeEnum.RETAIL.getCode().equals(projectInfo.getDecorateBusinessType())) {
			//人员依赖校验
			ProjectServerParam param = ProjectServerParam.builder().projectOrderId(Long.valueOf(projectInfo.getProjectOrderId())).build();
			List<ProjectServerInfoDTO> projectServerInfoList = shuttleOrderRpc.queryProjectServerInfo(param);
			if (CollectionUtils.isEmpty(projectServerInfoList)) {
				//todo cuiyubao 后续增加
//				throw new NrsBusinessException("项目人员信息为空，请添加相关信息", Level.WARN);
			}
			userList = projectServerInfoList.stream().map(ProjectServerInfoDTO::getType).collect(Collectors.toList());
			//团装单独校验，不走弹窗展示节点信息
			if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
				if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
					boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectInfo.getProjectOrderId());
					homeAndPcCommonService.groupDecorateCheck(config.get(0), userList);
					if (processV25) {
						//团装2.5正签判断B合同报价的是否已生成
						//过滤出B报价单
						List<HomeOrderAttachmentEntity> orderAttachmentEntityList = homeOrderOperationCheckService.queryOrderAttachmentByHomeOrderNo(projectInfo.getProjectOrderId());
						List<HomeOrderAttachmentEntity> formalOrderAttachmentList = orderAttachmentEntityList.stream().filter(item -> Integer.valueOf(item.getAttachmentType()).equals(PlanAttachment.报价单)).collect(Collectors.toList());
						if (CollectionUtil.isNotEmpty(orderAttachmentEntityList) && CollectionUtils.isEmpty(formalOrderAttachmentList)) {
							throw new NrsBusinessException("正签报价单还未生成，无法发起签约", Level.WARN);
						}
					} else {
						if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && !OrderStatusEnum.WAITING_SIGN.getCode().equals(projectInfo.getProjectOrderStatus())) {
							throw new NrsBusinessException("项目还没有报价，请先完成报价", Level.WARN);
						}
						return ContractCheckNodeRes.builder()
							.projectOrderId(coordinationProjectOrder.getProjectOrderId())
							.contractType(contractType)
							.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contractType, businessType))
							.checkNodeList(new ArrayList<>())
							.checkRes(Boolean.TRUE)
							.build();
					}
				}
			} else {
				//需要toast校验设计师
				List<Byte> needCheckDesignerContractTypeToast = new ArrayList<>(Arrays.asList(ContractTypeEnum.PACKAGE_CHANGE.getCode(), ContractTypeEnum.TERMINAL.getCode(), ContractTypeEnum.DRAWING.getCode(),
					ContractTypeEnum.DESIGN_CHANGE.getCode()));
				if (needCheckDesignerContractTypeToast.contains(contractType) && !userList.contains(ServerTypeEnum.DESIGNER.getType())) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请先完成设计师分配");
				}
			}
		}

		/**
		 * 签前校验：展示校验节点状态和展示信息
		 */
		ContractCheckNodeRes checkNodeRes = preSignCheckShowNode(contractType, projectInfo, userList, contractPreCheckBo.getChangeOrderId(), businessType, contractPreCheckBo, coordinationProjectOrder);
		List<Node> unCompleteNodeList = checkNodeRes.getCheckNodeList().stream().filter(node -> ConfigStatusEnum.TO_COMPLETE.getCode().equals(node.getStatus())).collect(Collectors.toList());
		if (Boolean.TRUE.equals(allToast) && !CollectionUtils.isEmpty(unCompleteNodeList)) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "请先" + unCompleteNodeList.get(0).getNodeDesc());
		}
		LOGGER.info("preSignCheck签前校验结束");
		return checkNodeRes;
	}

public Boolean preSignCheckPlanAllDTO(Byte businessType, String projectOrderId, Byte contractType) {
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType);
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) || (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && !processV25)) {
		return Boolean.FALSE;
	}
	ContractSourceDataBO contractSourceDataBO = homeOrderDataConversionService.contractSourceDateNoThrow(projectOrderId, null);
	//团装2.5
	if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25) {
		if (contractSourceDataBO.getPlanAllDTO() != null && org.apache.commons.collections4.CollectionUtils.isNotEmpty(contractSourceDataBO.getPersonalContractDataList())) {
			if (contractSourceDataBO.getPersonalContractDataList().size() > 1) {
				throw new NrsBusinessException("团装2.5只能有一个个性化套餐", Level.ERROR);
			}
		}
		return Boolean.FALSE;
	}
	//报价类型校验
	PlanAllDTO planAllDTO = contractSourceDataBO.getPlanAllDTO();
	//正签的报价信息查不到时，特殊toast提示：'请完成正式报价后再发起签约'
	if (Objects.isNull(planAllDTO) || Objects.isNull(planAllDTO.getPlanInfo())) {
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), "请完成正式报价后再发起签约", Level.WARN);
	}
	return Boolean.FALSE;
}

public ContractCheckNodeRes preSignCheckShowNode(Byte contractType, ProjectInfoDTO projectInfo, List<String> userList, String changeOrderId, Byte businessType, ContractPreCheckBo contractPreCheckBo, CoordinationProjectInfo coordinationProjectOrder) {
	//获取需要校验的节点
	List<PreSignCheckFirstNode> nodeKeyList = new ArrayList<>();
	Integer gbCode = commonContractService.getCityMapping(projectInfo.getCustomerHouse().getGbCode(), projectInfo.getProjectOrderId());
	if (ContractTypeEnum.ADVANCE.getCode().equals(contractType)) {
		if (!BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
			nodeKeyList = CityEnum.BEIJING.getGbCode() == gbCode ? PreSignCheckFirstNode.ADVANCE_PRE_CHECK : PreSignCheckFirstNode.ADVANCE_PRE_CHECK_ALL;
		}
	} else if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectInfo.getProjectOrderId(), contractType);
		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType)) {
			if (CityEnum.BEIJING.getGbCode() == gbCode) {
				nodeKeyList = new ArrayList<>(PreSignCheckFirstNode.PACKAGE_FORMAL_PRE_CHECK_MERGE_LAUNCH);
			} else if (processV25) {
				nodeKeyList = PreSignCheckFirstNode.PACKAGE_FORMAL_PRE_CHECK_NEW;
			} else {
				nodeKeyList = new ArrayList<>(PreSignCheckFirstNode.PACKAGE_FORMAL_PRE_CHECK);
			}
		}
		if (BusinessTypeEnum.PART_DECORATE.getCode().equals(businessType)) {
			ContractConfigRuleDTO contractConfigSignRule = contractConfigService.queryOrDefaultConfigRule(projectInfo.getCustomerHouse().getGbCode());
			if (contractConfigSignRule.getRetailAmountRatio().compareTo(BigDecimal.ZERO) > 0 || contractConfigSignRule.getRetailAndBureauChangeAmountSum().compareTo(BigDecimal.ZERO) > 0) {
				nodeKeyList.add(PreSignCheckFirstNode.RETAIL_SUPPORT);
			}
		}
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType) && processV25 && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
			nodeKeyList = Lists.newArrayList(PreSignCheckFirstNode.GROUP_COMPLETE_BUDGET);
		}
		if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType)) {
			nodeKeyList = PreSignCheckFirstNode.REFORM_ALL_PACKAGE_FORMAL_PRE_CHECK;
		}

	} else if (ContractTypeEnum.DESIGN.getCode().equals(contractType)) {
		nodeKeyList = PreSignCheckFirstNode.DESIGNER_PRE_CHECK;
	} else if (ContractTypeEnum.PERSONAL.getCode().equals(contractType) && StringUtils.isBlank(changeOrderId)) {
		if (BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			nodeKeyList = PreSignCheckFirstNode.GROUP_PERSONAL_PRE_CHECK;
		} else {
			nodeKeyList = PreSignCheckFirstNode.PERSONAL_PRE_CHECK;
		}
	}
	if (CollectionUtils.isEmpty(nodeKeyList)) {
		return ContractCheckNodeRes.builder()
			.projectOrderId(projectInfo.getProjectOrderId())
			.contractType(contractType)
			.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contractType, businessType))
			.checkNodeList(new ArrayList<>())
			.checkRes(Boolean.TRUE)
			.build();
	}
	List<Node> checkNodeList = new ArrayList<>();
	Map<String, NodeFillInfo> preSignCheckSecondNodeFillInfo = initPreSignCheckSecondNodeFillInfo();
	ContractCheckNodeRes contractCheckNodeRes = ContractCheckNodeRes.builder()
		.projectOrderId(coordinationProjectOrder.getProjectOrderId())
		.contractType(contractType)
		.contractName(ContractTypeEnum.getNameByContractTypeAndBusinessType(contractType, businessType))
		.build();
	//校验节点状态
	for (PreSignCheckFirstNode nodeKey : nodeKeyList) {
		//apollo控制校验：在订单名单 || 不在开城名单：不校验量房打卡或到店服务
		if (PreSignCheckFirstNode.MEASUREMENT_OR_MEETING_CHECK.contains(nodeKey) &&
			(contractApolloConfig.getSkipProjectOrderIds().contains(projectInfo.getProjectOrderId()) || !contractApolloConfig.getCheckCityCodes().contains(projectInfo.getCustomerHouse().getGbCode()))) {
			continue;
		}

		Boolean nodeCheckRes = null;
		switch (nodeKey) {
			case ASSIGN_GROUP_LEADER:
				nodeCheckRes = userList.contains(ServerTypeEnum.GROUP_LEADER.getType());
				break;
			case ASSIGN_DESIGNER:
				nodeCheckRes = userList.contains(ServerTypeEnum.DESIGNER.getType());
				break;
			case ASSIGN_BUDGETER:
				nodeCheckRes = userList.contains(ServerTypeEnum.BUDGETER.getType());
				break;
			case MEASUREMENT_OR_MEETING_ONLY_QUALITY:
				nodeCheckRes = measurementOrMeetingFinish(projectInfo.getCustomerCommission().getCustomerCommissionCode());
				break;
			case MEASUREMENT_OR_MEETING:
				nodeCheckRes = measurementOrMeetingOrMaintainOrSkipFinish(projectInfo.getCustomerCommission().getCustomerCommissionCode(), projectInfo.getProjectOrderId(), contractType);
				break;
			case COMPLETE_BUDGET:
			case COMPLETE_BUDGET_BUDGETER:
				nodeCheckRes = OrderStatusEnum.WAITING_SIGN.getCode().equals(projectInfo.getProjectOrderStatus());
				break;
			case GROUP_COMPLETE_BUDGET:
				nodeCheckRes = groupFormalQuoteFinishRes(projectInfo.getProjectOrderId());
				break;
			case COMPLETE_PRE_DISCLOSURE:
				nodeCheckRes = qualitySalesRpc.preDisclosureFinishRes(projectInfo.getCustomerCommission().getCustomerCommissionCode());
				break;
			case DELIVER_DRAWING:
				nodeCheckRes = deliverDrawingFinishRes(projectInfo.getProjectOrderId());
				break;
			case RETAIL_SUPPORT:
				nodeCheckRes = retailSupportFinishRes(projectInfo.getProjectOrderId(), projectInfo.getCustomerCommission().getCustomerCommissionCode(), projectInfo.getCustomerHouse().getGbCode(), preSignCheckSecondNodeFillInfo, contractPreCheckBo);
				break;
			case PERSONAL_NEED_QUOTE:
				nodeCheckRes = personalQuoteFinishRes(projectInfo.getProjectOrderId(), contractCheckNodeRes, changeOrderId);
				break;
			case GROUP_PERSONAL_NEED_QUOTE:
				nodeCheckRes = groupPersonalQuoteFinishRes(projectInfo.getProjectOrderId(), contractCheckNodeRes);
				break;
			case ADVANCE_NEED_QUOTE:
				nodeCheckRes = advanceQuoteFinishRes(projectInfo.getProjectOrderId(), contractType);
				break;

		}
		ConfigStatusEnum statusEnum = Boolean.TRUE.equals(nodeCheckRes) ? ConfigStatusEnum.COMPLETED : ConfigStatusEnum.TO_COMPLETE;
		List<SubNode> subNodes = convertToRelateSecondNode(nodeKey.getSecondNodeList(), projectInfo, contractType, preSignCheckSecondNodeFillInfo, coordinationProjectOrder);
		List<SubNode> relateSecondNodes = CommonNodeService.convertListNodeToTreeNode(subNodes, nodeKey.getId());
		LOGGER.info("preSignCheckShowNode subNodes:{},relateSecondNodesForTreeNode:{}", JSON.toJSONString(subNodes), JSON.toJSONString(relateSecondNodes));
		Node node = Node.builder()
			.nodeKey(nodeKey.getNodeKey())
			.nodeDesc(nodeKey.getNodeDesc())
			.nodeExtraDesc(CommonUtil.getChoice(relateSecondNodes.size()))
			.status(statusEnum.getCode())
			.statusDesc(statusEnum.getDesc())
			.relateSecondNode(relateSecondNodes)
			.build();
		node.setButtonInfo(buildButtonInfoForNode(statusEnum, node.getNodeKey(), projectInfo, contractType));
		checkNodeList.add(node);
	}
	contractCheckNodeRes.setCheckNodeList(checkNodeList);
	contractCheckNodeRes.setCheckRes(checkNodeList.stream().allMatch(node -> ConfigStatusEnum.COMPLETED.getCode().equals(node.getStatus())));
	return contractCheckNodeRes;
}

private ContractCheckNodeButton buildButtonInfoForNode(ConfigStatusEnum statusEnum, String nodeKey, ProjectInfoDTO projectInfo, Byte contractType) {
	String projectOrderId = projectInfo.getProjectOrderId();
	String customerCommissionCode = projectInfo.getCustomerCommission().getCustomerCommissionCode();
	LOGGER.info("buildButtonInfoForNode nodeKey:{} statusEnum:{}", nodeKey, statusEnum);
	if (nodeKey.equals(PreSignCheckFirstNode.RETAIL_SUPPORT.getNodeKey()) && ConfigStatusEnum.TO_COMPLETE.getCode().equals(statusEnum.getCode())) {
		ContractCheckNodeButton contractCheckNodeButton = ContractCheckNodeButton.builder().build();
		contractCheckNodeButton.setBtnText("修改报价");
		//默认2.0的链接跳转
		contractCheckNodeButton.setSkipUrl(getServiceSide().equals(AppIdEnum.HOME) ?
			String.format(contractApolloConfig.getQuotationPreview2TO0HOME(), projectOrderId, "", contractType, customerCommissionCode, contractType, commonContractService.getBusinessType(projectInfo)) :
			String.format(contractApolloConfig.getQuotationPreview2TO0PC(), projectOrderId, getPageParam(projectOrderId, customerCommissionCode, contractType)));
		boolean houseProcessV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contractType)
			&& BusinessTypeEnum.getHouseCertificate25ModeList().contains(commonBusinessService.getBusinessType(projectOrderId));
		if (houseProcessV25) {
			//2.5的链接跳转
			contractCheckNodeButton.setSkipUrl(getServiceSide().equals(AppIdEnum.HOME) ?
				String.format(contractApolloConfig.getQuotationPreview2TO5HOME(), projectOrderId, "", contractType, customerCommissionCode) :
				String.format(contractApolloConfig.getQuotationPreview2TO5PC(), contractType, getPageParam(projectOrderId, customerCommissionCode, contractType)));
		}
		contractCheckNodeButton.setBtnToast("");
		LOGGER.info("buildButtonInfoForNode contractCheckNodeButton:{}", JSONObject.toJSONString(contractCheckNodeButton));
		return contractCheckNodeButton;
	}
	return null;
}

private String getPageParam(String projectOrderId, String customerCommissionCode, Byte contractType) {
	Map<String, String> map = new HashMap<>();
	map.put("projectOrderId", projectOrderId);
	map.put("customerCommissionCode", customerCommissionCode);
	map.put("contractType", contractType.toString());
	map.put("type", contractType.toString());
	return JSON.toJSONString(map);
}

private AppIdEnum getServiceSide() {
	// 获取uri
	ServletRequestAttributes attributes = (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();
	String requestUri = Optional.ofNullable(attributes).map(ServletRequestAttributes::getRequest)
		.map(HttpServletRequest::getRequestURI).orElse("");

	if (requestUri.startsWith("/pc")) {
		return AppIdEnum.PC;
	}

	return AppIdEnum.HOME;
}

