public void saveContractAttach(String contractCode, ContractReqDTO contractReqDTO, List<String> moduleKeyList) {
	if (ContractTypeEnum.DESIGN.getCode().equals(contractReqDTO.getContractBaseInfo().getContractType())) {
		return;
	}
	if (!moduleKeyList.contains(ContractModuleEnum.SIGN_INFO.getKey()) && !moduleKeyList.contains(ContractModuleEnum.CONTRACT_ATTACH_INFO.getKey())) {
		return;
	}

	List<ContractAttach> contractAttachList = new ArrayList<>();
	ContractSignInfoReq signInfo = contractReqDTO.getSignInfo();
	if (UploadTypeEnum.MIDDLE_GROUND.getCode().equals(signInfo.fetchUploadType())) {
		Map<String, Boolean> firstLaneSyncAttachMap = Optional.ofNullable(signInfo.getFirstLaneSyncAttachMap()).orElse(new HashMap<>());
		List<CertificateFile> certificateFiles = getCertificateDTOListBySdk(contractReqDTO);
		SaveResponseDTO saveResponseDTO = certificateRpc.saveCertificateByDocumentCode(BatchSaveCertificateByCodeRequestDTO.builder()
			.projectOrderId(contractReqDTO.getContractBaseInfo().getProjectOrderId())
			.certificateFiles(certificateFiles)
			.operatorId(HeaderContext.getContext().getOperatorUcId())
			.userId(HeaderContext.getContext().getOperatorUcId())
			.build());
		List<CertificateDTO> certificateList = saveResponseDTO.getCertificateList();

		HashSet<String> hashSet = new HashSet<>();
		for (CertificateDTO certificateDTO : certificateList) {
			List<CertificateFile> certificateFileList = certificateDTO.getCertificateFileList();
			for (CertificateFile certificateFile : certificateFileList) {
				Byte attachType = AttachTypeEnum.getAttachType(certificateFile.getCertificateType(), certificateFile.getUserRole());
				String unionKey = attachType + certificateFile.getDocumentCode() + certificateFile.getFileKey();
				if (hashSet.contains(unionKey)) {
					continue;
				}
				hashSet.add(unionKey);

				com.ke.utopia.nrs.userservice.base.dto.enumeration.certificate.CertificateTypeEnum certificateTypeEnum = com.ke.utopia.nrs.userservice.base.dto.enumeration.certificate.CertificateTypeEnum.getCertificateTypeEnumByCertificateId(certificateFile.getCertificateType());
				Boolean isFirstLaneSyncAttach = firstLaneSyncAttachMap.getOrDefault(certificateTypeEnum.getOriginName(), Boolean.FALSE);
				ContractAttach attach = new ContractAttach();
				attach.setAttachType(attachType);
				attach.setUrl("");
				attach.setCertificateId("");
				attach.setDocumentCode(certificateFile.getDocumentCode());
				attach.setFileKey(certificateFile.getFileKey());
				attach.setContractCode(contractCode);
				attach.setVeracity(ContractAttachVeracityEnum.NONE.getCode());
				attach.setSyncType(isFirstLaneSyncAttach ? AttachSyncTypeEnum.FIRST_LANE_SYNC.getCode() : AttachSyncTypeEnum.NO_SYNC.getCode());
				attach.setCtime(new Date());
				attach.setMtime(new Date());
				attach.setCreateUserId(String.valueOf(HeaderContext.getUserId()));
				attach.setCreateUserName(ContractContextHandler.getOperatorName());
				attach.setModifyUserId(String.valueOf(HeaderContext.getUserId()));
				attach.setModifyUserName(ContractContextHandler.getOperatorName());
				attach.setDelStatus(CommonEnum.NO.getCode());
				contractAttachList.add(attach);
			}
		}

		// 存在代理人委托证明
		if (!EntrustSignTypeEnum.ONLINE.getCode().equals(signInfo.getEntrustSignType())) {
			Byte agentSign = contractReqDTO.getContractAttachInfo().getAgentSign();
			boolean haveAgentCertificate = contractAttachList.stream()
				.anyMatch(attach -> AttachTypeEnum.AGENT_CERTIFICATE.getCode().equals(attach.getAttachType()));
			if (CommonEnum.YES.getCode().equals(agentSign) && haveAgentCertificate) {
				contractReqDTO.getContractAttachInfo().setAgentSign(CommonEnum.YES.getCode());
			} else {
				contractReqDTO.getContractAttachInfo().setAgentSign(CommonEnum.NO.getCode());
			}
		}

		if (contractReqDTO.isContractSubmit()) {
			// 不存在房产证件、客户身份证件的情况提示需要上传
			contractAttachList.stream().filter(attach -> StringUtils.isNotBlank(attach.getDocumentCode()))
				.filter(attach -> AttachTypeEnum.getPersonalCertificateList().contains(attach.getAttachType()))
				.findFirst().orElseThrow(() -> new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "请上传个人证件", Level.WARN));
			contractAttachList.stream().filter(attach -> StringUtils.isNotBlank(attach.getDocumentCode()))
				.filter(attach -> AttachTypeEnum.getHouseCertificateList().contains(attach.getAttachType()))
				.findFirst().orElseThrow(() -> new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "请上传房产证件", Level.WARN));
		}
	}

	if (UploadTypeEnum.S3.getCode().equals(signInfo.fetchUploadType()) && moduleKeyList.contains(ContractModuleEnum.CONTRACT_ATTACH_INFO.getKey())) {
		//合同附件
		List<CertificateDTO> certificateDTOList = saveFileToMiddleGround(contractReqDTO.getContractAttachInfo(), contractReqDTO.getSignInfo(), contractReqDTO.getContractBaseInfo().getProjectOrderId());
		for (CertificateDTO certificateDTO : certificateDTOList) {
			ContractAttach attach = new ContractAttach();
			attach.setAttachType(certificateDTO.getCertificateCode().byteValue());
			attach.setUrl("");
			attach.setCertificateId(certificateDTO.getCertificateId());
			attach.setDocumentCode("");
			attach.setFileKey("");
			attach.setVeracity(ContractAttachVeracityEnum.NONE.getCode());
			attach.setContractCode(contractCode);
			attach.setSyncType(AttachSyncTypeEnum.NO_SYNC.getCode());
			attach.setCtime(new Date());
			attach.setMtime(new Date());
			attach.setCreateUserId(String.valueOf(HeaderContext.getUserId()));
			attach.setCreateUserName(ContractContextHandler.getOperatorName());
			attach.setModifyUserId(String.valueOf(HeaderContext.getUserId()));
			attach.setModifyUserName(ContractContextHandler.getOperatorName());
			attach.setDelStatus(CommonEnum.NO.getCode());
			contractAttachList.add(attach);
		}
	}

	if (!CollectionUtils.isEmpty(contractAttachList)) {
		contractAttachService.insertBatch(contractAttachList);
	}
}

private void saveContractAttachOcr(Contract contract, ContractReqDTO contractReq, List<String> moduleKeyList) {
	List<ContractAttach> contractAttachList = contractAttachService.getListByContractCode(contract.getContractCode());
	List<String> documentCodes = contractAttachList.stream().map(ContractAttach::getDocumentCode).filter(StringUtils::isNotBlank).collect(Collectors.toList());

	if (CollectionUtils.isEmpty(documentCodes)) {
		return;
	}

	String projectOrderId = contractReq.getContractBaseInfo().getProjectOrderId();
	List<CertificateDTO> certificateByCodes = certificateRpc.getCertificateByCodes(projectOrderId, documentCodes);
	List<CertificateFile> certificateFiles = new ArrayList<>();
	for (CertificateDTO certificateByCode : certificateByCodes) {
		Integer certificateType = certificateByCode.getCertificateType();
		List<CertificateFile> certificateFileList = certificateByCode.getCertificateFileList();
		for (CertificateFile certificateFile : certificateFileList) {
			String fileKey = certificateFile.getFileKey();
			String bucket = certificateFile.getBucket();

			certificateFiles.add(CertificateFile.builder()
				.fileKey(bucket + "/" + fileKey)
				.certificateType(certificateType)
				.build());
		}
	}

	List<OcrHistoryResDTO> ocrHistoryResult = certificateRpc.getOcrHistoryResultByCode(OcrHistoryResultByCodeRequestDTO.builder()
		.operatorId(contract.getModifyUserId())
		.projectOrderId(projectOrderId)
		.certificateFiles(certificateFiles)
		.build());

	Set<String> unionKeySet = new HashSet<>();
	List<ContractAttachOcr> contractAttachOcrList = new ArrayList<>();
	List<ContractAttach> attaches = contractAttachList.stream().filter(m -> !AttachTypeEnum.OFFLINE_CONTRACT.getCode().equals(m.getAttachType())).collect(Collectors.toList());
	for (OcrHistoryResDTO ocrHistoryResDTO : ocrHistoryResult) {
		String fileKey = ocrHistoryResDTO.getFileKey();
		ContractAttach contractAttach = attaches.stream().filter(attach -> fileKey.contains(attach.getFileKey())).findFirst().orElse(null);
		List<String> attachOcrFieldNames = attachCommonService.getAttachOcrFieldNames();
		if (contractAttach == null) {
			continue;
		}

		String unionKey = contract.getContractCode() + contractAttach.getDocumentCode() + contractAttach.getFileKey();
		if (unionKeySet.contains(unionKey)) {
			continue;
		}

		for (String attachOcrFieldName : attachOcrFieldNames) {
			if (ocrHistoryResDTO.getOcrField().containsKey(attachOcrFieldName)) {
				unionKeySet.add(unionKey);
				contractAttachOcrList.add(ContractAttachOcr.builder()
					.contractCode(contract.getContractCode())
					.documentCode(contractAttach.getDocumentCode())
					.fileKey(contractAttach.getFileKey())
					.fileOcrField(attachOcrFieldName)
					.fileOcrValue(ocrHistoryResDTO.getOcrField().get(attachOcrFieldName))
					.ctime(new Date())
					.mtime(new Date())
					.delStatus(CommonEnum.NO.getCode())
					.build());
			}
		}
	}

	Map<String, String> encryptMap = cipherService.encrypt(contractAttachOcrList.stream().map(ContractAttachOcr::getFileOcrValue).distinct().collect(Collectors.toList()));
	for (ContractAttachOcr contractAttachOcr : contractAttachOcrList) {
		String encryptValue = encryptMap.getOrDefault(contractAttachOcr.getFileOcrValue(), contractAttachOcr.getFileOcrValue());
		contractAttachOcr.setFileOcrValue(encryptValue);
	}

	if (!CollectionUtils.isEmpty(contractAttachOcrList)) {
		contractAttachOcrService.insertBatch(contractAttachOcrList);
	}
}

private List<CertificateFile> getCertificateDTOListBySdk(ContractReqDTO contractReqDTO) {
	ContractSignInfoReq signInfo = contractReqDTO.getSignInfo();
	List<CertificateFile> certificateFiles = new ArrayList<>();
	if (signInfo.getUserCertificateUnifyDocumentCode() != null && com.ke.utopia.construction.common.collection.CollectionUtils.isNotEmpty(signInfo.getUserCertificateUnifyDocumentCode().fetchDocumentCodes())) {
		Integer certificateType = CertificateTypeEnum.toUserCertificateType(signInfo.getOwnerCertificateType());
		List<String> documentCodes = signInfo.getUserCertificateUnifyDocumentCode().fetchDocumentCodes();
		for (String documentCode : documentCodes) {
			certificateFiles.add(CertificateFile.builder().fileTemplateKey(signInfo.getUserCertificateUnifyDocumentCode().getFileTemplateKey(documentCode)).certificateType(certificateType)
				.documentCode(documentCode).userRole(CertificateUserRoleEnum.OWNER.getRole()).build());
