public void saveContractMaterial(String contractCode, ContractReqDTO contractReqDTO, List<String> moduleKeyList) {
	if (!moduleKeyList.contains(ContractModuleEnum.PROMISE_INFO.getKey())) {
		return;
	}
	List<ContractMaterial> materialList = new LinkedList<>();
	if (Objects.nonNull(contractReqDTO.getPromiseInfo()) && !CollectionUtils.isEmpty(contractReqDTO.getPromiseInfo().getMaterialList())) {
		Map<Integer, MaterialOptionsVo> materialOptionsMap = contractApolloConfig.getMaterialOptionsMap();
		for (MaterialItemVo materialItemVo : contractReqDTO.getPromiseInfo().getMaterialList()) {
			Integer value = materialItemVo.getValue() == null ? 0 : materialItemVo.getValue();
			//如果是自定义的物料类型，取用户填写的描述; 历史自定义填写的甲供材料对应的value为0
			String description = (value.equals(9999) || value.equals(0)) ? materialItemVo.getDescription() : materialOptionsMap.get(value).getLabel();
			String unit = StringUtils.isBlank(materialItemVo.getUnit()) || !value.equals(9999) ? "" : materialItemVo.getUnit();
			materialList.add(ContractMaterial.builder()
				.contractCode(contractCode)
				.description(description)
				.value(value)
				.count(Objects.isNull(materialItemVo.getCount()) ? 0 : materialItemVo.getCount())
				.unit(unit)
				.delStatus((byte) 0)
				.build());
		}
	}
	if (CollectionUtils.isEmpty(materialList)) {
		return;
	}
	for (ContractMaterial contractMaterial : materialList) {
		contractMaterialService.insert(contractMaterial);
	}
}

public void saveContractPlan(String contractCode, ContractReqDTO contractReqDTO, List<String> moduleKeyList) {
	if (!moduleKeyList.contains(ContractModuleEnum.COLLECTION_PLAN_CONFIG_INFO.getKey())) {
		return;
	}
	if (contractReqDTO.getCollectionPlanConfigInfo() == null || CollectionUtils.isEmpty(contractReqDTO.getCollectionPlanConfigInfo().getContent())) {
		throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "传入的收款计划为空，请选择要使用的收款计划", Level.ERROR);
	}
	//防止修改变量内容对后续签约数据有影响
	CollectionPlanConfigInfo collectionPlanConfigInfoTemp = JSON.parseObject(JSON.toJSONString(contractReqDTO.getCollectionPlanConfigInfo()), CollectionPlanConfigInfo.class);
	//检查传入的收款计划
	fundBaseService.checkCollectionPlan(collectionPlanConfigInfoTemp);
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractReqDTO.getContractBaseInfo().getContractType())) {
		// 获取收款计划展示类型
		FundSnapConfigInfo fundSnapConfigInfo = payConfigService.getFundSnapConfigInfo(contractReqDTO.getContractBaseInfo().getProjectOrderId(), FundTypeEnum.PROJECT_CHARGE.getValue());
		Boolean districtSubType = ObjectUtil.isEmpty(fundSnapConfigInfo) || ObjectUtil.isEmpty(fundSnapConfigInfo.getFundPayControlConfigDTO()) || ObjectUtil.isEmpty(fundSnapConfigInfo.getFundPayControlConfigDTO().getDistrictSubType()) ? Boolean.FALSE : fundSnapConfigInfo.getFundPayControlConfigDTO().getDistrictSubType();
		if (!districtSubType) {
			fundBaseService.saveCollectionPlan(contractReqDTO.getCollectionPlanConfigInfo());
		}
	}
	contractCollectionPlanRecordService.insertOrUpdate(ContractCollectionPlanRecord.builder()
		.collectionPlan(JSON.toJSONString(contractReqDTO.getCollectionPlanConfigInfo()))
		.contractCode(contractCode)
		.build());
}

public void saveDraftContractPlan(String contractCode, ContractReqDTO contractReqDTO, List<String> moduleKeyList) {
	if (!moduleKeyList.contains(ContractModuleEnum.COLLECTION_PLAN_CONFIG_INFO.getKey())) {
		return;
	}
	if (Objects.nonNull(contractReqDTO.getCollectionPlanConfigInfo())) {
		//草稿只校验不保存
		if (ObjectUtil.isNotNull(contractReqDTO.getStep())) {
			//防止修改变量内容对后续签约数据有影响
			CollectionPlanConfigInfo collectionPlanConfigInfoTemp = JSON.parseObject(JSON.toJSONString(contractReqDTO.getCollectionPlanConfigInfo()), CollectionPlanConfigInfo.class);
			//检查传入的收款计划
			fundBaseService.checkCollectionPlan(collectionPlanConfigInfoTemp);
		}
		contractCollectionPlanRecordService.insertOrUpdate(ContractCollectionPlanRecord.builder()
			.collectionPlan(JSON.toJSONString(contractReqDTO.getCollectionPlanConfigInfo()))
			.contractCode(contractCode)
			.build());
	}
}

public void updateOrSaveContractNode(Contract contract, ContractReqDTO contractReqDTO) {
	String contractCode = contract.getContractCode();
	Byte auditType = contract.getAuditType();
	//把页面上录入的时间给干掉
	contractNodeService.softDeleteByContractCode(contractCode,
		Arrays.asList(NodeTypeEnum.USER_SIGN.getCode(), NodeTypeEnum.COMPANY_SIGN.getCode()));
	if (SignChannelTypeEnum.OFFLINE.getCode().equals(contractReqDTO.getSignInfo().getSignChannelType())) {
		List<ContractNode> nodeList = new ArrayList<>();
		if (Objects.nonNull(contractReqDTO.getSignInfo().getUserSignTime())) {
			nodeList.add(ContractNode.builder()
				.contractCode(contractCode)
				.nodeType(NodeTypeEnum.USER_SIGN.getCode())
				.fireTime(DateUtils.stringToTimeStamp(contractReqDTO.getSignInfo().getUserSignTime()))
				.build());
		}
		if (Objects.nonNull(contractReqDTO.getSignInfo().getCompanySignTime())) {
			nodeList.add(ContractNode.builder()
				.contractCode(contractCode)
				.nodeType(NodeTypeEnum.COMPANY_SIGN.getCode())
				.fireTime(DateUtils.stringToTimeStamp(contractReqDTO.getSignInfo().getCompanySignTime()))
				.build());
		}
		if (AuditTypeEnum.NONE.getCode().equals(auditType)) {
			nodeList.add(ContractNode.builder()
				.contractCode(contractCode)
				.nodeType(NodeTypeEnum.FINISH.getCode())
				.fireTime(System.currentTimeMillis())
				.build());
		}
		for (ContractNode contractNode : nodeList) {
			contractNodeService.updateOrCreate(contractCode, contractNode.getNodeType(), contractNode.getFireTime());
		}
	}
}

public List<CertificateDTO> saveFileToMiddleGround(ContractAttachInfo attachInfo, ContractSignInfoReq signInfo, String projectOrderId) {
	if (attachInfo == null) {
		return new ArrayList<>();
	}
	Function<List<File>, List<File>> filterFilesForNoSave = files ->
		files.stream()
			.filter(item -> StringUtils.isNotBlank(item.getCertificateId()))
			.collect(Collectors.toList());
	Function<List<File>, List<File>> filterFilesForSave = files ->
		files.stream()
			.filter(item -> StringUtils.isBlank(item.getCertificateId()) && (StringUtils.isNotBlank(item.getUrl()) || ObjectUtil.isNotEmpty(item.getDocumentCode())))
			.collect(Collectors.toList());
	//新上传的文件，需要保存到备件中台
	List<CertificateDTO> certificateForSave = getCertificateDTOList(attachInfo, signInfo, filterFilesForSave);
	//不是新上传的文件，不需要再次保存到备件中台
	List<CertificateDTO> certificateForNoSave = getCertificateDTOList(attachInfo, signInfo, filterFilesForNoSave);
	List<CertificateDTO> certificateListResult = new ArrayList<>(certificateForNoSave);
	if (com.ke.utopia.construction.common.collection.CollectionUtils.isNotEmpty(certificateForSave)) {
		certificateListResult.addAll(certificateRpc.batchSaveCertificate(BatchSaveCertificateRequestDTO.builder()
			.certificateList(certificateForSave)
			.projectOrderId(projectOrderId)
			.operatorId(HeaderContext.getContext().getOperatorUcId())
			.userId(HeaderContext.getContext().getOperatorUcId())
			.build()).getCertificateList());
	}
	return certificateListResult;
}

