private void dataValueCheck(ContractReqDTO contractReq, ContractFieldConfig fieldInfo, ContractModuleAndFieldInfoDTO moduleInfo) {
	//如果是不可编辑的字段或者非必填字段，则不需要校验
	if (fieldInfo.getDisabled().equals(CommonEnum.YES.getCode()) || CommonEnum.NO.getCode().equals(fieldInfo.getRequired())) {
		return;
	}
	Object moduleValue = CommonUtil.getObjectFieldData(fieldInfo.getModuleKey(), contractReq);
	if (Objects.isNull(moduleValue)) {
		String errorMsg = String.format("%s模块信息不能为空", moduleInfo.getModuleKey());
		throw new NrsBusinessException(errorMsg, Level.WARN);
	}
	String displayCondition = fieldInfo.getDisplayCondition();
	if (StringUtils.isBlank(displayCondition)) {
		//没有配置条件，直接校验字段
		try {
			checkFieldValue(fieldInfo, moduleValue, contractReq);
		} catch (Exception e) {
			LOGGER.info("数据校验未通过，字段key：{},字段名称：{}", fieldInfo.getFieldKey(), fieldInfo.getFieldName());
			throw e;
		}
		return;
	}
	//条件计算结果，true为当前字段需要校验非空，false为当前字段不需要校验非空
	boolean displayConditionCompute = true;
	String[] conditions = displayCondition.split("&&");
	for (String condition : conditions) {
		//配置的多个条件，只要有一个不通过则不需要校验
		if (!conditionCheck(condition, contractReq)) {
			displayConditionCompute = false;
			break;
		}
	}
	//配置的条件解析结果为true需要校验字段
	if (displayConditionCompute) {
		try {
			checkFieldValue(fieldInfo, moduleValue, contractReq);
		} catch (Exception e) {
			LOGGER.info("数据校验未通过，字段key：{},字段名称：{},displayCondition:{}", fieldInfo.getFieldKey(), fieldInfo.getFieldName(), displayCondition);
			throw e;
		}
	}
}

