	}
}

public void previewContractException(Throwable e, String contractPollKey) {
	try {
		Throwable cause = e.getCause();
		//pdf生成失败,允许重试
		boolean retrySubmit = cause instanceof NrsBusinessException && ((NrsBusinessException) cause).getCode() == ResponseCodeEnum.PDF_CREATE_ERROR.getCode();
		String errorMessage = "";
		if (cause instanceof NrsBusinessException && ResponseCodeEnum.CONTRACT_ERROR_USER_HAND.contains(((NrsBusinessException) cause).getCode())) {
			errorMessage = cause.getMessage();
		} else {
			String tempMessage = cause == null ? e.getMessage() : cause.getMessage();
			errorMessage = "合同生成失败，失败原因：" + tempMessage + "，如有疑问，请联系【我的客服】处理";
		}
		//保存发起结果到redis
		saveContractSubmitToRedis(Lists.emptyList(), ContractSubmitStatusEnum.FAIL, contractPollKey, errorMessage, retrySubmit);
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), errorMessage, Level.WARN);
	} finally {
		HeaderContext.clearContext();
	}
}

public String getContractSubmitErrorMessage(Throwable e) {
	Throwable cause = e.getCause();
	String errorMessage = "";
	if (cause instanceof NrsBusinessException && ResponseCodeEnum.CONTRACT_ERROR_USER_HAND.contains(((NrsBusinessException) cause).getCode())) {
		errorMessage = cause.getMessage();
	} else {
		String tempMessage = cause == null ? e.getMessage() : cause.getMessage();
		errorMessage = "合同生成失败，失败原因：" + tempMessage + "，如有疑问，请联系【我的客服】处理";
	}
	return errorMessage;
}

public void checkContractFieldConsistency(ContractReqDTO contractReq) {
	Byte businessType = contractReq.getProjectInfo().getBusinessType();
	Integer gbCode = contractReq.getProjectInfo().getGbCode();
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	//需要校验合同类型
	List<Byte> checkConsistencyContractTypeList = Arrays.asList(ContractTypeEnum.PACKAGE_FORMAL.getCode(), ContractTypeEnum.ADVANCE.getCode(), ContractTypeEnum.PACKAGE_CHANGE.getCode());
	ContractFieldForGbCodeConsistencyConfigDto contractFieldForGbCodeConsistencyConfigDto = apolloConfigService.getContractFieldForGbCodeConsistencyConfig();
	Short onDutyStatus = 1;
	if (!BusinessTypeEnum.getHouseCertificate25ModeList().contains(businessType)) {
		return;
	}
	if (!checkConsistencyContractTypeList.contains(contractType)) {
		return;
	}
	LOGGER.info("checkContractFieldConsistency businessType:" + businessType + " gbCode" + gbCode + " contractFieldForGbCodeConsistencyConfigDto:" + JSON.toJSONString(contractFieldForGbCodeConsistencyConfigDto));
	if (contractFieldForGbCodeConsistencyConfigDto.getContainGbCodes().contains(gbCode)) {
		//校验发起人所在组织城市集合和签约上所在城市是否包含
		Long ucId = Long.parseLong(HeaderContext.getContext().getOperatorUcId());
		PersonOrgTreeParam personOrgTreeParam = new PersonOrgTreeParam();
		personOrgTreeParam.setUcIdList(Collections.singletonList(ucId));
		List<PersonOrgTreeDTO> personOrgTrees = ceresRpc.queryPersonAndOrgTree(personOrgTreeParam);
		List<Integer> compareCityCode = personOrgTrees.stream().filter(t -> t.getUcId().equals(ucId) && !StringUtils.isEmpty(t.getCityCode()) && t.getStatus().equals(onDutyStatus)).map(t -> Integer.valueOf(t.getCityCode())).collect(Collectors.toList());
		if (!compareCityCode.contains(gbCode)) {
			throw new NrsBusinessException(ResponseCodeEnum.VERIFICAT_OF_CONTRACT_ADDRESS.getCode(), ResponseCodeEnum.VERIFICAT_OF_CONTRACT_ADDRESS.getMsg(), Level.WARN);
		}
	}

	//校验设计费
	if (ContractTypeEnum.DESIGN_CHANGE.getCode().equals(contractType) || ContractTypeEnum.PACKAGE_CHANGE.getCode().equals(contractType)) {
		contractFieldCheckService.checkDesignAmount(contractReq);
	}
}

public List<FullCompanyInfoDTO> getSignCompanyByProjectOrderIdAndContractType(String projectOrderId, Byte contractType) {
	CoordinationProjectInfo coordinationProjectInfo = commonBusinessService.getCoordinationProjectOrderNotNull(projectOrderId);
	CoordinationProjectRelationInfo projectOrder = coordinationProjectInfo.getRetailProjectOrder();
	if (projectOrder == null) {
		projectOrder = coordinationProjectInfo.getDecorateProjectOrder();
	}

	ProjectInfo projectInfo = projectInfoService.getByProjectOrderId(projectOrder.getProjectOrderId());
	if (projectInfo == null || projectInfo.getGbcode() == null) {
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "项目信息缺失，不支持查询分公司信息，请稍后重试", Level.WARN);
	}
	List<Integer> multiSubjectOpenCityList = contractApolloConfig.getMultiSubjectOpenCityList();

	//获取可用于签约的主体
	List<String> companyCodeList;
	if (!multiSubjectOpenCityList.contains(projectInfo.getGbcode())) {
		ConfigCoreDTO configCoreDTO = commonBusinessService.getCompanyCodeConfigCore(projectOrderId);
		companyCodeList = Collections.singletonList(configCoreDTO.getCompanyCode());
	} else {
		companyCodeList = contractCityCompanyConfigService.getCompanyCodeByContractType(projectInfo, contractType);
	}
	List<MdmDTO> mdmDTOList = mdmRpc.obtainMdmMerchantByMdmCodes(companyCodeList);
	if (mdmDTOList.isEmpty()) {
		throw new NrsBusinessException("未查询到签约主体信息，请提交工单反馈", Level.WARN);
