	List<ContractQuotationRelation> relationListByBillCodeList = quotationRelationCommonService.getRelationListByBillCodeList(billCodeList);
	List<String> relationStrList = relationListByBillCodeList.stream().map(item -> item.getBillCode() + "_" + item.getCompanyCode()).collect(Collectors.toList());


