public ContractDetailResp relationGroupFormalDetail(String projectOrderId, Boolean isDetail) {
	ContractDetailResp contractDetailResp = ContractDetailResp.builder().signInfo(ContractSignInfoDetail.builder().build()).build();
	String previousOrderNo = commonBusinessService.getPreviousOrderNo(projectOrderId);
	if (StringUtils.isBlank(previousOrderNo)) {
		return contractDetailResp;
	}
	Contract latestContract = contractService.getLatestContract(previousOrderNo, ContractTypeEnum.PACKAGE_FORMAL.getCode());
	if (latestContract == null) {
		return contractDetailResp;
	}
	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(latestContract.getContractCode());
	Map<String, String> fieldMap = Maps.newHashMap();
	contractFieldList.forEach(contractField -> fieldMap.put(contractField.getFieldKey(), contractField.getFieldValue()));
	ContractSignInfoDetail signInfoDetail = new ContractSignInfoDetail();
	BeanUtil.fillBeanWithMap(fieldMap, signInfoDetail, true);
	contractDetailResp.setSignInfo(signInfoDetail);
	ContractSignInfoDetail signInfo = contractDetailResp.getSignInfo();
	if (signInfo == null) {
		return contractDetailResp;
	}
	if (isDetail) {
		Map<String, String> encryptMap = cipherService.encrypt(
			Stream.of(
					signInfo.getOwnerCertificateNo(),
					signInfo.getAgentCertificateNo(),
					signInfo.getCompanyAgentCertificateNo(),
					signInfo.getLegalCertificateNo())
				.filter(StringUtils::isNotBlank)
				.distinct()
				.collect(Collectors.toList())
		);
		signInfo.setOwnerCertificateNo(encryptMap.getOrDefault(signInfo.getOwnerCertificateNo(), signInfo.getOwnerCertificateNo()));
		signInfo.setAgentCertificateNo(encryptMap.getOrDefault(signInfo.getAgentCertificateNo(), signInfo.getAgentCertificateNo()));
		signInfo.setCompanyAgentCertificateNo(encryptMap.getOrDefault(signInfo.getCompanyAgentCertificateNo(), signInfo.getCompanyAgentCertificateNo()));
		signInfo.setLegalCertificateNo(encryptMap.getOrDefault(signInfo.getLegalCertificateNo(), signInfo.getLegalCertificateNo()));
	} else {
		//不是详情页，证件号相关字段字段解密
		Map<String, String> decryptMap = cipherService.decrypt(
			Stream.of(
					signInfo.getOwnerCertificateNo(),
					signInfo.getAgentCertificateNo(),
					signInfo.getCompanyAgentCertificateNo(),
					signInfo.getLegalCertificateNo())
				.filter(StringUtils::isNotBlank)
				.distinct()
				.collect(Collectors.toList())
		);
		signInfo.setOwnerCertificateNo(decryptMap.getOrDefault(signInfo.getOwnerCertificateNo(), signInfo.getOwnerCertificateNo()));
		signInfo.setAgentCertificateNo(decryptMap.getOrDefault(signInfo.getAgentCertificateNo(), signInfo.getAgentCertificateNo()));
		signInfo.setCompanyAgentCertificateNo(decryptMap.getOrDefault(signInfo.getCompanyAgentCertificateNo(), signInfo.getCompanyAgentCertificateNo()));
		signInfo.setLegalCertificateNo(decryptMap.getOrDefault(signInfo.getLegalCertificateNo(), signInfo.getLegalCertificateNo()));
	}
	//手机号无论什么场景，都对手机号进行加密
	signInfo.setOwnerPhone(cipherService.encrypt(signInfo.getOwnerPhone()));
	signInfo.setAgentPhone(cipherService.encrypt(signInfo.getAgentPhone()));
	signInfo.setCompanyAgentPhone(cipherService.encrypt(signInfo.getCompanyAgentPhone()));
	signInfo.setSignatoryPhone(cipherService.encrypt(signInfo.getSignatoryPhone()));
	signInfo.setLegalPhone(cipherService.encrypt(signInfo.getLegalPhone()));
	return contractDetailResp;
}

private void checkAndDealWithCancelOrder(String projectOrderId, Byte contractType) {
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return;
	}
	String previousOrderNo = commonBusinessService.getPreviousOrderNo(projectOrderId);
	if (StringUtils.isBlank(previousOrderNo)) {
		return;
	}
	CancelOrderBaseInfoDTO lastCancelOrder = cancelOrderService.getLastRecordByProjectOrderId(previousOrderNo);
	if (lastCancelOrder == null
		|| CancelOrderStatusEnum.REVOKE_CANCEL_ORDER.getStatus().equals(lastCancelOrder.getStatus())) {
		return;
	}
	//如果是可撤销状态的退单，则进行退单撤销
	if (CancelOrderStatusEnum.CAN_REVOKE_STATUS.contains(lastCancelOrder.getStatus())) {
		LOGGER.info("发起正签时，发现关联项目有在途退单，进行退单撤销，projectOrderId:{},previousOrderNo:{}, contractType:{}", projectOrderId, previousOrderNo, contractType);
		cancelOrderService.revokeCancelOrder(lastCancelOrder.getCancelOrderId(), lastCancelOrder);
	}
}

public void formalPersonalContractCheck(ContractReqDTO contractReq) {
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	if (!ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		return;
	}
	BindOrderInfoGroup group = BindOrderInfoGroup.convert(contractReq.getContractBaseInfo().getProjectOrderId(), contractReq.getBusinessInfo());
	if (CollectionUtil.isEmpty(group.getBindOrderInfos())) {
		return;
	}

	boolean hasBoundInFormal = quotationRelationCommonService.hasBoundOtherPositiveContractInFormal(group, contractReq.getContractBaseInfo().getContractCode());

	if (hasBoundInFormal) {
		throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "发起正签选择的单据已发起合同，不允许重复发起合同，请回到合同列表刷新页面后重试", Level.WARN);
