	public boolean isDeveloperChannel(String projectOrderId) {
		// 查询订单的业务类型和 2.5 标
		// todo zqy 后续可以改为从主单查
		String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(projectOrderId);
		ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderIdWithoutCache(convertProjectOrderId);
		Byte businessType = commonContractService.getBusinessType(projectInfoDTO);
		boolean processV25 = commonBusinessService.isProcessV25New(convertProjectOrderId);

		if (!BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType) || !processV25) {
			LOGGER.info("根据订单号判断是否开渠-1, projectOrderId:{}, businessType: {}, processV25: {}",
				projectOrderId, businessType, processV25);
			return false;
		}

		// 拿到主单号，查询主订单平台的新房标签
//		HomeOrderRelationEntity homeOrderRelation = homeOrderRelationEntityService.getByProjectOrderId(projectOrderId);
//		String homeOrderNo = homeOrderRelation.getHomeOrderNo();
		String homeOrderNo = homeOrderQueryService.queryBaseRelevanceInfoFromCache(projectOrderId).getHomeOrderNo();
		HomeProject homeProject = orderStandardQueryRpc.homeStandardOutput(homeOrderNo, Collections.singletonList(HomeModelDefEnum.CUSTOMER_NEW_HOUSING_PROJECT.name()));
		NewHousingProjectModule newHousingProjectModule = Optional.ofNullable(homeProject)
			.map(HomeProject::getHighPriorityProject)
			.map(SubProject::getCustomer)
			.map(SubProjectModel.Customer::getNewHousingProjectModule)
			.orElse(null);


		boolean isDeveloperChannel = newHousingProjectModule != null;
		if (!isDeveloperChannel) {
			LOGGER.info("根据订单号判断是否开渠-2, projectOrderId:{}, homeOrderNo:{}, isDeveloperChannel:{}", projectOrderId, homeOrderNo, false);
			return false;
		}

		LOGGER.info("根据订单号判断是否开渠-3, projectOrderId:{}, homeOrderNo: {}", projectOrderId, homeOrderNo);
		return true;
	}

