public List<ItemContentConfig> supplementItemContentDetail(Byte contractType) {
	if (contractType == null) {
		throw new NrsBusinessException("合同协议条款内容获取，合同类型不能为空");
	}
	// 如果是[正签合同]，则转换为[补充协议]合同类型（兼容正签合并发起场景，前端传入正签类型时，也要下发补充协议的条款内容）
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		contractType = ContractTypeEnum.SUPPLEMENT.getCode();
	}
	List<ContractItemContentConfig> contractItemContentConfigList = contractApolloConfig.getContractItemContentConfigList();
	if (CollectionUtil.isEmpty(contractItemContentConfigList)) {
		return Collections.emptyList();
	}
	Byte finalContractType = contractType;
	return contractItemContentConfigList.stream()
		.filter(item -> item.getContractType().equals(finalContractType))
		.findFirst()
		.map(ContractItemContentConfig::getItemContentConfigList).orElse(Collections.emptyList());
}

public void supplementMergeLaunchCheck(ContractReqDTO contractReq, String projectOrderId) {
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	Byte launchSupplementType = contractReq.getSignInfo() != null ? contractReq.getSignInfo().getLaunchSupplementType() : null;
	boolean isMergeLaunch = ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType) && LaunchSupplementTypeEnum.MERGE_LAUNCH_SUPPLEMENT.getCode().equals(launchSupplementType);
	// 正签发起时，没有选择“合并发起补充协议”，则不校验补充协议的条款内容
	if (!isMergeLaunch) {
		return;
	}

	// 条款内容必填校验
	supplementRequiredCheck(contractReq.getSupplementItemInfo());

	// 无在途补充协议 && 项目未竣工 && 补充协议开城
	boolean checkRes = hasNoProgressingSupplement(projectOrderId) &&
		projectNoCompletion(projectOrderId) &&
		supplementIsOpen(projectOrderId);

	LOGGER.info("补充协议合并发起校验: {}, {}, {}, {}", projectOrderId, hasNoProgressingSupplement(projectOrderId), projectNoCompletion(projectOrderId), supplementIsOpen(projectOrderId));

	if (!checkRes) {
		throw new NrsBusinessException("补充协议签前校验失败");
	}

	// bpm 审批流校验逻辑
	ApproverInfo approverInfo = supplementBpmService.buildApproverInfo(projectOrderId, HeaderContext.getUserId().toString(), ContractTypeEnum.SUPPLEMENT.getCode());
	ApproverInfoCheckDTO checkDTO = supplementBpmService.check(approverInfo);
	if (!checkDTO.isConfig()) {
		String msg = checkDTO.getTips() + "，请联系配置人员操作";
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), msg, msg, Level.WARN);
	}
}

public void supplementAloneLaunchCheck(ContractReqDTO contractReq, String projectOrderId) {
	Byte contractType = contractReq.getContractBaseInfo().getContractType();

	// 单独发起补充协议的校验
	if (!ContractTypeEnum.SUPPLEMENT.getCode().equals(contractType)) {
		return;
	}

	if (contractReq.getSupplementItemInfo() == null) {
		throw new NrsBusinessException("补充协议发起，传入补充协议条款内容不能为空");
	}

	// 条款内容必填校验
	supplementRequiredCheck(contractReq.getSupplementItemInfo());

	// 补充协议单独发起校验
	supplementCheckList(projectOrderId);

	// bpm 审批流校验逻辑
	ApproverInfo approverInfo = supplementBpmService.buildApproverInfo(projectOrderId, HeaderContext.getUserId().toString(), ContractTypeEnum.SUPPLEMENT.getCode());
	ApproverInfoCheckDTO checkDTO = supplementBpmService.check(approverInfo);
	if (!checkDTO.isConfig()) {
		String msg = checkDTO.getTips() + "，请联系配置人员操作";
		throw new NrsBusinessException(ReturnCodeEnum.SHOW_TO_CLIENT.getCode(), msg, msg, Level.WARN);
	}
}

public void supplementRequiredCheck(SupplementItemInfo supplementItemInfo) {
	List<Byte> selectedSupplementItem = supplementItemInfo.getSelectedSupplementItem();
	// 如果没有选择条款内容，则无需校验
	if (CollectionUtil.isEmpty(selectedSupplementItem)) {
		return;
	}
	// 需要校验必填的条款
	List<SupplementItemTypeEnum> needCheckItem = Arrays.asList(SupplementItemTypeEnum.CONSTRUCTION_RISK_CUSTOMER_BEAR, SupplementItemTypeEnum.GENERAL_SCENARIO);
	// 遍历需要校验必填的条款，看是否选择
	for (SupplementItemTypeEnum item : needCheckItem) {
		// 如果没有选择需要校验必填的条款，则跳过
		if (!selectedSupplementItem.contains(item.getCode())) {
			continue;
		}
		// 获取条款对应内容的 key
		List<SupplementItemContentTypeEnum> requiredCheckList = SupplementItemTypeEnum.getRequiredCheckItem(item.getCode());
		for (SupplementItemContentTypeEnum itemContent : requiredCheckList) {
			String key = itemContent.getKey();
			String value = (String) CommonUtil.getObjectFieldData(key, supplementItemInfo);
			// 校验内容是否为空
			if (ObjectUtil.isEmpty(value)) {
				throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "补充协议参数校验：" + key + "不能为空");
			}
			// 补充协议条款内容长度校验
			if (value.length() > SupplementItemContentTypeEnum.MAX_LENGTH) {
				throw new NrsBusinessException(ResponseCodeEnum.PARAM_ERROR.getCode(), "补充协议参数校验：" + key + "长度不能超过" + SupplementItemContentTypeEnum.MAX_LENGTH + "个字符");
			}
		}
	}
}

public void settlementLaunchCheck(ContractReqDTO contractReq, String projectOrderId) {
	Byte contractType = contractReq.getContractBaseInfo().getContractType();
	// 单独发起补充协议的校验
