public ShareCheckDTO checkCanShareV2(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (contract == null) {
		throw new NrsBusinessException("未查询到合同,合同编码:" + contractCode, Level.WARN);
	}
	if (contract.getStatus().equals(ContractStatusEnum.CANCEL.getCode())) {
		throw new NrsBusinessException("合同已作废，无法查看", Level.WARN);
	}

	if (contract.getStatus().equals(ContractStatusEnum.DRAFT.getCode())) {
		throw new NrsBusinessException("当前合同还未发起，请先发起后再分享", Level.WARN);
	}

	if (ContractTypeEnum.TERMINAL.getCode().equals(contract.getType())) {
		CancelOrderBaseInfoDTO lastRecordByProjectOrderId = cancelOrderRecordService.getLastRecordByProjectOrderId(contract.getProjectOrderId());
		if (ObjectUtil.isNotEmpty(lastRecordByProjectOrderId)
			&& !CancelOrderStatusEnum.CAN_SHARE_TERMINAL_CONTRACT_STATUS.contains(lastRecordByProjectOrderId.getStatus())) {
			throw new NrsBusinessException("当前退单流程未满足签署合同条件，请先完成前置流程", Level.WARN);
		}

	}

	boolean processV25 = commonBusinessService.isProcessV25New(contract.getProjectOrderId());
	ShareCheckDTO shareCheckDTO = homeAndPcCommonService.getShareUrl(contractCode, processV25);

	// 如果不是2.5模式发起的合同，不需要校验是否有其他合同签署情况
	if (!processV25) {
		return shareCheckDTO;
	}

	List<Contract> relationContractList = contractBusinessService.getRelationContract(contractCode);
	for (Contract contractInfo : relationContractList) {
		if (contractInfo.getStatus().equals(ContractStatusEnum.PENDING_COMPANY_SIGN.getCode())) {
			String msg = "盖章中，预计1分钟后可分享给客户签约";
			List<ContractLog> contractLogList = contractLogService.getLogByCodeAndType(contractInfo.getContractCode(), LogTypeEnum.COMPANY_SIGN_FAIL.getCode());
			if (org.apache.commons.collections4.CollectionUtils.isNotEmpty(contractLogList) && contractLogList.size() > 2) {
				msg = "合同文件较大，盖章中，预计5-10分钟后可分享给客户签约";
			}
			throw new NrsBusinessException(msg, Level.WARN);
		}
		if (contractInfo.getStatus().equals(ContractStatusEnum.DRAFT.getCode())) {
			throw new NrsBusinessException("关联合同还未发起，请先发起后再分享", Level.WARN);
		}
	}

	List<Integer> auditingStatus = Arrays.asList(ContractStatusEnum.PENDING_SUBMIT_AUDIT.getCode(), ContractStatusEnum.AUDITING.getCode());
	if (ContractTypeEnum.SIGN_INFO_EXTEND_FROM_FORMAL.contains(contract.getType()) && auditingStatus.contains(contract.getStatus())) {
		throw new NrsBusinessException("合同审核中，审核通过后可以进行分享", Level.WARN);
	}
	return shareCheckDTO;
}

public DesignSignPriceInfo calculateDesignSignPriceInfo(String projectOrderId, Byte contractType, String valuationArea, Integer houseBuildType) {
	// 1、根据项目单号查询客源获取设计师ucId
	Long designerUcId = baseAuditChannel.queryProjectDesignerUcId(projectOrderId);

	// 2、根据设计师ucId请求服务者中心查询人员信息
	MidPersonBaseInfoDTO midPersonBaseInfoDTO = ceresRpc.getPersonInfo(designerUcId);

	String psLevelName = midPersonBaseInfoDTO.getPsLevelName();

	// 3、获取分公司
	String convertProjectOrderId = commonBusinessService.obtainProjectRelationId(projectOrderId);
	ProjectInfo projectInfo = projectInfoService.getByProjectOrderId(convertProjectOrderId);
	if (ContractContextHandler.getContext() == null) {
		ContractContextHandler.initContext();
	}
	if (ContractContextHandler.getPlanAllDTO() == null && ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contractType)) {
		//通用准备报价信息
		ContractSourceDataBO contractSourceDataBO = homeOrderDataConversionService.contractSourceDate(projectOrderId, null);
		PlanAllDTO planAllDTO = contractSourceDataBO.getPlanAllDTO();
		ContractContextHandler.setPlanAllDTO(planAllDTO);
	}
	String companyCode = commonBusinessService.getCompanyCodeFromQuotation(projectInfo, contractType, ContractContextHandler.getContractReq());

	// 入参检查
	if (StringUtils.isBlank(companyCode) ||
		designerUcId == null ||
		StringUtils.isBlank(psLevelName) ||
		StringUtils.isBlank(valuationArea) ||
		houseBuildType == null) {
		LOGGER.info("入参校验 - companyCode: {}, designerUcId: {}, psLevelName: {}, valuationArea: {}, houseBuildType: {}",
			companyCode, designerUcId, psLevelName, valuationArea, houseBuildType);
		throw new NrsBusinessException("获取设计服务费信息失败，参数不能为空");
	}

	// 4、构建请求参数
	DesignPriceCalculateParam param = DesignPriceCalculateParam.builder()
		.companyCode(companyCode)
		.designerUcId(designerUcId)
		.psLevelName(psLevelName)
		.valuationArea(valuationArea)
		.houseBuildType(houseBuildType)
		.build();

	BigDecimal standardDesignFeeAmount = null;
	BigDecimal valuationAreaFromQuote = null;
	if (StringUtils.isNotBlank(valuationArea)) {
		// 5、调用中控查询设计费
		DesignFeeResultDTO designFeeResultDTO = quotationFeignService.getDesignFeeConfigV2(param.buildRpcParam());
		// 异常结果拦截
		if (designFeeResultDTO == null || !designFeeResultDTO.getSuccess() || designFeeResultDTO.getDesignFee() == null || designFeeResultDTO.getDesignFee().compareTo(BigDecimal.ZERO) <= 0) {
			String msg = contractApolloConfig.getDesignFeeCalExceptionMsg();
			throw new NrsBusinessException(NrsBusinessException.DEFAULT_ERROR_CODE, msg, msg, Level.ERROR);
		}
		standardDesignFeeAmount = designFeeResultDTO.getDesignFee();
		valuationAreaFromQuote = designFeeResultDTO.getPricingArea();
	}

	return DesignSignPriceInfo.builder()
		.standardDesignFeeAmount(standardDesignFeeAmount)
		.designerUcId(designerUcId)
		.designerUserCode(midPersonBaseInfoDTO.getUserCode())
		.designerName(midPersonBaseInfoDTO.getName())
		.valuationAreaFromQuote(valuationAreaFromQuote)
		.psLevelName(psLevelName)
		.build();
}

