	Contract currentContract = contractUnifyService.buildDraftContract(contractReq);
	//DB-合同数据入库
	contractUnifyService.saveCoreContractDb(currentContract, contractReq);
	//合同节点信息处理
	contractUnifyService.updateOrSaveContractNode(currentContract, contractReq);
	//计算合同diff:仅计算模板字段变更
	List<ContractFieldChangeRecord> list = normalCalculateDiff(currentContract.getContractCode());
