public ContractSubmitResDTO changeContractConfirm(Contract contract) {
	//如果状态不是草稿中，提示合同已提交
	if (!ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())) {
		LOGGER.warn("该合同已提交，请勿重复操作,projectOrderId:{},contractCode:{}", contract.getProjectOrderId(), contract.getContractCode());
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "该合同已提交，请勿重复操作", Level.WARN);
	}
	contractUnifyService.checkContractLaunching(contract.getProjectOrderId(), contract.getType());
	String contractPollKey = contractUnifyService.getContractPollKey(contract.getProjectOrderId(), contract.getType());
	List<FileInfo> contractUrl = new ArrayList<>();
	HeaderParam headerContext = HeaderContext.getContext();
	CompletableFuture<Void> launchFuture = CompletableFuture.runAsync(RunnableWrapper.of(() -> {
		try {
			LOGGER.info("异步合同变更确认开始，contractCode:{}，threadId:{}", contract.getContractCode(), Thread.currentThread().getId());
			changeContractUnifyService.launchChangeContractBefore(contract, headerContext);
			//生成pdf,pdfUrl设置到contract对象中
			if (SignChannelTypeEnum.ONLINE.getCode().equals(contract.getSignChannelType())) {
				NormalChangeContractFreeformDTO normalChangeContractFreeformDTO = buildFreeformDTO(contract.getContractCode(), contract.getProjectOrderId());
				Map<String, Object> map = objectMapper.convertValue(normalChangeContractFreeformDTO, Map.class);
				contractBusinessService.generatePdf(contract, map);
				NormalChangeContractFreeformDTO.DynamicChangeContent dynamicChangeContent = JSON.parseObject(normalChangeContractFreeformDTO.getDynamicChangeContent(), NormalChangeContractFreeformDTO.DynamicChangeContent.class);
				//无变更内容，不允许提交
				if (ObjectUtil.isEmpty(dynamicChangeContent) || ObjectUtil.isEmpty(dynamicChangeContent.getChangeData())) {
					throw new NrsBusinessException(ResponseCodeEnum.CONTRACT_NO_CHANGE.getCode(), ResponseCodeEnum.CONTRACT_NO_CHANGE.getMsg(), Level.WARN);
				}
			} else {
				//线下签约
				List<ContractAttach> offlineAttachList = contractAttachService.getListByContractCode(contract.getContractCode(), AttachTypeEnum.OFFLINE_CONTRACT.getCode());
				for (ContractAttach attach : offlineAttachList) {
					contractUrl.add(FileInfo.builder().type(contractBusinessService.getAttachFileKey(Collections.singletonList(attach.getUrl()))).contractType(contract.getType()).url(attach.getUrl()).build());
				}
			}
			//更新contract状态，记录日志
			String operatorName = homeAndPcCommonService.getOperatorName(HeaderContext.getUserId());
			changeContractUnifyService.updateChangeContract(contract, operatorName);
			changeContractUnifyService.launchChangeContractAfter(contractPollKey, contract, contractUrl);
			LOGGER.info("异步合同变更确认结束，contractCode:{}，threadId:{}", contract.getContractCode(), Thread.currentThread().getId());
		} catch (Exception e) {
			LOGGER.info("异步合同变更确认异常，contractCode:{}，threadId:{}", contract.getContractCode(), Thread.currentThread().getId(), e);
			changeContractUnifyService.launchChangeContractException(contract, e, contractPollKey);
		}
	}),contractSubmitExternalExecutor);
	if (contractUnifyService.contractSubmitSync(contract.getType())) {
		try {
			launchFuture.get();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
		} catch (Exception e) {
			Throwable cause = e.getCause();
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), cause == null ? e.getMessage() : cause.getMessage());
		}
	}
	return ContractSubmitResDTO.builder()
		.contractCode(contract.getContractCode())
		.contractUrl(contractUrl)
		.contractResultPollingKey(contractPollKey)
		.estimatedLaunchTime(ContractTypeEnum.getEnumByCode(contract.getType()).getEstimatedLaunchTime())
		.build();
}

public List<ContractFieldChangeRecord> normalCalculateDiff(String contractCode) {
	Contract currentContract = contractService.getByContractCode(contractCode);
	//获取上一份正签/变更合同
	Contract prevContract = contractService.getContractList(currentContract.getProjectOrderId(), ContractTypeEnum.getRelateContractType(currentContract.getType())).stream()
		.filter(m -> ContractStatusEnum.FINISH.getCode().equals(m.getStatus()) || ContractStatusEnum.USER_CONFIRMED.getCode().equals(m.getStatus()))
		.findFirst()
		.orElse(null);

	if (Objects.isNull(prevContract)) {
		throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "计算补充协议差异内容失败，缺少上一份有效的正签/变更");
	}
	//获取上一份正签/变更合同详情
	FormalContractExpandInfoDTO currentDetail = getNormalContractDetail(currentContract);
	FormalContractExpandInfoDTO prevDetail = getNormalContractDetail(prevContract);
	//删除原有的差异记录
	contractFieldChangeRecordService.deleteByContractCode(contractCode, false);
	//计算差异
	List<FieldDiffDTO> fieldDiffDTOList = compareContract(prevDetail, currentDetail);
	List<ContractFieldChangeRecord> changeRecordList = fieldDiffDTOList.stream().map(
		fieldDiffDTO -> ContractFieldChangeRecord.builder()
			.contractCode(contractCode)
			.fieldKey(fieldDiffDTO.getFieldKey())
			.fieldName(fieldDiffDTO.getFieldName())
			.oldValue(Objects.isNull(fieldDiffDTO.getOldValue()) ? "" : fieldDiffDTO.getOldValue())
			.newValue(Objects.isNull(fieldDiffDTO.getNewValue()) ? "" : fieldDiffDTO.getNewValue())
			.delStatus(CommonEnum.NO.getCode())
			.ctime(new Date())
			.mtime(new Date())
			.build()
	).collect(Collectors.toList());
	if (CollectionUtils.isNotEmpty(changeRecordList)) {
		contractFieldChangeRecordService.insertBatch(changeRecordList);
	}
	return changeRecordList;
}

public FormalContractExpandInfoDTO getNormalContractDetail(Contract contract) {
	FormalContractExpandInfoDTO infoDTO = new FormalContractExpandInfoDTO();
	//字段
	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contract.getContractCode());
	Map<String, String> fieldsMap = contractFieldList.stream().collect(Collectors.toMap(ContractField::getFieldKey, ContractField::getFieldValue, (v1, v2) -> v2));
	//用户
	List<ContractUser> contractUserList = contractUserService.getListByContractCode(contract.getContractCode());
	Map<Byte, ContractUser> userMap = contractUserList.stream().collect(Collectors.toMap(ContractUser::getRoleType, Function.identity(), (v1, v2) -> v2));
	ContractUser owner = userMap.getOrDefault(RoleTypeEnum.OWNER.getCode(), null);

	//1.签约主体
	infoDTO.setContractObjectType(Byte.parseByte(fieldsMap.getOrDefault("contractObjectType", "0")));
	infoDTO.setSignChannelType(contract.getSignChannelType());

	//2.客户信息
	if (Objects.nonNull(owner)) {
		infoDTO.setOwnerName(owner.getName());
		infoDTO.setOwnerPhone(owner.getPhone());
		infoDTO.setOwnerCertificateType(owner.getCertificateType());
		infoDTO.setOwnerCertificateNo(owner.getCertificateNo());
	}
	infoDTO.setOwnerAddress(fieldsMap.getOrDefault("ownerAddress", ""));

	//3.约定设计费金额
	infoDTO.setAfterDiscountDesignerAmount(BigDecimal.valueOf(Double.parseDouble(fieldsMap.getOrDefault("afterDiscountDesignerAmount", "0"))));
	String preDiscountDesignerAmount = fieldsMap.get("preDiscountDesignerAmount");
	if (ObjectUtil.isNotEmpty(preDiscountDesignerAmount)) {
		infoDTO.setPreDiscountDesignerAmount(BigDecimal.valueOf(Double.parseDouble(preDiscountDesignerAmount)));
	}
	//约定设计师级别
	infoDTO.setDesignerLevelName(fieldsMap.getOrDefault("designerLevelName", ""));

	//4.房屋结构类型
	infoDTO.setHouseBuildType(fieldsMap.getOrDefault("houseBuildType", ""));

	return infoDTO;
}

private List<FieldDiffDTO> compareContract(FormalContractExpandInfoDTO prevExpandInfo, FormalContractExpandInfoDTO currentExpandInfo) {
	List<FieldDiffDTO> result = new LinkedList<>();
	// 加解密
	//加密
	changeContractService.encryptExpandInfo(prevExpandInfo);
	changeContractService.encryptExpandInfo(currentExpandInfo);
	//签约主体
	result.addAll(changeContractService.compareContractSignObject(prevExpandInfo, currentExpandInfo));
	//业主信息
	result.addAll(changeContractService.compareContractCustomer(prevExpandInfo, currentExpandInfo));
	//房屋信息
	result.addAll(changeContractService.compareProjectInfo(prevExpandInfo, currentExpandInfo));
	//对比设计费
	result.addAll(changeContractService.compareDesignAmount(prevExpandInfo, currentExpandInfo));
	return result;
}

public NormalChangeContractFreeformDTO buildFreeformDTO(String contractCode, String projectOrderId) {
	ProjectInfoDTO projectInfoDTO = projectInfoReadService.getByProjectOrderId(projectOrderId);
	@Nullable Contract contract = org.apache.commons.lang.StringUtils.isNotBlank(contractCode) ? contractService.getByContractCode(contractCode) : null;
	Contract formalContract = contractService.getContractList(projectOrderId, ContractTypeEnum.DESIGN.getCode(), Arrays.asList(ContractStatusEnum.FINISH.getCode(), ContractStatusEnum.USER_CONFIRMED.getCode())).get(0);

	List<ContractFieldChangeRecord> changeRecordList = changeContractUnifyService.getContractDiff(contractCode);
	Map<String, String> changeMap = changeRecordList.stream().collect(Collectors.toMap(ContractFieldChangeRecord::getFieldKey, ContractFieldChangeRecord::getNewValue, (v1, v2) -> v2));

	LOGGER.info("changeMap:{}", JSON.toJSONString(changeMap));

	//获取上一份合同的签约时间和签约公司信息
	List<ContractNode> contractNodes = contractNodeService.getListByContractCodesAndType(Collections.singletonList(formalContract.getContractCode()), Arrays.asList(NodeTypeEnum.FINISH.getCode(), NodeTypeEnum.USER_CONFIRM.getCode()));
	String signDate = CollectionUtils.isNotEmpty(contractNodes) ? DateUtils.getDateStr(new Date(contractNodes.get(0).getFireTime())) : "/";
	NormalChangeContractFreeformDTO.DynamicChangeContent changeContent = new NormalChangeContractFreeformDTO.DynamicChangeContent();
	//分公司取正签合同的分公司/客源的分公司名称
	CompanyInfoDTO companyInfoDTO = commonContractService.getCompanyInfo(commonBusinessService.getCompanyCodeConfigCore(projectOrderId).getCompanyCode());
	//获取设计师姓名
	String designerName = "/";
	ServiceProviderDTO designer = commonContractService.getDesignerInfo(projectOrderId);
	if (Objects.nonNull(designer) && StringUtils.isNotBlank(designer.getName())) {
		designerName = designer.getName();
	}
	if (contract == null) {
		throw new NrsBusinessException("未找到对应的合同信息");
	}
	//判断是否2.5模式
	boolean processV25 = commonBusinessService.isPROCESS_V2_5(projectOrderId, contract.getType());
	// 获取合同字段表
	Map<String, String> fieldMap = contractFieldService.getFieldMap(contractCode);

	//获取城市业务类型对应变更项
	List<String> changeKeyList = ChangeKeyEnum.getChangeKeyListByBussinessType(contract.getBusinessType(), contract.getType(), processV25, commonContractService.getCityMapping(contract.getGbCode(),contract.getProjectOrderId()));
	if (CollectionUtils.isEmpty(changeKeyList)) {
		throw new NrsBusinessException(String.format("未找到对应的变更项, businessType:%s, gbCode:%s, 合同类型：%s", contract.getBusinessType(), contract.getGbCode(), ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(),contract.getBusinessType())));
	}
	Map<String, ChangeKeyConfig> changKeyConfigMap = changeContractKeyConfig.getChangKeyConfigByCityAndBusinessType(contract.getBusinessType(), contract.getType(), commonContractService.getCityMapping(projectInfoDTO.getCustomerHouse().getGbCode(),contract.getProjectOrderId()));
	if (CollectionUtil.isEmpty(changKeyConfigMap)) {
		throw new NrsBusinessException(String.format("未找到对应的变更项条例位置, businessType:%s, gbCode:%s, 合同类型：%s", contract.getBusinessType(), contract.getGbCode(), ContractTypeEnum.getNameByContractTypeAndBusinessType(contract.getType(),contract.getBusinessType())));
	}
	List<NormalChangeContractFreeformDTO.NormalChangeDataItem> changeData = new LinkedList<>();

	//优惠前金额
	if (changeKeyList.contains(ChangeKeyEnum.PRE_DISCOUNT_DESIGNER_AMOUNT.getKey()) && changeMap.containsKey("preDiscountDesignerAmount")) {
		ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.PRE_DISCOUNT_DESIGNER_AMOUNT.getKey());
		NormalChangeContractFreeformDTO.NormalChangeDataItem preDesignFee = new NormalChangeContractFreeformDTO.NormalChangeDataItem();
		preDesignFee.setArticle(changeKeyConfig.getArticle());
		preDesignFee.setParagraph(changeKeyConfig.getParagraph());
		preDesignFee.setKey(ChangeKeyEnum.PRE_DISCOUNT_DESIGNER_AMOUNT.getKey());
		BigDecimal preDiscountDesignerAmount = new BigDecimal(changeMap.getOrDefault("preDiscountDesignerAmount", "0"));
		preDesignFee.setPreDiscountDesignerAmount(preDiscountDesignerAmount.setScale(2, RoundingMode.HALF_UP).toPlainString());
		MoneyConvertUtil moneyConvertUtil = new MoneyConvertUtil(preDiscountDesignerAmount.toString());
		preDesignFee.setPreDiscountDesignerAmountText(moneyConvertUtil.convert());
		preDesignFee.setDesignerLevelName(changeMap.getOrDefault("designerLevelName", ""));
		changeData.add(preDesignFee);
	}

	//优惠后金额
	if (changeKeyList.contains(ChangeKeyEnum.AFTER_DISCOUNT_DESIGNER_AMOUNT.getKey()) && changeMap.containsKey("afterDiscountDesignerAmount")) {
		ChangeKeyConfig changeKeyConfig = changKeyConfigMap.get(ChangeKeyEnum.AFTER_DISCOUNT_DESIGNER_AMOUNT.getKey());
		NormalChangeContractFreeformDTO.NormalChangeDataItem designFee = new NormalChangeContractFreeformDTO.NormalChangeDataItem();
		designFee.setArticle(changeKeyConfig.getArticle());
		designFee.setParagraph(changeKeyConfig.getParagraph());
		designFee.setKey(ChangeKeyEnum.AFTER_DISCOUNT_DESIGNER_AMOUNT.getKey());

		//设计费应收
		BigDecimal afterDiscountDesignerAmount = new BigDecimal(changeMap.getOrDefault("afterDiscountDesignerAmount", "0"));
		//获取设计费实收应收
		FundInfo designFundInfo = fundInfoService.getFundByOrderIdAndFundType(projectOrderId, FundTypeEnum.DESIGN_CHARGE.getValue());
		if (ObjectUtil.isNotEmpty(designFundInfo)) {
			//设计费待收和待退金额计算
			BigDecimal tobePaidAmount = afterDiscountDesignerAmount.subtract(designFundInfo.getPaidAmount());
			designFee.setDesignPaidAmount(designFundInfo.getPaidAmount().setScale(2, RoundingMode.HALF_UP).toPlainString());
			if (tobePaidAmount.compareTo(BigDecimal.ZERO) <= 0) {
				designFee.setDesignTobePaidAmount(BigDecimal.ZERO.setScale(2, RoundingMode.HALF_UP).toPlainString());
				designFee.setDesignTobeRefundAmount(tobePaidAmount.abs().setScale(2, RoundingMode.HALF_UP).toPlainString());
			} else {
				designFee.setDesignTobePaidAmount(tobePaidAmount.setScale(2, RoundingMode.HALF_UP).toPlainString());
				designFee.setDesignTobeRefundAmount(BigDecimal.ZERO.setScale(2, RoundingMode.HALF_UP).toPlainString());
			}
		}
		designFee.setAfterDiscountDesignerAmount(afterDiscountDesignerAmount.setScale(2, RoundingMode.HALF_UP).toPlainString());

		// 拿最新变更合同的字段
		designFee.setDesignerLevelName(fieldMap.getOrDefault("designerLevelName", ""));
		BigDecimal preDiscountDesignerAmount = new BigDecimal(fieldMap.getOrDefault("preDiscountDesignerAmount", "0"));
		designFee.setPreDiscountDesignerAmount(preDiscountDesignerAmount.setScale(2, RoundingMode.HALF_UP).toPlainString());
		changeData.add(designFee);
	}
	changeContent.setChangeData(changeData);

	return NormalChangeContractFreeformDTO.builder()
		.projectOrderId(projectOrderId)
		.currentContractNo(contract.getContractNo())
		.contractNo(formalContract.getContractNo())
		.jiafangXingming(getJiaFangName(contract))
		.companyName(companyInfoDTO.getCompanyName())
		.signDate(signDate)
		.dynamicChangeContent(JsonUtil.toJsonString(changeContent))
		.designerName(designerName)
		.build();
}

private String getJiaFangName(Contract contract) {
	if (contract == null ) {
		throw new NrsBusinessException("合同信息为空", Level.ERROR);
	}
	List<ContractField> contractFieldList = contractFieldService.getListByContractCode(contract.getContractCode());
	Map<String, String> fieldMap = Maps.newHashMap();
	contractFieldList.forEach(contractField -> fieldMap.put(contractField.getFieldKey(), contractField.getFieldValue()));
	Byte contractObjectType = fieldMap.get("contractObjectType") == null ? null : Byte.valueOf(fieldMap.get("contractObjectType"));
	if (contractObjectType == null) {
		throw new NrsBusinessException("合同字段没有主体类型" + contract.getContractCode(), Level.ERROR);
	}
	if (ContractObjectTypeEnum.PERSON.getCode().equals(contractObjectType)) {
		ContractUser owner = contractUserService.getUserByContractCodeAndType(contract.getContractCode(), UserTypeEnum.OWNER.getCode());
		return owner.getName();
	} else {
		String companyName = fieldMap.getOrDefault("companyName", "");
		if (StringUtils.isBlank(companyName)) {
			throw new NrsBusinessException("对公合同没有公司名称" + contract.getContractCode(), Level.ERROR);
		}
		return companyName;
	}
}

