	/**
	 * 正签场景：检查报价单是否关联了除当前合同及关联合同以外的有效合同
	 */
	public boolean hasBoundOtherPositiveContractInFormal(BindOrderInfoGroup group, String contractCode) {
		// 要绑定的【单据+主体】列表
		List<String> toBindOrderNosWithCompany = group.getBindOrderInfos().stream().flatMap(bindOrderInfo -> bindOrderInfo.getBindOrderNosWithCompany().stream()).collect(Collectors.toList());

		// 当前合同关联的【单据+主体】
		List<String> currentContractBindCodesWithCompany = getCurrentContractRelatedBindCodes(contractCode);

		// 过滤掉当前合同以及关联的销售合同所绑定的【单据+主体】列表
		toBindOrderNosWithCompany = toBindOrderNosWithCompany.stream()
			.filter(item -> !currentContractBindCodesWithCompany.contains(item))
			.collect(Collectors.toList());

		// 判断[单据号+主体]是否绑定了当前合同以外的其他合同
		if (hasBoundContracts(toBindOrderNosWithCompany)) {
			return true;
		}
		return false;
	}

	/**
	 * 销售合同场景：检查报价单是否关联了除当前合同及关联合同以外的有效合同
	 */
	public boolean hasBoundOtherPositiveContractInPersonal(BindOrderInfoGroup group, String contractCode) {
		// 如果单据号是空，则返回 true
		if (CollectionUtil.isEmpty(group.getBindOrderInfos())) {
			return false;
		}
		// 要绑定的【单据+主体】列表
		List<String> toBindOrderNosWithCompany = group.getBindOrderInfos().stream().flatMap(bindOrderInfo -> bindOrderInfo.getBindOrderNosWithCompany().stream()).collect(Collectors.toList());

		// 当前合同关联的【单据+主体】
		List<String> currentContractBindCodesWithCompany = getCurrentContractRelatedBindCodes(contractCode);

		// 过滤掉当前合同以及关联的销售合同所绑定的【单据+主体】列表
		toBindOrderNosWithCompany = toBindOrderNosWithCompany.stream()
			.filter(item -> !currentContractBindCodesWithCompany.contains(item))
			.collect(Collectors.toList());

		// 兼容多个销售合同发起场景：该场景下，发起合同时，合同号只有一个，但是单据传入了多个合同的单据，此时只过滤出来当前合同对应主体的单据，判断是否绑定了其他合同
		if (StringUtils.isNotBlank(contractCode)) {
			Contract contract = contractService.getByContractCode(contractCode);
			toBindOrderNosWithCompany = toBindOrderNosWithCompany.stream()
				.filter(item -> ObjectUtil.equal(contract.getCompanyCode(), item.split("_")[1]))
				.collect(Collectors.toList());
		}

		// 判断[单据号+主体]是否绑定了当前合同以外的其他合同
		if (hasBoundContracts(toBindOrderNosWithCompany)) {
			return true;
		}
		return false;
	}

	/**
	 * 判断单据号+主体是否绑定了状态有效的合同
	 */
	private boolean hasBoundContracts(List<String> toBindOrderNosWithCompany) {
		if (CollectionUtil.isEmpty(toBindOrderNosWithCompany)) {
			return false;
		}

		// 1. 提取所有单据号（去重）
		List<String> bindCodes = toBindOrderNosWithCompany.stream()
			.map(item -> item.split("_")[0])
			.distinct()
			.collect(Collectors.toList());

		// 2. 一次批量查询所有关联关系
		List<ContractQuotationRelation> allRelations = contractQuotationRelationService
			.getByBillCodesAndStatus(bindCodes, RelationStatusEnum.RELATED.getCode(), null);

		if (CollectionUtil.isEmpty(allRelations)) {
			return false;
		}

		// 3. 在内存中过滤出匹配 [单据+主体] 的关联关系
		Set<String> bindCodeWithCompanySet = new HashSet<>(toBindOrderNosWithCompany);
		List<String> matchedContractCodes = allRelations.stream()
			.filter(r -> bindCodeWithCompanySet.contains(r.getBillCode() + "_" + r.getCompanyCode()))
			.map(ContractQuotationRelation::getContractCode)
			.distinct()
			.collect(Collectors.toList());

		// 4. 一次批量查询合同状态
		if (CollectionUtil.isEmpty(matchedContractCodes)) {
			return false;
		}
		List<Contract> contracts = contractService.getListByContractCodes(matchedContractCodes, false);
		return contracts.stream().anyMatch(c -> ContractStatusEnum.inPositiveStatus.contains(c.getStatus()));
	}

	/**
	 * 获取当前合同关联的销售合同绑定的单据列表
	 */
	private List<String> getCurrentContractRelatedBindCodes(String mainContractCode) {
		List<String> res = new ArrayList<>();
		if (StringUtils.isBlank(mainContractCode)) {
			return Collections.emptyList();
		}

		List<String> relateContractCodes = new ArrayList<>();
		relateContractCodes.add(mainContractCode);
		List<ContractRelation> relations = contractRelationService.getRelationList(mainContractCode);
		if (CollectionUtil.isNotEmpty(relations)) {
			relateContractCodes.addAll(relations.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList()));
		}
		List<Contract> relatePersonalContracts = contractService.getListByContractCodes(relateContractCodes, false).stream()
			.filter(contract -> ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))
			.filter(contract -> ContractStatusEnum.inPositiveStatus.contains(contract.getStatus()))
			.collect(Collectors.toList());
		for (Contract personalContract : relatePersonalContracts) {
			//查询合同关联的报价单
			BindOrderInfoGroup group = getBindOrderInfoGroupByContractCode(personalContract.getContractCode());
			List<String> bindOrderNosWithCompany = group.getBindOrderInfos().stream()
				.flatMap(bindOrderInfo -> bindOrderInfo.getBindOrderNosWithCompany().stream())
				.collect(Collectors.toList());
			res.addAll(bindOrderNosWithCompany);
		}
		return res;
	}

}

public void bindCodeRelationWithClear(Contract contract, BindOrderInfoGroup group) {
	// 不存在需要绑定的单据，则返回
	if (CollectionUtil.isEmpty(group.getBindOrderInfos()) || (!ContractTypeEnum.ADVANCE.getCode().equals(contract.getType()) && !ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()))) {
		return;
	}

	lockService.lockElseThrow(LockService.CONTRACT_BIND_BILL_CODE + contract.getContractCode(), () -> {
		// 事务处理
		transactionTemplate.execute(status -> {
			// 清除合同下的所有关联关系
			contractQuotationRelationService.deleteRelationsByContractCode(contract.getContractCode());
			for (BindOrderInfo bindOrderInfo : group.getBindOrderInfos()) {
				// 绑定新的关联关系
				bindCodeRelation(contract.getContractCode(), contract.getCompanyCode(), bindOrderInfo.getBindOrderNoList(), bindOrderInfo.getBindType());
			}
			return null;
		});
		return null;
	});

}

public void bindCodeRelation(String contractCode, String companyCode, List<String> bindOrderNos, Integer bindType) {
	LOGGER.info("合同关联关系绑定, contractCode: {}, companyCode: {}, bindOrderNos: {}, bindType: {}", contractCode, companyCode, JSON.toJSONString(bindOrderNos), bindType);
	lockService.lockElseThrow(LockService.CONTRACT_BIND_BILL_CODE + contractCode, () -> {
		List<String> toBindOrderNosTmp = new ArrayList<>(bindOrderNos);

		// 查询合同关联的单据
		List<ContractQuotationRelation> relations = contractQuotationRelationService.getByContractCode(contractCode, RelationStatusEnum.RELATED.getCode(), bindType);
		if (CollectionUtil.isNotEmpty(relations)) {
			for (ContractQuotationRelation relation : relations) {
				// 已经绑定过，本次不需要重复绑定
				toBindOrderNosTmp.remove(relation.getBillCode());
			}
		}
		// 均绑定过则不需要再绑定
		if (CollectionUtil.isEmpty(toBindOrderNosTmp)) {
			return null;
		}
		List<ContractQuotationRelation> toBindRelations = new ArrayList<>();
		for (String bindCode : toBindOrderNosTmp) {
			ContractQuotationRelation relation = new ContractQuotationRelation();
			relation.setContractCode(contractCode);
			relation.setBillCode(bindCode);
			relation.setBindType(bindType);
			relation.setCompanyCode(companyCode);
			relation.setStatus(RelationStatusEnum.RELATED.getCode());
			relation.setDelStatus(CommonEnum.NO.getCode());
			relation.setCtime(new Date());
			relation.setMtime(new Date());
			toBindRelations.add(relation);
		}
		contractQuotationRelationService.insertBatch(toBindRelations);
		return null;
	});

}

