public Contract getContractByBindCodes(List<String> bindCodes, String companyCode, String changeOrderId) {
	if (CollectionUtil.isEmpty(bindCodes)) {
		return null;
	}
	List<ContractQuotationRelation> contractQuotationRelationList = contractQuotationRelationService.getByBindCodesAndStatus(bindCodes, RelationStatusEnum.RELATED.getCode());
	contractQuotationRelationList = contractQuotationRelationList.stream().filter(item -> ObjectUtil.equal(item.getCompanyCode(), companyCode)).collect(Collectors.toList());
	//获取关联的合同
	if (CollectionUtil.isEmpty(contractQuotationRelationList)) {
		return null;
	}
	//如果绑定了多份C合同，删除原有合同，重新创建
	List<String> contractCodes = contractQuotationRelationList.stream().map(ContractQuotationRelation::getContractCode).distinct().collect(Collectors.toList());
	List<Contract> contractList = contractService.getListByContractCodesAndStatus(contractCodes, ContractStatusEnum.inPositiveStatus);
	contractList = contractList.stream().filter(item -> ObjectUtil.equal(item.getChangeOrderId(), changeOrderId)).collect(Collectors.toList());
	if (CollectionUtil.isEmpty(contractList)){
		return null;
	}
	if (contractList.size() > 1) {
		for (Contract contract : contractList) {
			if (ContractTypeEnum.PERSONAL.getCode().equals(contract.getType()) && !ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus())) {
				//删除原有合同
				commonContractService.cancelCurrentContract(contract, HeaderContext.getUserId(), true);
			}
		}
		return null;
	} else {
		//如果合同已完结，不能重复创建
		if (StringUtils.isNotBlank(changeOrderId) && ContractStatusEnum.inEndStatus((contractList.get(0).getStatus()))) {
			throw new NrsBusinessException("报价单对应合同已签署完成，无需重复创建", Level.ERROR);
		}
		if (!ContractStatusEnum.DRAFT.getCode().equals(contractList.get(0).getStatus())) {
			throw new NrsBusinessException("单据对应合同已发起，无需重复创建");
		}
		return contractList.get(0);
	}
}

