public List<String> getBillCodeListByContractCode(String contractCode) {
	Contract contract = contractService.getByContractCode(contractCode);
	if (contract == null) {
		return new ArrayList<>();
	}
	//正签合同的关联的报价单列表从合同字段中获取
	if (ContractTypeEnum.PACKAGE_FORMAL.getCode().equals(contract.getType())) {
		ContractField billCodeInfoListField = contractFieldService.getByContractCodeAndKey(contractCode, "billCodeInfoList");
		ContractField billCodeListField = contractFieldService.getByContractCodeAndKey(contract.getContractCode(), "billCodeList");
		if (billCodeInfoListField != null && StringUtils.isNotBlank(billCodeInfoListField.getFieldValue())) {
			Gson gson = new Gson();
			Type listType = new TypeToken<List<BillCodeInfo>>() {
			}.getType();
			List<BillCodeInfo> billCodeInfoList = gson.fromJson(billCodeInfoListField.getFieldValue(), listType);
			return billCodeInfoList.stream().map(BillCodeInfo::getBillCode).filter(StringUtils::isNotBlank).distinct().collect(Collectors.toList());
		} else if (billCodeListField != null && StringUtils.isNotBlank(billCodeListField.getFieldValue())) {
			Gson gson = new Gson();
			Type listType = new TypeToken<List<String>>() {
			}.getType();
			return gson.fromJson(billCodeListField.getFieldValue(), listType);
		} else {
			return new ArrayList<>();
		}
	}
	List<ContractQuotationRelation> contractQuotationRelationList = contractQuotationRelationService.getByContractCode(contractCode, RelationStatusEnum.RELATED.getCode());
	if (CollectionUtil.isEmpty(contractQuotationRelationList)) {
		return null;
	}
	return contractQuotationRelationList.stream().map(ContractQuotationRelation::getBillCode).collect(Collectors.toList());
}

public BindOrderInfoGroup getBindOrderInfoGroupByContractCode(String contractCode) {
