			LOGGER.error("换绑 S 单后，重新触发 S 单的 pdf 生成, projectOrderId: {}, oldBindOrders: {}, newBindOrders: {}", contract.getProjectOrderId(), cooperBillCode, toBindSubOrderNos);
		}
	}));
