public void bindSubOrderNos(String contractCode, String companyCode, String cooperBillCode, List<String> toBindSubOrderNos) {
	if (CollectionUtil.isEmpty(toBindSubOrderNos)) {
		return;
	}
	LOGGER.info("协同报价单换绑至 S 单, cooperBillCode: {}, toBindSubOrderNos: {}", JSON.toJSONString(cooperBillCode), JSON.toJSONString(toBindSubOrderNos));
	// 外层用锁包上事务
	lockService.lockElseThrow(LockService.CONTRACT_BIND_BILL_CODE + contractCode, () -> {
		transactionTemplate.execute(status -> {
			// 记录换绑日志：协同报价单 -> S 单
			contractBindLogService.recordBindChangeLog(
				contractCode,
				"协同报价单换绑S单",
				cooperBillCode,
				toBindSubOrderNos
			);
			// 解除与协同报价单的关联
			contractQuotationRelationService.cancelRelationsByBillCodes(contractCode, Collections.singletonList(cooperBillCode));
			// 绑定子单
			quotationRelationCommonServiceSelf.bindCodeRelation(contractCode, companyCode, toBindSubOrderNos, BindTypeEnum.SUB_ORDER.getCode());
			return null;
		});
		return null;
	});
}

