	 */
	public Map<String, Object> getTerminalRelationHouseFormalInfo() {
		Map<String, Object> result = new HashMap<>();
		String houseFormalCompanyName = "/";
		String houseFormalContractName = "/";
		result.put("houseFormalCompanyName", houseFormalCompanyName);
		result.put("houseFormalContractName", houseFormalContractName);
		// 非合并发起的解约协议
		if (!ContractContextHandler.getContext().isMergeLaunch()) {
			return result;
		}
		//所有合并发起的合同
