@Service
@Slf4j
public class ChangeOrderSigningSourceStrategy extends AbstractContractSigningSource {

	@Resource
	private OrderStandardQueryRpc orderStandardQueryRpc;

	@Resource
	private AtomBudgetRpc atomBudgetRpc;

	@Resource
	private ProductQueryService productQueryService;

	@Override
	public Integer bindType() {
		return BindTypeEnum.CHANGE_ORDER.getCode();
	}

	@Override
	public boolean hasInvalidStatusOrders(BindOrderInfo bindOrderInfo) {
		// 参考 com.ke.utopia.nrs.salesproject.service.contract.v2.personal.FormalMultipleCompanyService.getNotSupportSignBillCodeList
		// 变更单状态不是[待签约]/[已完成]，则不允许签约
		ChangeApplyDetailsDTO changeApplyDetails = atomBudgetRpc.getChangeApplyDetails(bindOrderInfo.getChangeOrderId());

		List<Integer> signableChangeOrderStatus = Arrays.asList(ChangeBusinessStatusEnum.WAIT_SIGN.getCode(), ChangeBusinessStatusEnum.FINISHED.getCode());

		if (!signableChangeOrderStatus.contains(changeApplyDetails.getChangeApplyStatus())) {
			LOGGER.info("变更流程状态不允许签约 changeOrderId:{},changeApplyStatus:{}", bindOrderInfo.getChangeOrderId(), changeApplyDetails.getChangeApplyStatus());
			return true;  // 有无效状态
		}
		return false;  // 没有无效状态
	}

	@Override
	public Map<String, String> buildGoodsInfo(BindOrderInfo bindOrderInfo) {
		/**
		 * 构建变更单的 goodsInfo
		 * billCode -> goodsInfo
		 */
		String projectOrderId = bindOrderInfo.getProjectOrderId();
		Map<String, String> result = new HashMap<>();

		Set<SkuProductDTO> skuProducts = getSkuProductsByChangeOrderId(projectOrderId, bindOrderInfo.getChangeOrderId());

		// 遍历商品，将内控类目合并生成 goodsInfo合并后统一提取类目名
		Set<String> categoryNames = skuProducts.stream()
			.map(SkuProductDTO::getSkuCategoryName)
			.collect(Collectors.toSet());
		result.put(bindOrderInfo.getChangeOrderId(), mergeCategoryNames(categoryNames));
		return result;
	}

	@Override
	public List<SignableOrderInfo> buildSignableOrderInfos(String projectOrderId) {
		return Collections.emptyList();
	}

	@Override
	public boolean checkPersonalCanCreate(String projectOrderId) {
		return false;
	}

	@Override
	public boolean hasCPart(BindOrderInfo bindOrderInfo) {
		List<ChangeQuotationProductDTO> changeQuotationProductDTOS = productQueryService.getChangeQuotationProductDTOS(bindOrderInfo.getProjectOrderId(), bindOrderInfo.getChangeOrderId());
		if (CollectionUtils.isEmpty(changeQuotationProductDTOS)) {
			return false;
		}
		return changeQuotationProductDTOS.stream()
			.anyMatch(p -> isCPart(p.getPurchaseType()));
	}

	@Override
	public boolean hasBPart(BindOrderInfo bindOrderInfo) {
		List<ChangeQuotationProductDTO> changeQuotationProductDTOS = productQueryService.getChangeQuotationProductDTOS(bindOrderInfo.getProjectOrderId(), bindOrderInfo.getChangeOrderId());
		if (CollectionUtils.isEmpty(changeQuotationProductDTOS)) {
			return false;
		}
		return changeQuotationProductDTOS.stream().anyMatch(p -> isBPart(p.getPurchaseType()));
	}


	@Override
	protected DrawingParams.DrawingQuery buildDrawingQuery(String projectOrderId, String changeOrderId, List<String> productItemCodes, Boolean softConfigList, Boolean needMergePdf) {
		return DrawingParams.DrawingQuery.builder()
			.projectOrderId(projectOrderId)
			.projectChangeNo(changeOrderId)
			.softConfigList(softConfigList)
			.needMergePdf(needMergePdf)
			.productItemCodes(productItemCodes)
			.drawingStatus(DrawingServiceEnum.DrawingAggregationEnum.TEMP.getCode()).build();
	}

	@Override
	protected List<String> buildProductItemCodes(BindOrderInfo bindOrderInfo) {
		Set<SkuProductDTO> skuProducts = getSkuProductsByChangeOrderId(bindOrderInfo.getProjectOrderId(), bindOrderInfo.getChangeOrderId());
		return skuProducts.stream().map(SkuProductDTO::getProductItemCode).collect(Collectors.toList());
	}

	@Override
	public PersonalContractDataParam buildParam(BindOrderInfo bindOrderInfo) {
		return PersonalContractDataParam.builder()
			.projectOrderId(bindOrderInfo.getProjectOrderId())
			.changeOrderId(bindOrderInfo.getChangeOrderId())
			.build();
	}

	@Override
	protected List<ContractSourceDataBO.PersonalContractData> filterByCompanyCode(BindOrderInfo bindOrderInfo, List<ContractSourceDataBO.PersonalContractData> personalContractDataList) {
		Set<String> targetCodeWithCompany = bindOrderInfo.getBindOrderNosWithCompany();
		return personalContractDataList.stream()
			.filter(item -> targetCodeWithCompany.contains(item.getChangeOrderId() + "_" + item.getOrganizationCode()))
			.collect(Collectors.toList());
	}

	/**
	 * 根据变更单号获取报价商品 sku 集合
	 */
