public Map<String, Object> getJiaFangYiFangSealKeyword(Long fromId) {
	List<SealNewRuleParam> sealNewRule = freeformService.queryNewSealConfigs(fromId);
	String jiaFangSealKeyword = "";
	String jiaFangAgentSealKeyword = "";
	String yiFangSealKeyword = "";
	try {
		jiaFangSealKeyword = getJiaFangSealKeyword(sealNewRule, fromId);
	} catch (Exception e) {
		LOGGER.error("获取甲方签章关键字失败，formId：{},签章规则：{}", fromId, JSON.toJSONString(sealNewRule));
	}
	try {
		jiaFangAgentSealKeyword = getJiaFangAgentSealKeyword(sealNewRule, fromId);
	} catch (Exception e) {
		LOGGER.info("获取甲方代理人签章关键字失败，formId：{},签章规则：{}", fromId, JSON.toJSONString(sealNewRule));
	}
	try {
		yiFangSealKeyword = getYiFangSealKeyword(sealNewRule, fromId);
	} catch (Exception e) {
		LOGGER.info("获取乙方签章关键字失败，formId：{},签章规则：{}", fromId, JSON.toJSONString(sealNewRule));
	}

	Map<String, Object> map = new HashMap<>();
	map.put("jiaFangSealKeyword", jiaFangSealKeyword);
	map.put("jiaFangAgentSealKeyword", jiaFangAgentSealKeyword);
	map.put("yiFangSealKeyword", yiFangSealKeyword);
	return map;
}

private String resolveCustomAttachPdfUrl(Byte contractType, ContractCustomAttachConfig attachConfig){
	if(Objects.equals(ContractTypeEnum.ADVANCE.getCode(), contractType)){
		return attachConfig.getAdvancePdfUrl();
	}
	if(Objects.equals(ContractTypeEnum.PACKAGE_FORMAL.getCode(), contractType)){
		return attachConfig.getPackageFormalPdfUrl();
	}
	if(Objects.equals(ContractTypeEnum.PERSONAL.getCode(), contractType)){
		return attachConfig.getPersonalPdfUrl();
	}
	return "";
}

public String getCustomAttach(Contract contract) throws IOException {

	// 如果合同既不是首期款合同，也不是正签合同，也不是销售合同，就直接返回
	if(!CUSTOM_ATTACH_TYPES.contains(contract.getType())){
		return "";
	}

	Byte contractFormType = ContractFormTypeEnum.getCodeByDeveloperChannel(ContractContextHandler.getContext().getDeveloperChannel());

	ContractCustomAttachConfig queryParam = ContractCustomAttachConfig.builder()
		.gbCode(contract.getGbCode())
		.companyCode(contract.getCompanyCode())
		.businessType(contract.getBusinessType())
		.contractFormType(contractFormType)
		.build();

	List<ContractCustomAttachConfig> contractCustomAttachConfigList = contractCustomAttachConfigService.getContractCustomAttachWithDefault(queryParam);

	if (CollectionUtils.isEmpty(contractCustomAttachConfigList)) {
		return "";
	}

	if (contractCustomAttachConfigList.size() > 1) {
		LOGGER.error("获取个性化附件配置数量不唯一，gbCode:{},companyCode:{},businessType:{},contractFormType:{}",
			contract.getGbCode(), contract.getCompanyCode(), contract.getBusinessType(), contractFormType);
	}

	ContractCustomAttachConfig attachConfig = contractCustomAttachConfigList.get(0);
	String pdfUrl = resolveCustomAttachPdfUrl(contract.getType(), attachConfig);

	LOGGER.info("获取个性化附件配置，projectOrderId:{},gbCode:{},companyCode:{},businessType:{},contractFormType:{},个性化附件pdfUrl:{}",
		contract.getProjectOrderId(), contract.getGbCode(), contract.getCompanyCode(), contract.getBusinessType(), contractFormType, pdfUrl);

	if (StringUtils.isBlank(pdfUrl)) {
		return "";
	}

	// 文件大小 单位MB
	BigDecimal pdfSizeMB = IOUtils.getFileSizeMByFilePath(pdfUrl);
	if (pdfSizeMB.compareTo(BigDecimal.valueOf(contractApolloConfig.getFormalLaunchConfig().getCompressSize())) > 0) {
		// 压缩后的文件路径
		String tempPathAfterCompress = UUID.randomUUID() + ".pdf";
		try {
			LOGGER.info("contractCode:{},个性化附件pdf文件大小大于5MB，开始进行压缩处理", contract.getContractCode());
			contractPdfFileHandleService.compressPDF(pdfUrl, tempPathAfterCompress, 120);
			LOGGER.info("contractCode:{},个性化附件pdf文件大小大于5MB，压缩处理完成", contract.getContractCode());
			// 记录个性化附件说 pdf 文件大小(压缩前/压缩后)
			contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.CONTRACT_CUSTOM_ATTACH.getCode(), IOUtils.getFileSizeKBByFilePath(pdfUrl), IOUtils.getFileSizeKBByFilePath(tempPathAfterCompress));
			return tempPathAfterCompress;
		} finally {
			// 删除临时文件
			ContractPdfFileHandleService.cleanUp(Collections.singletonList(pdfUrl));
		}
	}
	return pdfUrl;

}

