@Component
@Slf4j
public class DrawingContractPdfBySelfStrategy implements CreateContractPdfBySelfStrategy {

	@Resource
	private ContractBusinessService contractBusinessService;

	@Resource
	private ContractPdfFileHandleService contractPdfFileHandleService;

	@Resource
	private S3Service s3Service;

	@Resource
	private FreeformService freeformService;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Resource
	private DrawingCompressionConfig drawingCompressionConfig;

	@Resource
	private ContractFileInfoService contractFileInfoService;

	@Resource
	private BaseContractPdfCreateService baseContractPdfCreateService;

	@Resource(name = "pdfHandleExecutor")
	private Executor pdfExecutor;


	@Override
	public String createPdf(Contract contract, ContractCityCompanyInfo config, boolean finalVersion) throws Exception {
		StopWatch stopWatch = new StopWatch();
		stopWatch.start();//计时开始
		//图纸合同机器pdf路径
		String drawingLocalContractPdf = "drawingContract_" + UUID.randomUUID() + ".pdf";
		//图纸合同s3 pdf路径
		String drawingS3PdfUrl = "";
		//临时文件目录记录，删除时使用
		List<String> tempFiles = new ArrayList<>();
		List<String> pdfUrls = getDrawingPdfUrlList();
		float jiaFangPositionXRatio = contractApolloConfig.getDrawingLaunchConfig().getPositionXRatio();
		float jiaFangPositionYRatio = contractApolloConfig.getDrawingLaunchConfig().getPositionYRatio();
		float jiaFangAgentPositionXRatio = contractApolloConfig.getDrawingLaunchConfig().getJiaFangAgentPositionXRatio();
		float jiaFangAgentPositionYRatio = contractApolloConfig.getDrawingLaunchConfig().getJiaFangAgentPositionYRatio();

		double spaceSizeMB = (double) IOUtils.calculateTotalFileSizeByUrl(pdfUrls) / 1024;
		List<SealNewRuleParam> sealNewRule = freeformService.queryNewSealConfigs(contractApolloConfig.getDrawingLaunchConfig().getFormId());
		String jiaFangSealKeyword = baseContractPdfCreateService.getJiaFangSealKeyword(sealNewRule, contractApolloConfig.getDrawingLaunchConfig().getFormId());
		String jiaFangAgentSealKeyword = baseContractPdfCreateService.getJiaFangAgentSealKeyword(sealNewRule, contractApolloConfig.getDrawingLaunchConfig().getFormId());

		List<AddFooterTextInfo> addFooterTextInfoList = new ArrayList<>();
		addFooterTextInfoList.add(AddFooterTextInfo.builder()
			.text(jiaFangSealKeyword)
			.positionXRatio(jiaFangPositionXRatio)
			.positionYRatio(jiaFangPositionYRatio)
			.build());
		if (StringUtils.isNotBlank(jiaFangAgentSealKeyword)) {
			addFooterTextInfoList.add(AddFooterTextInfo.builder()
				.text(jiaFangAgentSealKeyword)
				.positionXRatio(jiaFangAgentPositionXRatio)
				.positionYRatio(jiaFangAgentPositionYRatio)
				.build());
		}
		LOGGER.info("原始图纸pdf文件总大小：{}M，projectOrderId:{}", spaceSizeMB, contract.getProjectOrderId());
		//校验图纸pdf尺寸
		checkDrawingPdfAreaSize(pdfUrls);
		try {
			if (spaceSizeMB < contractApolloConfig.getDrawingLaunchConfig().getDrawingCompressSize()) {
				LOGGER.info("图纸pdf文件总大小小于设定阈值，文件总大小：{}M，阈值：{}M", spaceSizeMB, contractApolloConfig.getDrawingLaunchConfig().getDrawingCompressSize());
				//小于配置阈值进行盖章关键字加入签名-》合并
				List<String> modifiedPdfs = contractPdfFileHandleService.addFooterForListInput(pdfUrls, addFooterTextInfoList);
				tempFiles.addAll(modifiedPdfs);
				tempFiles.add(drawingLocalContractPdf);
				// 输出最终合并文件
				ContractPdfFileHandleService.mergePdfs(modifiedPdfs, drawingLocalContractPdf);
				contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.DRAWING_CONTRACT.getCode(), IOUtils.getFileSizeKBByFilePath(drawingLocalContractPdf), null);
			} else {
				LOGGER.info("图纸pdf文件总大小大于等于设定阈值，文件总大小：{}M，阈值：{}M", spaceSizeMB, contractApolloConfig.getDrawingLaunchConfig().getDrawingCompressSize());
				checkBeforeCompressPdf(pdfUrls, spaceSizeMB);
				//动态获取对应的dpi
				int dpi = drawingCompressionConfig.getDpi(pdfUrls.size(), spaceSizeMB);
				List<String> compressPdfs = contractPdfFileHandleService.batchCompressPdf(pdfUrls, dpi);
				List<String> modifiedPdfs = contractPdfFileHandleService.addFooterForListInput(compressPdfs, addFooterTextInfoList);
				tempFiles.addAll(compressPdfs);
				tempFiles.addAll(modifiedPdfs);
				tempFiles.add(drawingLocalContractPdf);
				ContractPdfFileHandleService.mergePdfs(modifiedPdfs, drawingLocalContractPdf);
				contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.DRAWING_CONTRACT.getCode(), new BigDecimal(String.valueOf(spaceSizeMB)).multiply(new BigDecimal(1024)).setScale(2, RoundingMode.HALF_UP),
					IOUtils.getFileSizeKBByFilePath(drawingLocalContractPdf));
				checkAfterCompressPdf(drawingLocalContractPdf, pdfUrls, spaceSizeMB);
			}
			File file = new File(drawingLocalContractPdf);
			String fileObjectKey = s3Service.md5FileName(file.getName()) + ".pdf";
			//pdf文件上传到s3
			s3Service.uploadByFile(file, fileObjectKey, false);
			drawingS3PdfUrl = s3Service.generateUrl(fileObjectKey, 604800);
			//pdf文件上传到协议平台，与协议平台实例关联
			Long instanceId = contractBusinessService.uploadPdfToFreeForm(contract, drawingS3PdfUrl, contractApolloConfig.getDrawingLaunchConfig().getFormKey());

			contract.setPreviewKey(fileObjectKey);
			contract.setPdfPageCount(ContractPdfFileHandleService.getPdfCount(drawingLocalContractPdf));
			contract.setPlatformInstanceId(instanceId);
		} finally {
			// 删除临时文件
			ContractPdfFileHandleService.cleanUp(tempFiles);
		}
		stopWatch.stop(); // 停止计时
		LOGGER.info("合同pdf生成-生成图纸合同pdf耗时：{}s", stopWatch.getTotalTimeSeconds());
		return drawingS3PdfUrl;
	}

	/**
	 * 压缩前校验，图纸pdf文件数量和占用空间大小如果超出最大给定的范围限制，则抛出异常
	 */
	private void checkBeforeCompressPdf(List<String> pdfUrls, double spaceSizeMB) {
		String errorMessage = String.format("当前项目图纸合同共%s页%sM，线上签约图纸清晰度低，无法保障客户体验，请联系设计ssc调整图纸张数或大小，或线下签署后补录至系统", pdfUrls.size(), String.format("%.2f", spaceSizeMB));
		if (pdfUrls.size() > contractApolloConfig.getDrawingLaunchConfig().getDrawingCountLimit()) {
			LOGGER.error("图纸pdf文件数量超过限制，文件数量：{}，阈值：{}", pdfUrls.size(), contractApolloConfig.getDrawingLaunchConfig().getDrawingCountLimit());
			throw new NrsBusinessException(ResponseCodeEnum.DRAWING_LIMIT_ERROR.getCode(), errorMessage, Level.WARN);
		}
		if (spaceSizeMB > contractApolloConfig.getDrawingLaunchConfig().getDrawingSpaceSizeLimit()) {
			LOGGER.error("图纸pdf图纸占用空间大小超过限制，图纸大小：{}，阈值：{}", spaceSizeMB, contractApolloConfig.getDrawingLaunchConfig().getDrawingSpaceSizeLimit());
			throw new NrsBusinessException(ResponseCodeEnum.DRAWING_LIMIT_ERROR.getCode(), errorMessage, Level.WARN);
		}
	}

	/**
	 * 检查压缩后pdf文件大小是否超过协议平台能支持的大小限制，超过则抛出异常
	 */
	private void checkAfterCompressPdf(String compressAfterLocalPdfUrl, List<String> pdfUrls, double spaceSizeMB) {
		String errorMessage = String.format("当前项目图纸合同共%s页%sM，线上签约图纸清晰度低，无法保障客户体验，请联系设计ssc调整图纸张数或大小，或线下签署后补录至系统", pdfUrls.size(), String.format("%.2f", spaceSizeMB));
		File file = new File(compressAfterLocalPdfUrl);
		//文件大小 单位MB
		float spaceSizeMBAfterCompress = (float) file.length() / 1024 / 1024;
		LOGGER.info("图纸pdf压缩后文件大小为：{}M, 原始大小为：{}M", String.format("%.2f", spaceSizeMBAfterCompress), String.format("%.2f", spaceSizeMB));
		if (spaceSizeMBAfterCompress > contractApolloConfig.getDrawingLaunchConfig().getDrawingCompressSize()) {
			LOGGER.error("图纸pdf压缩后文件大小超过限制，压缩后文件大小：{}M，阈值：{}M", spaceSizeMBAfterCompress, contractApolloConfig.getDrawingLaunchConfig().getDrawingCompressSize());
			throw new NrsBusinessException(ResponseCodeEnum.DRAWING_LIMIT_ERROR.getCode(), errorMessage, Level.WARN);
		}
	}

	/**
	 * 获取合同用户签章关键字
	 */
	private String getSealKeyword(Long formId) {
		List<SealNewRuleParam> sealNewRuleParams = freeformService.queryNewSealConfigs(formId);
		//签章关键字获取，由于个人签约&对公签约的关键字一样，这里取个人签约配置的关键字
		SealNewRuleParam sealNewRuleParam = sealNewRuleParams.stream().filter(item -> FreeFormRoleTypeEnum.SIGN_USER.getCode().equals(item.getRoleType()))
			.filter(item -> FreeFormSignTypeEnum.PERSON.getCode().equals(item.getSignType())).findFirst().orElse(null);
		if (sealNewRuleParam == null || CollectionUtils.isEmpty(sealNewRuleParam.getRuleList())) {
			LOGGER.error("合同生成pdf，获取签章关键字失败，formId：{},签章规则：{}", formId, JSON.toJSONString(sealNewRuleParam));
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "合同生成pdf，获取签章关键字失败", Level.WARN);
		}
		return sealNewRuleParam.getRuleList().get(0).getKeyword();
	}

	private List<String> getDrawingPdfUrlList() {
		DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = ContractContextHandler.getDrawingDTO();
		if (deliverDrawingDTO == null || CollectionUtils.isEmpty(deliverDrawingDTO.getDrawingDetailDTOList())) {
			return Collections.emptyList();
		}
		return deliverDrawingDTO.getDrawingDetailDTOList().stream()
			.filter(item -> ObjectUtil.equals(item.getBillType(), PlanAttachment.基础图纸))
			.filter(item -> DrawingEnum.ConstructionFileExtensionEnum.PDF.getCode().equals(item.getExtensionType()))
			.map(DrawingDTO.DrawingDetailDTO::getUrl)
			.collect(Collectors.toList());
	}

	/**
	 * 校验图纸pdf文件尺寸大小
	 */
	public void checkDrawingPdfAreaSize(List<String> pdfUrls) {
		if (CollectionUtils.isEmpty(pdfUrls)) {
			return;
		}
		if (!contractApolloConfig.getDrawingLaunchConfig().isCheckPdfAreaSize()) {
			LOGGER.info("校验图纸pdf文件尺寸大小开关关闭中，不进行校验");
			return;
		}
		List<PdfPageInfo> pdfPageInfo = getPdfPageInfo(pdfUrls);
		PdfPageInfo maxPdfAreaInfo = null;
		float maxArea = 0;
		for (PdfPageInfo pageInfo : pdfPageInfo) {
			float area = pageInfo.getWidth() * pageInfo.getHeight();
			if (area > maxArea) {
				maxArea = area;
				maxPdfAreaInfo = pageInfo;
			}
		}
		if (maxArea > contractApolloConfig.getDrawingLaunchConfig().getPdfMaxArea()) {
			LOGGER.error("校验图纸pdf文件尺寸大小超过限制，maxArea：{}，阈值：{},maxPdfAreaInfo:{}", maxArea, contractApolloConfig.getDrawingLaunchConfig().getPdfMaxArea(), maxPdfAreaInfo);
			throw new NrsBusinessException(ResponseCodeEnum.DRAWING_LIMIT_ERROR.getCode(), "当前图纸PDF宽高过大，请调整至【3370×2384】以内再发起签约", Level.WARN);
		}
	}

	public List<PdfPageInfo> getPdfPageInfo(List<String> pdfUrls) {
		List<PdfPageInfo> pdfPageInfo = Collections.synchronizedList(new ArrayList<>());
		LOGGER.info("获取图纸pdf文件尺寸大小start");
		long start = System.currentTimeMillis();
		List<CompletableFuture<Void>> futureList = new ArrayList<>();
		for (String url : pdfUrls) {
			final String finalUrl = url;
			CompletableFuture<Void> future = CompletableFuture.runAsync(RunnableWrapper.of(() -> {
				try (InputStream inputStream = new URL(finalUrl).openStream();
					 PDDocument document = PDDocument.load(inputStream)) {
					int numberOfPages = document.getNumberOfPages();
					for (int i = 0; i < numberOfPages; i++) {
						PDPage page = document.getPage(i);
						float width = page.getMediaBox().getWidth();
						float height = page.getMediaBox().getHeight();
						pdfPageInfo.add(new PdfPageInfo(url, i, width, height));
					}
				} catch (Exception e) {
					throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "校验图纸pdf文件尺寸大小失败，原因：{}", e.getCause());
				}
			}), pdfExecutor);
			futureList.add(future);
		}
		CompletableFuture<Void> allOf = CompletableFuture.allOf(
			futureList.toArray(new CompletableFuture[0]));
		//等待所有线程执行完毕
		try {
			allOf.get(15, TimeUnit.SECONDS); // 添加超时检查
		} catch (TimeoutException e) {
			LOGGER.info("校验图纸pdf文件尺寸大小超时");
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "校验图纸pdf文件尺寸大小超时");
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
		} catch (Exception e) {
			Throwable cause = e.getCause();
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, cause == null ? e.getMessage() : cause.getMessage());
		}
		LOGGER.info("获取图纸pdf文件尺寸大小end,耗时:{}", System.currentTimeMillis() - start);
		return pdfPageInfo;
	}


}

@Override
public String createPdf(Contract contract, ContractCityCompanyInfo config, boolean finalVersion) throws Exception {
	StopWatch stopWatch = new StopWatch();
	stopWatch.start();//计时开始
	//图纸合同机器pdf路径
	String drawingLocalContractPdf = "drawingContract_" + UUID.randomUUID() + ".pdf";
	//图纸合同s3 pdf路径
	String drawingS3PdfUrl = "";
	//临时文件目录记录，删除时使用
	List<String> tempFiles = new ArrayList<>();
	List<String> pdfUrls = getDrawingPdfUrlList();
	float jiaFangPositionXRatio = contractApolloConfig.getDrawingLaunchConfig().getPositionXRatio();
	float jiaFangPositionYRatio = contractApolloConfig.getDrawingLaunchConfig().getPositionYRatio();
	float jiaFangAgentPositionXRatio = contractApolloConfig.getDrawingLaunchConfig().getJiaFangAgentPositionXRatio();
	float jiaFangAgentPositionYRatio = contractApolloConfig.getDrawingLaunchConfig().getJiaFangAgentPositionYRatio();

	double spaceSizeMB = (double) IOUtils.calculateTotalFileSizeByUrl(pdfUrls) / 1024;
	List<SealNewRuleParam> sealNewRule = freeformService.queryNewSealConfigs(contractApolloConfig.getDrawingLaunchConfig().getFormId());
	String jiaFangSealKeyword = baseContractPdfCreateService.getJiaFangSealKeyword(sealNewRule, contractApolloConfig.getDrawingLaunchConfig().getFormId());
	String jiaFangAgentSealKeyword = baseContractPdfCreateService.getJiaFangAgentSealKeyword(sealNewRule, contractApolloConfig.getDrawingLaunchConfig().getFormId());

	List<AddFooterTextInfo> addFooterTextInfoList = new ArrayList<>();
	addFooterTextInfoList.add(AddFooterTextInfo.builder()
		.text(jiaFangSealKeyword)
		.positionXRatio(jiaFangPositionXRatio)
		.positionYRatio(jiaFangPositionYRatio)
		.build());
	if (StringUtils.isNotBlank(jiaFangAgentSealKeyword)) {
		addFooterTextInfoList.add(AddFooterTextInfo.builder()
			.text(jiaFangAgentSealKeyword)
			.positionXRatio(jiaFangAgentPositionXRatio)
			.positionYRatio(jiaFangAgentPositionYRatio)
			.build());
	}
	LOGGER.info("原始图纸pdf文件总大小：{}M，projectOrderId:{}", spaceSizeMB, contract.getProjectOrderId());
	//校验图纸pdf尺寸
	checkDrawingPdfAreaSize(pdfUrls);
	try {
		if (spaceSizeMB < contractApolloConfig.getDrawingLaunchConfig().getDrawingCompressSize()) {
			LOGGER.info("图纸pdf文件总大小小于设定阈值，文件总大小：{}M，阈值：{}M", spaceSizeMB, contractApolloConfig.getDrawingLaunchConfig().getDrawingCompressSize());
			//小于配置阈值进行盖章关键字加入签名-》合并
			List<String> modifiedPdfs = contractPdfFileHandleService.addFooterForListInput(pdfUrls, addFooterTextInfoList);
			tempFiles.addAll(modifiedPdfs);
			tempFiles.add(drawingLocalContractPdf);
			// 输出最终合并文件
			ContractPdfFileHandleService.mergePdfs(modifiedPdfs, drawingLocalContractPdf);
			contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.DRAWING_CONTRACT.getCode(), IOUtils.getFileSizeKBByFilePath(drawingLocalContractPdf), null);
		} else {
			LOGGER.info("图纸pdf文件总大小大于等于设定阈值，文件总大小：{}M，阈值：{}M", spaceSizeMB, contractApolloConfig.getDrawingLaunchConfig().getDrawingCompressSize());
			checkBeforeCompressPdf(pdfUrls, spaceSizeMB);
			//动态获取对应的dpi
			int dpi = drawingCompressionConfig.getDpi(pdfUrls.size(), spaceSizeMB);
			List<String> compressPdfs = contractPdfFileHandleService.batchCompressPdf(pdfUrls, dpi);
			List<String> modifiedPdfs = contractPdfFileHandleService.addFooterForListInput(compressPdfs, addFooterTextInfoList);
			tempFiles.addAll(compressPdfs);
			tempFiles.addAll(modifiedPdfs);
			tempFiles.add(drawingLocalContractPdf);
			ContractPdfFileHandleService.mergePdfs(modifiedPdfs, drawingLocalContractPdf);
			contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.DRAWING_CONTRACT.getCode(), new BigDecimal(String.valueOf(spaceSizeMB)).multiply(new BigDecimal(1024)).setScale(2, RoundingMode.HALF_UP),
				IOUtils.getFileSizeKBByFilePath(drawingLocalContractPdf));
			checkAfterCompressPdf(drawingLocalContractPdf, pdfUrls, spaceSizeMB);
		}
		File file = new File(drawingLocalContractPdf);
		String fileObjectKey = s3Service.md5FileName(file.getName()) + ".pdf";
		//pdf文件上传到s3
		s3Service.uploadByFile(file, fileObjectKey, false);
		drawingS3PdfUrl = s3Service.generateUrl(fileObjectKey, 604800);
		//pdf文件上传到协议平台，与协议平台实例关联
		Long instanceId = contractBusinessService.uploadPdfToFreeForm(contract, drawingS3PdfUrl, contractApolloConfig.getDrawingLaunchConfig().getFormKey());

		contract.setPreviewKey(fileObjectKey);
		contract.setPdfPageCount(ContractPdfFileHandleService.getPdfCount(drawingLocalContractPdf));
		contract.setPlatformInstanceId(instanceId);
	} finally {
		// 删除临时文件
		ContractPdfFileHandleService.cleanUp(tempFiles);
	}
	stopWatch.stop(); // 停止计时
	LOGGER.info("合同pdf生成-生成图纸合同pdf耗时：{}s", stopWatch.getTotalTimeSeconds());
	return drawingS3PdfUrl;
}

private void checkBeforeCompressPdf(List<String> pdfUrls, double spaceSizeMB) {
	String errorMessage = String.format("当前项目图纸合同共%s页%sM，线上签约图纸清晰度低，无法保障客户体验，请联系设计ssc调整图纸张数或大小，或线下签署后补录至系统", pdfUrls.size(), String.format("%.2f", spaceSizeMB));
	if (pdfUrls.size() > contractApolloConfig.getDrawingLaunchConfig().getDrawingCountLimit()) {
		LOGGER.error("图纸pdf文件数量超过限制，文件数量：{}，阈值：{}", pdfUrls.size(), contractApolloConfig.getDrawingLaunchConfig().getDrawingCountLimit());
		throw new NrsBusinessException(ResponseCodeEnum.DRAWING_LIMIT_ERROR.getCode(), errorMessage, Level.WARN);
	}
	if (spaceSizeMB > contractApolloConfig.getDrawingLaunchConfig().getDrawingSpaceSizeLimit()) {
		LOGGER.error("图纸pdf图纸占用空间大小超过限制，图纸大小：{}，阈值：{}", spaceSizeMB, contractApolloConfig.getDrawingLaunchConfig().getDrawingSpaceSizeLimit());
		throw new NrsBusinessException(ResponseCodeEnum.DRAWING_LIMIT_ERROR.getCode(), errorMessage, Level.WARN);
	}
}

private void checkAfterCompressPdf(String compressAfterLocalPdfUrl, List<String> pdfUrls, double spaceSizeMB) {
	String errorMessage = String.format("当前项目图纸合同共%s页%sM，线上签约图纸清晰度低，无法保障客户体验，请联系设计ssc调整图纸张数或大小，或线下签署后补录至系统", pdfUrls.size(), String.format("%.2f", spaceSizeMB));
	File file = new File(compressAfterLocalPdfUrl);
	//文件大小 单位MB
	float spaceSizeMBAfterCompress = (float) file.length() / 1024 / 1024;
	LOGGER.info("图纸pdf压缩后文件大小为：{}M, 原始大小为：{}M", String.format("%.2f", spaceSizeMBAfterCompress), String.format("%.2f", spaceSizeMB));
	if (spaceSizeMBAfterCompress > contractApolloConfig.getDrawingLaunchConfig().getDrawingCompressSize()) {
		LOGGER.error("图纸pdf压缩后文件大小超过限制，压缩后文件大小：{}M，阈值：{}M", spaceSizeMBAfterCompress, contractApolloConfig.getDrawingLaunchConfig().getDrawingCompressSize());
		throw new NrsBusinessException(ResponseCodeEnum.DRAWING_LIMIT_ERROR.getCode(), errorMessage, Level.WARN);
	}
}

private String getSealKeyword(Long formId) {
	List<SealNewRuleParam> sealNewRuleParams = freeformService.queryNewSealConfigs(formId);
	//签章关键字获取，由于个人签约&对公签约的关键字一样，这里取个人签约配置的关键字
	SealNewRuleParam sealNewRuleParam = sealNewRuleParams.stream().filter(item -> FreeFormRoleTypeEnum.SIGN_USER.getCode().equals(item.getRoleType()))
		.filter(item -> FreeFormSignTypeEnum.PERSON.getCode().equals(item.getSignType())).findFirst().orElse(null);
	if (sealNewRuleParam == null || CollectionUtils.isEmpty(sealNewRuleParam.getRuleList())) {
		LOGGER.error("合同生成pdf，获取签章关键字失败，formId：{},签章规则：{}", formId, JSON.toJSONString(sealNewRuleParam));
		throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "合同生成pdf，获取签章关键字失败", Level.WARN);
	}
	return sealNewRuleParam.getRuleList().get(0).getKeyword();
}

private List<String> getDrawingPdfUrlList() {
	DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = ContractContextHandler.getDrawingDTO();
	if (deliverDrawingDTO == null || CollectionUtils.isEmpty(deliverDrawingDTO.getDrawingDetailDTOList())) {
		return Collections.emptyList();
	}
	return deliverDrawingDTO.getDrawingDetailDTOList().stream()
		.filter(item -> ObjectUtil.equals(item.getBillType(), PlanAttachment.基础图纸))
		.filter(item -> DrawingEnum.ConstructionFileExtensionEnum.PDF.getCode().equals(item.getExtensionType()))
		.map(DrawingDTO.DrawingDetailDTO::getUrl)
		.collect(Collectors.toList());
}

