		List<String> comboCodesByPlanAllDTO = commonContractService.getComboCodesByPlanAllDTO(ContractContextHandler.getPlanAllDTO());
		List<String> decorateRulePdfs = new ArrayList<>();
		for (int i = 0; i < comboCodesByPlanAllDTO.size(); i++) {
			String comboCode = comboCodesByPlanAllDTO.get(i);
			String decorateRulePdf = getDecorateRulePdf(contract, jiaFangSealKeyword, yiFangSealKeyword, jiaFangAgentSealKeyword, comboCode, i == comboCodesByPlanAllDTO.size() - 1);
			decorateRulePdfs.add(decorateRulePdf);
		}
		LOGGER.info("正式套餐合同自定义生成合同pdf,精装细则处理完成，contractCode：{}", contract.getContractCode());
		List<String> budgetDescPdfs = new ArrayList<>();
