			String budgetRulePdf = getBudgetRulePdf(contract, comboCode);
			budgetDescPdfs.add(budgetRulePdf);
		}
		LOGGER.info("正式套餐合同自定义生成合同pdf,预算编制说明处理完成，contractCode：{}", contract.getContractCode());
		List<String> materialPdfs = new ArrayList<>();
