		}
		for (String budgetDescPdf : budgetDescPdfs) {
			addFileToLists(budgetDescPdf, comporessPdfList, tempFiles);
		}
		for (String materialPdf : materialPdfs) {
			addFileToLists(materialPdf, comporessPdfList, tempFiles);
		}
		addFileToLists(budgetUrlPdf, comporessPdfList, tempFiles);
		if (StringUtils.isNotBlank(customAttachPdf)) {
			addFileToLists(customAttachPdf, comporessPdfList, tempFiles);
		}
