@Component
@Slf4j
public class ReformAllFormalContractPdfBySelfStrategy extends BaseContractPdfCreateService  implements CreateContractPdfBySelfStrategy{

	@Resource
	private S3Service s3Service;

	@Resource
	private ContractBusinessService contractBusinessService;

	@Resource
	private ContractFileInfoService contractFileInfoService;

	@Resource
	private FreeformService freeformService;

	@Resource
	private CommonContractService commonContractService;

	@Resource
	private HouseFormalContractPdfBySelfStrategy houseFormalContractPdfBySelfStrategy;

	@Resource
	private ContractAttachConfigService contractAttachConfigService;

	@Resource
	private ContractUnifyService contractUnifyService;

	@Resource
	private ContractPdfFileHandleService contractPdfFileHandleService;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	@Override
	public String createPdf(Contract contract, ContractCityCompanyInfo config, boolean finalVersion) throws IOException {
		return reformAllContractCreate(contract, config, finalVersion);
	}

	/**
	 * 翻新全案正签合同pdf生成
	 * 	 整装正签合同附件拼接顺序
	 * 	 1、正签文本部分合同pdf
	 * 	 2、报价单 (需要写关键字，最后一页)
	 */
	private String reformAllContractCreate(Contract contract, ContractCityCompanyInfo config, boolean finalVersion)throws IOException{
		StopWatch stopWatch = new StopWatch();
		stopWatch.start();//计时开始
		//合并后pdf路径
		String formalLocalContractPdf = "formalContract_" + UUID.randomUUID() + ".pdf";
		List<SealNewRuleParam> sealNewRule = freeformService.queryNewSealConfigs(Long.valueOf(config.getFormId()));
		String jiaFangSealKeyword = getJiaFangSealKeyword(sealNewRule, Long.valueOf(config.getFormId()));
		String yiFangSealKeyword = getYiFangSealKeyword(sealNewRule, Long.valueOf(config.getFormId()));
		String jiaFangAgentSealKeyword = getJiaFangAgentSealKeyword(sealNewRule, Long.valueOf(config.getFormId()));
		LOGGER.info("翻新全案正式套餐合同自定义生成合同pdf,开始生成正式套餐合同pdf，contractCode：{}", contract.getContractCode());
		String formalTextPdf = getTextPdfUrl(contract, config,finalVersion);
		LOGGER.info("翻新全案正式套餐合同自定义生成合同pdf,正签文本部分合同pdf处理完成，contractCode：{}", contract.getContractCode());
		String budgetUrlPdf = getFormalBudgetUrlPdf(contract, jiaFangSealKeyword, yiFangSealKeyword, jiaFangAgentSealKeyword);
		LOGGER.info("翻新全案正式套餐合同自定义生成合同pdf,报价单处理完成，contractCode：{}", contract.getContractCode());
		String durationDescriptionAttachPdf = getDurationDescriptionAttachPdfUrl(contract);
		LOGGER.info("翻新全案正式套餐合同自定义生成合同pdf, 工期说明附件处理完成, contractCode:{}, durationDescriptionAttachPdf: {}", contract.getContractCode(), durationDescriptionAttachPdf);
		String customAttachPdf = getCustomAttach(contract);
		LOGGER.info("翻新全案正式套餐合同自定义生成合同pdf, 个性化附件处理完成, contractCode:{}, customeAttachPdf: {}", contract.getContractCode(), customAttachPdf);
		List<String> comporessPdfList = new ArrayList<>();
		//临时文件目录记录，删除时使用
		List<String> tempFiles = new ArrayList<>();
		tempFiles.add(formalLocalContractPdf);
		addFileToLists(formalTextPdf, comporessPdfList, tempFiles);
		addFileToLists(budgetUrlPdf, comporessPdfList, tempFiles);
		if (StringUtils.isNotBlank(durationDescriptionAttachPdf)) {
			addFileToLists(durationDescriptionAttachPdf, comporessPdfList, tempFiles);
		}
		if (StringUtils.isNotBlank(customAttachPdf)) {
			addFileToLists(customAttachPdf, comporessPdfList, tempFiles);
		}
		try {
			//pdf合并
			ContractPdfFileHandleService.mergePdfs(comporessPdfList, formalLocalContractPdf);
			File file = new File(formalLocalContractPdf);
			String fileObjectKey = s3Service.md5FileName(file.getName()) + ".pdf";
			LOGGER.info("翻新全案正式套餐合同自定义生成合同pdf,上传s3开始，contractCode：{}", contract.getContractCode());
			//pdf文件上传到s3
			s3Service.uploadByFile(file, fileObjectKey, false);
			String formalS3PdfUrl = s3Service.generateUrl(fileObjectKey, 604800);
			LOGGER.info("翻新全案正式套餐合同自定义生成合同pdf,上传s3完成，contractCode：{}", contract.getContractCode());
			//pdf文件上传到协议平台，与协议平台实例关联
			LOGGER.info("翻新全案正式套餐合同自定义生成合同pdf,上传协议平台开始，contractCode：{}", contract.getContractCode());
			Long instanceId = contractBusinessService.uploadPdfToFreeForm(contract, formalS3PdfUrl, config.getFormKey());
			LOGGER.info("翻新全案正式套餐合同自定义生成合同pdf,上传协议平台完成，contractCode：{}", contract.getContractCode());
			contract.setPreviewKey(fileObjectKey);
			contract.setPdfPageCount(ContractPdfFileHandleService.getPdfCount(formalLocalContractPdf));
			contract.setPlatformInstanceId(instanceId);
			contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.PACKAGE_FORMAL_CONTRACT.getCode(),IOUtils.getFileSizeKBByFilePath(formalLocalContractPdf),null);
			stopWatch.stop(); // 停止计时
			LOGGER.info("合同pdf生成-翻新全案正式套餐合同自定义生成合同pdf,生成正式套餐合同pdf完成，contractCode：{},耗时：{}", contract.getContractCode(), stopWatch.getTotalTimeSeconds());
			return formalS3PdfUrl;
		} finally {
			// 删除临时文件
			ContractPdfFileHandleService.cleanUp(tempFiles);
		}
	}

	/**
	 * 获取工期说明附件 pdf 链接：先从附件配置表查询图片 url，再转 pdf
	 */
	private String getDurationDescriptionAttachPdfUrl(Contract contract) throws IOException {
		// 查询工期说明附件的 imageUrl
		List<String> durationDescriptionAttachImgUrls = getDurationDescriptionAttach(contract);
		LOGGER.info("contractCode:{},查询工期说明附件 imageUrl 结果: {}", contract.getContractCode(), durationDescriptionAttachImgUrls);
		// imageUrl -> pdfUrl
		String tempPdfPath = contractPdfFileHandleService.imageToPdfAndUpload(durationDescriptionAttachImgUrls);

		// 文件大小 单位MB
		BigDecimal pdfSizeMB = IOUtils.getFileSizeMByFilePath(tempPdfPath);
		if (pdfSizeMB.compareTo(BigDecimal.valueOf(contractApolloConfig.getFormalLaunchConfig().getCompressSize())) > 0) {
			// 压缩后的文件路径
			String tempPathAfterCompress = UUID.randomUUID() + ".pdf";
			try {
				LOGGER.info("contractCode:{},工期说明附件pdf文件大小大于5MB，开始进行压缩处理", contract.getContractCode());
				contractPdfFileHandleService.compressPDF(tempPdfPath, tempPathAfterCompress, 120);
				LOGGER.info("contractCode:{},工期说明附件pdf文件大小大于5MB，压缩处理完成", contract.getContractCode());
				// 记录工期说明附件 pdf 文件大小(压缩前/压缩后)
				contractFileInfoService.saveContractFileInfoRecord(contract.getProjectOrderId(), ContractFileTypeEnum.DURATION_DESCRIPTION_ATTACH.getCode(), IOUtils.getFileSizeKBByFilePath(tempPdfPath), IOUtils.getFileSizeKBByFilePath(tempPathAfterCompress));
				return tempPathAfterCompress;
			} finally {
				// 删除临时文件
				ContractPdfFileHandleService.cleanUp(Collections.singletonList(tempPdfPath));
			}
		}
		return tempPdfPath;
	}

	/**
	 * 获取工期说明附件
	 */
	private List<String> getDurationDescriptionAttach(Contract contract) {
		boolean developerChannel = contractUnifyService.isDeveloperChannel(contract.getProjectOrderId());
		Byte contractFormType = ContractFormTypeEnum.getCodeByDeveloperChannel(developerChannel);
		return contractAttachConfigService.getByGbCodeAndCompanyCodeAndAttachTypeWithDefaultConfig(contract.getGbCode(), contract.getCompanyCode(), contractFormType, ContractAttachTypeEnum.DURATION_DESCRIPTION_ATTACH.getCode())
			.stream()
			.map(ContractAttachConfig::getImageUrl)
			.collect(Collectors.toList());
	}


	// 添加文件到两个列表的方法
	private void addFileToLists(String filePath, List<String> comporessList, List<String> tempList) {
		if (StringUtils.isNotBlank(filePath)) {
			comporessList.add(filePath);
			tempList.add(filePath);
		}
	}




}

