	//提交接口1:2.0整装、局装分模块diff字段
	ChangeContractSubmitRes changeContractSubmit(ContractReqDTO contractReq);

	//提交接口2:2.5整装、团装统一diff字段
	ChangeContractSubmitResV2 changeContractSubmitV2(ContractReqDTO contractReq);

	//合同确认接口
	ContractSubmitResDTO changeContractConfirm(Contract contract);


