public ContractComboInfo getContractComboInfoBySignDate(Date signDate, String comboCode, Byte contractFormType) {
	List<ContractComboInfo> contractComboInfoList = contractComboInfoService.getContractComboInfoWithDefaultConfig(comboCode, contractFormType);
	if (CollectionUtils.isEmpty(contractComboInfoList)) {
		throw new NrsBusinessException(String.format("套餐【%s】【%s】配置不存在", comboCode, contractFormType));
	}
	//获取第一个小于等于date的配置
	ContractComboInfo contractComboInfo = contractComboInfoList.stream().filter(contractComboInfo1 -> contractComboInfo1.getCtime().before(signDate)).max(Comparator.comparing(ContractComboInfo::getCtime)).orElse(null);
	if (ObjectUtil.isEmpty(contractComboInfo)) {
		//获取最新的配置
		return contractComboInfoList.stream().max(Comparator.comparing(ContractComboInfo::getCtime)).orElse(null);
	} else {
