@Slf4j
@Service
public class MaterialPdfDiffService {

	/**
	 * 检查远程实时数据与数据库存储数据是否一致
	 *
	 * @param remoteComboSkuGroup 远程查询的套餐 SKU
	 * @param dbMaterialDataList  数据库存储的材料 PDF 数据列表
	 * @return true: 数据一致，false: 数据不一致
	 */
	public boolean isConsistent(ComboSkuGroupDTO remoteComboSkuGroup,
								List<ContractMaterialPdfData> dbMaterialDataList) {
		LOGGER.info("开始检查套餐 {} 的数据一致性", remoteComboSkuGroup.getComboId());

		// 步骤1: 转换远程数据
		List<ComboSkuVO> remoteMaterialDataList = convertFromSkuGroup(remoteComboSkuGroup);
		LOGGER.info("远程数据转换完成: {}", JSON.toJSONString(remoteMaterialDataList));

		// 步骤2: 转换数据库数据
		List<ComboSkuVO> dbComboSkuVOList = convertFromDbData(dbMaterialDataList);
		LOGGER.info("数据库数据转换完成: {}", JSON.toJSONString(dbComboSkuVOList));

		// 步骤3: 对比数据是否一致
		return compareMaterialData(remoteMaterialDataList, dbComboSkuVOList);
	}

	/**
	 * 对比两个 List<MaterialDataDTO> 是否一致
	 * 比较规则：
	 * 1. 先将两个 List<MaterialDataDTO> 转换为 List<MaterialItemVO>
	 * 2. 比较数量是否相同
	 * 3. 比较每条记录的关键字段（categoryLevel3Name, brandNames）是否完全匹配
	 *
	 * @param remoteList 远程数据列表
	 * @param dbList 数据库数据列表
	 * @return true: 数据一致，false: 数据不一致
	 */
	private boolean compareMaterialData(List<ComboSkuVO> remoteList, List<ComboSkuVO> dbList) {
		if (remoteList == null || dbList == null) {
			LOGGER.info("数据对比：存在一方数据为 null");
			return false;
		}

		// 步骤1: 将两个 List<MaterialDataDTO> 转换为 List<MaterialItemVO>
		List<MaterialPdfItemVO> remoteMaterialItemList = aggregateMaterialData(remoteList);
		List<MaterialPdfItemVO> dbMaterialItemList = aggregateMaterialData(dbList);

		LOGGER.info("数据对比: 转换后的远程数据: {}", JSON.toJSONString(remoteMaterialItemList));
		LOGGER.info("数据对比: 转换后的数据库数据: {}", JSON.toJSONString(dbMaterialItemList));

		// 步骤2: 比较数量
		if (remoteMaterialItemList.size() != dbMaterialItemList.size()) {
			LOGGER.info("数据对比: 数量不一致，远程数据 {} 条，数据库数据 {} 条", remoteMaterialItemList.size(), dbMaterialItemList.size());
			return false;
		}

		// 步骤3: 比较每条记录的关键字段
		// 将两个列表转为 Set，用于对比
		// 比较维度：categoryLevel3Name + brandNames
		Set<String> remoteKeySet = remoteMaterialItemList.stream()
			.map(this::buildMaterialItemCompareKey)
			.collect(Collectors.toSet());

		Set<String> dbKeySet = dbMaterialItemList.stream()
			.map(this::buildMaterialItemCompareKey)
			.collect(Collectors.toSet());

		// 直接比较两个 Set 是否相等
		return remoteKeySet.equals(dbKeySet);
	}

	/**
	 * 将 ComboSkuGroupDTO 转换为 List<MaterialDataDTO>
	 */
	public List<ComboSkuVO> convertFromSkuGroup(ComboSkuGroupDTO remoteComboSkuGroup) {
		if (remoteComboSkuGroup == null) {
			return Collections.emptyList();
		}

		List<ComboSkuDTO> skuList = remoteComboSkuGroup.getSkuList();
		if (skuList == null || skuList.isEmpty()) {
			return Collections.emptyList();
		}

		// 按 (categoryLevel3Code + brandCode) 去重：保留第一条，保持原始顺序
		Map<String, ComboSkuVO> distinctValues = skuList.stream()
			.filter(Objects::nonNull)
			.collect(Collectors.toMap(
				sku -> sku.getCategoryLevel3Code() + "#" + sku.getBrandCode(),
				sku -> ComboSkuVO.builder()
					.categoryLevel3Code(sku.getCategoryLevel3Code())
					.categoryLevel3Name(sku.getCategoryLevel3Name())
					.brandCode(sku.getBrandCode())
					.brandName(sku.getBrandName())
					.build(),
				(first, ignored) -> first,          // key 冲突时保留第一条
				LinkedHashMap::new                  // 保持插入顺序
			));

		return new ArrayList<>(distinctValues.values());
	}


	/**
	 * 将 List<ContractMaterialPdfData> 转换为 List<MaterialDataDTO>
	 *
	 * @param contractMaterialList 合同材料 PDF 数据列表
	 * @return MaterialDataDTO 列表
	 */
	public List<ComboSkuVO> convertFromDbData(List<ContractMaterialPdfData> contractMaterialList) {
		if (contractMaterialList == null || contractMaterialList.isEmpty()) {
			return Collections.emptyList();
		}

		return contractMaterialList.stream()
			.map(data -> ComboSkuVO.builder()
				.categoryLevel3Code(data.getCategoryLevel3Code())
				.categoryLevel3Name(data.getCategoryLevel3Name())
				.brandCode(data.getBrandCode())
				.brandName(data.getBrandName())
				.build())
			.collect(Collectors.toList());
	}

	/**
	 * 聚合材料数据
	 * 聚合规则：
	 * 1. 按 categoryLevel3Code 分组
	 * 2. 过滤掉 brandName 为 "其他" 的项
	 * 3. 同一组内的品牌名称按字母排序后用 "/" 连接
	 * 4. 品牌为空的三级类目不展示
	 * 5. 结果按 categoryLevel3Name 正序排序
	 *
	 * @param materialDataList 材料数据列表
	 * @return 聚合后的材料项列表
	 */
	private List<MaterialPdfItemVO> aggregateMaterialData(List<ComboSkuVO> materialDataList) {
		if (materialDataList == null || materialDataList.isEmpty()) {
			return Collections.emptyList();
		}

		// 按 categoryLevel3Code 分组
		Map<String, List<ComboSkuVO>> groupedMap = materialDataList.stream()
				.collect(Collectors.groupingBy(ComboSkuVO::getCategoryLevel3Code));

		List<MaterialPdfItemVO> result = new ArrayList<>();

		// 遍历每个分组，聚合品牌名称
		for (Map.Entry<String, List<ComboSkuVO>> entry : groupedMap.entrySet()) {
			List<ComboSkuVO> groupList = entry.getValue();

			// 按 brandName 升序排序
			groupList.sort(Comparator.comparing(ComboSkuVO::getBrandName));

			// 获取 categoryLevel3Name（同一组的应该都相同，取第一个即可）
			String categoryLevel3Name = groupList.get(0).getCategoryLevel3Name();

			// 聚合所有 brandName，过滤掉"其他"，用 "/" 连接
			String brandNames = groupList.stream()
					.map(ComboSkuVO::getBrandName)
					.filter(brandName -> !"其他".equals(brandName)) // 过滤掉"其他"
					.distinct() // 去重
					.collect(Collectors.joining("/"));

			// 品牌为空的三级类目不在 PDF 展示
			if (StringUtils.isBlank(brandNames)) {
				continue;
			}

			// 构建 MaterialItemVO（暂不设置 sequenceNumber）
			MaterialPdfItemVO item = MaterialPdfItemVO.builder()
					.categoryLevel3Name(categoryLevel3Name)
					.brandNames(brandNames)
					.build();

			result.add(item);
		}

		// 按 categoryLevel3Name 正序排序
		result.sort(Comparator.comparing(MaterialPdfItemVO::getCategoryLevel3Name));

		// 从小到大重新赋值 sequenceNumber
		for (int i = 0; i < result.size(); i++) {
			result.get(i).setSequenceNumber(String.valueOf(i + 1));
		}

		return result;
	}

	/**
	 * 构建 MaterialItemVO 的对比唯一键
	 * 格式：categoryLevel3Name|brandNames
	 *
	 * @param item MaterialItemVO 对象
	 * @return 对比唯一键
	 */
	private String buildMaterialItemCompareKey(MaterialPdfItemVO item) {
		return item.getCategoryLevel3Name() + "|" + item.getBrandNames();
	}
}

