@Slf4j
@Service
public class MaterialPdfGenerator {

	@Resource
	private MaterialPdfUtil materialPdfUtil;

	@Resource
	private MaterialPdfDiffService materialPdfDiffService;

	@Resource
	private PdfToImageService pdfToImageService;

	@Resource
	private ContractMaterialPdfDataRepository contractMaterialPdfDataRepository;

	@Resource
	private ContractApolloConfig contractApolloConfig;

	public Map<String, MaterialPdfData> generateMaterialPdf(List<ComboSkuGroupDTO> comboSkuGroupList) {
		Map<String, MaterialPdfData> result = new HashMap<>();
		if (CollectionUtils.isEmpty(comboSkuGroupList)) {
			LOGGER.info("系统自动生成材料配送清单, comboSkuGroupList 为空");
			return result;
		}

		// 1. 遍历各 comboCode 对应 sku 数据
		for (ComboSkuGroupDTO skuGroup : comboSkuGroupList) {
			// 2. 检查是否需要生成 pdf
			if (noNeedGenerateMaterialPdf(skuGroup)) {
				continue;
			}

			// 3. 生成 comboCode 的材料配送清单 pdf
			String materialPdfUrl = generateMaterialPdfByComboSkus(skuGroup);

			if (StringUtils.isBlank(materialPdfUrl)) {
				LOGGER.error("系统自动生成材料配送清单, pdfUrl 为空, comboCode: {}", skuGroup.getComboId());
				continue;
			}

			// 4. pdf 转图片
			String materialImageUrls = StringUtils.join(pdfToImageService.pdf2ImagePublicParallel(materialPdfUrl), ",");

			// 5. 存储材料配送清单数据快照
			List<ComboSkuVO> materialSkus = materialPdfDiffService.convertFromSkuGroup(skuGroup);
			MaterialPdfData materialPdfData = MaterialPdfData.builder()
				.comboCode(skuGroup.getComboId())
				.materialPdfUrl(materialPdfUrl)
				.materialImageUrls(materialImageUrls)
				.materialSkus(materialSkus)
				.build();

			result.put(materialPdfData.getComboCode(), materialPdfData);
		}
		return result;
	}

	private boolean noNeedGenerateMaterialPdf(ComboSkuGroupDTO remoteData) {
		// 如果 apollo 配置当前套餐, 无需生成, 则跳过
		if (contractApolloConfig.getNoNeedAutoGenerateComboCodes().contains(remoteData.getComboId())) {
			LOGGER.info("系统自动生成材料配送清单, apollo 配置当前套餐不自动生成: {}", remoteData.getComboId());
			return true;
		}

		String comboCode = remoteData.getComboId();
		List<ContractMaterialPdfData> dbData = contractMaterialPdfDataRepository.getByComboCode(comboCode);

		// 检查 pdf 与最新数据是否一致
		boolean consistent = materialPdfDiffService.isConsistent(remoteData, dbData);
		LOGGER.info("系统自动生成材料配送清单, diff 检查数据是否一致: {}", consistent);
		return consistent;
	}

	/**
	 * 基于套餐的 sku 信息生成材料配送清单 pdf
	 * 如果当前套餐对应的 sku 信息为空，则报警提示
	 */
	private String generateMaterialPdfByComboSkus(ComboSkuGroupDTO skuGroup) {
		List<ComboSkuDTO> comboSkus = skuGroup.getSkuList();
		String comboCode = skuGroup.getComboId();
		if (CollectionUtils.isEmpty(comboSkus)) {
			throw new NrsBusinessException("系统自动生成材料配送清单失败,查询套餐 sku 信息为空, comboCode: " + comboCode);
		}
		LOGGER.info("套餐 sku 数据聚合, before: {}", JSON.toJSONString(comboSkus));
		// 1. 按照规则聚合 sku 数据
		List<MaterialPdfItemVO> materialItems = aggregateMaterialData(comboSkus);
		LOGGER.info("套餐 sku 数据聚合, after: {}", JSON.toJSONString(materialItems));

		// 2. 生成 PDF
		String fileKey = "material_list" + "_" + UUID.randomUUID() + ".pdf";
		return materialPdfUtil.doGeneral(
			"pdftemplate/material.html",
			fileKey,
			ImmutableBiMap.of("materialItems", materialItems)
		);
	}

	/**
	 * 聚合材料数据
	 * 聚合规则：
	 * 1. 按 categoryLevel3Code 分组
	 * 2. 过滤掉 brandName 为 "其他" 的项
	 * 3. 同一组内的品牌名称按字母排序后用 "/" 连接
	 * 4. 品牌为空的三级类目不展示
	 * 5. 结果按 categoryLevel3Name 正序排序
	 */
	public List<MaterialPdfItemVO> aggregateMaterialData(List<ComboSkuDTO> comboSkuDTOS) {
		if (comboSkuDTOS == null || comboSkuDTOS.isEmpty()) {
			return Collections.emptyList();
		}

		// 按 categoryLevel3Code 分组
		Map<String, List<ComboSkuDTO>> groupedMap = comboSkuDTOS.stream()
			.collect(Collectors.groupingBy(ComboSkuDTO::getCategoryLevel3Code));

		List<MaterialPdfItemVO> result = new ArrayList<>();

		// 遍历每个分组，聚合品牌名称
		for (Map.Entry<String, List<ComboSkuDTO>> entry : groupedMap.entrySet()) {
			List<ComboSkuDTO> skus = entry.getValue();

			// 按 brandName 升序排序
			skus.sort(Comparator.comparing(ComboSkuDTO::getBrandName));

			// 获取 categoryLevel3Name（同一组的应该都相同，取第一个即可）
			String categoryLevel3Name = skus.get(0).getCategoryLevel3Name();

			// 聚合所有 brandName，过滤掉"其他"，用 "/" 连接，“其他”品牌的 brandCode 恒为 672，这里硬编码
			String brandNames = skus.stream()
				.filter(sku -> !ObjectUtils.equals(672, sku.getBrandCode()))
				.map(ComboSkuDTO::getBrandName)
				.distinct()
				.collect(Collectors.joining("/"));

			// 品牌为空的三级类目不在 PDF 展示
			if (StringUtils.isBlank(brandNames)) {
				continue;
			}

			// 构建 MaterialItemVO
			MaterialPdfItemVO item = MaterialPdfItemVO.builder()
				.categoryLevel3Name(categoryLevel3Name)
				.brandNames(brandNames)
				.build();

			result.add(item);
		}

		// 按 categoryLevel3Name 正序排序
		result.sort(Comparator.comparing(MaterialPdfItemVO::getCategoryLevel3Name));

		// 从小到大重新赋值 sequenceNumber
		for (int i = 0; i < result.size(); i++) {
			result.get(i).setSequenceNumber(String.valueOf(i + 1));
		}
		return result;
	}
}

public Map<String, MaterialPdfData> generateMaterialPdf(List<ComboSkuGroupDTO> comboSkuGroupList) {
	Map<String, MaterialPdfData> result = new HashMap<>();
	if (CollectionUtils.isEmpty(comboSkuGroupList)) {
		LOGGER.info("系统自动生成材料配送清单, comboSkuGroupList 为空");
		return result;
	}

	// 1. 遍历各 comboCode 对应 sku 数据
	for (ComboSkuGroupDTO skuGroup : comboSkuGroupList) {
		// 2. 检查是否需要生成 pdf
		if (noNeedGenerateMaterialPdf(skuGroup)) {
			continue;
		}

		// 3. 生成 comboCode 的材料配送清单 pdf
		String materialPdfUrl = generateMaterialPdfByComboSkus(skuGroup);

		if (StringUtils.isBlank(materialPdfUrl)) {
			LOGGER.error("系统自动生成材料配送清单, pdfUrl 为空, comboCode: {}", skuGroup.getComboId());
			continue;
		}

		// 4. pdf 转图片
		String materialImageUrls = StringUtils.join(pdfToImageService.pdf2ImagePublicParallel(materialPdfUrl), ",");

		// 5. 存储材料配送清单数据快照
		List<ComboSkuVO> materialSkus = materialPdfDiffService.convertFromSkuGroup(skuGroup);
		MaterialPdfData materialPdfData = MaterialPdfData.builder()
			.comboCode(skuGroup.getComboId())
			.materialPdfUrl(materialPdfUrl)
			.materialImageUrls(materialImageUrls)
			.materialSkus(materialSkus)
			.build();

		result.put(materialPdfData.getComboCode(), materialPdfData);
	}
	return result;
}

private boolean noNeedGenerateMaterialPdf(ComboSkuGroupDTO remoteData) {
	// 如果 apollo 配置当前套餐, 无需生成, 则跳过
	if (contractApolloConfig.getNoNeedAutoGenerateComboCodes().contains(remoteData.getComboId())) {
		LOGGER.info("系统自动生成材料配送清单, apollo 配置当前套餐不自动生成: {}", remoteData.getComboId());
		return true;
	}

	String comboCode = remoteData.getComboId();
	List<ContractMaterialPdfData> dbData = contractMaterialPdfDataRepository.getByComboCode(comboCode);

	// 检查 pdf 与最新数据是否一致
	boolean consistent = materialPdfDiffService.isConsistent(remoteData, dbData);
	LOGGER.info("系统自动生成材料配送清单, diff 检查数据是否一致: {}", consistent);
	return consistent;
}

private String generateMaterialPdfByComboSkus(ComboSkuGroupDTO skuGroup) {
	List<ComboSkuDTO> comboSkus = skuGroup.getSkuList();
	String comboCode = skuGroup.getComboId();
	if (CollectionUtils.isEmpty(comboSkus)) {
		throw new NrsBusinessException("系统自动生成材料配送清单失败,查询套餐 sku 信息为空, comboCode: " + comboCode);
	}
	LOGGER.info("套餐 sku 数据聚合, before: {}", JSON.toJSONString(comboSkus));
	// 1. 按照规则聚合 sku 数据
	List<MaterialPdfItemVO> materialItems = aggregateMaterialData(comboSkus);
	LOGGER.info("套餐 sku 数据聚合, after: {}", JSON.toJSONString(materialItems));

	// 2. 生成 PDF
	String fileKey = "material_list" + "_" + UUID.randomUUID() + ".pdf";
	return materialPdfUtil.doGeneral(
		"pdftemplate/material.html",
		fileKey,
		ImmutableBiMap.of("materialItems", materialItems)
	);
}

public List<MaterialPdfItemVO> aggregateMaterialData(List<ComboSkuDTO> comboSkuDTOS) {
	if (comboSkuDTOS == null || comboSkuDTOS.isEmpty()) {
		return Collections.emptyList();
	}

	// 按 categoryLevel3Code 分组
	Map<String, List<ComboSkuDTO>> groupedMap = comboSkuDTOS.stream()
		.collect(Collectors.groupingBy(ComboSkuDTO::getCategoryLevel3Code));

	List<MaterialPdfItemVO> result = new ArrayList<>();

	// 遍历每个分组，聚合品牌名称
	for (Map.Entry<String, List<ComboSkuDTO>> entry : groupedMap.entrySet()) {
		List<ComboSkuDTO> skus = entry.getValue();

		// 按 brandName 升序排序
		skus.sort(Comparator.comparing(ComboSkuDTO::getBrandName));

		// 获取 categoryLevel3Name（同一组的应该都相同，取第一个即可）
		String categoryLevel3Name = skus.get(0).getCategoryLevel3Name();

		// 聚合所有 brandName，过滤掉"其他"，用 "/" 连接，“其他”品牌的 brandCode 恒为 672，这里硬编码
		String brandNames = skus.stream()
			.filter(sku -> !ObjectUtils.equals(672, sku.getBrandCode()))
			.map(ComboSkuDTO::getBrandName)
			.distinct()
			.collect(Collectors.joining("/"));

		// 品牌为空的三级类目不在 PDF 展示
		if (StringUtils.isBlank(brandNames)) {
			continue;
		}

		// 构建 MaterialItemVO
		MaterialPdfItemVO item = MaterialPdfItemVO.builder()
			.categoryLevel3Name(categoryLevel3Name)
			.brandNames(brandNames)
			.build();

		result.add(item);
	}

	// 按 categoryLevel3Name 正序排序
	result.sort(Comparator.comparing(MaterialPdfItemVO::getCategoryLevel3Name));

	// 从小到大重新赋值 sequenceNumber
	for (int i = 0; i < result.size(); i++) {
		result.get(i).setSequenceNumber(String.valueOf(i + 1));
	}
	return result;
}

